async function quickToggleHabit(id) {
  const r = await fetch(`/api/habits/${id}/toggle`, {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin',
    body: JSON.stringify({date_key: localToday()}),
  }).then(r => r.json()).catch(() => null);
  const chip = document.getElementById(`qlg-habit-${id}`);
  if (chip && r) chip.classList.toggle('done', !!r.done);
  try { loadWellnessStrip(); } catch (e) {}
  if (r?.done) { try { checkHabitCelebrations(); } catch (e) {} }
}

async function quickCopyYesterday() {
  const items = window._qlgYesterday || [];
  if (!items.length) return;
  await Promise.all(items.map(item => fetch('/api/food/log', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin',
    body: JSON.stringify({
      food_id: item.food_id, food_name: item.food_name, meal_type: item.meal_type,
      date_key: localToday(), quantity_g: item.quantity_g,
      calories: item.calories, protein: item.protein, carbs: item.carbs,
      fat: item.fat, fiber: item.fiber,
    }),
  }).catch(() => {})));
  closeQuickLog();
  showToast(tformat('🍽️ %1 item(s) copied from yesterday', items.length));
  try { if (document.getElementById('view-food').classList.contains('active')) loadFoodTracker(); } catch (e) {}
}

// ── Web Push subscription ─────────────────────────────────────────
function _urlB64ToUint8(b64) {
  const pad = '='.repeat((4 - b64.length % 4) % 4);
  const raw = atob((b64 + pad).replace(/-/g, '+').replace(/_/g, '/'));
  return Uint8Array.from([...raw].map(c => c.charCodeAt(0)));
}

// The only reminder path. The client used to run a second one beside it — a
// setInterval loop that fired its own dose/water/habit/sleep/mood
// notifications whenever the tab was open. It was strictly worse and actively
// harmful, so it's gone; don't bring it back:
//
//   - Two notifications for one dose, worded differently, whenever the tab
//     happened to be open. Only the server's had a working button.
//   - Its "✓ Mark as Taken" button emitted the action `taken`, which the
//     service worker doesn't handle — so it fell through to "open the app"
//     and the dose was never logged. The user believed it was.
//   - It registered a second, blob-built service worker at scope '/', which
//     would have displaced the real /sw.js — killing push and offline — if
//     browsers hadn't rejected blob: script URLs.
//
// scheduler.py covers every one of those reminders, works with the tab closed,
// and its action buttons write straight through the service worker.
async function setupPushSubscription() {
  try {
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) return;
    if (Notification.permission !== 'granted') return;
    const reg = await navigator.serviceWorker.ready;
    let sub = await reg.pushManager.getSubscription();
    if (!sub) {
      const cfg = await fetch('/api/push/vapid-public-key', {credentials: 'same-origin'})
        .then(r => r.json()).catch(() => null);
      if (!cfg || !cfg.enabled || !cfg.key) return;
      sub = await reg.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: _urlB64ToUint8(cfg.key),
      });
    }
    await fetch('/api/push/subscribe', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      credentials: 'same-origin',
      body: JSON.stringify({subscription: sub.toJSON()}),
    });
  } catch (e) {
    console.warn('[push] subscription setup failed:', e);
  }
}

// ── PWA: register the service worker ─────────────────────────────
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js').catch(err =>
      console.warn('[pwa] service worker registration failed:', err));
  });
}

// ── Keyboard: Enter submits the active form ──────────────────────
document.addEventListener('keydown', e => {
  if (e.key !== 'Enter') return;
  const screen = document.getElementById('auth-screen');
  if (!screen || screen.style.display === 'none') return;
  const visible = id => document.getElementById(id)?.style.display !== 'none';
  if      (visible('auth-form-reset'))  submitReset();
  else if (visible('auth-form-forgot')) submitForgot();
  else if (visible('auth-form-login'))  submitLogin();
  else                                  submitRegister();
});

// ── Accessibility: overlay focus + keyboard handling ──
// Every full-screen overlay in the app matches one of these. Kept in one place
// so Escape-to-close, focus-restore, and the Tab focus-trap all agree on what
// "an open overlay" is (the Q1 pass only knew about the first three).
const _A11Y_OVERLAY_SEL = '.modal-overlay, .checkin-overlay, .global-search-wrap, .fd-overlay, #onboarding-overlay';

// Remember the last thing focused OUTSIDE any overlay, so closing a modal can
// return focus where it was instead of dumping it at the top of the document.
let _a11yLastFocus = null;
document.addEventListener('focusin', e => {
  const t = e.target;
  if (t && t.closest && !t.closest(_A11Y_OVERLAY_SEL)) _a11yLastFocus = t;
});

function _a11yShown(el) {
  // Robust "is it visible" that works for position:fixed overlays too, where
  // offsetParent is always null even when the element is on screen.
  const st = getComputedStyle(el);
  if (st.display === 'none' || st.visibility === 'hidden') return false;
  return !!(el.offsetWidth || el.offsetHeight || el.getClientRects().length);
}
function _a11yVisibleOverlays() {
  return [...document.querySelectorAll(_A11Y_OVERLAY_SEL)].filter(_a11yShown);
}
function _a11yTopOverlay() {
  const open = _a11yVisibleOverlays();
  return open.length ? open[open.length - 1] : null;
}
function _a11yFocusables(el) {
  return [...el.querySelectorAll(
    'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),' +
    'textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')]
    .filter(n => _a11yShown(n) || n === document.activeElement);
}

// Escape closes the topmost open overlay and restores focus.
document.addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  const top = _a11yTopOverlay();
  if (!top) return;
  if (top.id === 'feature-dir-overlay') top.remove();   // this one is built/torn-down
  else top.style.display = 'none';
  e.preventDefault();
  try { if (_a11yLastFocus && document.contains(_a11yLastFocus)) _a11yLastFocus.focus(); } catch (err) {}
});

// Trap Tab within the topmost overlay so keyboard focus can't wander behind it.
document.addEventListener('keydown', e => {
  if (e.key !== 'Tab') return;
  const top = _a11yTopOverlay();
  if (!top) return;
  const f = _a11yFocusables(top);
  if (!f.length) return;
  const first = f[0], last = f[f.length - 1];
  const active = document.activeElement;
  if (e.shiftKey && (active === first || !top.contains(active))) { last.focus(); e.preventDefault(); }
  else if (!e.shiftKey && active === last) { first.focus(); e.preventDefault(); }
});

// Enter/Space activate a non-native clickable (div/span carrying data-ev-click
// that we've marked role="button"). Bridges the CSP-safe delegation to keyboard.
document.addEventListener('keydown', e => {
  if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
  const el = e.target;
  if (!el || el.getAttribute('role') !== 'button' || !el.hasAttribute('data-ev-click')) return;
  const tag = el.tagName;
  if (tag === 'BUTTON' || tag === 'A' || tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
  e.preventDefault();
  try { _evRun(el.getAttribute('data-ev-click'), el, e); } catch (err) {}
});

// ── Accessibility: label modals + icon-only controls for screen readers ──
function _applyA11yLabels() {
  document.querySelectorAll('.modal').forEach(m => {
    m.setAttribute('role', 'dialog');
    m.setAttribute('aria-modal', 'true');
    const title = m.querySelector('.modal-title');
    if (title && !m.getAttribute('aria-label')) m.setAttribute('aria-label', title.textContent.trim());
  });
  document.querySelectorAll('.modal-close').forEach(b => {
    if (!b.getAttribute('aria-label')) b.setAttribute('aria-label', 'Close');
  });
}
document.addEventListener('DOMContentLoaded', _applyA11yLabels);

// ── Accessibility: make rendered markup keyboard- & screen-reader-friendly ──
// Runs over the shell on load and over each view after it renders. Idempotent
// (marks processed elements) so repeat passes on navigation stay cheap.
const _A11Y_NATIVE = { BUTTON: 1, A: 1, INPUT: 1, SELECT: 1, TEXTAREA: 1, LABEL: 1 };
let _a11yIdSeq = 0;
function _a11yEnhance(root) {
  if (!root || !root.querySelectorAll) return;

  // 1. Keyboard-operable click surfaces: a div/span carrying data-ev-click is
  //    mouse-only. Give it button semantics so it's focusable + Enter/Space
  //    works (see the keydown bridge above). Skip native controls and the
  //    click-outside backdrops (announcing those as buttons is noise).
  root.querySelectorAll('[data-ev-click]:not([data-a11y])').forEach(el => {
    el.setAttribute('data-a11y', '1');
    if (_A11Y_NATIVE[el.tagName] || el.getAttribute('role')) return;
    const ev = el.getAttribute('data-ev-click') || '';
    if (/backdropClose/.test(ev)) return;                 // dismiss-on-outside-click, not a control
    el.setAttribute('role', 'button');
    if (!el.hasAttribute('tabindex')) el.setAttribute('tabindex', '0');
  });

  // 2. Hide purely decorative inline icons from the a11y tree — every icon in
  //    this app sits beside its own visible text label, so an unlabeled SVG is
  //    just duplicate noise for a screen reader.
  root.querySelectorAll('svg:not([data-a11y])').forEach(svg => {
    svg.setAttribute('data-a11y', '1');
    if (svg.getAttribute('role') === 'img' || svg.getAttribute('aria-label')) return;
    svg.setAttribute('aria-hidden', 'true');
    svg.setAttribute('focusable', 'false');
  });

  // 3. Programmatically associate visible labels with their control. The app's
  //    labels rely on proximity (no for=); wire them up so a screen reader
  //    announces the field name, without editing every form by hand.
  root.querySelectorAll('label.form-label:not([data-a11y])').forEach(lbl => {
    lbl.setAttribute('data-a11y', '1');
    if (lbl.htmlFor || lbl.querySelector('input,select,textarea')) return;
    let ctl = lbl.nextElementSibling;
    while (ctl && !/^(INPUT|SELECT|TEXTAREA)$/.test(ctl.tagName)) ctl = ctl.nextElementSibling;
    if (!ctl) return;
    if (!ctl.id) ctl.id = 'a11y-f-' + (++_a11yIdSeq);
    lbl.htmlFor = ctl.id;
  });
}
document.addEventListener('DOMContentLoaded', () => { try { _a11yEnhance(document); } catch (e) {} });

// ── State ──
let selectedTags = [], selectedFile = null, selectedIcon = '💊', selectedColor = 'teal', selectedActivityType = 'running';
let notifPermission = 'default';

// ── Init ──
document.addEventListener('DOMContentLoaded', () => {
  // Gate the entire app behind auth check
  initAuth();
  return; // rest of boot runs inside showApp() → switchView('dashboard')
  // --- unreachable code below kept for reference ---
  setGreeting();
  setDates();
  setupNavigation();
  setupDropzone();
  setupTagPicker();
  setupUploadForm();
  setupMedForm();
  setupActivityForm();
  setupIconColorPicker();
  setupFreqPicker();
  setupActivityTypePicker();
  setupFilters();
  loadDashboard();
  updateSidebarUser();
  checkNotifPermission();
  scheduleTodoReminderChecks();
  // Init date pickers
  const tdp = document.getElementById('thoughts-date-picker');
  if (tdp) tdp.value = localToday();
});

// ── Greeting & Date ──
function setGreeting() {
  const h = new Date().getHours();
  const g = h < 12 ? 'Good morning' : h < 17 ? 'Good afternoon' : 'Good evening';
  const el = document.getElementById('greeting');
  if (el) el.textContent = t(g);
  const hd = document.getElementById('header-date');
  if (hd) hd.textContent = new Date().toLocaleDateString('en-US', { weekday:'long', month:'long', day:'numeric', year:'numeric' });
  const mt = document.getElementById('med-today-date');
  if (mt) mt.textContent = new Date().toLocaleDateString('en-US', { weekday:'short', month:'short', day:'numeric' });
}

function setDates() {
  const today = localToday();
  ['report-date','med-start-date','activity-date'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = today;
  });
}

// ── Navigation ──
function setupNavigation() {
  // Sidebar items, mobile tab bar and the mobile "More" sheet all navigate
  document.querySelectorAll('[data-view]').forEach(item => {
    item.addEventListener('click', e => {
      e.preventDefault();
      switchView(item.dataset.view);
    });
  });
}

// ── Mobile "More" sheet ──
function toggleMobileMore() {
  const sheet = document.getElementById('mobile-more-sheet');
  if (sheet) sheet.style.display = sheet.style.display === 'none' ? '' : 'none';
}
function closeMobileMore() {
  const sheet = document.getElementById('mobile-more-sheet');
  if (sheet) sheet.style.display = 'none';
}

function switchView(view) {
  try { stopSpeaking(); } catch (e) {}      // don't keep talking after leaving
  // Redirect removed/merged views
  const REDIRECT = {
    'consistency': 'habits',
    'report':      'progress',
    // 'export' was accidentally redirected here, which orphaned the whole
    // data-export page (the DPDP "download all my data" + scoped export). It is
    // a real, reachable page — see the "Export data" item in the More nav group.
  };
  view = REDIRECT[view] || view;

  document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
  document.querySelectorAll('[data-view]').forEach(n => {
    n.classList.remove('active');
    n.removeAttribute('aria-current');       // a11y: only the active nav is "current"
  });
  const viewEl = document.getElementById('view-' + view);
  if (viewEl) viewEl.classList.add('active');
  document.querySelectorAll('[data-view="' + view + '"]')
    .forEach(n => { n.classList.add('active'); n.setAttribute('aria-current', 'page'); });
  try { _applyNavGroups(); } catch (e) {}   // keep the active view's nav group open
  // a11y: make this view's dynamically-rendered click surfaces keyboard-operable
  // and hide its decorative icons. Deferred so view loaders have painted.
  try { setTimeout(() => _a11yEnhance(viewEl || document), 60); } catch (e) {}
  closeMobileMore();   // navigating always dismisses the mobile sheet

  if (view === 'dashboard')     { loadDashboard(); loadWellnessStrip(); }
  if (view === 'food')          { loadFoodTracker(); loadHydration(localToday()); }
  if (view === 'fitness')       { loadFitness(); loadConnectedServices(); }
  if (view === 'medicines')     loadMedicines();
  if (view === 'reports')       loadReports();
  if (view === 'habits')        loadHabits();
  if (view === 'thoughts')      { loadWellness(); setTimeout(() => switchWellnessTab('thoughts'), 50); }
  if (view === 'sleep')         loadSleepView();
  if (view === 'body')          loadBodyView();
  if (view === 'labs')          loadLabsView();
  if (view === 'conditions')    loadConditionsView();
  if (view === 'immunizations') loadImmunizations();
  if (view === 'timeline')      loadTimeline();
  if (view === 'goals')         loadGoals();
  if (view === 'fasting')       loadFasting();
  if (view === 'health-id')     loadHealthId();
  if (view === 'care-plan')     loadCarePlan();
  if (view === 'care-team')     loadCareTeam();
  if (view === 'prescriptions') loadPrescriptions();
  if (view === 'claims')        loadClaims();
  if (view === 'allergies')     loadAllergies();
  if (view === 'dentalvision')  loadDentalVision();
  if (view === 'supplies')      loadSupplies();
  if (view === 'symptomphotos') loadSymptomPhotos();
  if (view === 'binder')        loadHealthBinder();
  if (view === 'familyhistory') loadFamilyHistory();
  if (view === 'procedures')    loadProcedures();
  if (view === 'quit')          loadQuit();
  if (view === 'menopause')     loadMenopause();
  if (view === 'pregnancy')     loadPregnancy();
  if (view === 'reminders')     loadHealthReminders();
  if (view === 'upcoming')      loadUpcoming();
  if (view === 'meal-plan')     loadMealPlan();
  if (view === 'taper')         loadTaper();
  if (view === 'strength')      loadStrength();
  if (view === 'med-budget')    loadMedBudget();
  if (view === 'dependents')    loadDependents();
  if (view === 'spending')      loadSpendingView();
  if (view === 'todos')         loadTodos();
  if (view === 'export')        initExportView();
  if (view === 'progress')      loadProgress();
  if (view === 'datatrust')     loadDataTrust();
  if (view === 'family')        loadFamily();
  if (view === 'notifications') loadNotifications();
}

// ── Family sharing (Phase 3) ──────────────────────────────────────
function escapeHtml(s) {
  return String(s ?? '').replace(/[&<>"']/g, c =>
    ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

const FAMILY_CATEGORIES = [
  ['share_sleep',     '🌙', 'Sleep'],
  ['share_vitals',    '❤️', 'Vitals'],
  ['share_medicines', '💊', 'Medicines'],
  ['share_food',      '🍽️', 'Food'],
  ['share_symptoms',  '🤒', 'Symptoms'],
  ['share_emergency', '🆘', 'Emergency card'],
];

async function loadFamily() {
  const box = document.getElementById('family-content');
  if (!box) return;
  const r = await fetch('/api/family', {credentials: 'same-origin'}).catch(() => null);
  const group = r && r.ok ? (await r.json()).group : null;
  box.innerHTML = group ? renderFamilyGroup(group) : renderFamilyEmpty();
  if (group) loadAlertContacts();
}

// ── Caregiver acting-as (manage a family member on one device) ──────────────
// Whose account am I currently driving. null = my own. Kept so the banner can
// render immediately on any view without another round-trip.
let _actingAs = null;

// Reflect the server's acting-as state in the banner. Called on load and after
// every switch. The grant is enforced server-side; this is presentation only.
async function refreshActingAs() {
  const banner = document.getElementById('managing-banner');
  let state = null;
  try {
    const r = await fetch('/api/family/acting-as', {credentials: 'same-origin'});
    if (r.ok) state = await r.json();
  } catch (e) { /* offline — leave banner as-is */ return; }
  _actingAs = state && state.acting_as ? state.acting_as : null;
  if (!banner) return;
  if (_actingAs) {
    const who = (state.managed || []).find(m => m.user_id === _actingAs);
    const name = who ? who.name : '';
    const txt = document.getElementById('managing-banner-text');
    if (txt) txt.textContent = tformat("Managing %1's medicines & health", name);
    banner.style.display = 'flex';
  } else {
    banner.style.display = 'none';
  }
}

// Start managing a family member. The server re-checks the grant; on success we
// reload so every view now shows that member's data.
async function startActAs(uid, name) {
  const r = await fetch('/api/family/act-as', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin', body: JSON.stringify({user_id: uid}),
  });
  const d = await r.json().catch(() => ({}));
  if (!r.ok) { showToast(d.error || 'Could not switch', 'error'); return; }
  showToast(tformat('Now managing %1', d.name || name || ''));
  await refreshActingAs();
  // Re-render the active view so its data reloads under the new scope.
  const v = _activeViewName();
  if (v) switchView(v);
}

// Return to my own account.
async function stopActAs() {
  await fetch('/api/family/act-as/stop', {method: 'POST', credentials: 'same-origin'}).catch(() => {});
  _actingAs = null;
  const banner = document.getElementById('managing-banner');
  if (banner) banner.style.display = 'none';
  showToast(t('Back to your account'));
  await refreshActingAs();
  const v = _activeViewName();
  if (v) switchView(v);
}

// ── Zero-install caregiver alert contacts (SMS/WhatsApp) ────────────────────
async function loadAlertContacts() {
  const list = document.getElementById('alert-contacts-list');
  if (!list) return;
  const r = await fetch('/api/family/alert-contacts', {credentials: 'same-origin'}).catch(() => null);
  const d = (r && r.ok) ? await r.json() : {contacts: [], sms_live: false, whatsapp_live: false};
  const contacts = d.contacts || [];
  if (!contacts.length) {
    list.innerHTML = `<div style="font-size:12px;color:var(--gray-400)">No alert contacts yet.</div>`;
    return;
  }
  list.innerHTML = contacts.map(c => {
    const live = c.channel === 'whatsapp' ? d.whatsapp_live : d.sms_live;
    const chan = c.channel === 'whatsapp' ? 'WhatsApp' : 'SMS';
    // Be honest: until a provider is wired, say alerts are simulated, don't imply delivery.
    const status = live ? '' :
      ` <span style="font-size:10px;color:var(--amber-600,#b45309)" title="No SMS provider is configured yet, so these are simulated">· not sending yet</span>`;
    return `
      <div style="display:flex;align-items:center;gap:10px;font-size:13px;padding:6px 0;border-bottom:1px solid var(--gray-50)">
        <div style="flex:1;min-width:120px">
          <b>${escapeHtml(c.name)}</b>
          <span style="color:var(--gray-400)">· ${escapeHtml(c.phone)} · ${chan}</span>${status}
        </div>
        <label style="display:flex;align-items:center;gap:5px;font-size:12px;cursor:pointer">
          <input type="checkbox" ${c.alerts_enabled ? 'checked' : ''}
                 data-ev-change="toggleAlertContact('${c.id}', this.checked)"> on
        </label>
        <button class="btn-outline" style="font-size:11px" data-ev-click="testAlertContact('${c.id}')">${t('Test')}</button>
        <button class="btn-outline" style="font-size:11px;color:#DC2626" data-ev-click="deleteAlertContact('${c.id}')">${t('Remove')}</button>
      </div>`;
  }).join('');
}

async function addAlertContact() {
  const name = (document.getElementById('ac-name')?.value || '').trim();
  const phone = (document.getElementById('ac-phone')?.value || '').trim();
  const channel = document.getElementById('ac-channel')?.value || 'sms';
  if (!name || !phone) { showToast('Enter a name and phone number', 'error'); return; }
  const r = await fetch('/api/family/alert-contacts', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin', body: JSON.stringify({name, phone, channel}),
  });
  const d = await r.json().catch(() => ({}));
  if (!r.ok) { showToast(d.error || 'Could not add contact', 'error'); return; }
  showToast('Added ' + name);
  loadAlertContacts();
}

async function toggleAlertContact(id, on) {
  await fetch('/api/family/alert-contacts/' + id, {
    method: 'PATCH', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin', body: JSON.stringify({alerts_enabled: on}),
  }).catch(() => {});
}

async function deleteAlertContact(id) {
  await fetch('/api/family/alert-contacts/' + id, {method: 'DELETE', credentials: 'same-origin'}).catch(() => {});
  loadAlertContacts();
}

async function testAlertContact(id) {
  const r = await fetch('/api/family/alert-contacts/' + id + '/test', {
    method: 'POST', credentials: 'same-origin'});
  const d = await r.json().catch(() => ({}));
  if (d.delivered) showToast('✓ Test message sent');
  else if (d.dev_mode) showToast('Simulated — no SMS provider is set up yet', 'info');
  else showToast('Could not send test', 'error');
}

// The privacy explainer. Written to reassure someone deciding whether to let
// their family see any of this — and it used to render only *inside* an
// existing group, so the one person who most needed it could never reach it.
// It belongs wherever that decision is being made.
function familyExplainer() {
  return `
      <details class="family-explainer">
        <summary>${t('How sharing works')}</summary>
        <ul>
          <li><b>${t('Nothing is shared by default.')}</b> ${t('Each category is off until you turn it on — and you can switch any of them off again anytime.')}</li>
          <li><b>${t('You choose per category.')}</b> ${t("Sharing medicines doesn't share your journal; sharing sleep doesn't share your vitals.")}</li>
          <li><b>${t('Missed-dose alerts are opt-in.')}</b> ${t('Your family is only told about a missed dose if you turn that on — and you always get a heads-up first.')}</li>
          <li><b>${t('Primary vs. viewer.')}</b> ${t('Anyone can see what\'s shared; only those who opt in to "Notify me…" get pinged about missed doses.')}</li>
        </ul>
      </details>`;
}

function renderFamilyEmpty() {
  return `
    <div class="panel" style="padding:32px;text-align:center;max-width:480px">
      <div style="font-size:34px;margin-bottom:10px">👨‍👩‍👧</div>
      <h2 style="font-size:17px;font-weight:700;margin-bottom:6px">${t('Create your family group')}</h2>
      <p style="font-size:13px;color:var(--gray-400);margin-bottom:18px;line-height:1.6">
${t('Invite family members by email. Everyone chooses exactly which categories they share — nothing is visible unless they turn it on.')}</p>
      <div style="display:flex;gap:8px;justify-content:center">
        <input type="text" class="form-input" id="family-group-name" placeholder="${t('Group name (e.g. The Guptas)')}"
               style="max-width:220px">
        <button class="btn-primary" data-ev-click="createFamilyGroup()">${t('Create group')}</button>
      </div>
      <div style="margin-top:18px;text-align:left">${familyExplainer()}</div>
    </div>`;
}

function renderFamilyGroup(g) {
  const isOwner = g.my_role === 'owner';

  const memberCards = g.members.map(m => {
    const shared = FAMILY_CATEGORIES.filter(([f]) => m.shares[f]);
    let badges = shared.length
      ? shared.map(([, icon, label]) =>
          `<span style="font-size:11px;background:var(--gray-50);border-radius:6px;padding:2px 8px">${icon} ${t(label)}</span>`).join(' ')
      : `<span style="font-size:11px;color:var(--gray-400)">${t('Shares nothing yet')}</span>`;
    const isMe = _currentUser && m.user_id === _currentUser.id;
    if (m.alerts_on)
      badges += ` <span style="font-size:11px;background:var(--amber-50);border-radius:6px;padding:2px 8px">${t('🚨 dose alerts')}</span>`;
    const actions = [];
    if (!isMe && shared.length)
      actions.push(`<button class="btn-outline" style="font-size:12px" data-ev-click="toggleFamilySummary('${m.user_id}')">${t('View shared data')}</button>`);
    // Simple View control — only when this member opted in (allows_display).
    if (!isMe && m.allows_display) {
      const on = m.ui_mode === 'simple';
      actions.push(`<button class="btn-outline" style="font-size:12px" data-ev-click="setMemberDisplay('${m.user_id}','${on ? 'standard' : 'simple'}')">${on ? t('🔎 Simple View: on') : t('🔍 Turn on Simple View')}</button>`);
    }
    // Manage-on-this-device — only when this member opted in (allows_manage).
    if (!isMe && m.allows_manage) {
      const nm = (m.name || m.email || '').replace(/'/g, "\\'");
      actions.push(`<button class="btn-outline" style="font-size:12px;border-color:#3E7862;color:#3E7862" data-ev-click="startActAs('${m.user_id}','${nm}')">${t('👥 Manage on this device')}</button>`);
    }
    if (isOwner && !isMe)
      actions.push(`<button class="btn-outline" style="font-size:12px;color:#DC2626" data-ev-click="removeFamilyMember('${m.user_id}')">${t('Remove')}</button>`);
    return `
      <div class="panel" style="padding:16px 18px;margin-bottom:10px">
        <div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap">
          <div style="flex:1;min-width:180px">
            <div style="font-size:14px;font-weight:600">${escapeHtml(m.name || m.email)}
              ${m.role === 'owner' ? `<span style="font-size:10px;color:var(--gray-400);margin-left:6px">${t('OWNER')}</span>` : ''}
              ${isMe ? `<span style="font-size:10px;color:#3E7862;margin-left:6px">${t('YOU')}</span>` : ''}
            </div>
            <div style="font-size:12px;color:var(--gray-400)">${escapeHtml(m.email)}</div>
          </div>
          <div style="display:flex;gap:6px;flex-wrap:wrap">${badges}</div>
          ${actions.join(' ')}
        </div>
        <div id="family-summary-${m.user_id}" style="display:none;margin-top:14px"></div>
      </div>`;
  }).join('');

  const consentToggles = FAMILY_CATEGORIES.map(([f, icon, label]) => `
    <label style="display:flex;align-items:center;gap:8px;font-size:13px;cursor:pointer">
      <input type="checkbox" ${g.my_consent[f] ? 'checked' : ''}
             data-ev-change="saveFamilyConsent('${f}', this.checked)">
      ${icon} ${t(label)}
    </label>`).join('');

  // Caregiver alerts — only offered while medicines are shared
  const alertToggle = g.my_consent.share_medicines ? `
    <label style="display:flex;align-items:center;gap:8px;font-size:13px;cursor:pointer;
                  margin-top:12px;padding:10px 12px;border:1px solid var(--amber-100);
                  border-radius:10px;background:var(--amber-50)">
      <input type="checkbox" ${g.my_alerts ? 'checked' : ''}
             data-ev-change="saveFamilyConsent('alert_missed_doses', this.checked)">
      ${t('🚨 Alert my family if I miss a dose by 2+ hours')}
    </label>` : '';

  // Caregiver role: primary (gets alerts) vs viewer (sees status, no pings)
  const receiveAlertsToggle = `
    <label style="display:flex;align-items:center;gap:8px;font-size:13px;cursor:pointer;
                  margin-top:10px;padding:10px 12px;border:1px solid var(--gray-100);border-radius:10px">
      <input type="checkbox" ${g.my_receive_alerts ? 'checked' : ''}
             data-ev-change="saveFamilyConsent('receive_care_alerts', this.checked)">
      ${t('🔔 Notify me when a family member misses a dose')}
    </label>`;

  // Opt-in so a family member can switch Simple View on your account for you
  // (e.g. an adult child setting up a parent's phone). You're always notified.
  const allowDisplayToggle = `
    <label style="display:flex;align-items:center;gap:8px;font-size:13px;cursor:pointer;
                  margin-top:10px;padding:10px 12px;border:1px solid var(--gray-100);border-radius:10px">
      <input type="checkbox" ${g.my_allow_display ? 'checked' : ''}
             data-ev-change="saveFamilyConsent('allow_family_display', this.checked)">
      ${t('👁️ Let my family turn Simple View on or off for me')}
    </label>`;

  // Opt-in so a family member can manage my medicines & health on their own
  // device (for someone who can't run the app themselves). They can view and
  // edit my health data while managing — but never my account, password, or
  // family settings. I can switch this off anytime.
  const allowManageToggle = `
    <label style="display:flex;align-items:flex-start;gap:8px;font-size:13px;cursor:pointer;
                  margin-top:10px;padding:10px 12px;border:1px solid var(--gray-100);border-radius:10px">
      <input type="checkbox" ${g.my_allow_manage ? 'checked' : ''} style="margin-top:2px"
             data-ev-change="saveFamilyConsent('allow_manage', this.checked)">
      <span>${t('👥 Let a family member manage my medicines & health on their device')}
        <span style="display:block;font-size:11px;color:var(--gray-400);margin-top:2px">${t('They can view and update my health data — never my account, password, or family settings.')}</span>
      </span>
    </label>`;

  const inviteSection = isOwner ? `
    <div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Invite someone')}</h2>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <input type="email" class="form-input" id="family-invite-email"
               placeholder="their-email@example.com" style="max-width:260px">
        <button class="btn-primary" data-ev-click="sendFamilyInvite()">${t('Send invite')}</button>
      </div>
      ${(g.pending_invites || []).length ? `
        <div style="margin-top:14px">
          <div style="font-size:12px;color:var(--gray-400);margin-bottom:6px">${t('Pending invites')}</div>
          ${g.pending_invites.map(i => `
            <div style="display:flex;align-items:center;gap:10px;font-size:13px;padding:4px 0">
              <span style="flex:1">${escapeHtml(i.email)}</span>
              <button class="btn-outline" style="font-size:11px" data-ev-click="revokeFamilyInvite('${i.id}')">${t('Revoke')}</button>
            </div>`).join('')}
        </div>` : ''}
    </div>` : '';

  // Zero-install alert contacts — a phone that gets pinged if I miss a dose,
  // no app needed on their end. Filled in by loadAlertContacts().
  const alertContactsSection = `
    <div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:4px">${t('📱 Text a loved one if I miss a dose')}</h2>
      <p style="font-size:12px;color:var(--gray-400);margin-bottom:12px">
${t("Add a phone number and they'll get an SMS or WhatsApp if one of my doses is 2+ hours overdue — no app or account needed on their end. This works once")} <b>${t('🚨 Alert my family if I miss a dose')}</b> ${t('is on above. I can remove anyone anytime.')}</p>
      <div id="alert-contacts-list" style="margin-bottom:12px"></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
        <input type="text" class="form-input" id="ac-name" placeholder="${t('Name (e.g. Mom)')}"
               aria-label="Contact name" style="max-width:150px">
        <input type="tel" class="form-input" id="ac-phone" placeholder="+9198XXXXXXXX"
               aria-label="Phone with country code" style="max-width:175px">
        <select class="form-input" id="ac-channel" aria-label="Channel" style="max-width:130px">
          <option value="sms">SMS</option>
          <option value="whatsapp">WhatsApp</option>
        </select>
        <button class="btn-primary" data-ev-click="addAlertContact()">${t('Add')}</button>
      </div>
    </div>`;

  const dangerBtn = isOwner
    ? `<button class="btn-outline" style="color:#DC2626" data-ev-click="deleteFamilyGroup()">${t('Delete group')}</button>`
    : `<button class="btn-outline" style="color:#DC2626" data-ev-click="leaveFamilyGroup()">${t('Leave group')}</button>`;

  return `
    <div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:4px">
        <h2 class="panel-title" style="flex:1">${escapeHtml(g.name)}</h2>
        ${dangerBtn}
      </div>
      <p style="font-size:12px;color:var(--gray-400)">${t('You share only what you switch on below. Changes apply immediately.')}</p>
      ${familyExplainer()}
      <div style="display:flex;gap:18px;flex-wrap:wrap;margin-top:12px">${consentToggles}</div>
      ${alertToggle}
      ${receiveAlertsToggle}
      ${allowDisplayToggle}
      ${allowManageToggle}
    </div>
    ${inviteSection}
    ${alertContactsSection}
    <div>${memberCards}</div>`;
}

async function createFamilyGroup() {
  const name = document.getElementById('family-group-name')?.value || '';
  const r = await fetch('/api/family', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin', body: JSON.stringify({name}),
  });
  const d = await r.json().catch(() => ({}));
  if (!r.ok) { showToast(d.error || 'Could not create group', 'error'); return; }
  loadFamily();
}

async function saveFamilyConsent(field, on) {
  await fetch('/api/family/consent', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin', body: JSON.stringify({[field]: on}),
  }).catch(() => {});
  loadFamily();
}

// Caregiver flips a consenting member's Simple View. Server enforces the
// consent gate; the member is notified. `mode` is 'simple' or 'standard'.
async function setMemberDisplay(uid, mode) {
  let d = {};
  try {
    const r = await fetch(`/api/family/member/${uid}/display`, {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      credentials: 'same-origin', body: JSON.stringify({ui_mode: mode}),
    });
    d = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(d.error || 'Could not change their display');
    showToast(mode === 'simple' ? 'Simple View turned on for them' : 'Switched them to Standard View');
  } catch (e) {
    showToast(e.message || 'Could not change their display', 'error');
  }
  loadFamily();
}

async function sendFamilyInvite() {
  const email = (document.getElementById('family-invite-email')?.value || '').trim();
  if (!email) { showToast('Enter an email address', 'error'); return; }
  const r = await fetch('/api/family/invite', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin', body: JSON.stringify({email}),
  });
  const d = await r.json().catch(() => ({}));
  if (!r.ok) { showToast(d.error || 'Could not send invite', 'error'); return; }
  showToast('Invite sent to ' + email);
  loadFamily();
}

async function revokeFamilyInvite(id) {
  await fetch('/api/family/invite/' + id, {method: 'DELETE', credentials: 'same-origin'}).catch(() => {});
  loadFamily();
}

function removeFamilyMember(uid) {
  undoable('Removing member…', async () => {
    const r = await fetch('/api/family/member/' + uid, {method: 'DELETE', credentials: 'same-origin'});
    const d = await r.json().catch(() => ({}));
    if (!r.ok) { showToast(d.error || 'Could not remove member', 'error'); return; }
    loadFamily();
  });
}

function leaveFamilyGroup() {
  undoable('Leaving family group…', async () => {
    const r = await fetch('/api/family/leave', {method: 'POST', credentials: 'same-origin'});
    const d = await r.json().catch(() => ({}));
    if (!r.ok) { showToast(d.error || 'Could not leave group', 'error'); return; }
    loadFamily();
  });
}

function deleteFamilyGroup() {
  undoable('Deleting family group…', async () => {
    const r = await fetch('/api/family', {method: 'DELETE', credentials: 'same-origin'});
    const d = await r.json().catch(() => ({}));
    if (!r.ok) { showToast(d.error || 'Could not delete group', 'error'); return; }
    loadFamily();
  });
}

async function toggleFamilySummary(uid) {
  const el = document.getElementById('family-summary-' + uid);
  if (!el) return;
  if (el.style.display !== 'none') { el.style.display = 'none'; return; }
  el.style.display = '';
  el.innerHTML = '<div style="font-size:12px;color:var(--gray-400)">Loading…</div>';
  const r = await fetch(`/api/family/member/${uid}/summary`, {credentials: 'same-origin'});
  const s = await r.json().catch(() => null);
  if (!r.ok || !s) {
    el.innerHTML = '<div style="font-size:12px;color:#DC2626">Could not load shared data</div>';
    return;
  }
  el.innerHTML = renderFamilySummary(s);
}

function renderFamilySummary(s) {
  const rows = [];
  if (s.sleep)
    rows.push(`🌙 <b>Sleep:</b> ${s.sleep.nights} night(s) logged this week` +
              (s.sleep.avg_hours != null ? `, avg ${s.sleep.avg_hours}h` : ''));
  if (s.vitals && Object.keys(s.vitals).length) {
    const parts = Object.entries(s.vitals).map(([t, v]) =>
      `${t.replace('_', ' ')}: ${v.value1}${v.value2 ? '/' + v.value2 : ''} ${v.unit || ''}`);
    rows.push(`❤️ <b>Vitals:</b> ${parts.join(' · ')}`);
  } else if (s.vitals) {
    rows.push('❤️ <b>Vitals:</b> nothing logged yet');
  }
  if (s.medicines)
    rows.push(`💊 <b>Medicines:</b> ${s.medicines.active.length} active — ` +
              `${s.medicines.today.taken}/${s.medicines.today.total} doses taken today`);
  if (s.food)
    rows.push(`🍽️ <b>Food:</b> ${s.food.today_calories} kcal across ${s.food.today_logs} log(s) today`);
  if (s.symptoms)
    rows.push(`🤒 <b>Symptoms (7d):</b> ` + (s.symptoms.length
      ? s.symptoms.slice(0, 5).map(x => `${escapeHtml(x.name)} (${x.severity}/10)`).join(', ')
      : 'none reported'));
  if (!rows.length && !s.emergency)
    rows.push('This member is not sharing any categories with the group.');

  // Emergency card — surfaced prominently for crisis fast-access
  let emergencyBlock = '';
  if (s.emergency) {
    const e = s.emergency;
    const line = (label, val) => val ? `<div><span style="color:var(--gray-400)">${label}:</span> ${escapeHtml(val)}</div>` : '';
    const contact = (n, p) => (n || p) ? `<div><span style="color:var(--gray-400)">Contact:</span> ${escapeHtml(n || '')}${p ? ` · <a href="tel:${escapeHtml(p)}" style="color:var(--red-500);font-weight:600">${escapeHtml(p)}</a>` : ''}</div>` : '';
    const inner = [
      line('Blood type', e.blood_type), line('Allergies', e.allergies),
      line('Conditions', e.conditions), line('Medications', e.medications),
      contact(e.contact1_name, e.contact1_phone), contact(e.contact2_name, e.contact2_phone),
    ].filter(Boolean).join('');
    emergencyBlock = `<div class="emergency-card-share">
        <div class="emergency-card-share-title">🆘 Emergency card</div>
        ${inner || '<div style="color:var(--gray-400)">No details filled in yet.</div>'}
      </div>`;
  }

  return `<div style="border-top:1px solid var(--gray-100);padding-top:12px;
               display:flex;flex-direction:column;gap:8px;font-size:13px">
            ${rows.map(x => `<div>${x}</div>`).join('')}
            ${emergencyBlock}
          </div>`;
}

// ── First-run "get started" checklist ─────────────────────────────
// Medication leads — it's Arogo's core loop, so onboarding starts there.
const FIRSTRUN_STEPS = [
  {key: 'medicines',      icon: '💊', label: 'Add your first medication', ev: 'openMedModal()', primary: true},
  {key: 'family',         icon: '👪', label: 'Connect a family member', ev: "switchView('family')"},
  {key: 'food_logs',      icon: '🍽️', label: 'Log your first meal',  ev: "quickAdd('food')"},
  {key: 'hydration_logs', icon: '💧', label: 'Log a glass of water', ev: 'quickWater(250)'},
  {key: 'habits',         icon: '⭐', label: 'Create a habit',       ev: "switchView('habits')"},
];

async function checkFirstRun() {
  const el = document.getElementById('firstrun-card');
  if (!el || !_currentUser) return;
  const dismissKey = 'me_firstrun_' + _currentUser.id;
  if (localStorage.getItem(dismissKey)) { el.style.display = 'none'; return; }

  const counts = await fetch('/api/export/counts', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!counts) return;

  const remaining = FIRSTRUN_STEPS.filter(s => !(counts[s.key] > 0)).length;
  if (remaining === 0) {
    // Everything done — celebrate once, then never show again
    localStorage.setItem(dismissKey, '1');
    el.style.display = 'none';
    showToast('🎉 You’re all set up!');
    return;
  }

  el.style.display = '';
  el.innerHTML = `
    <div class="panel" style="padding:18px 20px;border-color:var(--teal-200);background:var(--teal-50)">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:12px">
        <div style="font-size:15px;font-weight:700;color:var(--gray-900);flex:1">
          👋 Welcome to Arogo — ${FIRSTRUN_STEPS.length - remaining}/${FIRSTRUN_STEPS.length} done
        </div>
        <a href="#" style="font-size:12px;color:var(--gray-400);text-decoration:none"
           data-ev-click="dismissFirstRun()">Dismiss</a>
      </div>
      <div style="display:flex;flex-direction:column;gap:8px">
        ${FIRSTRUN_STEPS.map(s => {
          const done = counts[s.key] > 0;
          return done
            ? `<div style="display:flex;align-items:center;gap:10px;font-size:13px;color:var(--gray-400)">
                 <span style="width:20px;height:20px;border-radius:50%;background:var(--teal-600);color:#fff;
                              display:inline-flex;align-items:center;justify-content:center;font-size:11px">✓</span>
                 <span style="text-decoration:line-through">${s.icon} ${s.label}</span>
               </div>`
            : `<button style="display:flex;align-items:center;gap:10px;font-size:13px;
                              color:${s.primary ? '#fff' : 'var(--gray-700)'};font-weight:${s.primary ? '600' : '400'};
                              background:${s.primary ? 'var(--teal-600)' : 'var(--gray-0)'};
                              border:1px solid ${s.primary ? 'var(--teal-600)' : 'var(--gray-100)'};border-radius:10px;
                              padding:10px 12px;cursor:pointer;text-align:left;font-family:inherit;min-height:42px"
                       data-ev-click="${s.ev}">
                 <span style="width:20px;height:20px;border-radius:50%;border:2px solid ${s.primary ? 'rgba(255,255,255,.6)' : 'var(--gray-200)'};flex-shrink:0"></span>
                 ${s.icon} ${s.label}
                 <span style="margin-left:auto;color:${s.primary ? '#fff' : 'var(--teal-600)'};font-weight:600">→</span>
               </button>`;
        }).join('')}
      </div>
    </div>`;
}

function dismissFirstRun() {
  if (_currentUser) localStorage.setItem('me_firstrun_' + _currentUser.id, '1');
  const el = document.getElementById('firstrun-card');
  if (el) el.style.display = 'none';
}

// ── Insight cards ─────────────────────────────────────────────────
async function loadInsightCards() {
  const box = document.getElementById('insight-cards');
  if (!box) return;
  const d = await fetch('/api/insights/cards', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  const cards = d?.cards || [];
  if (!cards.length) { box.style.display = 'none'; return; }
  const tones = {
    success: 'background:var(--green-50);border-color:#D1FAE5',
    warning: 'background:var(--amber-50);border-color:var(--amber-100)',
    info:    'background:var(--blue-50);border-color:#DBEAFE',
  };
  box.style.display = '';
  box.innerHTML = `<div style="display:flex;gap:12px;flex-wrap:wrap">` +
    cards.map(c => `
      <div style="flex:1;min-width:220px;display:flex;gap:10px;align-items:flex-start;
                  border:1px solid transparent;border-radius:12px;padding:12px 14px;
                  ${tones[c.tone] || tones.info}">
        <span style="font-size:20px">${c.icon}</span>
        <span style="font-size:13px;color:var(--gray-700);line-height:1.5">${escapeHtml(c.text)}</span>
      </div>`).join('') + '</div>';
}

// I10: "this week vs last" — a small, honest delta card. Only shows metrics the
// user logged in BOTH weeks; up/down is coloured only where a direction has a
// clear meaning (adherence, sleep), neutral for weight and BP.
async function loadWeekOverWeek() {
  const box = document.getElementById('week-over-week');
  if (!box) return;
  const d = await fetch('/api/week-over-week', {credentials:'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { box.innerHTML = ''; return; }
  const fmt = (v, unit) => unit === '%' ? `${v}%` : `${v}${unit ? ' ' + unit : ''}`;
  const cells = d.metrics.map(m => {
    const arrow = m.dir === 'flat' ? '→' : m.dir === 'up' ? '▲' : '▼';
    let cls = 'wow-flat';
    if (m.dir !== 'flat' && m.higher_better !== null) {
      const good = (m.dir === 'up') === m.higher_better;
      cls = good ? 'wow-good' : 'wow-bad';
    } else if (m.dir !== 'flat') {
      cls = 'wow-neutral';
    }
    const deltaTxt = m.delta > 0 ? `+${m.delta}` : `${m.delta}`;
    return `<div class="wow-cell">
        <div class="wow-label">${t(m.label)}</div>
        <div class="wow-this">${fmt(m.this, m.unit)}</div>
        <div class="wow-delta ${cls}">${arrow} ${deltaTxt}${m.unit === '%' ? '' : ''}
          <span class="wow-prev">${tformat('was %1', fmt(m.last, m.unit))}</span></div>
      </div>`;
  }).join('');
  box.innerHTML = `<div class="panel wow-panel">
      <div class="panel-header"><h2 class="panel-title">📊 ${t('This week vs last')}</h2>
        <span class="panel-badge">${t('7 days')}</span></div>
      <div class="wow-grid">${cells}</div>
    </div>`;
}

// Consolidation: collapsible "insights" groups. State is remembered per group so
// a user who opens the deep analytics keeps them open. Collapsed by default keeps
// the core view (schedule, cards, log form) uncluttered.
function toggleInsightsGroup(key) {
  const wrap = document.getElementById(key + '-collapse');
  if (!wrap) return;
  const open = wrap.classList.toggle('open');
  const btn = wrap.querySelector('.insights-head');
  if (btn) btn.setAttribute('aria-expanded', open ? 'true' : 'false');
  try { localStorage.setItem('me_collapse_' + key, open ? '1' : '0'); } catch (e) {}
}
function _applyCollapseState(key) {
  const wrap = document.getElementById(key + '-collapse');
  if (!wrap) return;
  let open = false;
  try { open = localStorage.getItem('me_collapse_' + key) === '1'; } catch (e) {}
  wrap.classList.toggle('open', open);
  const btn = wrap.querySelector('.insights-head');
  if (btn) btn.setAttribute('aria-expanded', open ? 'true' : 'false');
}

// Sidebar nav grouping — collapsible sections so a 30-item sidebar scans easily.
function toggleNavGroup(key) {
  const g = document.querySelector('.nav-group[data-group="' + key + '"]');
  if (!g) return;
  const collapsed = g.classList.toggle('collapsed');
  try { localStorage.setItem('me_nav_' + key, collapsed ? '1' : '0'); } catch (e) {}
}
function _applyNavGroups() {
  document.querySelectorAll('.nav-group').forEach(g => {
    let collapsed = false;
    try { collapsed = localStorage.getItem('me_nav_' + g.dataset.group) === '1'; } catch (e) {}
    g.classList.toggle('collapsed', collapsed);
  });
  // The group holding the current view is always expanded so the active item shows.
  const active = document.querySelector('.nav-item.active');
  const g = active && active.closest('.nav-group');
  if (g) g.classList.remove('collapsed');
}

// Auto-hide an insights group's header until at least one of its panels has
// content — so a brand-new user with no data doesn't see an empty section.
// Panels fill asynchronously, so a MutationObserver keeps the header in sync.
function _refreshInsightGroup(wrap) {
  const body = wrap.querySelector('.insights-body');
  if (!body) return;
  const hasContent = [...body.children].some(c => c.innerHTML.trim() !== '');
  wrap.classList.toggle('empty-hidden', !hasContent);
}
function _watchInsightGroups() {
  document.querySelectorAll('.insights-collapse').forEach(wrap => {
    _refreshInsightGroup(wrap);
    if (wrap._insightObs) return;   // observer already attached
    const body = wrap.querySelector('.insights-body');
    if (!body) return;
    const obs = new MutationObserver(() => _refreshInsightGroup(wrap));
    obs.observe(body, { childList: true, subtree: true, characterData: true });
    wrap._insightObs = obs;
  });
}

// ── Dashboard ──
async function loadDashboard() {
  try { checkFirstRun(); }      catch (e) {}
  try { renderDashShortcuts(); } catch (e) {}
  try { loadInsightCards(); }   catch (e) {}
  try { loadWeekOverWeek(); }   catch (e) {}
  try { loadWellnessStrip(); }  catch (e) {}
  try { loadCarePanel(); }      catch (e) {}
  try { loadEncouragements(); } catch (e) {}
  try { loadLowStock(); }       catch (e) {}
  try { loadNextAppointment(); } catch (e) {}
  try { loadAtRiskDose(); }     catch (e) {}
  try { loadTodayGlance(); }    catch (e) {}
  try { loadProfileCompleteness(); } catch (e) {}
  try { loadConditionCheckin(); } catch (e) {}
  initDailyCheckin();

  const [doses, fitnessStats] = await Promise.all([
    fetch('/api/medicines/today').then(r => r.json()).catch(() => []),
    fetch('/api/fitness/stats').then(r => r.json()).catch(() => ({})),
  ]);

  // Active minutes (this week)
  setText('dash-active-min', fitnessStats.week?.duration || 0);

  // Calorie balance — calm inline stat (no coloured card)
  fetch('/api/calorie-balance').then(r => r.json()).then(cb => {
    const t = cb.today || {};
    // No target → no budget, so there is no "remaining". Show what they
    // actually ate, which needs no target to be true. `net ?? 0` used to turn
    // a missing budget into "2000 kcal remaining" — the most confident thing
    // on a new user's first screen, about a number nobody had computed.
    if (!cb.has_target) {
      setText('dash-cal-deficit', t.eaten || 0);
      setText('dash-cal-deficit-sub',
        t.eaten ? 'calories eaten' : 'no meals logged yet');
    } else {
      const net = t.net ?? 0;
      setText('dash-cal-deficit', Math.abs(net));
      setText('dash-cal-deficit-sub',
        t.burned > 0 ? `${t.burned} kcal burned` :
        net > 100 ? 'kcal remaining' : net < -100 ? 'kcal over budget' : 'calories today');
    }
    renderNextAction(doses, cb);   // refine the hero once calorie state is known
  }).catch(() => {});

  // ── Today's medicines — panel only appears if there are doses ──
  const remaining = doses.filter(d => !d.taken).length;
  const hasMeds   = doses.length > 0;

  // Medication adherence tile — the core loop, front and centre in the focal panel
  const takenToday = doses.filter(d => d.taken).length;
  const totalToday = doses.length;
  setText('dws-meds', totalToday ? `${takenToday} / ${totalToday}` : '—');
  const medsBar = document.getElementById('dws-meds-bar');
  if (medsBar) medsBar.style.width = totalToday ? Math.round(takenToday / totalToday * 100) + '%' : '0%';
  setText('dws-meds-sub', !totalToday ? t('no meds today')
    : takenToday === totalToday ? t('all doses taken ✓') : t('doses today'));

  // Single "what do I do right now" hero — meds first, then a gentle fallback
  renderNextAction(doses, null);
  try { renderBriefing(doses); } catch (e) {}
  const medPanel  = document.getElementById('dash-medicines-panel');
  const medList   = document.getElementById('dash-medicine-list');
  if (medPanel) medPanel.style.display = hasMeds ? '' : 'none';
  if (hasMeds && medList) {
    medList.innerHTML = doses.slice(0, 5).map(d => `
      <div class="dash-dose-item ${d.taken ? 'taken' : ''}" data-ev-click="markDoseTaken('${d.med_id}','${d.time}',this)">
        <div class="dash-dose-icon">${d.icon}</div>
        <div class="dash-dose-info">
          <div class="dash-dose-name">${escHtml(d.med_name)}</div>
          <div class="dash-dose-detail">${d.dosage} ${d.unit}${medTimingText(d) ? ' · ' + escHtml(medTimingText(d)) : ''}</div>
        </div>
        <div class="dash-dose-time">${d.time}</div>
        <div class="dash-dose-check ${d.taken ? 'done' : ''}">${d.taken ? '✓' : ''}</div>
      </div>`).join('');
  }

  // ── Pending tasks — panel only appears if there are any ──
  const pendingCount = await loadDashboardTodos();
  const taskPanel = document.getElementById('dash-tasks-panel');
  if (taskPanel) taskPanel.style.display = pendingCount > 0 ? '' : 'none';

  // Show the agenda grid only if at least one panel is visible
  const agenda = document.getElementById('dash-agenda-grid');
  if (agenda) agenda.style.display = (hasMeds || pendingCount > 0) ? '' : 'none';

  // ── Weekly activity — only when there is activity this week ──
  const weeklyDays = fitnessStats.weekly_days || {};
  const hasActivity = Object.values(weeklyDays).some(d => (d.duration || 0) > 0 || (d.calories || 0) > 0);
  const weeklyPanel = document.getElementById('dash-weekly-panel');
  if (weeklyPanel) weeklyPanel.style.display = hasActivity ? '' : 'none';
  if (hasActivity) renderWeeklyChart(weeklyDays);

  // Nav dose badge
  const badge = document.getElementById('nav-dose-badge');
  if (badge) {
    if (remaining > 0) { badge.textContent = remaining; badge.style.display = 'inline-block'; }
    else badge.style.display = 'none';
  }

  // Consistency streak badge
  fetch('/api/fitness/consistency').then(r => r.json()).then(con => {
    const sb = document.getElementById('dash-streak-badge');
    if (sb) {
      const streak = con.current_streak || 0;
      if (streak > 0) { sb.textContent = `🔥${streak}`; sb.style.display = 'inline-block'; }
      else sb.style.display = 'none';
    }
  }).catch(() => {});
}

// The dashboard hero: surface the single most important next action.
// Priority — an untaken dose (the app's core adherence loop) > "all caught up"
// affirmation > a gentle "log your first meal" nudge on an otherwise-empty day.
// A one-line, plain-language overview of the day's counts — a "briefing" that
// complements (doesn't repeat) the single-action hero below it. Shows only what
// there is to say, and nothing when there's nothing to do.
async function renderBriefing(doses) {
  const el = document.getElementById('dash-briefing');
  if (!el) return;
  const parts = [];
  const list = Array.isArray(doses) ? doses : [];
  const untaken = list.filter(d => !d.taken);
  if (list.length) {
    if (!untaken.length) {
      parts.push('💊 all doses taken');
    } else {
      const now = new Date();
      const hhmm = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
      const times = untaken.map(d => d.time).filter(Boolean).sort();
      const next = times.find(t => t >= hhmm) || times[0];
      parts.push(`💊 ${untaken.length} dose${untaken.length > 1 ? 's' : ''} left today${next ? ` · next ${_mc12h(next)}` : ''}`);
    }
  }
  const low = await fetch('/api/medicines/low-stock').then(r => r.json()).catch(() => []);
  if (Array.isArray(low) && low.length) {
    parts.push(`🔄 ${low.length} to refill`);
  }
  if (!parts.length) { el.style.display = 'none'; return; }
  const readBtn = _canSpeak()
    ? `<button class="briefing-read" data-ev-click="readDailyBriefing()" title="Read my day aloud"><span id="read-aloud-icon">🔊</span> <span id="read-aloud-label">Read aloud</span></button>`
    : '';
  el.innerHTML = `<span class="briefing-text">${parts.map(escHtml).join('   ·   ')}</span>${readBtn}`;
  el.style.display = 'flex';
}

// ── Read-aloud (Web Speech API) — spoken day summary for the senior audience ──
function _canSpeak() { return typeof window !== 'undefined' && 'speechSynthesis' in window; }
let _speaking = false;

function _updateReadBtn() {
  const icon = document.getElementById('read-aloud-icon');
  const label = document.getElementById('read-aloud-label');
  if (icon)  icon.textContent  = _speaking ? '⏹' : '🔊';
  if (label) label.textContent = _speaking ? 'Stop' : 'Read aloud';
}

function stopSpeaking() {
  if (_canSpeak()) speechSynthesis.cancel();
  _speaking = false;
  _updateReadBtn();
}

function speakText(text) {
  if (!_canSpeak() || !text) return;
  speechSynthesis.cancel();                    // never stack utterances
  const u = new SpeechSynthesisUtterance(text);
  u.rate = 0.95; u.pitch = 1; u.lang = 'en-US';   // a touch slow, easier to follow
  u.onend = u.onerror = () => { _speaking = false; _updateReadBtn(); };
  _speaking = true; _updateReadBtn();
  speechSynthesis.speak(u);
}

// Compose a natural spoken sentence — kept pure so it's easy to reason about.
function composeSpokenBriefing(doses, low, hour) {
  const parts = [];
  parts.push(hour < 12 ? 'Good morning.' : hour < 18 ? 'Good afternoon.' : 'Good evening.');
  const list = Array.isArray(doses) ? doses : [];
  const untaken = list.filter(d => !d.taken);
  if (!list.length) {
    parts.push('You have no medicines scheduled today.');
  } else if (!untaken.length) {
    parts.push('You have taken all your doses today. Well done.');
  } else {
    parts.push(`You have ${untaken.length} dose${untaken.length > 1 ? 's' : ''} left today.`);
    const hhmm = `${String(hour).padStart(2, '0')}:00`;
    const sorted = untaken.filter(d => d.time).sort((a, b) => a.time.localeCompare(b.time));
    const next = sorted.find(d => d.time >= hhmm) || sorted[0];
    if (next) parts.push(`Your next is ${next.med_name} at ${_mc12h(next.time)}${next.timing_text ? ', ' + next.timing_text : ''}.`);
  }
  if (Array.isArray(low) && low.length) {
    parts.push(`${low.length} medicine${low.length > 1 ? 's are' : ' is'} running low.`);
  }
  return parts.join(' ');
}

async function readDailyBriefing() {
  if (!_canSpeak()) { showToast("Read-aloud isn't supported on this device", 'error'); return; }
  if (_speaking) { stopSpeaking(); return; }                 // tapping again stops
  const [doses, low] = await Promise.all([
    fetch('/api/medicines/today').then(r => r.json()).catch(() => []),
    fetch('/api/medicines/low-stock').then(r => r.json()).catch(() => []),
  ]);
  speakText(composeSpokenBriefing(doses, low, new Date().getHours()));
}

// Condition-tailored daily check-in — a focused capture for the user's chosen
// condition (diabetes → fasting/post-meal sugar; hypertension → today's BP).
async function loadConditionCheckin() {
  const el = document.getElementById('dash-condition-checkin');
  if (!el) return;
  const d = await fetch('/api/condition-checkin').then(r => r.json()).catch(() => null);
  if (!d) { el.style.display = 'none'; return; }
  if (!d.focus) {
    // Offer to set one up — unless the user waved it off this session.
    try { if (sessionStorage.getItem('cchk_dismissed')) { el.style.display = 'none'; return; } } catch (e) {}
    const opts = (d.options || []).map(o => `<button class="cchk-opt" data-ev-click="setConditionFocus('${o.key}')">${t(o.label)}</button>`).join('');
    if (!opts) { el.style.display = 'none'; return; }
    el.style.display = '';
    el.innerHTML = `<div class="panel cchk-card cchk-setup">
      <span class="cchk-setup-lbl">🩺 ${t('Daily check-in for a condition?')}</span>${opts}
      <button class="cchk-opt cchk-dismiss" data-ev-click="dismissConditionSetup()">${t('Not now')}</button>
    </div>`;
    return;
  }
  if (d.all_done) { el.style.display = 'none'; return; }   // nothing left to capture today
  el.style.display = '';
  const rows = d.prompts.filter(p => !p.done).map(p => {
    if (p.type === 'blood_pressure') {
      return `<div class="cchk-row"><label>${t(p.label)}</label>
        <input type="number" class="cchk-in" id="cchk-${p.key}-s" placeholder="120" min="30" max="400">
        <span>/</span>
        <input type="number" class="cchk-in" id="cchk-${p.key}-d" placeholder="80" min="10" max="300">
        <button class="btn-primary btn-sm" data-ev-click="logConditionBP('${p.key}')">${t('Log')}</button></div>`;
    }
    return `<div class="cchk-row"><label>${t(p.label)}</label>
      <input type="number" class="cchk-in" id="cchk-${p.key}" placeholder="${p.unit}" min="5" max="2000">
      <button class="btn-primary btn-sm" data-ev-click="logConditionSugar('${p.context}','${p.key}')">${t('Log')}</button></div>`;
  }).join('');
  const done = d.prompts.filter(p => p.done);
  const doneChips = done.map(p => {
    const val = p.value2 != null ? `${p.value}/${p.value2}` : p.value;
    return `<span class="cchk-done">✓ ${t(p.label)} ${escHtml(String(val))}</span>`;
  }).join('');
  el.innerHTML = `<div class="panel cchk-card">
    <div class="cchk-head">🩺 ${tformat('%1 check-in', escHtml(t(d.focus_label)))}
      <button class="cchk-gear" title="${t('Change')}" data-ev-click="changeConditionFocus()">⚙</button></div>
    ${rows}${doneChips ? `<div class="cchk-done-row">${doneChips}</div>` : ''}
  </div>`;
}

async function setConditionFocus(focus) {
  await fetch('/api/condition-focus', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ focus }) }).catch(() => {});
  loadConditionCheckin();
}
function dismissConditionSetup() { const el = document.getElementById('dash-condition-checkin'); if (el) { el.style.display = 'none'; } try { sessionStorage.setItem('cchk_dismissed', '1'); } catch (e) {} }
async function changeConditionFocus() { await setConditionFocus(''); }

async function logConditionSugar(context, key) {
  const v = parseFloat(document.getElementById('cchk-' + key)?.value);
  if (!v) { showToast(t('Enter a reading'), 'error'); return; }
  const r = await fetch('/api/vitals', { method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ type: 'blood_sugar', value1: v, context, unit: 'mg/dL', date_key: localToday() }) })
    .then(r => r.json()).catch(() => null);
  if (r && r.success) { showToast(t('Logged ✓')); loadConditionCheckin(); loadTodayGlance(); }
  else showToast((r && r.error) || t('Could not save'), 'error');
}

async function logConditionBP(key) {
  const s = parseFloat(document.getElementById(`cchk-${key}-s`)?.value);
  const dia = parseFloat(document.getElementById(`cchk-${key}-d`)?.value);
  if (!s || !dia) { showToast(t('Enter both numbers'), 'error'); return; }
  const r = await fetch('/api/vitals', { method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ type: 'blood_pressure', value1: s, value2: dia, unit: 'mmHg', date_key: localToday() }) })
    .then(r => r.json()).catch(() => null);
  if (r && r.success) { showToast(t('Logged ✓')); loadConditionCheckin(); loadTodayGlance(); }
  else showToast((r && r.error) || t('Could not save'), 'error');
}

// Health-profile completeness — a gentle bar that only shows while incomplete,
// prompting the specific gaps (a weight unlocks BMI; blood type + a contact make
// the emergency card useful).
async function loadProfileCompleteness() {
  const el = document.getElementById('dash-profile-complete');
  if (!el) return;
  const d = await fetch('/api/profile/completeness').then(r => r.json()).catch(() => null);
  if (!d || d.complete || d.pct >= 100) { el.style.display = 'none'; el.innerHTML = ''; return; }
  el.style.display = '';
  const chips = d.missing.map(m => `<span class="pcx-chip" data-ev-click="gotoProfileGap('${m.where}')">${t(m.label)}</span>`).join('');
  el.innerHTML = `<div class="panel pcx-card">
    <div class="pcx-top">
      <div class="pcx-title">🩺 ${tformat('Your health profile is %1% complete', d.pct)}</div>
      <div class="pcx-count">${d.done}/${d.total}</div>
    </div>
    <div class="pcx-bar"><div class="pcx-fill" style="width:${d.pct}%"></div></div>
    <div class="pcx-missing">${t('Still to add')}: ${chips}</div>
  </div>`;
}
function gotoProfileGap(where) {
  if (where === 'emergency') {
    switchView('reports'); setTimeout(() => { try { switchMedTab('emergency'); } catch (e) {} }, 80);
  } else {
    // Profile basics (name/age/sex/height/weight) live in the profile modal.
    try { openProfileModal(); } catch (e) {}
  }
}

// Today at a glance — a compact chip row of what stands today. Each chip only
// appears when it has something real to say; the strip hides when all is quiet.
const _MEASURE_LABEL = { blood_pressure: 'BP', blood_sugar: 'Sugar', heart_rate: 'Heart rate',
                         weight: 'Weight', spo2: 'SpO2', temperature: 'Temp' };

async function loadTodayGlance() {
  const el = document.getElementById('dash-glance');
  if (!el) return;
  const d = await fetch('/api/today/glance').then(r => r.json()).catch(() => null);
  if (!d || !d.has_anything) { el.style.display = 'none'; el.innerHTML = ''; return; }
  const chips = [];
  if (d.doses_left > 0) {
    chips.push(`<button class="glance-chip" data-ev-click="switchView('medicines')">
      💊 <b>${d.doses_left}</b> ${d.doses_left === 1 ? t('dose left') : t('doses left')}</button>`);
  }
  if (d.next_appointment) {
    const when = _glanceWhen(d.next_appointment.date);
    chips.push(`<button class="glance-chip" data-ev-click="switchView('reports')">
      📅 ${escHtml(d.next_appointment.title)} <span class="glance-sub">${escHtml(when)}</span></button>`);
  }
  if (d.low_stock_count > 0) {
    chips.push(`<button class="glance-chip glance-chip--warn" data-ev-click="openRefillList()">
      🛒 <b>${d.low_stock_count}</b> ${t('to refill')}</button>`);
  }
  if ((d.measurements_due || []).length) {
    const names = d.measurements_due.map(k => t(_MEASURE_LABEL[k] || k)).join(', ');
    chips.push(`<button class="glance-chip" data-ev-click="switchView('medicines');setTimeout(()=>switchMedTab&&switchMedTab('vitals'),60)">
      📏 ${tformat('Measure: %1', escHtml(names))}</button>`);
  }
  if (!chips.length) { el.style.display = 'none'; return; }
  el.style.display = '';
  el.innerHTML = `<div class="glance-strip">${chips.join('')}</div>`;
}
// Friendly relative date for a glance chip: Today / Tomorrow / weekday / date.
function _glanceWhen(iso) {
  try {
    const d = new Date(iso + 'T12:00:00'), today = new Date(); today.setHours(12, 0, 0, 0);
    const diff = Math.round((d - today) / 86400000);
    if (diff === 0) return t('today');
    if (diff === 1) return t('tomorrow');
    if (diff > 1 && diff < 7) return d.toLocaleDateString([], { weekday: 'long' });
    return d.toLocaleDateString([], { month: 'short', day: 'numeric' });
  } catch (e) { return iso; }
}

// A gentle, forward-looking heads-up: of today's still-pending doses, the one
// this user historically misses most. Only shows when the backend judges the
// risk real (enough history + high miss rate). Hidden when nothing qualifies.
async function loadAtRiskDose() {
  const el = document.getElementById('dash-at-risk');
  if (!el) return;
  const d = await fetch('/api/medicines/at-risk').then(r => r.json()).catch(() => null);
  const r = d && d.at_risk;
  if (!r) { el.style.display = 'none'; el.innerHTML = ''; return; }
  el.style.display = '';
  el.innerHTML = `<div class="at-risk-card">
    <span class="at-risk-icon">👀</span>
    <div class="at-risk-body">
      <div class="at-risk-lead">${tformat("Don't forget your %1 dose today", t(r.label))}</div>
      <div class="at-risk-sub">${escHtml(r.icon)} ${escHtml(r.med_name)} · ${tformat('you missed it %1% of the last %2 days', r.miss_pct, r.scheduled)}</div>
    </div>
    <button class="at-risk-btn" data-ev-click="markDoseTaken('${r.med_id}','${r.time}')">${t('Mark taken')}</button>
  </div>`;
}

function renderNextAction(doses, calorieState) {
  const el = document.getElementById('dash-next-action');
  if (!el) return;
  const untaken = (doses || []).filter(d => !d.taken);

  // Current local time as HH:MM, to tell "due/overdue" from "coming up"
  const now  = new Date();
  const hhmm = String(now.getHours()).padStart(2, '0') + ':' + String(now.getMinutes()).padStart(2, '0');

  if (untaken.length) {
    const sorted  = untaken.slice().sort((a, b) => (a.time || '').localeCompare(b.time || ''));
    const due     = sorted.filter(d => (d.time || '') <= hhmm);
    const next    = due.length ? due[due.length - 1] : sorted[0];  // most-overdue, else soonest
    const overdue = (next.time || '') <= hhmm;
    const more    = untaken.length - 1;
    el.className = 'next-action';
    el.innerHTML = `
      <div class="next-action-icon">${next.icon || '💊'}</div>
      <div class="next-action-body">
        <div class="next-action-eyebrow">${overdue ? t('Time for your dose') : t('Next dose')}</div>
        <div class="next-action-title">${tformat('Take %1', escHtml(next.med_name))}</div>
        <div class="next-action-sub">${escHtml(next.dosage || '')} ${escHtml(next.unit || '')} · ${next.time}${medTimingText(next) ? ' · ' + escHtml(medTimingText(next)) : ''}${more > 0 ? ' · ' + tformat('+%1 more today', more) : ''}</div>
      </div>
      <button class="next-action-btn" data-ev-click="markDoseTaken('${next.med_id}','${next.time}')">${t('Mark taken')}</button>`;
    el.style.display = '';
    return;
  }

  if ((doses || []).length) {
    // Meds exist and every dose is done — a quiet affirmation, no action needed
    el.className = 'next-action is-calm';
    el.innerHTML = `
      <div class="next-action-icon">✓</div>
      <div class="next-action-body">
        <div class="next-action-eyebrow">${t('All caught up')}</div>
        <div class="next-action-title">${t('Every dose taken today')}</div>
        <div class="next-action-sub">${t('Nice work staying on track.')}</div>
      </div>`;
    el.style.display = '';
    return;
  }

  // No medicines scheduled — nudge the next most useful log only if the day is empty
  const eaten = calorieState && calorieState.today ? (calorieState.today.eaten || 0) : 0;
  if (calorieState && eaten === 0) {
    el.className = 'next-action is-calm';
    el.innerHTML = `
      <div class="next-action-icon">🍽️</div>
      <div class="next-action-body">
        <div class="next-action-eyebrow">Start your day</div>
        <div class="next-action-title">Log your first meal</div>
        <div class="next-action-sub">A quick log keeps your nutrition picture accurate.</div>
      </div>
      <button class="next-action-btn" data-ev-click="quickAdd('food')">${t('Log a meal')}</button>`;
    el.style.display = '';
    return;
  }

  el.style.display = 'none';
}

// Caregiver panel: today's medication status for family members who share
// their meds with you. Consent-gated server-side; only appears if ≥1 member.
async function loadCarePanel() {
  const el = document.getElementById('dash-care-panel');
  if (!el) return;
  const members = await fetch('/api/family/care-status').then(r => r.json()).catch(() => []);
  if (!Array.isArray(members) || !members.length) { el.style.display = 'none'; return; }
  // Reassurance: turn "no alerts" into explicit good news.
  const allGood = members.every(m => !m.overdue.length);
  const ago = (min) => min == null ? '' : min < 1 ? 'just now' : min < 60 ? `${min}m ago` : `${Math.round(min / 60)}h ago`;
  el.innerHTML = `
    <div class="care-panel-head">
      <span class="care-panel-title">People you're caring for${allGood ? ' · everyone’s on track today ✓' : ''}</span>
      <a href="#" class="panel-link" data-ev-click="switchView('family');return false">Family →</a>
    </div>
    <div class="care-list">${members.map(m => {
      const overdue = m.overdue.length;
      const done    = m.total > 0 && m.taken >= m.total;
      const status  = overdue ? tformat(overdue > 1 ? '%1 doses overdue' : '%1 dose overdue', overdue)
                    : m.total === 0 ? t('No medicines scheduled today')
                    : done ? t('All doses taken ✓')
                    : tformat('%1 of %2 doses taken', m.taken, m.total);
      const detail  = overdue ? m.overdue.map(o => `${escHtml(o.med_name || 'dose')} · ${o.time}`).join(', ')
                    : (m.last_ago_min != null ? `last dose ${ago(m.last_ago_min)}` : '');
      const low     = (m.low_stock && m.low_stock.length) ? m.low_stock[0] : null;
      const refill  = low
        ? `🔄 ${escHtml(low.name || 'A medicine')} running low${low.days_left != null ? ` (~${Math.max(0, Math.round(low.days_left))}d)` : ''}`
          + (m.low_stock.length > 1 ? ` +${m.low_stock.length - 1} more` : '')
        : '';
      const cls     = overdue ? 'is-alert' : done ? 'is-ok' : 'is-pending';
      const icon    = overdue ? '🚨' : done ? '✓' : '💊';
      // Coordination: on an overdue member, let one caregiver claim it so the
      // others don't all call at once.
      let right;
      if (overdue && m.checking_is_me)      right = `<span class="care-ack-chip is-me">You're on it ✓</span>`;
      else if (overdue && m.checking_by)    right = `<span class="care-ack-chip">${escHtml(m.checking_by)} is on it</span>`;
      else if (overdue)                     right = `<button class="care-ack-btn" data-ev-click="careAck('${m.user_id}')">I'll check</button>`;
      else                                  right = `<div class="care-item-actions">
        <button class="care-cheer-btn" data-ev-click="cheer('${m.user_id}','${escHtml(m.name)}')" title="Send encouragement">👏</button>
        <button class="care-cheer-btn" data-ev-click="pingMember('${m.user_id}','${escHtml(m.name)}')" title="Thinking of you">💛</button>
      </div>`;
      return `<div class="care-item ${cls}">
        <div class="care-item-avatar">${escHtml((m.name || '?').slice(0, 1).toUpperCase())}</div>
        <div class="care-item-body">
          <div class="care-item-name">${escHtml(m.name)}</div>
          <div class="care-item-status">${status}${detail ? ' · ' + detail : ''}</div>
          ${refill ? `<div class="care-item-refill">${refill}</div>` : ''}
        </div>
        ${right}
      </div>`;
    }).join('')}</div>`;
  el.style.display = '';
}

// Every action below tells one person something reassuring about another. If
// the write didn't land, claiming it did is worse than staying quiet: the
// member stops worrying because they believe their family knows they're okay,
// and the family is still sitting there waiting. So: check, then speak.
// Returns the parsed body on success, or null — never throws.
async function postJson(url, body) {
  try {
    const r = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });
    if (!r.ok) return null;
    const d = await r.json().catch(() => ({}));
    return (d && d.success === false) ? null : (d || {});
  } catch {
    return null;
  }
}

async function careAck(uid) {
  const ok = await postJson('/api/family/care-ack', { target_user_id: uid });
  if (!ok) { showToast("Couldn't let them know — check your connection", 'error'); return; }
  showToast("Thanks — your family will see you're on it", 'success');
  loadCarePanel();
}

// Caregiver → member encouragement (one tap; turns monitoring into connection)
async function cheer(uid, name) {
  const ok = await postJson('/api/family/encourage', { to_user_id: uid, emoji: '👏', message: '' });
  showToast(ok ? `👏 Sent encouragement to ${name || 'them'}`
               : "Couldn't send that — try again", ok ? 'success' : 'error');
}

async function pingMember(uid, name) {
  const ok = await postJson('/api/family/ping', { to_user_id: uid });
  showToast(ok ? `💛 Let ${name || 'them'} know you're thinking of them`
               : "Couldn't send that — try again", ok ? 'success' : 'error');
}

// Recipient side: warm cards for encouragements sent to me
async function loadEncouragements() {
  const el = document.getElementById('dash-encouragements');
  if (!el) return;
  const items = await fetch('/api/family/encouragements').then(r => r.json()).catch(() => []);
  if (!Array.isArray(items) || !items.length) { el.style.display = 'none'; return; }
  const verb = { ping: 'is thinking of you', reply: 'is okay 💛' };
  el.innerHTML = items.map(e => `
    <div class="cheer-card">
      <div class="cheer-emoji">${escHtml(e.emoji || '👏')}</div>
      <div class="cheer-body">
        <div class="cheer-from">${escHtml(e.from_name || 'Family')} ${verb[e.kind] || 'cheered you on'}</div>
        ${e.message ? `<div class="cheer-msg">${escHtml(e.message)}</div>` : ''}
      </div>
      ${e.kind === 'ping' ? `<button class="cheer-reply-btn" data-ev-click="replyOkay('${e.id}')">I'm okay 💛</button>` : ''}
    </div>`).join('') +
    `<button class="cheer-dismiss" data-ev-click="dismissEncouragements()">Thanks 💛</button>`;
  el.style.display = '';
}

async function replyOkay(eid) {
  const ok = await postJson(`/api/family/encouragements/${eid}/ok`);
  if (!ok) {
    // Leave the card up so they can retry — this is someone answering a
    // worried family member; a swallowed failure leaves both sides stranded.
    showToast("Couldn't send your reply — check your connection", 'error');
    return;
  }
  showToast("Sent — they'll know you're okay 💛", 'success');
  loadEncouragements();
}

async function dismissEncouragements() {
  await fetch('/api/family/encouragements/read', { method: 'POST' }).catch(() => {});
  const el = document.getElementById('dash-encouragements');
  if (el) el.style.display = 'none';
}

// Low-stock refill nudge — the other half of the pill-stock loop. Now that
// taking a dose decrements stock, surface medicines that are running low so
// the refill actually happens.
async function loadLowStock() {
  const el = document.getElementById('dash-lowstock');
  if (!el) return;
  const low = await fetch('/api/medicines/low-stock').then(r => r.json()).catch(() => []);
  if (!Array.isArray(low) || !low.length) { el.style.display = 'none'; return; }
  const title = low.length === 1
    ? `${escHtml(low[0].name)} is running low`
    : `${low.length} medicines are running low`;
  const detail = low.slice(0, 3).map(m => {
    const d = m.days_left;
    const left = (d != null && isFinite(d)) ? `~${Math.max(0, Math.round(d))}d left` : 'low';
    return `${escHtml(m.name)} · ${left}`;
  }).join('  ·  ');
  el.innerHTML = `
    <div class="lowstock-icon">🔔</div>
    <div class="lowstock-body">
      <div class="lowstock-title">${title} — time to refill</div>
      <div class="lowstock-sub">${detail}</div>
    </div>
    <button class="lowstock-btn" data-ev-click="switchView('medicines')">${t('Review')}</button>`;
  el.style.display = 'flex';
}

// ── Doctor visit summary (printable one-pager) ──
async function openDoctorSummary() {
  const el = document.getElementById('doctor-summary-content');
  const modal = document.getElementById('doctor-summary-modal');
  if (!el || !modal) return;
  el.innerHTML = '<div style="padding:30px;text-align:center;color:var(--gray-400)">Compiling your summary…</div>';
  modal.style.display = 'flex';
  const d = await fetch('/api/doctor-summary').then(r => r.json()).catch(() => null);
  el.innerHTML = d ? renderDoctorSummary(d)
    : '<div style="padding:20px;color:#DC2626">Could not build the summary.</div>';
}
function closeDoctorSummary() { document.getElementById('doctor-summary-modal').style.display = 'none'; }

// ── Shareable health snapshot (time-limited public link) ────────────────────
function openShareManager() {
  const m = document.getElementById('share-manager-modal');
  if (m) { m.style.display = 'flex'; loadShareLinks(); }
}
function closeShareManager() { const m = document.getElementById('share-manager-modal'); if (m) m.style.display = 'none'; }

async function createShareLink() {
  const label = document.getElementById('share-label')?.value || '';
  const days = parseInt(document.getElementById('share-days')?.value, 10) || 7;
  const scope = document.getElementById('share-scope')?.value || 'summary';
  const r = await fetch('/api/share/snapshot', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ label, days_valid: days, scope })
  }).then(r => r.json()).catch(() => null);
  if (r && r.success) {
    showToast(t('Link created 🔗'));
    document.getElementById('share-label').value = '';
    loadShareLinks();
  } else {
    showToast(t('Could not create link'), 'error');
  }
}

async function loadShareLinks() {
  const el = document.getElementById('share-list');
  if (!el) return;
  const d = await fetch('/api/share/snapshots').then(r => r.json()).catch(() => null);
  const snaps = (d && d.snapshots) || [];
  if (!snaps.length) { el.innerHTML = `<div style="font-size:13px;color:var(--gray-400);padding:8px 0">${t('No share links yet.')}</div>`; return; }
  const origin = window.location.origin;
  el.innerHTML = snaps.map(s => {
    const url = origin + '/share/' + s.token;
    const badge = { active: '#22C55E', expired: '#94A3B8', revoked: '#EF4444' }[s.status] || '#94A3B8';
    const exp = new Date(s.expires_at).toLocaleDateString([], { month: 'short', day: 'numeric', year: 'numeric' });
    const active = s.status === 'active';
    return `<div class="share-row">
      <div class="share-row-main">
        <div class="share-row-top"><span class="share-dot" style="background:${badge}"></span>
          <b>${s.label ? escHtml(s.label) : t('Health snapshot')}</b>
          <span class="share-status">${t(s.status)}</span></div>
        ${active ? `<div class="share-url"><input readonly value="${escHtml(url)}" data-ev-click="this.select()"><button class="btn-outline btn-sm" data-ev-click="copyShareUrl('${escHtml(url)}')">${t('Copy')}</button></div>`
                 : `<div class="share-url-dead">${t('This link is no longer active.')}</div>`}
        <div class="share-meta">${active ? tformat('expires %1', exp) : ''} ${s.views ? '· ' + tformat('%1 views', s.views) : ''}</div>
      </div>
      ${active ? `<button class="btn-outline btn-sm" data-ev-click="revokeShareLink('${s.id}')">${t('Turn off')}</button>` : ''}
    </div>`;
  }).join('');
}

function copyShareUrl(url) {
  if (navigator.clipboard) navigator.clipboard.writeText(url).then(() => showToast(t('Copied ✓'))).catch(() => {});
  else showToast(url);
}

async function revokeShareLink(id) {
  const r = await fetch(`/api/share/snapshot/${id}/revoke`, { method: 'POST' }).then(r => r.json()).catch(() => null);
  if (r && r.success) { showToast(t('Link turned off')); loadShareLinks(); }
  else showToast(t('Could not update'), 'error');
}
function printDoctorSummary() { window.print(); }

// "Since your last visit" — anchored on the last past doctor appointment. Only
// rendered when there's a visit AND something actually changed since it.
function _renderVisitPrep(vp, esc, fmt) {
  if (!vp || !vp.last_visit) return '';
  const lbl = t => String(t || '').replace(/_/g, ' ');
  const vitals = (vp.vitals_changes || []).map(v => {
    const from = `${v.from.value1}${v.from.value2 ? '/' + v.from.value2 : ''}`;
    const to = `${v.to.value1}${v.to.value2 ? '/' + v.to.value2 : ''}`;
    return `<tr><td>${esc(lbl(v.type))}</td><td>${esc(from)} → <b>${esc(to)}</b> ${esc(v.unit || '')}</td><td>${fmt(v.to.date)}</td></tr>`;
  }).join('');
  const labs = (vp.new_labs || []).map(l =>
    `<li>${esc(l.name || '')}: ${esc(String(l.value))} ${esc(l.unit || '')} <span class="ds-muted">(${fmt(l.date)})</span></li>`).join('');
  const medWord = { started: 'started', stopped: 'stopped', deleted: 'removed' };
  const meds = (vp.med_changes || []).map(m =>
    `<li>${esc(medWord[m.kind] || m.kind)}: ${esc(m.name || '')} <span class="ds-muted">(${fmt(m.date)})</span></li>`).join('');
  if (!vitals && !labs && !meds) return '';
  return `<h2 class="ds-h2">Since your last visit (${fmt(vp.last_visit.date)})</h2>
    ${vitals ? `<table class="ds-table"><thead><tr><th>Vital</th><th>Change</th><th>Latest</th></tr></thead><tbody>${vitals}</tbody></table>` : ''}
    ${labs ? `<div class="ds-muted" style="margin-top:6px"><b>New labs:</b></div><ul class="ds-list">${labs}</ul>` : ''}
    ${meds ? `<div class="ds-muted" style="margin-top:6px"><b>Medication changes:</b></div><ul class="ds-list">${meds}</ul>` : ''}`;
}

function renderDoctorSummary(d) {
  const esc = escapeHtml;
  const p = d.person || {};
  const fmt = iso => { try { return new Date(iso + 'T12:00:00').toLocaleDateString('en-US', {month:'short', day:'numeric', year:'numeric'}); } catch (e) { return iso || ''; } };

  const meds = (d.medications || []).length
    ? `<table class="ds-table"><thead><tr><th>Medicine</th><th>Dose</th><th>Schedule</th></tr></thead><tbody>`
      + d.medications.map(m => `<tr><td>${esc(m.name || '')}</td><td>${esc(((m.dosage || '') + ' ' + (m.unit || '')).trim())}</td><td>${esc((m.times || []).join(', '))}${medTimingText(m) ? ' · ' + esc(medTimingText(m)) : ''}</td></tr>`).join('')
      + `</tbody></table>`
    : '<p class="ds-empty">No active medicines.</p>';

  const vrows = Object.entries(d.vitals || {}).map(([t, v]) =>
    `<tr><td>${esc(t.replace('_', ' '))}</td><td>${esc(String(v.value1))}${v.value2 ? '/' + esc(String(v.value2)) : ''} ${esc(v.unit || '')}</td><td>${fmt(v.date)}</td></tr>`).join('');
  const vitals = vrows
    ? `<table class="ds-table"><thead><tr><th>Vital</th><th>Latest</th><th>Measured</th></tr></thead><tbody>${vrows}</tbody></table>`
    : '<p class="ds-empty">No vitals recorded.</p>';

  const syms = (d.symptoms || []).length
    ? `<ul class="ds-list">` + d.symptoms.map(s => `<li>${esc(s.name)} <span class="ds-muted">(${s.severity}/10 · ${fmt(s.date)})</span></li>`).join('') + `</ul>`
    : '<p class="ds-empty">No symptoms logged in the last 30 days.</p>';

  const adh = d.adherence_30d || {};
  const adhLine = adh.total ? `${adh.pct}% (${adh.taken}/${adh.total} scheduled doses, last 30 days)` : 'No dose history yet';

  return `
    <div class="ds-sheet">
      <div class="ds-topline">
        <div class="ds-brand">🌱 Arogo — Health summary</div>
        <div class="ds-muted">Generated ${fmt(d.generated)}</div>
      </div>
      <div class="ds-name">${esc(p.name || '—')}</div>
      <div class="ds-meta">${[p.age ? 'Age ' + esc(String(p.age)) : '', p.gender ? esc(p.gender) : '', p.blood_type ? 'Blood type ' + esc(p.blood_type) : ''].filter(Boolean).join('  ·  ')}</div>
      ${(d.conditions || d.allergies) ? `<div class="ds-flags">
        ${d.conditions ? `<div><b>Conditions:</b> ${esc(d.conditions)}</div>` : ''}
        ${d.allergies ? `<div><b>Allergies:</b> ${esc(d.allergies)}</div>` : ''}
      </div>` : ''}
      <h2 class="ds-h2">Current medications</h2>${meds}
      <div class="ds-muted" style="margin-top:6px">Adherence: ${esc(adhLine)}</div>
      <h2 class="ds-h2">Latest vitals</h2>${vitals}
      <h2 class="ds-h2">Recent symptoms (30 days)</h2>${syms}
      ${_renderVisitPrep(d.visit_prep, esc, fmt)}
      ${(d.questions || []).length ? `<h2 class="ds-h2">Questions to ask</h2><ul class="ds-list">${d.questions.map(q => `<li>${esc(q)}</li>`).join('')}</ul>` : ''}
      <div class="ds-foot ds-muted">Generated by the patient from self-tracked data in Arogo. Not an official medical record.</div>
    </div>`;
}

// ── Printable medication card (fridge / wallet reference) ──
async function openMedCard() {
  const d = await fetch('/api/medicines/card').then(r => r.json()).catch(() => null);
  if (!d) { showToast('Could not build the card', 'error'); return; }
  if (!d.count) { showToast('Add a medicine first', 'error'); return; }
  const win = window.open('', '_blank', 'width=760,height=900');
  if (!win) { showToast('Allow pop-ups to open the printable card', 'error'); return; }
  win.document.write(buildMedCardHtml(d));
  win.document.close();
  // Wire the print button from here — a blank window can inherit the opener's
  // CSP, which would block an inline onclick in the written document.
  const btn = win.document.querySelector('.mc-print-btn');
  if (btn) btn.addEventListener('click', () => win.print());
}

// Printable week grid: what to take in each time slot across the next 7 days.
// Built from the same planner the app uses; a fridge sheet, print-friendly.
async function openWeekSchedule() {
  const d = await fetch('/api/medicines/planner?days=7').then(r => r.json()).catch(() => null);
  if (!d) { showToast(t('Could not build the schedule'), 'error'); return; }
  if (!d.has_schedule) { showToast(t('Add a scheduled medicine first'), 'error'); return; }
  const win = window.open('', '_blank', 'width=900,height=760');
  if (!win) { showToast(t('Allow pop-ups to open the printable schedule'), 'error'); return; }
  win.document.write(buildWeekScheduleHtml(d));
  win.document.close();
  const btn = win.document.querySelector('.ws-print-btn');
  if (btn) btn.addEventListener('click', () => win.print());
}

function buildWeekScheduleHtml(d) {
  const esc = escapeHtml;
  const head = d.days.map(day =>
    `<th class="${day.is_today ? 'ws-today' : ''}"><div class="ws-wd">${esc(day.weekday)}</div><div class="ws-dn">${esc(String(day.day))}</div></th>`).join('');
  const rows = d.rows.map(r => {
    const cells = r.cells.map((due, i) => {
      const items = (due || []).map(m =>
        `<div class="ws-med"><span>${esc(m.icon || '💊')}</span> ${esc(m.name)}${m.dose ? ` <span class="ws-dose">${esc(m.dose)}</span>` : ''}</div>`).join('');
      return `<td class="${d.days[i] && d.days[i].is_today ? 'ws-today' : ''}">${items || '<span class="ws-dash">–</span>'}</td>`;
    }).join('');
    return `<tr><th class="ws-time">${esc(_mc12h(r.time))}<div class="ws-slot">${esc(t(r.label))}</div></th>${cells}</tr>`;
  }).join('');
  return `<!doctype html><html><head><meta charset="utf-8"><title>${t('Week schedule')} — Arogo</title>
    <style>
      body{font:14px/1.4 -apple-system,Segoe UI,Roboto,sans-serif;color:#243027;margin:0;padding:26px}
      h1{font-size:20px;margin:0 0 2px} .sub{color:#7A867C;font-size:12px;margin-bottom:16px}
      table{width:100%;border-collapse:collapse;table-layout:fixed}
      th,td{border:1px solid #E1E7E0;padding:7px 8px;vertical-align:top;text-align:left}
      thead th{background:#F2F6F1;text-align:center;font-size:12px}
      .ws-wd{font-weight:700}.ws-dn{color:#7A867C;font-size:11px}
      .ws-time{width:96px;background:#FAFBF9;font-weight:700}.ws-slot{font-weight:400;color:#7A867C;font-size:11px}
      .ws-today{background:#EAF5EC}
      .ws-med{font-size:12px;margin:2px 0}.ws-dose{color:#7A867C}.ws-dash{color:#C7CFC8}
      .ws-print-btn{position:fixed;top:16px;right:16px;padding:9px 16px;background:#5A9E70;color:#fff;border:none;border-radius:9px;font-weight:600;cursor:pointer}
      .foot{margin-top:14px;color:#9AA69C;font-size:11px}
      @media print{.ws-print-btn{display:none}}
    </style></head><body>
    <button class="ws-print-btn">🖨 ${t('Print')}</button>
    <h1>🌱 ${t('Weekly medication schedule')}</h1>
    <div class="sub">${t('Take each medicine in its time row, on each day it appears. As-needed medicines are not shown here.')}</div>
    <table><thead><tr><th class="ws-time"></th>${head}</tr></thead><tbody>${rows}</tbody></table>
    <div class="foot">${t('Generated from your own schedule in Arogo. Not a prescription.')}</div>
    </body></html>`;
}

// Printable symptom log for a doctor — the user's symptom history, newest first,
// as a clean table. Built from the same data the history panel shows.
async function openSymptomLog() {
  const rows = await fetch('/api/symptoms?days=90').then(r => r.json()).catch(() => null);
  if (!Array.isArray(rows)) { showToast(t('Could not build the log'), 'error'); return; }
  if (!rows.length) { showToast(t('No symptoms logged yet'), 'error'); return; }
  const win = window.open('', '_blank', 'width=820,height=900');
  if (!win) { showToast(t('Allow pop-ups to open the printable log'), 'error'); return; }
  win.document.write(buildSymptomLogHtml(rows));
  win.document.close();
  const btn = win.document.querySelector('.sl-print-btn');
  if (btn) btn.addEventListener('click', () => win.print());
}

function buildSymptomLogHtml(rows) {
  const esc = escapeHtml;
  const sorted = rows.slice().sort((a, b) => (b.date_key || '').localeCompare(a.date_key || '')
    || (a.time_of_day || '').localeCompare(b.time_of_day || ''));
  const body = sorted.map(s => {
    const d = (() => { try { return new Date(s.date_key + 'T12:00:00').toLocaleDateString([], { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' }); } catch (e) { return s.date_key || ''; } })();
    const sev = s.severity != null ? `${s.severity}/10` : '';
    return `<tr><td>${esc(d)}</td><td>${esc(s.name || '')}</td><td>${esc(sev)}</td><td>${esc(s.time_of_day || '')}</td><td>${esc(s.notes || '')}</td></tr>`;
  }).join('');
  return `<!doctype html><html><head><meta charset="utf-8"><title>${t('Symptom log')} — Arogo</title>
    <style>
      body{font:14px/1.5 -apple-system,Segoe UI,Roboto,sans-serif;color:#243027;margin:0;padding:26px}
      h1{font-size:20px;margin:0 0 2px} .sub{color:#7A867C;font-size:12px;margin-bottom:16px}
      table{width:100%;border-collapse:collapse;font-size:13px}
      th,td{border:1px solid #E1E7E0;padding:7px 9px;text-align:left;vertical-align:top}
      thead th{background:#F2F6F1;font-size:11px;text-transform:uppercase;letter-spacing:.03em;color:#5A6B5E}
      .sl-print-btn{position:fixed;top:16px;right:16px;padding:9px 16px;background:#5A9E70;color:#fff;border:none;border-radius:9px;font-weight:600;cursor:pointer}
      .foot{margin-top:14px;color:#9AA69C;font-size:11px}
      @media print{.sl-print-btn{display:none}}
    </style></head><body>
    <button class="sl-print-btn">🖨 ${t('Print')}</button>
    <h1>🌱 ${t('Symptom log')}</h1>
    <div class="sub">${tformat('%1 entries · last 90 days', sorted.length)}</div>
    <table><thead><tr><th>${t('Date')}</th><th>${t('Symptom')}</th><th>${t('Severity')}</th><th>${t('When')}</th><th>${t('Notes')}</th></tr></thead>
    <tbody>${body}</tbody></table>
    <div class="foot">${t('Self-tracked in Arogo. Not an official medical record.')}</div>
    </body></html>`;
}

// Human timing label for a medicine/dose object. Backend supplies timing_text;
// fall back to the older with_food flag so nothing regresses.
function medTimingText(m) {
  if (!m) return '';
  return m.timing_text || (m.with_food ? 'with food' : '');
}

// ── Refill shopping list (everything to pick up on a pharmacy run) ──
async function openRefillList() {
  const el = document.getElementById('refill-content');
  const modal = document.getElementById('refill-modal');
  if (!el || !modal) return;
  el.innerHTML = '<div style="padding:24px;text-align:center;color:var(--gray-400)">Loading…</div>';
  modal.style.display = 'flex';
  const d = await fetch('/api/medicines/refill-list').then(r => r.json()).catch(() => null);
  el.innerHTML = d ? renderRefillList(d) : '<div style="padding:20px;color:#DC2626">Could not load the list.</div>';
}

// Pharmacy quick-actions: call the saved pharmacy and copy a ready refill note.
function _pharmacyBar(d) {
  const ph = d.pharmacy || {};
  const msg = d.refill_message || '';
  const callable = ph.phone
    ? `<a class="btn-primary btn-sm" href="tel:${escAttrPhone(ph.phone)}">📞 ${tformat('Call %1', escHtml(ph.name || t('pharmacy')))}</a>`
    : '';
  const copyBtn = msg
    ? `<button class="btn-outline btn-sm" data-ev-click="copyRefillMessage()">📋 ${t('Copy refill note')}</button>` : '';
  const editBtn = `<button class="btn-outline btn-sm" data-ev-click="openPharmacyEditor()">${ph.has_pharmacy ? '✎ ' + t('Pharmacy') : '+ ' + t('Add pharmacy')}</button>`;
  window._refillMessage = msg;
  return (callable || copyBtn || editBtn)
    ? `<div class="rf-pharmacy">${callable}${copyBtn}${editBtn}</div>` : '';
}
// Phone is server-sanitized to [0-9+-() space]; strip spaces/() for the tel: URI.
function escAttrPhone(p) { return String(p || '').replace(/[^0-9+]/g, ''); }

function copyRefillMessage() {
  const msg = window._refillMessage || '';
  if (!msg) return;
  if (navigator.clipboard) navigator.clipboard.writeText(msg).then(() => showToast(t('Copied ✓'))).catch(() => showToast(msg));
  else showToast(msg);
}

function openPharmacyEditor() {
  fetch('/api/pharmacy').then(r => r.json()).then(ph => {
    closeSkipPicker();
    const ov = document.createElement('div');
    ov.className = 'lang-picker-overlay'; ov.id = 'pharmacy-editor';
    ov.setAttribute('data-ev-click', 'pharmacyEditorBackdrop(event)');
    ov.innerHTML = `<div class="lang-picker" style="max-width:320px;padding:16px">
      <div class="lang-picker-head">${t('Your pharmacy')}</div>
      <input type="text" id="pharmacy-name" class="form-input" placeholder="${t('Pharmacy name')}" value="${escHtml(ph.name || '')}" style="margin-bottom:8px">
      <input type="tel" id="pharmacy-phone" class="form-input" placeholder="${t('Phone')}" value="${escHtml(ph.phone || '')}" style="margin-bottom:12px">
      <button class="btn-primary" style="width:100%" data-ev-click="savePharmacy()">${t('Save')}</button>
    </div>`;
    document.body.appendChild(ov);
  }).catch(() => {});
}
function pharmacyEditorBackdrop(ev) { if (ev.target && ev.target.id === 'pharmacy-editor') closePharmacyEditor(); }
function closePharmacyEditor() { const el = document.getElementById('pharmacy-editor'); if (el) el.remove(); }

async function savePharmacy() {
  const name = document.getElementById('pharmacy-name')?.value || '';
  const phone = document.getElementById('pharmacy-phone')?.value || '';
  const r = await fetch('/api/pharmacy', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name, phone })
  }).then(r => r.json()).catch(() => null);
  if (r?.success) { showToast(t('Pharmacy saved')); closePharmacyEditor(); openRefillList(); }
  else showToast(t('Could not save'), 'error');
}
function closeRefillList() { const m = document.getElementById('refill-modal'); if (m) m.style.display = 'none'; }

function _refillStatusLabel(it) {
  if (it.ordered) return '<span class="rf-tag rf-tag--ordered">on the way</span>';
  if (it.out) return '<span class="rf-tag rf-tag--out">out of stock</span>';
  if (it.days_left != null) return `<span class="rf-tag rf-tag--low">~${it.days_left}d left</span>`;
  return '';
}

function renderRefillList(d) {
  const esc = escHtml;
  const items = (d && d.items) || [];
  if (!items.length) {
    return `<div class="rf-empty">✅ Nothing to refill — every tracked medicine has enough on hand.</div>` + _pharmacyBar(d || {});
  }
  const rows = items.map((it, i) => `
    <label class="rf-row">
      <input type="checkbox" class="rf-check" data-i="${i}">
      <span class="rf-icon">${esc(it.icon)}</span>
      <div class="rf-body">
        <div class="rf-name">${esc(it.name)}${it.dose ? ` <span class="rf-dose">${esc(it.dose)}</span>` : ''} ${_refillStatusLabel(it)}</div>
        ${it.pharmacy_note ? `<div class="rf-note">📍 ${esc(it.pharmacy_note)}</div>` : ''}
      </div>
    </label>`).join('');
  return _pharmacyBar(d) + `<div class="rf-list">${rows}</div>
    <p class="rf-hint">Tick items as you go. Ordered ones sit at the bottom.</p>`;
}

function printRefillList() {
  const list = document.getElementById('refill-content');
  if (!list || !list.querySelector('.rf-row')) { showToast('Nothing to print', 'error'); return; }
  const names = [...list.querySelectorAll('.rf-row')].map(r => r.querySelector('.rf-name').textContent.trim());
  const win = window.open('', '_blank', 'width=620,height=800');
  if (!win) { showToast('Allow pop-ups to print', 'error'); return; }
  const items = names.map(n => `<li>${escHtml(n)}</li>`).join('');
  win.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Refill shopping list</title>
<style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#1f2a24;padding:28px;max-width:560px;margin:0 auto}
h1{font-size:24px;margin-bottom:4px}.sub{font-size:13px;color:#8a978f;margin-bottom:20px}
ul{list-style:none}li{font-size:17px;padding:12px 4px 12px 34px;border-bottom:1px solid #ECE7DC;position:relative}
li:before{content:'';position:absolute;left:2px;top:12px;width:18px;height:18px;border:2px solid #B9C2BB;border-radius:4px}
.foot{font-size:11.5px;color:#a4afa7;margin-top:20px;text-align:center}
.pp-print-btn{background:#5A9E70;color:#fff;border:none;border-radius:99px;padding:9px 18px;font-size:14px;font-weight:600;cursor:pointer;margin-bottom:16px}
@media print{body{padding:0}.no-print{display:none!important}@page{margin:16mm}}</style></head><body>
<button class="pp-print-btn no-print" type="button">🖨️ Print / Save as PDF</button>
<h1>🛒 Refill shopping list</h1><div class="sub">Arogo · from your own medicine list</div>
<ul>${items}</ul><div class="foot">Not a prescription.</div></body></html>`);
  win.document.close();
  const btn = win.document.querySelector('.pp-print-btn');
  if (btn) btn.addEventListener('click', () => win.print());
}

// ── Medicine history (a dated record of what changed) ──
const MED_EVENT_META = {
  started:   { icon: '➕', label: 'Started',   color: 'var(--teal-600,#4F8D74)' },
  stopped:   { icon: '⏸️', label: 'Paused',    color: '#B4443A' },
  resumed:   { icon: '▶️', label: 'Resumed',   color: 'var(--teal-600,#4F8D74)' },
  deleted:   { icon: '🗑️', label: 'Removed',   color: 'var(--gray-500,#888)' },
  restocked: { icon: '🔄', label: 'Restocked', color: '#B4843A' },
};

async function openMedHistory() {
  const el = document.getElementById('medhistory-content');
  const modal = document.getElementById('medhistory-modal');
  if (!el || !modal) return;
  el.innerHTML = '<div style="padding:28px;text-align:center;color:var(--gray-400)">Loading…</div>';
  modal.style.display = 'flex';
  const d = await fetch('/api/medicines/history?days=365').then(r => r.json()).catch(() => null);
  el.innerHTML = d ? renderMedHistory(d.events || []) : '<div style="padding:20px;color:#DC2626">Could not load history.</div>';
}
function closeMedHistory() { const m = document.getElementById('medhistory-modal'); if (m) m.style.display = 'none'; }

function renderMedHistory(events) {
  const esc = escHtml;
  if (!events.length) {
    return `<div class="mh-empty">No changes yet. Adding, pausing, or restocking a medicine will show up here.</div>`;
  }
  const fmt = at => { try { return new Date(at).toLocaleDateString('en-US', {month:'short', day:'numeric', year:'numeric'}); } catch(e){ return (at||'').slice(0,10); } };
  const rows = events.map(e => {
    const m = MED_EVENT_META[e.kind] || { icon:'•', label:e.kind, color:'var(--gray-500)' };
    return `<div class="mh-row">
      <span class="mh-icon" style="color:${m.color}">${m.icon}</span>
      <div class="mh-body">
        <div class="mh-line"><b>${esc(e.med_name || 'A medicine')}</b> — ${esc(m.label)}${e.detail ? ` <span class="mh-detail">${esc(e.detail)}</span>` : ''}</div>
        <div class="mh-date">${esc(fmt(e.at))}</div>
      </div>
    </div>`;
  }).join('');
  return `<div class="mh-list">${rows}</div>`;
}

// ── Weekly pill planner (days×times grid of the upcoming plan) ──
async function openPillPlanner() {
  const el = document.getElementById('planner-content');
  const modal = document.getElementById('planner-modal');
  if (!el || !modal) return;
  el.innerHTML = '<div style="padding:28px;text-align:center;color:var(--gray-400)">Building your week…</div>';
  modal.style.display = 'flex';
  const d = await fetch('/api/medicines/planner?days=7').then(r => r.json()).catch(() => null);
  el.innerHTML = d ? renderPlanner(d)
    : '<div style="padding:20px;color:#DC2626">Could not build the planner.</div>';
}
function closePlanner() { const m = document.getElementById('planner-modal'); if (m) m.style.display = 'none'; }

function renderPlanner(d) {
  const esc = escapeHtml;
  if (!d.has_schedule) {
    return `<div class="planner-empty">No scheduled medicines yet. Add one with set times and it'll show up here.</div>`;
  }
  const head = `<div class="planner-cell planner-cell--corner"></div>` +
    d.days.map(day => `<div class="planner-col-head${day.is_today ? ' is-today' : ''}">
        <span class="planner-wd">${day.is_today ? 'Today' : esc(day.weekday)}</span>
        <span class="planner-dnum">${day.day}</span>
      </div>`).join('');

  const rows = d.rows.map(row => {
    const timeCell = `<div class="planner-time"><span class="planner-hour">${esc(_mc12h(row.time))}</span><span class="planner-slotlbl">${esc(row.label)}</span></div>`;
    const cells = row.cells.map((meds, i) => {
      const today = d.days[i].is_today;
      const chips = meds.map(m => `<span class="planner-chip" title="${esc(m.name)}${m.dose ? ' · ' + esc(m.dose) : ''}${m.timing_text ? ' · ' + esc(m.timing_text) : ''}"><span class="planner-chip-icon">${esc(m.icon)}</span>${esc(m.name)}</span>`).join('');
      return `<div class="planner-cell${today ? ' is-today' : ''}">${chips || '<span class="planner-dash">–</span>'}</div>`;
    }).join('');
    return timeCell + cells;
  }).join('');

  return `<div class="planner-toolbar no-print">
      <button class="btn-outline" data-ev-click="printPillPlanner()" title="Print or save this week as a PDF">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 01-2-2v-5a2 2 0 012-2h16a2 2 0 012 2v5a2 2 0 01-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>
        Print / Save as PDF
      </button>
    </div>
    <div class="planner-scroll"><div class="planner-grid" style="grid-template-columns:88px repeat(${d.days.length},minmax(84px,1fr))">${head}${rows}</div></div>
    <div class="planner-note">Your upcoming plan. As-needed medicines aren't shown here — see the printable card for those.</div>`;
}

async function printPillPlanner() {
  const d = await fetch('/api/medicines/planner?days=7').then(r => r.json()).catch(() => null);
  if (!d || !d.has_schedule) { showToast('Nothing scheduled to print', 'error'); return; }
  const win = window.open('', '_blank', 'width=1000,height=760');
  if (!win) { showToast('Allow pop-ups to print the planner', 'error'); return; }
  win.document.write(buildPlannerPrintHtml(d));
  win.document.close();
  const btn = win.document.querySelector('.pp-print-btn');
  if (btn) btn.addEventListener('click', () => win.print());
}

function buildPlannerPrintHtml(d) {
  const esc = escapeHtml;
  const head = `<th class="pp-corner"></th>` + d.days.map(day =>
    `<th class="${day.is_today ? 'pp-today' : ''}"><div class="pp-wd">${day.is_today ? 'Today' : esc(day.weekday)}</div><div class="pp-dnum">${day.day}</div></th>`).join('');
  const rows = d.rows.map(row => {
    const cells = row.cells.map((meds, i) =>
      `<td class="${d.days[i].is_today ? 'pp-today' : ''}">${meds.map(m => `<div class="pp-chip">${esc(m.icon)} ${esc(m.name)}${m.dose ? ` <span class="pp-dose">${esc(m.dose)}</span>` : ''}</div>`).join('') || '<span class="pp-dash">–</span>'}</td>`).join('');
    return `<tr><th class="pp-time"><div class="pp-hour">${esc(_mc12h(row.time))}</div><div class="pp-lbl">${esc(row.label)}</div></th>${cells}</tr>`;
  }).join('');

  return `<!DOCTYPE html><html><head><meta charset="UTF-8">
<title>This week's medicines</title>
<style>
  *{box-sizing:border-box;margin:0;padding:0}
  body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:#F4F1EA;color:#1f2a24;padding:24px}
  .pp-sheet{max-width:960px;margin:0 auto;background:#fff;border-radius:14px;padding:28px 30px;box-shadow:0 2px 16px rgba(0,0,0,.06)}
  .pp-bar{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}
  .pp-title{font-size:26px;font-weight:800}
  .pp-sub{font-size:13px;color:#8a978f;margin-bottom:18px}
  .pp-print-btn{background:#5A9E70;color:#fff;border:none;border-radius:99px;padding:9px 18px;font-size:14px;font-weight:600;cursor:pointer}
  table{width:100%;border-collapse:collapse;table-layout:fixed}
  th,td{border:1px solid #ECE7DC;padding:8px 6px;vertical-align:top;text-align:center;font-size:12px}
  thead th{background:#F7F5F0}
  .pp-wd{font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.04em;color:#3c4b42}
  .pp-dnum{font-size:13px;color:#96a29a}
  .pp-today{background:#EAF3EE!important}
  .pp-time{text-align:left;width:104px}
  .pp-hour{font-size:14px;font-weight:800;color:#20362D}
  .pp-lbl{font-size:10px;text-transform:uppercase;letter-spacing:.05em;color:#96a29a}
  .pp-chip{font-size:12px;font-weight:600;color:#2b3a32;margin-bottom:4px;line-height:1.3}
  .pp-dose{font-weight:500;color:#5A9E70}
  .pp-dash{color:#c9d2cb}
  .pp-foot{font-size:11.5px;color:#a4afa7;margin-top:18px;text-align:center}
  @media print{ body{background:#fff;padding:0} .pp-sheet{box-shadow:none;border-radius:0;max-width:100%;padding:0} .pp-no-print{display:none!important} @page{size:A4 landscape;margin:12mm} }
</style></head><body>
<div class="pp-sheet">
  <div class="pp-bar"><div class="pp-title">📅 This week's medicines</div>
    <button class="pp-print-btn pp-no-print" type="button">🖨️ Print / Save as PDF</button></div>
  <div class="pp-sub">The next ${d.days.length} days. As-needed medicines aren't shown here.</div>
  <table><thead><tr>${head}</tr></thead><tbody>${rows}</tbody></table>
  <div class="pp-foot">Made with Arogo from your own list. Not a prescription.</div>
</div>
</body></html>`;
}

function _mc12h(hhmm) {
  const parts = String(hhmm).split(':');
  let h = parseInt(parts[0], 10);
  const m = parts[1] || '00';
  if (isNaN(h)) return hhmm;
  const ap = h < 12 ? 'AM' : 'PM';
  h = h % 12; if (h === 0) h = 12;
  return `${h}:${m} ${ap}`;
}

function buildMedCardHtml(d) {
  const esc = escapeHtml;
  const p = d.person || {};
  const emg = d.emergency || {};
  let gen = d.generated || '';
  try { gen = new Date(d.generated + 'T12:00:00').toLocaleDateString('en-US', {month:'long', day:'numeric', year:'numeric'}); } catch (e) {}

  const medLine = m => `
    <div class="mc-med">
      <span class="mc-med-icon">${esc(m.icon || '💊')}</span>
      <div class="mc-med-body">
        <div class="mc-med-name">${esc(m.name)}${m.dose ? ` <span class="mc-dose">${esc(m.dose)}</span>` : ''}</div>
        ${m.purpose ? `<div class="mc-med-purpose">for ${esc(m.purpose)}</div>` : ''}
      </div>
      ${medTimingText(m) ? `<span class="mc-tag">${m.timing === 'bedtime' ? '🌙' : m.timing === 'with_water' ? '💧' : m.timing === 'empty_stomach' ? '⏳' : '🍽️'} ${esc(medTimingText(m))}</span>` : ''}
    </div>`;

  const schedule = (d.schedule || []).length
    ? d.schedule.map(s => `
        <div class="mc-slot">
          <div class="mc-slot-time"><span class="mc-slot-hour">${esc(_mc12h(s.time))}</span><span class="mc-slot-label">${esc(s.label)}</span></div>
          <div class="mc-slot-meds">${s.meds.map(medLine).join('')}</div>
        </div>`).join('')
    : '<p class="mc-empty">No scheduled medicines.</p>';

  const prn = (d.as_needed || []).length
    ? `<div class="mc-section">
         <h2 class="mc-h2">As needed</h2>
         <div class="mc-slot-meds">${d.as_needed.map(medLine).join('')}</div>
       </div>`
    : '';

  const contacts = (emg.contacts || []).length
    ? emg.contacts.map(c => `<div class="mc-contact"><b>${esc(c.name || 'Contact')}</b>${c.phone ? ` — ${esc(c.phone)}` : ''}</div>`).join('')
    : '';
  const emgRows = [
    emg.blood_type ? `<div><span class="mc-emg-key">Blood type</span> ${esc(emg.blood_type)}</div>` : '',
    emg.allergies ? `<div><span class="mc-emg-key">Allergies</span> ${esc(emg.allergies)}</div>` : '',
    emg.conditions ? `<div><span class="mc-emg-key">Conditions</span> ${esc(emg.conditions)}</div>` : '',
  ].filter(Boolean).join('');
  const emergency = (emgRows || contacts)
    ? `<div class="mc-emg">
         <h2 class="mc-h2">In an emergency</h2>
         ${emgRows}
         ${contacts ? `<div class="mc-contacts">${contacts}</div>` : ''}
       </div>`
    : '';

  return `<!DOCTYPE html><html><head><meta charset="UTF-8">
<title>My medication card</title>
<style>
  *{box-sizing:border-box;margin:0;padding:0}
  body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
    background:#F4F1EA;color:#1f2a24;padding:24px;line-height:1.5}
  .mc-sheet{max-width:680px;margin:0 auto;background:#fff;border-radius:16px;
    padding:32px 36px;box-shadow:0 2px 16px rgba(0,0,0,.06)}
  .mc-bar{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}
  .mc-print-btn{background:#5A9E70;color:#fff;border:none;border-radius:99px;
    padding:10px 20px;font-size:15px;font-weight:600;cursor:pointer}
  .mc-title{font-size:30px;font-weight:800;letter-spacing:-.02em}
  .mc-person{font-size:19px;color:#3c4b42;margin-top:4px;font-weight:600}
  .mc-gen{font-size:13px;color:#8a978f;margin-top:2px;margin-bottom:22px}
  .mc-slot{display:flex;gap:18px;padding:14px 0;border-top:1px solid #ECE7DC}
  .mc-slot-time{flex:0 0 120px}
  .mc-slot-hour{display:block;font-size:20px;font-weight:800;color:#20362D}
  .mc-slot-label{display:block;font-size:12px;text-transform:uppercase;
    letter-spacing:.06em;color:#96a29a;margin-top:1px}
  .mc-slot-meds{flex:1;display:flex;flex-direction:column;gap:10px}
  .mc-med{display:flex;align-items:flex-start;gap:10px}
  .mc-med-icon{font-size:20px;line-height:1.3}
  .mc-med-body{flex:1}
  .mc-med-name{font-size:18px;font-weight:700}
  .mc-dose{font-weight:600;color:#5A9E70}
  .mc-med-purpose{font-size:14px;color:#6b7970;margin-top:1px}
  .mc-tag{font-size:13px;color:#946a3d;background:#F6ECDD;border-radius:99px;
    padding:3px 10px;white-space:nowrap;align-self:center}
  .mc-section{margin-top:8px;padding-top:8px;border-top:2px solid #ECE7DC}
  .mc-h2{font-size:15px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;
    color:#8a978f;margin:16px 0 10px}
  .mc-emg{margin-top:20px;background:#FBECEC;border:1px solid #F3D6D6;border-radius:12px;
    padding:16px 20px}
  .mc-emg .mc-h2{color:#B4443A;margin-top:0}
  .mc-emg>div{font-size:16px;margin-bottom:5px}
  .mc-emg-key{font-weight:700;color:#8a4a44;margin-right:6px}
  .mc-contacts{margin-top:8px}
  .mc-contact{font-size:16px;margin-bottom:3px}
  .mc-empty{color:#96a29a;font-size:15px;padding:12px 0}
  .mc-foot{font-size:12px;color:#a4afa7;margin-top:22px;text-align:center;line-height:1.6}
  @media print{
    body{background:#fff;padding:0}
    .mc-sheet{box-shadow:none;border-radius:0;max-width:100%;padding:0}
    .mc-no-print{display:none!important}
    @page{size:A4;margin:16mm}
  }
</style></head><body>
<div class="mc-sheet">
  <div class="mc-bar">
    <div class="mc-title">💊 My medicines</div>
    <button class="mc-print-btn mc-no-print" type="button">🖨️ Print / Save as PDF</button>
  </div>
  ${p.name ? `<div class="mc-person">${esc(p.name)}</div>` : ''}
  <div class="mc-gen">Updated ${esc(gen)}</div>
  ${schedule}
  ${prn}
  ${emergency}
  <div class="mc-foot">Keep this where you'll see it — the fridge, a wallet, a bedside drawer.<br>Made with Arogo from your own list. Not a prescription.</div>
</div>
</body></html>`;
}

async function openCalorieBreakdown() {
  const cb = await fetch('/api/calorie-balance').then(r => r.json()).catch(() => null);
  if (!cb) return;

  const t        = cb.today || {};
  const targets  = cb.targets || {};
  const profile  = cb.profile || {};
  const eaten    = t.eaten    || 0;
  const burned   = t.burned   || 0;
  // No profile → no target, and therefore no budget, no net and no percentage.
  // These used to fall back to 2000 and present the result as the user's own.
  const known    = cb.has_target && t.target;
  const target   = known ? t.target : null;
  const budget   = known ? (t.budget || target) : null;
  const net      = known ? (t.net || 0) : null;
  const pct      = known ? Math.min(Math.round((eaten / budget) * 100), 150) : 0;
  const today    = localToday();

  // Date label
  const d = new Date(today + 'T12:00:00');
  setText('cbd-date-label', d.toLocaleDateString('en-US', { weekday:'long', month:'long', day:'numeric' }));

  // Equation — show budget (target + burned) not raw target
  setText('cbd-target-val', known ? budget + ' kcal' : 'Not set');
  setText('cbd-eaten-val',  eaten  + ' kcal');
  setText('cbd-result-val', known ? Math.abs(net) + ' kcal' : '—');

  // Sub-label under target shows the breakdown when exercise exists
  const targetBlock = document.querySelector('.cbd-eq-block--target');
  if (targetBlock) {
    const sub = targetBlock.querySelector('.cbd-eq-label');
    if (sub) sub.textContent = burned > 0
      ? `Budget (${target} + ${burned} burned)`
      : 'Daily budget';
  }

  const resultBlock = document.getElementById('cbd-result-block');
  const resultLabel = document.getElementById('cbd-result-label');
  const resultIcon  = document.getElementById('cbd-result-icon');
  if (resultBlock) {
    resultBlock.className = 'cbd-eq-block cbd-eq-block--result ' +
      (net < -100 ? 'surplus' : net > 100 ? 'deficit' : 'balanced');
  }
  if (resultLabel) resultLabel.textContent = net < -100 ? 'Over budget' : net > 100 ? 'Remaining' : 'Balanced!';
  if (resultIcon)  resultIcon.textContent  = net < -100 ? '⚠️' : net > 100 ? '✅' : '⚖️';

  // Progress bar
  const fill = document.getElementById('cbd-progress-fill');
  if (fill) {
    fill.style.width = Math.min(pct, 100) + '%';
    fill.classList.toggle('over', pct > 105);
  }
  setText('cbd-progress-pct-label', `${pct}% of daily budget`);
  setText('cbd-target-label', budget + ' kcal');

  // Macro bars
  const foodDay = await fetch(`/api/food/log/${today}`).then(r => r.json()).catch(() => null);
  const totals  = foodDay?.summary?.totals || {};
  const macros  = [
    { id:'prot',  val: Math.round(totals.protein||0), target: targets.protein_g, unit:'g' },
    { id:'carb',  val: Math.round(totals.carbs||0),   target: targets.carbs_g,   unit:'g' },
    { id:'fat',   val: Math.round(totals.fat||0),     target: targets.fat_g,     unit:'g' },
    { id:'fiber', val: Math.round(totals.fiber||0),   target: targets.fiber_g,   unit:'g' },
  ];
  macros.forEach(m => {
    const bar = document.getElementById(`cbd-bar-${m.id}`);
    const val = document.getElementById(`cbd-${m.id}-val`);
    const has = hasTargets(targets) && m.target;
    if (bar) bar.style.width = has ? Math.min((m.val / m.target) * 100, 100).toFixed(0) + '%' : '0%';
    if (val) val.textContent = has ? `${m.val}${m.unit} / ${m.target}${m.unit}` : `${m.val}${m.unit}`;
  });

  // Workouts today
  const formulaEl = document.getElementById('cbd-formula-rows');
  if (formulaEl) {
    const goalLabels = {
      lose_fast: 'Lose fast (−500)', lose: 'Lose weight (−250)',
      maintain: 'Maintain (±0)', gain: 'Gain muscle (+250)', gain_fast: 'Bulk (+500)',
    };
    const workoutsHTML = t.workouts?.length
      ? t.workouts.map(w =>
          `<div class="cbd-formula-row">
            <span class="cbd-formula-key">🏃 ${escHtml(w.name || w.type)} (${w.duration} min)</span>
            <span class="cbd-formula-val" style="color:#22C55E">+${w.calories} kcal</span>
           </div>`).join('')
      : '';
    formulaEl.innerHTML = `
      <div class="cbd-formula-row">
        <span class="cbd-formula-key">BMR (${profile.gender||'male'}, ${profile.age||25} yrs, ${profile.weight_kg||70}kg, ${profile.height_cm||170}cm)</span>
        <span class="cbd-formula-val">${targets.bmr||'—'} kcal</span>
      </div>
      <div class="cbd-formula-row">
        <span class="cbd-formula-key">× Activity multiplier (${(profile.activity_level||'moderate').replace('_',' ')})</span>
        <span class="cbd-formula-val">${targets.tdee||'—'} kcal TDEE</span>
      </div>
      <div class="cbd-formula-row">
        <span class="cbd-formula-key">Goal adjustment</span>
        <span class="cbd-formula-val">${goalLabels[profile.goal||'maintain']}</span>
      </div>
      ${workoutsHTML}
      <div class="cbd-formula-row" style="border-top:1px solid var(--gray-100);margin-top:6px;padding-top:6px">
        <span class="cbd-formula-key" style="font-weight:600">Daily budget</span>
        <span class="cbd-formula-val highlight">${budget} kcal</span>
      </div>
    `;
  }

  // 7-day trend chart
  renderCalorieTrendChart(cb.daily || []);

  // CTA text
  const ctaEl = document.getElementById('cbd-cta-text');
  if (ctaEl) {
    const logCount = foodDay?.summary?.log_count || 0;
    if (logCount === 0) {
      ctaEl.textContent = "No food logged today yet. Add your meals to see the full picture.";
    } else if (net > 300) {
      ctaEl.textContent = `${net} kcal remaining. ${burned > 0 ? 'Great job burning ' + burned + ' kcal!' : 'Log a workout to earn more calories.'}`;
    } else if (net < -100) {
      ctaEl.textContent = `${Math.abs(net)} kcal over budget. A ${Math.round(Math.abs(net)/8)}-min walk would balance it.`;
    } else {
      ctaEl.textContent = "Nice balance today! You're right on target.";
    }
  }

  document.getElementById('calorie-breakdown-overlay').style.display = 'flex';
}


function renderSuggestions(el, suggestions) {
  if (suggestions.length === 0) {
    el.innerHTML = '<div style="color:var(--gray-400);font-size:13px;padding:8px 0">Log workouts to get personalized suggestions.</div>';
    return;
  }
  el.innerHTML = suggestions.map(s => `
    <div class="suggestion-item suggestion-item--${s.type}">
      <div class="sug-icon">${s.icon}</div>
      <div class="sug-text">${escHtml(s.text)}</div>
    </div>
  `).join('');
}

function renderWeeklyChart(days) {
  const el = document.getElementById('weekly-chart');
  if (!el) return;
  const entries = Object.entries(days);
  if (entries.length === 0) { el.innerHTML = '<div style="color:var(--gray-400);font-size:13px">No activity data yet</div>'; return; }
  const maxCal = Math.max(...entries.map(([,v]) => v.calories), 1);
  const maxMin = Math.max(...entries.map(([,v]) => v.duration), 1);
  const dayNames = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
  el.innerHTML = entries.map(([date, data], i) => {
    const calH = Math.round((data.calories / maxCal) * 90);
    const minH = Math.round((data.duration / maxMin) * 90);
    const isToday = date === localToday();
    return `
      <div class="week-bar-col">
        <div class="week-bar-wrap">
          <div class="week-bar week-bar--cal" style="height:${calH}px;opacity:${isToday?1:.7}" title="${data.calories} cal"></div>
          <div class="week-bar week-bar--min" style="height:${minH}px;opacity:${isToday?1:.7}" title="${data.duration} min"></div>
        </div>
        <div class="week-bar-label" style="font-weight:${isToday?'600':'400'};color:${isToday?'var(--teal-600)':'var(--gray-400)'}">${dayNames[i]}</div>
        <div class="week-bar-count">${data.calories > 0 ? data.calories : ''}</div>
      </div>`;
  }).join('');
}

// ── Reports ──
function openUploadModal() {
  document.getElementById('upload-modal-overlay').style.display = 'flex';
}

let _docTypeFilter = '';
let _visibleReports = [];   // last-fetched, for the visit pack

function setDocType(type) {
  _docTypeFilter = type;
  document.querySelectorAll('.doc-type-chip').forEach(c =>
    c.classList.toggle('active', (c.dataset.type || '') === type));
  loadReports();
}

async function loadReports() {
  const search = document.getElementById('search-input')?.value || '';
  const severity = document.getElementById('severity-filter')?.value || '';
  const tag = document.getElementById('tag-filter')?.value || '';
  const params = new URLSearchParams();
  if (search) params.set('search', search);
  if (severity) params.set('severity', severity);
  if (tag) params.set('tag', tag);
  if (_docTypeFilter) params.set('type', _docTypeFilter);
  const reports = await fetch(`/api/reports?${params}`).then(r => r.json()).catch(() => []);
  _visibleReports = reports;
  const label = document.getElementById('reports-count-label');
  if (label) label.textContent = `${reports.length} report${reports.length !== 1 ? 's' : ''}`;
  const grid = document.getElementById('reports-grid');
  if (!grid) return;
  if (reports.length === 0) {
    grid.innerHTML = `<div class="empty-state"><div class="empty-icon">📋</div><div class="empty-text">${t('No reports found')}</div><div class="empty-sub">${t('Upload your first medical report')}</div><button class="btn-primary" data-ev-click="openUploadModal()">${t('Upload Report')}</button></div>`;
    return;
  }
  grid.innerHTML = reports.map(r => `
    <div class="report-card" data-ev-click="openReportDetail(${JSON.stringify(r).replace(/"/g,'&quot;')})">
      <div class="report-card-header">
        <div class="report-card-file-icon">${fileIcon(r.file_ext)}</div>
        <div class="report-card-info">
          <div class="report-card-title" title="${escHtml(r.original_name)}">${escHtml(r.original_name)}</div>
          <div class="report-card-patient">${escHtml(r.patient_name)}${r.doctor ? ' · ' + escHtml(r.doctor) : ''}</div>
        </div>
        <span class="severity-badge sev-badge-${r.severity}">${r.severity}</span>
      </div>
      ${r.tags?.length ? `<div class="report-card-tags">${r.tags.slice(0,4).map(t=>`<span class="report-tag">${escHtml(t)}</span>`).join('')}${r.tags.length>4?`<span class="report-tag">+${r.tags.length-4}</span>`:''}</div>` : ''}
      ${r.analysis_notes ? `<div class="report-card-notes">${escHtml(r.analysis_notes)}</div>` : ''}
      <div class="report-card-footer">
        <span class="report-card-date">${r.report_date}</span>
        <div class="report-card-actions">
          <button class="btn-icon" title="Download" data-ev-click="event.stopPropagation();downloadFile('/uploads/${r.filename}',r.original_name)">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
          </button>
          <button class="btn-icon" title="Delete" data-ev-click="event.stopPropagation();deleteReport('${r.id}')">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/><path d="M10 11v6M14 11v6M9 6V4h6v2"/></svg>
          </button>
        </div>
      </div>
    </div>
  `).join('');
}

// Bundle the records currently in view (after any type/tag/search filter) into a
// one-page "visit pack" to print or save as PDF and carry to an appointment.
// Metadata only — the files themselves stay on the device; this is the index a
// doctor can scan in seconds.
function printVisitPack() {
  const list = _visibleReports || [];
  if (!list.length) { showToast(t('No records to include — adjust the filter'), 'info'); return; }
  const who = (_currentUser?.name || _currentUser?.email || '').replace(/</g, '');
  const rows = list.map(r => `
    <tr>
      <td>${escHtml(r.report_date || '—')}</td>
      <td>${escHtml(r.report_type || r.doc_bucket || '—')}</td>
      <td>${escHtml(r.original_name || '')}</td>
      <td>${escHtml(r.doctor || '')}</td>
      <td>${escHtml((r.analysis_notes || '').slice(0, 120))}</td>
    </tr>`).join('');
  const label = _docTypeFilter ? (' · ' + _docTypeFilter) : '';
  const html = `<!doctype html><html><head><meta charset="utf-8"><title>Visit pack</title>
    <style>
      body{font-family:-apple-system,Segoe UI,Roboto,sans-serif;color:#222;margin:32px;font-size:13px}
      h1{font-size:19px;margin:0 0 2px} .sub{color:#666;font-size:12px;margin-bottom:18px}
      table{border-collapse:collapse;width:100%} th,td{border:1px solid #ddd;padding:7px 9px;text-align:left;vertical-align:top}
      th{background:#f2f2f2;font-size:11px;text-transform:uppercase;letter-spacing:.03em}
      .foot{margin-top:18px;color:#888;font-size:11px}
    </style></head><body>
    <h1>${t('Records for my visit')}</h1>
    <div class="sub">${escHtml(who)}${label} · ${list.length} ${t('records')} · ${new Date().toLocaleDateString()}</div>
    <table><thead><tr>
      <th>${t('Date')}</th><th>${t('Type')}</th><th>${t('Document')}</th><th>${t('Doctor')}</th><th>${t('Notes')}</th>
    </tr></thead><tbody>${rows}</tbody></table>
    <div class="foot">${t('An index of records held in Arogo. Bring the originals if your doctor needs them.')}</div>
    </body></html>`;
  const w = window.open('', '_blank');
  if (!w) { showToast(t('Allow pop-ups to print the visit pack'), 'error'); return; }
  w.document.write(html); w.document.close();
  w.focus(); setTimeout(() => w.print(), 300);
}

function openReportDetail(r) {
  document.getElementById('rdetail-title').textContent = r.original_name;
  document.getElementById('rdetail-body').innerHTML = `
    <div style="display:flex;align-items:center;gap:12px;margin-bottom:18px">
      <div style="font-size:40px">${fileIcon(r.file_ext)}</div>
      <div>
        <div style="font-size:13px;color:var(--gray-400)">${escHtml(r.patient_name)}${r.doctor?' · Dr. '+escHtml(r.doctor):''}</div>
        <span class="severity-badge sev-badge-${r.severity}" style="margin-top:6px;display:inline-block">${r.severity}</span>
      </div>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:18px">
      ${[['Type',r.report_type],['Date',r.report_date],['Uploaded',new Date(r.upload_date).toLocaleDateString()],['Format',(r.file_ext||'').toUpperCase()]].map(([l,v])=>`<div><div style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--gray-400);margin-bottom:3px">${l}</div><div style="font-size:13.5px;font-family:'JetBrains Mono',monospace;color:var(--gray-800)">${v}</div></div>`).join('')}
    </div>
    ${r.tags?.length?`<div style="margin-bottom:18px"><div style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--gray-400);margin-bottom:8px">Tags</div><div style="display:flex;flex-wrap:wrap;gap:6px">${r.tags.map(t=>`<span class="report-tag">${escHtml(t)}</span>`).join('')}</div></div>`:''}
    ${r.analysis_notes?`<div style="margin-bottom:18px"><div style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--gray-400);margin-bottom:8px">Analysis Notes</div><div style="font-size:13.5px;line-height:1.7;color:var(--gray-700);background:var(--gray-25);border:1px solid var(--gray-100);border-radius:var(--r-md);padding:12px">${escHtml(r.analysis_notes)}</div></div>`:''}
    <div id="rdetail-readings" style="margin-bottom:18px"></div>
    <div class="form-actions" style="margin-top:16px;padding-top:16px">
      <button class="btn-primary" data-ev-click="downloadFile('/uploads/${r.filename}','${r.original_name}')">${t('Download')}</button>
      <button class="btn-danger" data-ev-click="deleteReport('${r.id}');closeModal('report-detail-overlay')">${t('Delete')}</button>
    </div>
  `;
  document.getElementById('report-detail-overlay').style.display = 'flex';
  loadReportReadings(r.id);
}

// ── Readings found in a report ──
// An uploaded report used to be a filing cabinet: it went in and nothing came
// back. We read the numbers out of it and *offer* them — the user confirms
// every one. Wrong data in a health chart is worse than no data, so nothing
// here writes a vital until they say so.
let _reportReadings = [], _reportReadingsDate = '';

function _readingValue(v) {
  return v.value2 ? `${+v.value1}/${+v.value2}` : `${+v.value1}`;
}

async function loadReportReadings(rid) {
  const box = document.getElementById('rdetail-readings');
  if (!box) return;
  box.innerHTML = `<div style="font-size:12.5px;color:var(--gray-400)">Checking this report for readings…</div>`;
  let d;
  try {
    d = await (await fetch(`/api/reports/${rid}/readings`)).json();
  } catch { box.innerHTML = ''; return; }

  _reportReadings = d.readings || [];
  _reportReadingsDate = d.date_key || localToday();

  if (!_reportReadings.length) {
    // Say why, rather than showing nothing and letting them wonder.
    box.innerHTML = d.reason
      ? `<div style="font-size:12.5px;color:var(--gray-400);background:var(--gray-25);border:1px solid var(--gray-100);border-radius:var(--r-md);padding:10px 12px">${escHtml(d.reason)}</div>`
      : '';
    return;
  }

  box.innerHTML = `
    <div style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:var(--gray-400);margin-bottom:8px">
      Readings in this report
    </div>
    <div style="font-size:12.5px;color:var(--gray-500);margin-bottom:10px">
      We read these off the report — check them against it, then add the ones you want.
      Nothing is saved to your vitals until you do.
    </div>
    <div style="display:flex;flex-direction:column;gap:8px">
      ${_reportReadings.map((v, i) => `
        <label style="display:flex;gap:10px;align-items:flex-start;background:var(--gray-25);border:1px solid var(--gray-100);border-radius:var(--r-md);padding:10px 12px;cursor:pointer">
          <input type="checkbox" class="rdetail-reading-cb" data-idx="${i}" checked style="margin-top:3px">
          <span style="flex:1;min-width:0">
            <span style="font-size:13.5px;color:var(--gray-800)">
              <b>${escHtml(v.label)}</b>
              <span style="font-family:'JetBrains Mono',monospace">${_readingValue(v)}</span>
              ${escHtml(v.unit || '')}
              ${v.note ? `<span style="color:var(--gray-400);font-size:11.5px"> · ${escHtml(v.note)}</span>` : ''}
            </span>
            <span style="display:block;font-size:11.5px;color:var(--gray-400);margin-top:3px;overflow-wrap:anywhere">
              from the report: “${escHtml(v.context || '')}”
            </span>
          </span>
        </label>`).join('')}
    </div>
    <button class="btn-secondary" style="margin-top:10px" data-ev-click="addReportReadings('${rid}')"
            id="rdetail-add-readings">${t('Add checked to vitals')}</button>
  `;
}

async function addReportReadings() {
  const btn = document.getElementById('rdetail-add-readings');
  const picked = [..._reportReadings.keys()].filter(i =>
    document.querySelector(`.rdetail-reading-cb[data-idx="${i}"]`)?.checked);
  if (!picked.length) { showToast('Nothing checked to add', 'error'); return; }
  if (btn) { btn.disabled = true; btn.textContent = 'Adding…'; }

  let added = 0;
  for (const i of picked) {
    const v = _reportReadings[i];
    try {
      const r = await fetch('/api/vitals', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: v.type, value1: v.value1, value2: v.value2, unit: v.unit,
          // Date it to the day of the test, not the day it was uploaded.
          date_key: _reportReadingsDate,
          notes: 'From lab report',
        }),
      });
      if ((await r.json()).success) added++;
    } catch { /* counted as not added */ }
  }

  // Report honestly: if some failed the range check, don't claim they landed.
  showToast(added === picked.length
      ? `Added ${added} reading${added > 1 ? 's' : ''} to vitals`
      : `Added ${added} of ${picked.length} — check the rest by hand`,
    added ? 'success' : 'error');
  if (added) { closeModal('report-detail-overlay'); loadDashboard(); }
  else if (btn) { btn.disabled = false; btn.textContent = 'Add checked to vitals'; }
}

function deleteReport(id) {
  undoable('Deleting report…', async () => {
    await fetch(`/api/reports/${id}`, { method:'DELETE' });
    loadReports();
    loadDashboard();
  });
}

// ── Upload Form ──
function setupDropzone() {
  const dz = document.getElementById('dropzone');
  const fi = document.getElementById('file-input');
  if (!dz || !fi) return;
  dz.addEventListener('click', e => { if (e.target === dz || e.target.closest('.dropzone') === dz) fi.click(); });
  fi.addEventListener('change', () => { if (fi.files[0]) setFile(fi.files[0]); });
  dz.addEventListener('dragover', e => { e.preventDefault(); dz.classList.add('drag-over'); });
  dz.addEventListener('dragleave', () => dz.classList.remove('drag-over'));
  dz.addEventListener('drop', e => { e.preventDefault(); dz.classList.remove('drag-over'); if (e.dataTransfer.files[0]) setFile(e.dataTransfer.files[0]); });
}

function setFile(file) {
  selectedFile = file;
  const icons = { pdf:'📄', png:'🖼️', jpg:'🖼️', jpeg:'🖼️', txt:'📝', csv:'📊' };
  const ext = file.name.split('.').pop().toLowerCase();
  document.getElementById('file-preview-icon').textContent = icons[ext] || '📄';
  document.getElementById('file-preview-name').textContent = file.name;
  document.getElementById('file-preview-size').textContent = fmtBytes(file.size);
  document.getElementById('dropzone').style.display = 'none';
  document.getElementById('file-preview').style.display = 'flex';
}

function clearFile() {
  selectedFile = null;
  document.getElementById('file-input').value = '';
  document.getElementById('dropzone').style.display = 'flex';
  document.getElementById('file-preview').style.display = 'none';
}

function setupTagPicker() {
  document.querySelectorAll('.tag-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const tag = btn.dataset.tag;
      if (btn.classList.contains('selected')) { selectedTags = selectedTags.filter(t=>t!==tag); btn.classList.remove('selected'); }
      else { selectedTags.push(tag); btn.classList.add('selected'); }
      renderSelectedTags();
    });
  });
}

function addCustomTag() {
  const input = document.getElementById('custom-tag-input');
  const val = input.value.trim();
  if (val && !selectedTags.includes(val)) { selectedTags.push(val); renderSelectedTags(); input.value = ''; }
}

document.getElementById('custom-tag-input')?.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); addCustomTag(); } });

function renderSelectedTags() {
  const el = document.getElementById('selected-tags');
  if (!el) return;
  el.innerHTML = selectedTags.map(tag => `
    <span class="selected-tag">${escHtml(tag)}<span class="selected-tag-remove" data-ev-click="removeTag('${escHtml(tag)}')">×</span></span>
  `).join('');
}

function removeTag(tag) {
  selectedTags = selectedTags.filter(t => t !== tag);
  const btn = document.querySelector(`.tag-btn[data-tag="${tag}"]`);
  if (btn) btn.classList.remove('selected');
  renderSelectedTags();
}

function setupUploadForm() {
  document.getElementById('upload-form')?.addEventListener('submit', async e => {
    e.preventDefault();
    if (!selectedFile) { showToast('Please select a file', 'error'); return; }
    const form = e.target;
    const fd = new FormData();
    fd.append('file', selectedFile);
    ['patient_name','doctor','report_type','report_date','analysis_notes'].forEach(n => fd.append(n, form[n]?.value || ''));
    fd.append('severity', form.querySelector('input[name="severity"]:checked')?.value || 'normal');
    selectedTags.forEach(t => fd.append('tags', t));
    const btn = document.getElementById('submit-btn');
    btn.disabled = true; btn.textContent = 'Uploading…';
    try {
      const res = await fetch('/api/upload', { method:'POST', body:fd });
      const data = await res.json();
      if (data.success) {
        showToast('Report uploaded!', 'success');
        form.reset(); clearFile(); selectedTags = []; renderSelectedTags();
        document.querySelectorAll('.tag-btn.selected').forEach(b => b.classList.remove('selected'));
        setDates();
        closeModal('upload-modal-overlay');
        loadReports();
        // If the report has readings in it, this is the moment to offer them —
        // they just held the document; they'd never think to reopen it later.
        // Quiet when there's nothing to add: no modal, no interruption.
        try {
          const rd = await (await fetch(`/api/reports/${data.report.id}/readings`)).json();
          if (rd.readings?.length) openReportDetail(data.report);
        } catch { /* the report is saved either way */ }
      } else showToast(data.error || 'Upload failed', 'error');
    } catch { showToast('Network error', 'error'); }
    finally { btn.disabled = false; btn.textContent = 'Upload & Save'; }
  });
}

// ── Medicines ──
function openMedModal() {
  document.getElementById('med-modal-overlay').style.display = 'flex';
}

async function loadMedicines() {
  const [meds, doses] = await Promise.all([
    fetch('/api/medicines').then(r => r.json()).catch(() => []),
    fetch('/api/medicines/today').then(r => r.json()).catch(() => [])
  ]);
  renderTodayTimeline(doses);
  renderMedicinesGrid(meds);
  // cache active names so the add-medicine form can warn about duplicates
  window._activeMedNames = (Array.isArray(meds) ? meds : [])
    .filter(m => m.active).map(m => (m.name || '').trim().toLowerCase());
  const mc = document.getElementById('med-count');
  if (mc) mc.textContent = `${meds.filter(m=>m.active).length} active`;
  loadMedAdherence();
  loadAdherenceForecast();
  loadMissedDoses();
  loadAdherenceTimeOfDay();
  loadAdherenceWeekday();
  loadNewMedWatch();
  loadExpiringMeds();
  loadPillBurden();
  _applyCollapseState('med-insights');
  _watchInsightGroups();
  loadPrnFrequency();
  loadEffectiveness();
  loadResponsiveness();
  loadSkipReasons();
  loadMedCost();
  loadDoseCalendar();
  loadTimingConflicts();
}

// Timing hygiene: flag same-time meds with conflicting food instructions.
async function loadTimingConflicts() {
  const el = document.getElementById('timing-conflicts-banner');
  if (!el) return;
  const d = await fetch('/api/medicines/timing-conflicts', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {conflicts:[]}).catch(() => ({conflicts:[]}));
  const conflicts = d.conflicts || [];
  if (!conflicts.length) { el.innerHTML = ''; return; }
  const rows = conflicts.map(c => {
    const w = c.with_food.map(m => escHtml(m.name)).join(', ');
    const wo = c.without_food.map(m => escHtml(m.name)).join(', ');
    return `<div class="tc-row">
        <span class="tc-time">${escHtml(c.time)}</span>
        <span class="tc-detail">${tformat('%1 (with food) vs %2 (empty stomach)', w, wo)}</span>
      </div>`;
  }).join('');
  el.innerHTML = `<div class="panel tc-panel" style="padding:14px 18px;margin-bottom:14px">
      <div class="tc-head">⏱️ ${t('Timing worth a glance')}</div>
      ${rows}
      <div class="tc-note">${t('These are scheduled at the same time with opposite food instructions — you may want to space them out or ask your pharmacist. Not a safety warning.')}</div>
    </div>`;
}

// ── Monthly medicine cost ──
async function loadMedCost() {
  const el = document.getElementById('med-cost-summary');
  if (!el) return;
  const d = await fetch('/api/medicines/cost').then(r => r.json()).catch(() => null);
  if (!d || !d.count) { el.style.display = 'none'; return; }
  const fmt = n => '₹' + (Math.round(n * 100) / 100).toLocaleString('en-IN');
  el.style.display = 'block';
  el.innerHTML = `<div class="med-cost-card">
    <span class="med-cost-total">${fmt(d.total)}<span class="med-cost-per">/month</span></span>
    <span class="med-cost-sub">across ${d.count} priced medicine${d.count !== 1 ? 's' : ''}</span>
  </div>`;
}

// ── Which doses you miss most (per-slot adherence, worst first) ──
async function loadMissedDoses() {
  const el = document.getElementById('med-missed-section');
  if (!el) return;
  const d = await fetch('/api/medicines/adherence-breakdown?days=30')
    .then(r => r.json()).catch(() => null);
  el.innerHTML = d ? renderMissedDoses(d) : '';
}

// ── Reminder responsiveness (how fast you log after a dose is due) ──
const _RESP_COLOR = { early:'#3B82F6', ontime:'#22C55E', late:'#F59E0B', very_late:'#EF4444' };
async function loadResponsiveness() {
  const el = document.getElementById('responsiveness-section');
  if (!el) return;
  const d = await fetch('/api/medicines/adherence/responsiveness?days=30').then(r => r.json()).catch(() => null);
  if (!d || !d.has_data || d.count < 3) { el.innerHTML = ''; return; }   // too few to say anything
  const withCount = d.buckets.filter(b => b.count > 0);
  const bars = withCount.map(b =>
    `<div class="resp-seg" style="flex:${b.count};background:${_RESP_COLOR[b.key]}" title="${t(b.label)}: ${b.count}"></div>`).join('');
  const legend = withCount.map(b =>
    `<span class="resp-leg"><i style="background:${_RESP_COLOR[b.key]}"></i>${t(b.label)} ${b.count}</span>`).join('');
  const median = d.median_delay_min;
  const medLine = median == null ? '' : (median <= 0
    ? t('You usually log doses right on time or early.')
    : tformat('You usually log a dose about %1 min after it’s due.', median));
  el.innerHTML = `<div class="panel" style="padding:16px 18px">
      <div class="panel-header" style="padding:0 0 8px"><h2 class="panel-title">⏱️ ${t('How quickly you log doses')}</h2><span class="panel-badge">${t('last 30 days')}</span></div>
      ${d.ontime_pct != null ? `<div class="resp-head">${tformat('%1% logged on time', d.ontime_pct)}</div>` : ''}
      <div class="resp-bar">${bars}</div>
      <div class="resp-legend">${legend}</div>
      ${medLine ? `<div class="resp-median">${escHtml(medLine)}</div>` : ''}
    </div>`;
}

// ── Adherence goal + month-end forecast ──
async function loadAdherenceForecast() {
  const el = document.getElementById('adherence-forecast-section');
  if (!el) return;
  const d = await fetch('/api/medicines/adherence/forecast').then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { el.innerHTML = ''; return; }
  const cur = d.current_pct != null ? d.current_pct : 0;
  const goalVal = d.goal_pct != null ? d.goal_pct : '';
  let statusLine;
  if (d.goal_pct == null) {
    statusLine = `<div class="afc-status">${t('Set a monthly goal to track it')}</div>`;
  } else if (d.on_track) {
    statusLine = `<div class="afc-status afc-ok">✓ ${tformat('On track for your %1% goal', d.goal_pct)}${d.misses_allowed != null ? ` · ${tformat('room to miss %1 more', d.misses_allowed)}` : ''}</div>`;
  } else {
    statusLine = `<div class="afc-status afc-behind">${tformat('Behind your %1% goal', d.goal_pct)}${d.misses_allowed === 0 ? ' · ' + t('take every remaining dose') : ''}</div>`;
  }
  const ringColor = d.goal_pct != null && !d.on_track ? '#F59E0B' : 'var(--teal-500,#14B8A6)';
  el.innerHTML = `<div class="panel afc-panel" style="padding:16px 18px">
      <div class="panel-header" style="padding:0 0 8px"><h2 class="panel-title">🎯 ${t('This month')}</h2></div>
      <div class="afc-body">
        <div class="afc-ring" style="background:conic-gradient(${ringColor} ${cur * 3.6}deg, var(--gray-100,#F0EDE6) 0)">
          <div class="afc-ring-in"><b>${cur}%</b><span>${t('so far')}</span></div>
        </div>
        <div class="afc-info">
          <div class="afc-proj">${tformat('At this rate: ~%1% by month-end', d.projected_pct != null ? d.projected_pct : cur)}</div>
          <div class="afc-sub">${tformat('%1 of %2 doses taken · %3 left this month', d.taken_to_date, d.scheduled_to_date, d.remaining_scheduled)}</div>
          ${statusLine}
          <div class="afc-goal-row">
            <label>${t('Goal')}</label>
            <input type="number" id="afc-goal-input" class="form-input" min="1" max="100" value="${goalVal}" placeholder="90" style="width:70px">
            <span>%</span>
            <button class="btn-outline btn-sm" data-ev-click="saveAdherenceGoal()">${t('Save')}</button>
          </div>
        </div>
      </div>
    </div>`;
}

async function saveAdherenceGoal() {
  const raw = document.getElementById('afc-goal-input')?.value;
  const r = await fetch('/api/medicines/adherence/goal', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ pct: raw === '' ? null : parseInt(raw, 10) })
  }).then(r => r.json()).catch(() => null);
  if (r && r.success) { showToast(r.goal_pct ? t('Goal set 🎯') : t('Goal cleared')); loadAdherenceForecast(); }
  else showToast(t('Could not save'), 'error');
}

// ── Adherence by part of day (coarser, cross-medicine lens) ──
const _TOD_ICON = { morning: '🌅', afternoon: '☀️', evening: '🌆', night: '🌙' };

async function loadAdherenceTimeOfDay() {
  const el = document.getElementById('med-tod-section');
  if (!el) return;
  const d = await fetch('/api/medicines/adherence/timeofday?days=30').then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { el.innerHTML = ''; return; }
  const withDoses = d.buckets.filter(b => b.total > 0);
  if (!withDoses.length) { el.innerHTML = ''; return; }
  const barColor = p => p == null ? 'var(--gray-200)' : p >= 90 ? 'var(--teal-500,#5A9E70)' : p >= 70 ? '#F59E0B' : '#EF4444';
  const rows = withDoses.map(b => `
    <div class="tod-row${b.bucket === d.worst ? ' tod-row--worst' : ''}">
      <div class="tod-label">${_TOD_ICON[b.bucket] || ''} ${t(b.label)}</div>
      <div class="tod-bar-wrap"><div class="tod-bar" style="width:${b.pct == null ? 0 : b.pct}%;background:${barColor(b.pct)}"></div></div>
      <div class="tod-stat">${b.pct == null ? '—' : b.pct + '%'}<span class="tod-sub">${b.taken}/${b.total}</span></div>
    </div>`).join('');
  const worstLine = d.worst
    ? `<div class="tod-note">${tformat('Your %1 doses are the easiest to miss.', t(_TOD_LABEL(d.worst)))}</div>`
    : '';
  el.innerHTML = `<div class="panel" style="padding:18px 20px">
      <div class="panel-header"><h2 class="panel-title">🕑 ${t('When you miss doses')}</h2><span class="panel-badge">${t('last 30 days')}</span></div>
      ${rows}
      ${worstLine}
    </div>`;
}
function _TOD_LABEL(bucket) { return { morning: 'morning', afternoon: 'afternoon', evening: 'evening', night: 'night' }[bucket] || bucket; }

// I4: Adherence by weekday — the "weekends slip" cut the time-of-day view can't
// show. 90-day window (more than the 30-day TOD view, so each weekday has enough
// doses to mean something). Only renders days that actually had scheduled doses.
async function loadAdherenceWeekday() {
  const el = document.getElementById('med-weekday-section');
  if (!el) return;
  const d = await fetch('/api/medicines/adherence/weekday?days=90').then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { el.innerHTML = ''; return; }
  const withDoses = d.weekdays.filter(b => b.total > 0);
  if (!withDoses.length) { el.innerHTML = ''; return; }
  const barColor = p => p == null ? 'var(--gray-200)' : p >= 90 ? 'var(--teal-500,#5A9E70)' : p >= 70 ? '#F59E0B' : '#EF4444';
  const rows = withDoses.map(b => `
    <div class="tod-row${b.weekday === d.worst ? ' tod-row--worst' : ''}">
      <div class="tod-label">${t(b.label)}</div>
      <div class="tod-bar-wrap"><div class="tod-bar" style="width:${b.pct == null ? 0 : b.pct}%;background:${barColor(b.pct)}"></div></div>
      <div class="tod-stat">${b.pct == null ? '—' : b.pct + '%'}<span class="tod-sub">${b.taken}/${b.total}</span></div>
    </div>`).join('');
  const worstLine = d.worst != null
    ? `<div class="tod-note">${tformat('%1 is your hardest day to keep up.', t(_WEEKDAY_NAME(d.worst)))}</div>`
    : '';
  el.innerHTML = `<div class="panel" style="padding:18px 20px">
      <div class="panel-header"><h2 class="panel-title">📆 ${t('Which day you miss')}</h2><span class="panel-badge">${t('last 90 days')}</span></div>
      ${rows}
      ${worstLine}
    </div>`;
}
function _WEEKDAY_NAME(i) {
  return ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i] || '';
}

// J5: "Is it working?" — a periodic 1-5 self-rating per medicine, with a trend.
// Captures the patient's own read; purely self-report, not a clinical measure.
async function loadEffectiveness() {
  const el = document.getElementById('effectiveness-section');
  if (!el) return;
  const [meds, eff] = await Promise.all([
    fetch('/api/medicines', {credentials:'same-origin'}).then(r => r.json()).catch(() => []),
    fetch('/api/medicines/effectiveness?days=180', {credentials:'same-origin'}).then(r => r.json()).catch(() => null),
  ]);
  const active = (Array.isArray(meds) ? meds : []).filter(m => m.active && m.frequency !== 'as_needed');
  if (!active.length) { el.innerHTML = ''; return; }
  const byMed = Object.fromEntries(((eff && eff.meds) || []).map(m => [m.id, m]));
  const arrow = { up: '▲', down: '▼', flat: '→' };
  const arrowCls = { up: 'eff-up', down: 'eff-down', flat: 'eff-flat' };
  const rows = active.map(m => {
    const e = byMed[m.id];
    const dots = [1,2,3,4,5].map(n =>
      `<button type="button" class="eff-dot${e && n <= e.latest ? ' on' : ''}"
         data-ev-click="rateMed('${m.id}',${n})" title="${tformat('Rate %1/5', n)}" aria-label="${tformat('Rate %1 of 5', n)}"></button>`).join('');
    const summary = e
      ? `<span class="eff-summary"><span class="${arrowCls[e.direction]}">${arrow[e.direction]}</span>
           ${tformat('avg %1', e.average)} · ${tformat('%1 rating(s)', e.count)}</span>`
      : `<span class="eff-summary eff-none">${t('not rated yet')}</span>`;
    return `<div class="eff-row">
        <div class="eff-name">💊 ${escapeHtml(m.name)}</div>
        <div class="eff-dots">${dots}</div>
        ${summary}
      </div>`;
  }).join('');
  el.innerHTML = `<div class="panel" style="padding:18px 20px">
      <div class="panel-header"><h2 class="panel-title">📈 ${t('Is it working?')}</h2></div>
      <p style="font-size:12px;color:var(--gray-500);margin:2px 0 12px">
        ${t('Your own sense of how well each medicine is working, 1–5. It’s a self-check to share with your doctor — not a measure of the drug.')}</p>
      ${rows}
    </div>`;
}

async function rateMed(mid, rating) {
  const r = await fetch('/api/medicines/effectiveness', {
    method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
    body: JSON.stringify({medicine_id: mid, rating, date_key: localToday()}),
  }).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(t('Rating saved'), 'success'); loadEffectiveness(); }
  else showToast((r && r.error) || t('Could not save'), 'error');
}

// J4: PRN / rescue-med frequency — how often you reach for an as-needed med,
// by week, with a gentle "more than usual" flag. Own data; a prompt to mention
// to a doctor, never a diagnosis.
async function loadPrnFrequency() {
  const el = document.getElementById('prn-frequency-section');
  if (!el) return;
  const d = await fetch('/api/medicines/prn-frequency?weeks=8', {credentials:'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { el.innerHTML = ''; return; }
  const rows = d.meds.map(m => {
    const spark = _miniSpark(m.weekly);
    const base = m.baseline_per_week == null
      ? t('no baseline yet')
      : tformat('usually ~%1/wk', m.baseline_per_week);
    const flag = m.elevated
      ? `<span class="prn-flag">⚠️ ${t('more than usual')}</span>` : '';
    return `<div class="prn-row">
        <div class="prn-name">💊 ${escapeHtml(m.name)} ${flag}</div>
        <div class="prn-spark">${spark}</div>
        <div class="prn-stat"><b>${m.this_week}</b> ${t('this week')}<span class="prn-base">${base}</span></div>
      </div>`;
  }).join('');
  el.innerHTML = `<div class="panel" style="padding:18px 20px">
      <div class="panel-header"><h2 class="panel-title">🌡️ ${t('As-needed medicine use')}</h2>
        <span class="panel-badge">${t('last 8 weeks')}</span></div>
      <p style="font-size:12px;color:var(--gray-500);margin:2px 0 12px">
        ${t('How often you’ve reached for each as-needed medicine. A rise can be worth mentioning to your doctor.')}</p>
      ${rows}
    </div>`;
}

// A tiny inline bar sparkline from an array of counts.
function _miniSpark(vals) {
  const max = Math.max(...vals, 1);
  return `<div class="spark-bars">` + vals.map(v =>
    `<span class="spark-bar" style="height:${Math.max(2, Math.round(v / max * 20))}px" title="${v}"></span>`).join('') + `</div>`;
}

// I5: New-medication side-effect watch. For meds started recently, shows the
// symptoms logged since — explicitly framed as TIMING, not proof of cause, so
// it's a "mention this to your doctor" prompt, never a diagnosis.
async function loadNewMedWatch() {
  const el = document.getElementById('new-med-watch-section');
  if (!el) return;
  const d = await fetch('/api/medicines/new-med-watch?days=45', {credentials:'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!d || !d.has_data || !d.meds.length) { el.innerHTML = ''; return; }
  const cards = d.meds.map(m => {
    const chips = m.symptoms.map(s => {
      const times = s.count > 1 ? ` ·${s.count}×` : '';
      return `<span class="nmw-chip">${escapeHtml(s.name)}${times}</span>`;
    }).join('');
    const since = m.days_since != null
      ? tformat('started %1 days ago', m.days_since)
      : tformat('started %1', m.start_date);
    return `<div class="nmw-med">
        <div class="nmw-med-head">
          <span class="nmw-med-name">💊 ${escapeHtml(m.name)}</span>
          <span class="nmw-med-since">${since}</span>
        </div>
        <div class="nmw-chips">${chips}</div>
      </div>`;
  }).join('');
  el.innerHTML = `<div class="panel nmw-panel">
      <div class="panel-header">
        <h2 class="panel-title">🔎 ${t('Since starting a new medicine')}</h2>
      </div>
      <p class="nmw-note">${t('Symptoms you’ve logged since a recent medicine started. This is timing only — it does not mean the medicine caused them. Worth mentioning to your doctor.')}</p>
      ${cards}
    </div>`;
}

// A timely, per-slot adherence nudge (last 7 days) — what's slipping NOW, above
// the 30-day pattern. Localized from structured fields; '' when nothing to say.
function renderAdherenceNudge(n) {
  if (!n || !n.kind) return '';
  const esc = escHtml;
  const label = t(n.label || 'Anytime');
  const who = `${esc(n.icon || '💊')} ${esc(n.med_name)}`;
  let lead, detail;
  if (n.kind === 'slipping') {
    lead = tformat('Your %1 dose is slipping', label);
    detail = tformat('%1 — %2% this week, down from %3%', who, n.recent_pct, n.prev_pct);
  } else {
    lead = tformat('Your %1 dose is easy to miss lately', label);
    detail = tformat('%1 — missed %2 of the last %3', who, n.missed, n.scheduled);
  }
  return `<div class="panel adh-nudge">
    <div class="adh-nudge-icon">📉</div>
    <div class="adh-nudge-body">
      <div class="adh-nudge-lead">${esc(lead)}</div>
      <div class="adh-nudge-detail">${detail}</div>
      <div class="adh-nudge-tip">${t('Try moving its reminder a little earlier, or a few minutes before the dose.')}</div>
    </div>
  </div>`;
}

function renderMissedDoses(d) {
  const esc = escHtml;
  const nudge = renderAdherenceNudge(d.nudge);
  // Nothing worth showing until there's a slot with real misses — but a recent
  // nudge can still stand on its own.
  if (!d.has_data || !d.worst) { return nudge; }
  const barColor = p => p >= 90 ? 'var(--teal-500,#5A9E70)' : p >= 70 ? '#F59E0B' : '#EF4444';
  const t12 = _mc12h;

  // Show the weakest few slots (those with any misses), best-effort up to 5.
  const missed = d.slots.filter(s => s.missed > 0).slice(0, 5);
  const w = d.worst;

  const rows = missed.map(s => `
    <div class="miss-row">
      <div class="miss-slot">
        <span class="miss-time">${esc(t12(s.time))}</span>
        <span class="miss-name">${esc(s.icon)} ${esc(s.med_name)}</span>
      </div>
      <div class="miss-bar-wrap"><div class="miss-bar" style="width:${s.pct}%;background:${barColor(s.pct)}"></div></div>
      <div class="miss-stat">${s.pct}%<span class="miss-sub">${s.taken}/${s.total}</span></div>
    </div>`).join('');

  const wBold = `<b>${esc(t12(w.time))} ${esc(w.med_name)}</b>`;
  return nudge + `<div class="panel">
    <div class="panel-header">
      <h2 class="panel-title">${t('🎯 Doses you miss most')}</h2>
      <span class="panel-badge">${tformat('Last %1 days', d.days)}</span>
    </div>
    <div style="padding:14px 16px">
      <div class="miss-headline">${tformat('Your %1 dose is the easiest to forget — taken %2% of the time (%3 missed).', wBold, w.pct, w.missed)}${w.timing_text ? ' ' + tformat('Take it %1.', esc(w.timing_text)) : ''}</div>
      <div class="miss-list">${rows}</div>
      <p class="miss-note">${t('Tip: if a slot keeps slipping, try moving its time or turning on a reminder for it.')}</p>
    </div>
  </div>`;
}

// ── Dose calendar (month heatmap of taken vs missed) ────────────────
let _calRange = 35;   // 35 = 5-week grid; 364 = year heatmap

function setDoseCalRange(days) {
  _calRange = days;
  loadDoseCalendar();
}

const _CAL_COLOR = { all: 'var(--teal-500)', partial: '#F59E0B', missed: '#EF4444', none: 'var(--gray-100)' };

async function loadDoseCalendar() {
  const el = document.getElementById('med-calendar-section');
  if (!el) return;
  const isYear = _calRange >= 300;
  const d = await fetch('/api/medicines/calendar?days=' + _calRange, { credentials: 'same-origin' })
    .then(r => r.json()).catch(() => ({ days: [] }));
  const days = d.days || [];
  // Nothing scheduled anywhere in the window → don't show an empty grid.
  if (!days.length || days.every(x => x.status === 'none')) { el.innerHTML = ''; return; }
  const LABEL = { all: t('All taken'), partial: t('Some'), missed: t('Missed'), none: t('None due') };

  // Motivational streak — consecutive perfect days (every scheduled dose taken).
  const s = d.streak || {};
  let streakBanner = '';
  if ((s.streak || 0) >= 2) {
    const extra = (s.best && s.streak >= s.best && s.best >= 3) ? ' · ' + t('your best yet!')
                : (s.best > s.streak) ? ' · ' + tformat('best %1', s.best) : '';
    streakBanner = `<div class="adh-streak"><span class="adh-streak-flame">🔥</span>
      <span>${tformat('%1-day streak', s.streak)} · <b>${t('every dose taken')}</b>${extra}</span>
      <button class="adh-streak-share" title="${t('Share')}" data-ev-click="shareStreak(${s.streak})">${t('Share')}</button></div>`;
  }

  const toggle = `<div class="cal-range-toggle">
      <button class="cal-range${!isYear ? ' selected' : ''}" data-ev-click="setDoseCalRange(35)">${t('5 weeks')}</button>
      <button class="cal-range${isYear ? ' selected' : ''}" data-ev-click="setDoseCalRange(364)">${t('Year')}</button>
    </div>`;

  const grid = isYear ? _renderCalYear(days) : _renderCalWeeks(days);
  const badge = isYear ? t('last year') : t('last 5 weeks');

  el.innerHTML =
    `<div class="panel" style="padding:18px 20px">
       <div class="panel-header"><h2 class="panel-title">${t('📅 Dose calendar')}</h2>${toggle}</div>
       ${streakBanner}
       ${grid}
       <div id="cal-day-detail" class="cal-detail"></div>
       <div class="cal-legend"><span class="cal-leg-badge">${badge}</span>${Object.entries(LABEL).map(([k, l]) => `<span class="cal-leg"><i style="background:${_CAL_COLOR[k]}"></i>${l}</span>`).join('')}</div>
     </div>`;
}

function _renderCalWeeks(days) {
  const first = new Date(days[0].date + 'T00:00:00');
  const cells = [];
  for (let i = 0; i < first.getDay(); i++) cells.push('<div class="cal-cell cal-cell--empty"></div>');
  for (const day of days) {
    const dt = new Date(day.date + 'T00:00:00');
    const tip = `${dt.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' })} — ${day.total ? `${day.taken}/${day.total} taken` : 'nothing scheduled'}`;
    cells.push(`<div class="cal-cell" style="background:${_CAL_COLOR[day.status]}" title="${tip}" data-ev-click="showCalDay('${day.date}',${day.taken},${day.total})"></div>`);
  }
  return `<div class="cal-weekdays">${['S','M','T','W','T','F','S'].map(w => `<span>${w}</span>`).join('')}</div>
     <div class="cal-grid">${cells.join('')}</div>`;
}

// GitHub-style year heatmap: 7 rows (Sun–Sat), one column per week, filled
// column-major. Leading blanks pad the first partial week.
function _renderCalYear(days) {
  const first = new Date(days[0].date + 'T00:00:00');
  const cells = [];
  for (let i = 0; i < first.getDay(); i++) cells.push('<div class="caly-cell caly-cell--empty"></div>');
  for (const day of days) {
    const dt = new Date(day.date + 'T00:00:00');
    const tip = `${dt.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })} — ${day.total ? `${day.taken}/${day.total} taken` : 'nothing scheduled'}`;
    cells.push(`<div class="caly-cell" style="background:${_CAL_COLOR[day.status]}" title="${tip}" data-ev-click="showCalDay('${day.date}',${day.taken},${day.total})"></div>`);
  }
  return `<div class="caly-scroll"><div class="caly-grid">${cells.join('')}</div></div>`;
}

function showCalDay(date, taken, total) {
  const el = document.getElementById('cal-day-detail');
  if (!el) return;
  const dt = new Date(date + 'T00:00:00').toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' });
  el.textContent = total ? `${dt}: ${taken} of ${total} dose${total !== 1 ? 's' : ''} taken` : `${dt}: nothing scheduled`;
}

// ── Drug-name autocomplete on the add-medicine form ─────────────────────────
let _drugSuggestTimer = null, _drugSuggestIdx = -1;

function drugAutocomplete(value) {
  const box = document.getElementById('med-name-suggest');
  const input = document.getElementById('med-name-input');
  checkDupMedicine(value);
  const q = (value || '').trim();
  if (!box) return;
  if (q.length < 2) { _hideDrugSuggest(); return; }
  clearTimeout(_drugSuggestTimer);
  _drugSuggestTimer = setTimeout(async () => {
    const r = await fetch('/api/medicines/drugs?q=' + encodeURIComponent(q)).then(x => x.json()).catch(() => null);
    if (!r || !r.drugs || !r.drugs.length) { _hideDrugSuggest(); return; }
    // don't keep showing the list once it exactly matches what they typed
    if (r.drugs.length === 1 && r.drugs[0].name.toLowerCase() === q.toLowerCase()) { _hideDrugSuggest(); return; }
    _drugSuggestIdx = -1;
    box.innerHTML = r.drugs.map((d, i) =>
      `<div class="drug-suggest-item" role="option" data-idx="${i}" data-ev-click="pickDrug('${escHtml(d.name).replace(/'/g, "\\'")}')">
        <span>${escHtml(d.name)}</span><span class="dsi-hint">${escHtml(d.hint || '')}</span>
      </div>`).join('');
    box.style.display = 'block';
    if (input) input.setAttribute('aria-expanded', 'true');
  }, 150);
}

function _hideDrugSuggest() {
  const box = document.getElementById('med-name-suggest');
  const input = document.getElementById('med-name-input');
  if (box) { box.style.display = 'none'; box.innerHTML = ''; }
  if (input) input.setAttribute('aria-expanded', 'false');
  _drugSuggestIdx = -1;
}

function pickDrug(name) {
  const input = document.getElementById('med-name-input');
  if (input) { input.value = name; input.focus(); }
  _hideDrugSuggest();
  checkDupMedicine(name);
}

function drugAutocompleteKey(e) {
  const box = document.getElementById('med-name-suggest');
  if (!box || box.style.display === 'none') return;
  const items = [...box.querySelectorAll('.drug-suggest-item')];
  if (!items.length) return;
  if (e.key === 'ArrowDown') { _drugSuggestIdx = Math.min(_drugSuggestIdx + 1, items.length - 1); _highlightDrug(items); e.preventDefault(); }
  else if (e.key === 'ArrowUp') { _drugSuggestIdx = Math.max(_drugSuggestIdx - 1, 0); _highlightDrug(items); e.preventDefault(); }
  else if (e.key === 'Enter' && _drugSuggestIdx >= 0) { items[_drugSuggestIdx].click(); e.preventDefault(); }
  else if (e.key === 'Escape') { _hideDrugSuggest(); }
}

function _highlightDrug(items) {
  items.forEach((it, i) => it.classList.toggle('active', i === _drugSuggestIdx));
  items[_drugSuggestIdx]?.scrollIntoView({ block: 'nearest' });
}

// Safe, data-free duplicate check — no interaction data, just "you already
// track this name", so the same medicine isn't added twice by accident.
function checkDupMedicine(value) {
  const warn = document.getElementById('med-name-dup');
  if (!warn) return;
  const name = (value || '').trim().toLowerCase();
  const names = window._activeMedNames || [];
  if (name && names.includes(name)) {
    warn.textContent = '⚠️ You already track a medicine called “' + value.trim() + '”.';
    warn.style.display = 'block';
  } else {
    warn.style.display = 'none';
  }
}

function fmt12(t) {
  if (!t || !t.includes(':')) return t || '';
  let [h, m] = t.split(':').map(Number);
  const ap = h >= 12 ? 'pm' : 'am';
  h = h % 12 || 12;
  return `${h}:${String(m).padStart(2, '0')} ${ap}`;
}

function renderTodayTimeline(doses) {
  const el = document.getElementById('today-dose-timeline');
  if (!el) return;
  const total = doses.length, taken = doses.filter(d => d.taken).length;
  // ── Focal panel: adherence ring + next dose ──
  const focal = document.getElementById('med-focal');
  if (focal) focal.style.display = total > 0 ? 'flex' : 'none';
  const ring = document.getElementById('med-ring');
  if (ring) ring.setAttribute('stroke-dasharray', `${total ? (taken / total * 194.8).toFixed(1) : 0} 194.8`);
  setText('med-ring-val', `${taken}/${total}`);
  setText('med-ring-label', (total && taken === total) ? t('all doses taken 🎉') : t('doses taken today'));
  const nextIcon = document.getElementById('med-next-icon');
  const upcoming = [...doses].filter(d => !d.taken)
    .sort((a, b) => (a.time || '').localeCompare(b.time || ''))[0];
  if (upcoming) {
    setText('med-next-val', `${fmt12(upcoming.time)} · ${escHtml(upcoming.med_name)}`);
    setText('med-next-key', `${upcoming.dosage} ${upcoming.unit}${medTimingText(upcoming) ? ' · ' + medTimingText(upcoming) : ''}`);
    if (nextIcon) nextIcon.textContent = upcoming.icon || '💊';
  } else if (total) {
    setText('med-next-val', t('All done for today'));
    setText('med-next-key', t('nothing left to take'));
    if (nextIcon) nextIcon.textContent = '✅';
  }
  if (doses.length === 0) {
    el.innerHTML = '<div style="color:var(--gray-400);font-size:13px;padding:16px 0;text-align:center">No doses scheduled. <a href="#" data-ev-click="openMedModal();return false" style="color:var(--teal-600)">Add a medicine →</a></div>';
    return;
  }
  // Group by time
  const byTime = {};
  doses.forEach(d => { if (!byTime[d.time]) byTime[d.time] = []; byTime[d.time].push(d); });
  const times = Object.keys(byTime).sort();
  const now = new Date().toTimeString().slice(0,5);
  el.innerHTML = times.map((time, idx) => {
    const group = byTime[time];
    const allTaken = group.every(d => d.taken);
    const isPast = time < now;
    const dotClass = allTaken ? 'taken' : (isPast ? 'missed' : '');
    return `
      <div class="dose-slot">
        <div class="dose-time-col"><span class="dose-time-label">${time}</span></div>
        <div class="dose-line-col">
          <div class="dose-dot ${dotClass}"></div>
          ${idx < times.length - 1 ? '<div class="dose-vline"></div>' : ''}
        </div>
        <div class="dose-cards-col">
          ${group.map(d => `
            <div class="dose-card ${d.taken ? 'taken' : ''}" data-ev-click="markDoseTaken('${d.med_id}','${d.time}',this)">
              <div class="dose-card-emoji">${d.icon}</div>
              <div class="dose-card-info">
                <div class="dose-card-name">${escHtml(d.med_name)}</div>
                <div class="dose-card-detail">${d.dosage} ${d.unit}${medTimingText(d) ? ' · ' + escHtml(medTimingText(d)) : ''}</div>
              </div>
              ${d.taken ? '' : `<button class="dose-skip-btn" title="${t('Skip this dose')}" data-ev-click="event.stopPropagation();skipDose('${d.med_id}','${d.time}')">${t('Skip')}</button>`}
              <div class="dose-card-check">${d.taken ? '✓' : ''}</div>
            </div>
          `).join('')}
        </div>
      </div>
    `;
  }).join('');
}

let _medsById = {};   // last-rendered meds, so the restock modal can read a med's pharmacy note

function renderMedicinesGrid(meds) {
  const grid = document.getElementById('medicines-grid');
  if (!grid) return;
  if (meds.length === 0) {
    grid.innerHTML = `<div class="empty-state"><div class="empty-icon">💊</div><div class="empty-text">${t('No medicines added')}</div><div class="empty-sub">${t('Add your first medicine to track doses')}</div><button class="btn-primary" data-ev-click="openMedModal()">${t('Add Medicine')}</button></div>`;
    return;
  }
  _medsById = {};
  meds.forEach(m => { _medsById[m.id] = m; });
  grid.innerHTML = meds.map(m => {
    // Pill count / refill section
    const isPRN = m.frequency === 'as_needed';
    const hasPills = m.pill_count != null;
    // A day-of-week or N-day schedule stretches supply below the daily rate.
    const sd = Array.isArray(m.schedule_days) && m.schedule_days.length && m.schedule_days.length < 7 ? m.schedule_days : null;
    const dosesPerActiveDay = Math.max((m.times || []).length, 1);
    const freqDoses = m.interval_days ? dosesPerActiveDay / m.interval_days
      : sd ? dosesPerActiveDay * (sd.length / 7)
      : ({once_daily:1,twice_daily:2,thrice_daily:3,weekly:1/7}[m.frequency] || 1);
    // As-needed usage is unpredictable, so a "days left" estimate would be a lie.
    const daysLeft = (hasPills && !isPRN) ? Math.floor(m.pill_count / Math.max(freqDoses * (m.pills_per_dose||1), 0.01)) : null;
    const maxDays  = m.refill_threshold ? m.refill_threshold * 4 : 28;
    const fillPct  = (hasPills && daysLeft != null) ? Math.min(100, Math.round((daysLeft / maxDays) * 100)) : 0;
    const isLow    = hasPills && daysLeft != null && daysLeft < (m.refill_threshold || 7);
    const stockColor = isLow ? '#EF4444' : (daysLeft != null && daysLeft < (m.refill_threshold||7)*2) ? '#F59E0B' : '#22C55E';

    const pillSection = hasPills ? `
      <div class="med-pill-track">
        <div class="med-pill-track-row">
          <span class="med-pill-count-label" style="color:${stockColor}">
            ${isLow ? '⚠️' : '💊'} ${tformat('%1 pills', m.pill_count)}${daysLeft != null ? ' · ' + tformat('%1d left', daysLeft) : ''}
          </span>
          <button class="med-restock-btn" data-ev-click="openRestockModal('${m.id}','${escHtml(m.name)}',${m.pill_count},${m.pills_per_dose||1},${m.refill_threshold||7})">${t('Restock')}</button>
        </div>
        <div class="med-pill-bar-track">
          <div class="med-pill-bar-fill" style="width:${fillPct}%;background:${stockColor}"></div>
        </div>
      </div>` : `
      <div class="med-pill-track med-pill-track--empty">
        <button class="med-add-stock-btn" data-ev-click="openRestockModal('${m.id}','${escHtml(m.name)}',0,1,7)">${t('+ Track pill count')}</button>
      </div>`;

    // Refill row — appears when stock is low or a refill is on the way.
    const ordered = m.refill_status === 'ordered';
    const refillRow = (hasPills && (isLow || ordered)) ? `
      <div class="med-refill-row">
        ${ordered
          ? `<span class="med-refill-ordered">${t('🚚 Refill ordered')}</span>
             <button class="med-refill-btn" data-ev-click="openRestockModal('${m.id}','${escHtml(m.name)}',${m.pill_count},${m.pills_per_dose||1},${m.refill_threshold||7})">${t('Mark picked up')}</button>`
          : `<button class="med-refill-btn med-refill-btn--order" data-ev-click="orderRefill('${m.id}')">${t('🔄 Order refill')}</button>`}
        ${m.pharmacy_note ? `<span class="med-pharmacy-note">🏥 ${escHtml(m.pharmacy_note)}</span>` : ''}
      </div>` : '';

    return `<div class="med-card med-card--${m.color}${isLow?' med-card--low-stock':''}">
      <div class="med-card-header">
        <div class="med-card-icon">${m.photo_path
          ? `<img class="med-card-photo" src="/uploads/${encodeURIComponent(m.photo_path)}" alt="${t('Medicine photo')}" data-ev-click="viewMedPhoto('${encodeURIComponent(m.photo_path)}','${escapeHtml(m.name)}')">`
          : m.icon}</div>
        <div class="med-card-info">
          <div class="med-card-name">${escHtml(m.name)}</div>
          <div class="med-card-dose">${m.dosage} ${m.unit} · ${freqLabel(m.frequency)}${scheduleLabel(m) ? ' · ' + scheduleLabel(m) : ''}</div>
        </div>
      </div>
      <div class="med-card-times">
        ${isPRN ? `<span class="time-chip">${t('🕐 As needed')}</span>`
                : (m.times?.map(t => `<span class="time-chip">⏰ ${t}</span>`).join('') || '')}
        ${medTimingText(m) ? `<span class="med-food-badge">${m.timing === 'bedtime' ? '🌙' : m.timing === 'with_water' ? '💧' : m.timing === 'empty_stomach' ? '⏳' : '🍽️'} ${escHtml(medTimingText(m))}</span>` : ''}
        ${m.cost != null ? `<span class="med-cost-badge">₹${(Math.round(m.cost * 100) / 100).toLocaleString('en-IN')}/mo</span>` : ''}
        ${_expiryBadge(m)}
      </div>
      ${isPRN ? `
      <div class="med-prn-row">
        <button class="med-prn-btn" data-ev-click="takeNow('${m.id}','${escHtml(m.name)}')">${t('＋ Log a dose now')}</button>
        ${m.taken_today ? `<span class="med-prn-count">${tformat('Taken %1× today', m.taken_today)}${m.last_taken ? ' · ' + tformat('last %1', fmtTime(m.last_taken)) : ''}</span>` : ''}
      </div>` : ''}
      ${m.purpose ? `<div class="med-purpose">${tformat('💡 For %1', escHtml(m.purpose))}</div>` : ''}
      ${m.notes ? `<div style="font-size:12px;color:var(--gray-400);margin-bottom:8px">${escHtml(m.notes)}</div>` : ''}
      ${pillSection}
      ${refillRow}
      <div class="med-card-footer">
        <span class="med-card-status ${m.active ? 'active' : ''}">● ${m.active ? t('Active') : t('Paused')}</span>
        <div class="med-card-actions">
          <button class="btn-icon" title="${t('View details')}" data-ev-click="openMedDetail('${m.id}')">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>
          </button>
          <button class="btn-icon" title="${m.photo_path ? t('Change photo') : t('Add a photo')}" data-ev-click="openMedPhotoPicker('${m.id}')">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M23 19a2 2 0 01-2 2H3a2 2 0 01-2-2V8a2 2 0 012-2h4l2-3h6l2 3h4a2 2 0 012 2z"/><circle cx="12" cy="13" r="4"/></svg>
          </button>
          ${m.photo_path ? `<button class="btn-icon" title="${t('Remove photo')}" data-ev-click="removeMedPhoto('${m.id}')">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M23 19a2 2 0 01-2 2H3a2 2 0 01-2-2V8a2 2 0 012-2h4l2-3h6l2 3h4a2 2 0 012 2z"/><line x1="1" y1="1" x2="23" y2="23"/></svg>
          </button>` : ''}
          <button class="btn-icon" title="${m.active ? t('Pause') : t('Activate')}" data-ev-click="toggleMed('${m.id}')">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">${m.active ? '<rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/>' : '<polygon points="5 3 19 12 5 21 5 3"/>'}</svg>
          </button>
          <button class="btn-icon" title="${m.expiry_date ? t('Edit expiry date') : t('Set expiry date')}" data-ev-click="editMedExpiry('${m.id}')">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
          </button>
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteMed('${m.id}')">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/></svg>
          </button>
        </div>
      </div>
      <div class="med-expiry-edit" id="med-expiry-edit-${m.id}" style="display:none">
        <input type="date" class="form-input" id="med-expiry-input-${m.id}" value="${m.expiry_date || ''}" style="max-width:170px">
        <button class="btn-primary" style="padding:8px 12px" data-ev-click="saveMedExpiry('${m.id}')">${t('Save')}</button>
        ${m.expiry_date ? `<button class="btn-outline" style="padding:8px 12px" data-ev-click="clearMedExpiry('${m.id}')">${t('Clear')}</button>` : ''}
      </div>
    </div>`;
  }).join('');
}

// K3: pill burden — total pills/day + medicine count, with a gentle review nudge
// at the polypharmacy threshold. From the user's own list; never says to stop.
async function loadPillBurden() {
  const el = document.getElementById('pill-burden-section');
  if (!el) return;
  const d = await fetch('/api/medicines/pill-burden', {credentials:'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!d || !d.has_data || d.medicine_count < 2) { el.innerHTML = ''; return; }
  const nudge = d.polypharmacy
    ? `<div class="pbur-nudge">💬 ${tformat('You’re on %1 medicines. It can be worth asking your doctor whether every one is still needed.', d.medicine_count)}</div>`
    : '';
  el.innerHTML = `<div class="panel pbur-panel">
      <div class="pbur-stats">
        <div class="pbur-stat"><span class="pbur-num">${d.daily_pills}</span><span class="pbur-k">${t('pills / day')}</span></div>
        <div class="pbur-stat"><span class="pbur-num">${d.medicine_count}</span><span class="pbur-k">${t('medicines')}</span></div>
        ${d.as_needed_count ? `<div class="pbur-stat"><span class="pbur-num">${d.as_needed_count}</span><span class="pbur-k">${t('as-needed')}</span></div>` : ''}
      </div>
      ${nudge}
    </div>`;
}

// K1: banner listing expired / soon-to-expire medicines (own entered dates).
async function loadExpiringMeds() {
  const el = document.getElementById('med-expiring-banner');
  if (!el) return;
  const d = await fetch('/api/medicines/expiring?days=60', {credentials:'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!d || !d.has_any) { el.innerHTML = ''; return; }
  const line = (m, expired) => `<span class="mexp-item">${escapeHtml(m.name)} — ${
    expired ? t('expired') : tformat('%1d left', m.days_left)}</span>`;
  const parts = [];
  if (d.expired.length) parts.push(`⛔ <b>${t('Expired')}:</b> ` + d.expired.map(m => line(m, true)).join(' '));
  if (d.soon.length)    parts.push(`📅 <b>${t('Expiring soon')}:</b> ` + d.soon.map(m => line(m, false)).join(' '));
  el.innerHTML = `<div class="med-expiring-alert">
      <div class="mexp-icon">🗓️</div>
      <div class="mexp-body">${parts.join('<br>')}</div>
    </div>`;
}

// K1: expiry badge + inline editor. Only from the user's own entered date.
function _expiryBadge(m) {
  const exp = m.expiry_date;
  if (!exp) return '';
  const days = Math.round((new Date(exp + 'T12:00:00').getTime() - Date.now()) / 86400000);
  if (days < 0)  return `<span class="med-expiry-badge med-expiry-badge--expired">⛔ ${t('Expired')}</span>`;
  if (days <= 60) return `<span class="med-expiry-badge med-expiry-badge--soon">📅 ${tformat('Expires in %1d', days)}</span>`;
  return `<span class="med-expiry-badge">📅 ${tformat('Expires %1', _fmtShortDate(exp))}</span>`;
}
function editMedExpiry(id) {
  const box = document.getElementById('med-expiry-edit-' + id);
  if (box) box.style.display = box.style.display === 'none' ? 'flex' : 'none';
}
async function saveMedExpiry(id) {
  const v = document.getElementById('med-expiry-input-' + id)?.value || '';
  if (!v) { showToast(t('Pick a date'), 'error'); return; }
  const r = await fetch(`/api/medicines/${id}/expiry`, {
    method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
    body: JSON.stringify({expiry_date: v}),
  }).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(t('Expiry date saved'), 'success'); loadMedicines(); }
  else showToast((r && r.error) || t('Could not save'), 'error');
}
async function clearMedExpiry(id) {
  await fetch(`/api/medicines/${id}/expiry`, {
    method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
    body: JSON.stringify({expiry_date: ''}),
  }).catch(() => {});
  showToast(t('Expiry cleared'));
  loadMedicines();
}

// ── I8: medicine identification photos ──────────────────────────────────────
// A pill/pack photo helps a caregiver or an older user recognise the medicine.
// Images only; served through the authenticated /uploads route with an owner check.
function openMedPhotoPicker(mid) {
  let inp = document.getElementById('med-photo-input');
  if (!inp) {
    inp = document.createElement('input');
    inp.type = 'file'; inp.accept = 'image/*'; inp.id = 'med-photo-input';
    inp.style.display = 'none';
    document.body.appendChild(inp);
  }
  inp.value = '';
  inp.onchange = () => { const f = inp.files && inp.files[0]; if (f) uploadMedPhoto(mid, f); };
  inp.click();
}

async function uploadMedPhoto(mid, file) {
  // Guard client-side too so an oversized pick fails fast with a clear message.
  if (file.size > 8 * 1024 * 1024) { showToast(t('Image is too large (max 8 MB).'), 'error'); return; }
  const fd = new FormData();
  fd.append('file', file);
  showToast(t('Uploading photo…'));
  const r = await fetch(`/api/medicines/${mid}/photo`, {
    method: 'POST', body: fd, credentials: 'same-origin',
  }).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(t('Photo added'), 'success'); loadMedicines(); }
  else showToast((r && r.error) || t('Could not upload the photo'), 'error');
}

async function removeMedPhoto(mid) {
  await fetch(`/api/medicines/${mid}/photo`, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  showToast(t('Photo removed'));
  loadMedicines();
}

// K4/K5: two-group BP comparison cards (home vs clinic; morning vs evening).
function _bpCompareCard(title, badge, a, b, note) {
  const fmt = g => g.diastolic != null ? `${g.systolic}/${g.diastolic}` : `${g.systolic}`;
  return `<div class="panel bpc-panel">
      <div class="panel-header"><h2 class="panel-title">${title}</h2>
        ${badge ? `<span class="panel-badge">${badge}</span>` : ''}</div>
      <div class="bpc-cols">
        <div class="bpc-col"><div class="bpc-side">${a.label}</div>
          <div class="bpc-val">${fmt(a.data)}</div>
          <div class="bpc-meta">${tformat('%1 readings', a.data.count)}</div></div>
        <div class="bpc-vs">vs</div>
        <div class="bpc-col"><div class="bpc-side">${b.label}</div>
          <div class="bpc-val">${fmt(b.data)}</div>
          <div class="bpc-meta">${tformat('%1 readings', b.data.count)}</div></div>
      </div>
      ${note ? `<div class="bpc-note">${note}</div>` : ''}
    </div>`;
}

async function loadBpHomeClinic() {
  const el = document.getElementById('bp-home-clinic-section');
  if (!el) return;
  const d = await fetch('/api/vitals/bp-home-clinic?days=180', {credentials:'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { el.innerHTML = ''; return; }
  const note = d.white_coat
    ? `⚠️ ${tformat('Your clinic readings run about %1 mmHg higher than at home — a possible white-coat effect worth mentioning to your doctor.', d.systolic_gap)}`
    : tformat('Home and clinic differ by about %1 mmHg (systolic).', Math.abs(d.systolic_gap));
  el.innerHTML = _bpCompareCard('🏠🏥 ' + t('Home vs clinic BP'), t('last 6 months'),
    {label: '🏠 ' + t('At home'), data: d.home}, {label: '🏥 ' + t('Clinic'), data: d.clinic}, note);
}

async function loadBpTimePattern() {
  const el = document.getElementById('bp-time-pattern-section');
  if (!el) return;
  const d = await fetch('/api/vitals/bp-time-pattern?days=180', {credentials:'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { el.innerHTML = ''; return; }
  const g = d.systolic_gap;
  const note = Math.abs(g) < 5
    ? t('Your morning and evening readings are similar.')
    : tformat('%1 systolic runs about %2 mmHg higher.', g > 0 ? t('Morning') : t('Evening'), Math.abs(g));
  el.innerHTML = _bpCompareCard('🌅🌆 ' + t('Morning vs evening BP'), t('by time logged'),
    {label: '🌅 ' + t('Morning'), data: d.morning}, {label: '🌆 ' + t('Evening'), data: d.evening}, note);
}

// K2: estimated HbA1c from logged glucose (ADAG formula). An estimate from your
// own readings — never a lab result. Shown only with enough readings.
async function loadEstimatedA1c() {
  const el = document.getElementById('estimated-a1c-section');
  if (!el) return;
  const d = await fetch('/api/vitals/estimated-a1c?days=90', {credentials:'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { el.innerHTML = ''; return; }
  el.innerHTML = `<div class="panel a1c-panel">
      <div class="a1c-main">
        <div class="a1c-val">~${d.estimated_a1c}%</div>
        <div class="a1c-label">${t('estimated HbA1c')}</div>
      </div>
      <div class="a1c-side">
        <div class="a1c-side-row">${tformat('avg glucose %1 mg/dL', d.avg_glucose)}</div>
        <div class="a1c-side-row">${tformat('from %1 readings · %2 days', d.count, d.days)}</div>
        <div class="a1c-note">${t('A rough estimate from your logged readings, not a lab test. Discuss the real number with your doctor.')}</div>
      </div>
    </div>`;
}

// J7: "your own normal" — a personal baseline band (your mean ± 1 SD) per vital,
// with where the latest reading sits. Descriptive stats of your own logs; a
// complement to the population reference ranges, never a diagnosis.
async function loadPersonalBaselines() {
  const el = document.getElementById('personal-baselines-section');
  if (!el) return;
  const d = await fetch('/api/vitals/baselines?days=180', {credentials:'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { el.innerHTML = ''; return; }
  const posMeta = {
    within: { color: 'var(--teal-600)', label: 'in your usual range' },
    above:  { color: '#B45309', label: 'above your usual' },
    below:  { color: '#2563EB', label: 'below your usual' },
  };
  const rows = d.metrics.map(m => {
    const pm = posMeta[m.position] || posMeta.within;
    // Position the latest marker within a display span padded around the band.
    const span = (m.high - m.low) || 1;
    const dispLo = m.low - span * 0.8, dispHi = m.high + span * 0.8, w = dispHi - dispLo;
    const pct = x => Math.max(0, Math.min(100, (x - dispLo) / w * 100));
    return `<div class="pb-row">
        <div class="pb-head">
          <span class="pb-label">${t(m.label)}</span>
          <span class="pb-latest" style="color:${pm.color}">${m.latest} ${escapeHtml(m.unit)} · ${t(pm.label)}</span>
        </div>
        <div class="pb-track">
          <div class="pb-band" style="left:${pct(m.low).toFixed(1)}%;width:${(pct(m.high)-pct(m.low)).toFixed(1)}%"></div>
          <div class="pb-mark" style="left:${pct(m.latest).toFixed(1)}%;background:${pm.color}"></div>
        </div>
        <div class="pb-meta">${tformat('your usual %1–%2 %3', m.low, m.high, m.unit)} · ${tformat('from %1 readings', m.count)}</div>
      </div>`;
  }).join('');
  el.innerHTML = `<div class="panel" style="padding:16px 18px;margin-bottom:14px">
      <div class="panel-header"><h2 class="panel-title">🎯 ${t('Your own normal')}</h2>
        <span class="panel-badge">${t('last 6 months')}</span></div>
      <p style="font-size:12px;color:var(--gray-500);margin:2px 0 12px">
        ${t('Your typical range for each vital, from your own readings — a companion to the general reference ranges.')}</p>
      ${rows}
    </div>`;
}

// ── J2: peak-flow / respiratory tracker ─────────────────────────────────────
// PEF readings zoned green/yellow/red against the user's OWN personal best
// (asthma-action-plan traffic lights). Framing only — never a diagnosis.
const _PF_ZONE = {
  green:  { color: '#16A34A', label: 'Green — doing well' },
  yellow: { color: '#F59E0B', label: 'Yellow — caution' },
  red:    { color: '#DC2626', label: 'Red — get help' },
};

async function loadPeakFlow() {
  const el = document.getElementById('peak-flow-section');
  if (!el) return;
  const d = await fetch('/api/peak-flow?days=180', {credentials:'same-origin'})
    .then(r => r.json()).catch(() => null);
  const logRow = `
    <div style="display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap;margin-top:${d && d.has_data ? '14px' : '10px'}">
      <div class="form-group" style="margin-bottom:0">
        <label class="form-label" data-i18n="Peak flow (L/min)">Peak flow (L/min)</label>
        <input type="number" class="form-input" id="peak-flow-input" min="30" max="900" step="1"
               style="width:130px" placeholder="e.g. 450">
      </div>
      <button class="btn-primary" style="padding:10px 16px" data-ev-click="logPeakFlow()">${t('Save reading')}</button>
    </div>`;

  if (!d || !d.has_data) {
    el.innerHTML = `<div class="panel" style="padding:16px 18px;margin-bottom:14px">
        <div class="panel-header"><h2 class="panel-title">🫁 ${t('Peak flow')}</h2></div>
        <p style="font-size:12.5px;color:var(--gray-500);margin:0">
          ${t('For asthma/COPD — log your peak flow and Arogo zones it against your personal best.')}</p>
        ${logRow}
      </div>`;
    return;
  }

  const z = _PF_ZONE[d.latest.zone] || _PF_ZONE.green;
  const zoneBar = `
    <div class="pf-zonebar" title="${t('Zones are % of your personal best')}">
      <div class="pf-zone" style="flex:50;background:#FCA5A5"></div>
      <div class="pf-zone" style="flex:30;background:#FCD34D"></div>
      <div class="pf-zone" style="flex:20;background:#86EFAC"></div>
      <div class="pf-marker" style="left:${Math.min(100, Math.round(d.latest.value / d.personal_best * 100))}%"></div>
    </div>`;
  const recent = d.readings.slice(0, 8).map(r => {
    const zz = _PF_ZONE[r.zone] || _PF_ZONE.green;
    return `<div class="pf-row">
        <span class="pf-dot" style="background:${zz.color}"></span>
        <span class="pf-val">${r.value} <span style="color:var(--gray-400);font-weight:400">L/min</span></span>
        <span class="pf-pct">${r.pct_of_best}%</span>
        <span class="pf-date">${_fmtShortDate(r.date)}</span>
        <button class="todo-act-btn del" data-ev-click="delVital('${r.id}')" title="${t('Remove')}">✕</button>
      </div>`;
  }).join('');

  el.innerHTML = `<div class="panel" style="padding:16px 18px;margin-bottom:14px">
      <div class="panel-header"><h2 class="panel-title">🫁 ${t('Peak flow')}</h2>
        <span class="panel-badge">${tformat('best %1', d.personal_best)}</span></div>
      <div class="pf-latest" style="color:${z.color}">
        <span class="pf-latest-val">${d.latest.value}</span>
        <span class="pf-latest-zone">${t(z.label)} · ${d.latest.pct_of_best}% ${t('of best')}</span>
      </div>
      ${zoneBar}
      <div class="pf-thresholds">${tformat('Green ≥ %1 · Yellow ≥ %2 · Red below', d.green_min, d.yellow_min)}</div>
      <div class="pf-recent">${recent}</div>
      ${logRow}
    </div>`;
}

async function logPeakFlow() {
  const inp = document.getElementById('peak-flow-input');
  const v = inp && inp.value;
  if (v === '' || v == null) { showToast(t('Enter a reading'), 'error'); return; }
  const r = await fetch('/api/vitals', {
    method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
    body: JSON.stringify({type:'peak_flow', value1: v, date_key: localToday()}),
  }).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(t('Reading saved'), 'success'); loadPeakFlow(); }
  else showToast((r && r.error) || t('Could not save'), 'error');
}

// ── J1: injection-site rotation ─────────────────────────────────────────────
// For injectable meds — log which site was used so the app can suggest the
// least-recently-used one next. Sites/keys mirror db.injections.INJECTION_SITES.
const INJECTION_SITES = [
  { key: 'arm_left',      label: 'Left arm' },
  { key: 'arm_right',     label: 'Right arm' },
  { key: 'abdomen_left',  label: 'Abdomen (L)' },
  { key: 'abdomen_right', label: 'Abdomen (R)' },
  { key: 'thigh_left',    label: 'Left thigh' },
  { key: 'thigh_right',   label: 'Right thigh' },
  { key: 'buttock_left',  label: 'Left buttock' },
  { key: 'buttock_right', label: 'Right buttock' },
];

function openInjectionSites() {
  const m = document.getElementById('injection-modal');
  if (m) m.style.display = 'flex';
  loadInjectionSites();
}
function closeInjectionSites() {
  const m = document.getElementById('injection-modal');
  if (m) m.style.display = 'none';
}

async function loadInjectionSites() {
  const el = document.getElementById('injection-content');
  if (!el) return;
  el.innerHTML = `<div style="padding:24px;text-align:center;color:var(--gray-400)">${t('Loading…')}</div>`;
  const d = await fetch('/api/injections?days=30', {credentials:'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!d) { el.innerHTML = `<div class="hint-inline">${t('Could not load')}</div>`; return; }
  const meta = Object.fromEntries(INJECTION_SITES.map(s => [s.key, s]));
  const ago = last => {
    if (!last) return t('never used');
    const days = Math.round((Date.now() - new Date(last + 'T12:00:00').getTime()) / 86400000);
    return days <= 0 ? t('today') : days === 1 ? t('yesterday') : tformat('%1 days ago', days);
  };
  const byKey = Object.fromEntries(d.sites.map(s => [s.site, s]));
  const cell = key => {
    const s = byKey[key] || {last_used:null, count:0};
    const suggested = key === d.suggested_next;
    return `<button type="button" class="inj-site${suggested ? ' inj-site--suggested' : ''}"
        data-ev-click="pickInjectionSite('${key}')" title="${t('Log an injection here')}">
        <span class="inj-site-name">${t(meta[key].label)}</span>
        <span class="inj-site-last">${ago(s.last_used)}</span>
        ${suggested ? `<span class="inj-site-tag">${t('use next')}</span>` : ''}
      </button>`;
  };
  const grid = `<div class="inj-grid">
      ${cell('arm_left')}${cell('arm_right')}
      ${cell('abdomen_left')}${cell('abdomen_right')}
      ${cell('thigh_left')}${cell('thigh_right')}
      ${cell('buttock_left')}${cell('buttock_right')}
    </div>`;
  const recent = d.recent.length ? `
    <div class="inj-recent">
      <div class="inj-recent-title">${t('Recent injections')}</div>
      ${d.recent.slice(0, 8).map(r => `
        <div class="inj-recent-row">
          <span>💉 ${t((meta[r.site]||{}).label || r.site)}</span>
          <span class="inj-recent-date">${_fmtShortDate(r.date_key)}</span>
          <button class="todo-act-btn del" data-ev-click="delInjection('${r.id}')" title="${t('Remove')}">✕</button>
        </div>`).join('')}
    </div>` : '';
  el.innerHTML = `
    <p style="font-size:13px;color:var(--gray-500);margin-bottom:14px">
      ${t('Rotating sites gives each spot time to recover. The highlighted site is the one you’ve used least recently.')}</p>
    ${grid}${recent}`;
}

async function pickInjectionSite(site) {
  const r = await fetch('/api/injections', {
    method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
    body: JSON.stringify({site, date_key: localToday()}),
  }).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(t('Injection logged'), 'success'); loadInjectionSites(); }
  else showToast((r && r.error) || t('Could not save'), 'error');
}

async function delInjection(id) {
  await fetch('/api/injections/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadInjectionSites();
}

function viewMedPhoto(encodedPath, name) {
  let ov = document.getElementById('med-photo-lightbox');
  if (!ov) {
    ov = document.createElement('div');
    ov.id = 'med-photo-lightbox';
    ov.className = 'med-photo-lightbox';
    ov.setAttribute('role', 'dialog');
    ov.addEventListener('click', () => { ov.style.display = 'none'; ov.innerHTML = ''; });
    document.body.appendChild(ov);
  }
  ov.innerHTML = `<figure><img src="/uploads/${encodedPath}" alt="${escapeHtml(name || '')}">
    <figcaption>${escapeHtml(name || '')}</figcaption></figure>`;
  ov.style.display = 'flex';
}

// ── Per-medicine detail drill-down (L1) ─────────────────────────────────────
// One medicine's whole story — its own adherence, skip reasons, on-time
// quality, days of supply, and change history — pulled together from the
// scattered account-wide panels. Everything shown is the user's own logged
// data; the modal renders "not enough yet" honestly rather than inventing.
const _MED_EVENT_LABEL = { started: 'Started', stopped: 'Stopped',
  resumed: 'Resumed', deleted: 'Removed', restocked: 'Restocked' };

function _detailBar(pct, cls) {
  const w = Math.max(0, Math.min(100, Math.round(pct || 0)));
  return `<div class="mdt-bar"><span class="mdt-bar-fill ${cls || ''}" style="width:${w}%"></span></div>`;
}

async function openMedDetail(id) {
  let ov = document.getElementById('med-detail-overlay');
  if (!ov) {
    ov = document.createElement('div');
    ov.id = 'med-detail-overlay';
    ov.className = 'med-detail-overlay';
    ov.setAttribute('role', 'dialog');
    ov.setAttribute('aria-modal', 'true');
    ov.addEventListener('click', (e) => {
      if (e.target === ov || e.target.closest('[data-close-detail]')) {
        ov.style.display = 'none'; ov.innerHTML = '';
      }
    });
    document.body.appendChild(ov);
  }
  ov.innerHTML = `<div class="mdt-card"><div class="mdt-loading">${t('Loading…')}</div></div>`;
  ov.style.display = 'flex';

  const d = await fetch(`/api/medicines/${id}/detail`, { credentials: 'same-origin' })
    .then(r => r.ok ? r.json() : null).catch(() => null);
  if (!d) {
    ov.innerHTML = `<div class="mdt-card"><button class="mdt-close" data-close-detail aria-label="${t('Close')}">×</button>
      <p class="mdt-empty">${t('Could not load this medicine.')}</p></div>`;
    return;
  }

  const a = d.adherence || {};
  const ot = d.ontime || {};
  // Adherence section
  let adhHtml;
  if (d.is_prn) {
    adhHtml = `<p class="mdt-note">${t('As-needed medicine — no fixed schedule to measure adherence against.')}</p>`;
  } else if (a.has_data) {
    const slots = (d.slots || []).map(s =>
      `<div class="mdt-slot"><span class="mdt-slot-time">⏰ ${escapeHtml(s.time)}</span>
        ${_detailBar(s.pct, s.pct >= 80 ? 'good' : s.pct >= 50 ? 'mid' : 'low')}
        <span class="mdt-slot-pct">${s.pct}%</span></div>`).join('');
    adhHtml = `<div class="mdt-big"><span class="mdt-big-num">${a.pct}%</span>
        <span class="mdt-big-sub">${tformat('%1 of %2 doses over %3 days', a.taken, a.total, d.days)}</span></div>
      ${slots ? `<div class="mdt-slots">${slots}</div>` : ''}`;
  } else {
    adhHtml = `<p class="mdt-note">${t('Not enough scheduled doses yet to measure adherence.')}</p>`;
  }

  // On-time quality
  let otHtml = '';
  if (ot.has_data) {
    const bars = (ot.buckets || []).map(b => {
      const pct = ot.count ? Math.round(b.count / ot.count * 100) : 0;
      return `<div class="mdt-slot"><span class="mdt-slot-time">${t(b.label)}</span>
        ${_detailBar(pct, b.key === 'ontime' || b.key === 'early' ? 'good' : b.key === 'late' ? 'mid' : 'low')}
        <span class="mdt-slot-pct">${b.count}</span></div>`;
    }).join('');
    const med = ot.median_delay_min;
    const medTxt = med == null ? '' :
      (med <= 0 ? t('usually logged on time or early')
                : tformat('typically logged about %1 min after the scheduled time', med));
    otHtml = `<div class="mdt-section"><h4>${t('On-time quality')}</h4>
      <div class="mdt-big-sub" style="margin-bottom:8px">${tformat('%1% within the on-time window', ot.ontime_pct)}${medTxt ? ' · ' + medTxt : ''}</div>
      <div class="mdt-slots">${bars}</div>
      <p class="mdt-fineprint">${t('Timing is approximate — it compares the scheduled time with when you logged the dose.')}</p></div>`;
  }

  // Skip reasons
  let reasonsHtml = '';
  if ((d.skip_reasons || []).length) {
    const chips = d.skip_reasons.map(r =>
      `<span class="mdt-chip">${escapeHtml(t(r.label))} · ${r.count}</span>`).join('');
    reasonsHtml = `<div class="mdt-section"><h4>${t('Why doses were missed')}</h4>
      <div class="mdt-chips">${chips}</div></div>`;
  }

  // Supply
  let supplyHtml = '';
  if (d.days_of_supply != null) {
    supplyHtml = `<div class="mdt-section"><h4>${t('Supply')}</h4>
      <div class="mdt-big-sub">${tformat('About %1 days of stock left', d.days_of_supply)}${
        d.pill_count != null ? ' · ' + tformat('%1 left', d.pill_count) : ''}</div></div>`;
  }

  // History
  let historyHtml = '';
  if ((d.history || []).length) {
    const rows = d.history.map(e => {
      const lbl = _MED_EVENT_LABEL[e.kind] || e.kind;
      return `<li><span class="mdt-hist-date">${escapeHtml((e.at || '').slice(0, 10))}</span>
        <span class="mdt-hist-kind">${t(lbl)}</span>${e.detail ? ` <span class="mdt-hist-detail">${escapeHtml(e.detail)}</span>` : ''}</li>`;
    }).join('');
    historyHtml = `<div class="mdt-section"><h4>${t('History')}</h4><ul class="mdt-hist">${rows}</ul></div>`;
  }

  // Backfill a past dose (L5): the only place in the app to record a dose you
  // took (or skipped) but forgot to log on an earlier day, so adherence stays
  // truthful. Scheduled meds only — PRN uses "log a dose now". Future dates are
  // impossible by construction (max=today).
  let backfillHtml = '';
  if (!d.is_prn && (d.times || []).length) {
    const today = (typeof localToday === 'function') ? localToday()
      : new Date().toISOString().slice(0, 10);
    const y = new Date(); y.setDate(y.getDate() - 1);
    const yesterday = y.toISOString().slice(0, 10);
    const timeOpts = d.times.map(tm => `<option value="${escapeHtml(tm)}">${escapeHtml(tm)}</option>`).join('');
    backfillHtml = `<div class="mdt-section"><h4>${t('Log a missed entry')}</h4>
      <p class="mdt-fineprint" style="margin:0 0 8px">${t('Forgot to log a dose? Record it for a past day so your history is accurate.')}</p>
      <div class="mdt-bf">
        <input type="date" id="mdt-bf-date" class="form-input" max="${today}" value="${yesterday}">
        <select id="mdt-bf-time" class="form-input">${timeOpts}</select>
      </div>
      <div class="mdt-bf-actions">
        <button class="btn-primary" data-ev-click="submitBackfillDose('${d.id}', true)">${t('Took it')}</button>
        <button class="btn-outline" data-ev-click="submitBackfillDose('${d.id}', false)">${t('Skipped it')}</button>
      </div></div>`;
  }

  const status = d.active ? `<span class="mdt-status active">● ${t('Active')}</span>`
                          : `<span class="mdt-status">● ${t('Paused')}</span>`;
  ov.innerHTML = `<div class="mdt-card" role="document">
    <button class="mdt-close" data-close-detail aria-label="${t('Close')}">×</button>
    <div class="mdt-head">
      <span class="mdt-icon">${escapeHtml(d.icon || '💊')}</span>
      <div><div class="mdt-name">${escapeHtml(d.name)}</div>
        <div class="mdt-sub">${escapeHtml([d.dosage, d.unit].filter(Boolean).join(' '))}${
          d.purpose ? ' · ' + escapeHtml(d.purpose) : ''}</div></div>
      ${status}
    </div>
    <div class="mdt-section"><h4>${tformat('Adherence · last %1 days', d.days)}</h4>${adhHtml}</div>
    ${otHtml}${reasonsHtml}${supplyHtml}${backfillHtml}${historyHtml}
  </div>`;
}

async function submitBackfillDose(id, taken) {
  const date = (document.getElementById('mdt-bf-date') || {}).value;
  const time = (document.getElementById('mdt-bf-time') || {}).value;
  if (!date || !time) { showToast('Pick a date and time', 'error'); return; }
  const today = (typeof localToday === 'function') ? localToday()
    : new Date().toISOString().slice(0, 10);
  if (date > today) { showToast("A dose can't be logged for a future day", 'error'); return; }
  const res = await fetch(`/api/medicines/${id}/log`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    credentials: 'same-origin', body: JSON.stringify({ date, time, taken })
  }).then(r => r.json()).catch(() => null);
  if (res && res.success) {
    showToast(taken ? 'Past dose logged' : 'Marked as skipped');
    openMedDetail(id);                       // refresh the modal's numbers
    if (typeof loadMedicines === 'function') { try { loadMedicines(); } catch (e) {} }
  } else {
    showToast('Could not log that dose', 'error');
  }
}

// ── Offline write queue (IndexedDB outbox) ──────────────────────────────────
// So a dose logged with no connection isn't lost: the write is queued and
// replayed when the device is back online. We tell the user it's *queued*, not
// server-confirmed — honest, and better than dropping the write.
const _OUTBOX_DB = 'arogo-outbox', _OUTBOX_STORE = 'writes';

function _openOutbox() {
  return new Promise((res, rej) => {
    if (!('indexedDB' in window)) return rej(new Error('no indexeddb'));
    const req = indexedDB.open(_OUTBOX_DB, 1);
    req.onupgradeneeded = () => req.result.createObjectStore(_OUTBOX_STORE, {keyPath: 'id', autoIncrement: true});
    req.onsuccess = () => res(req.result);
    req.onerror = () => rej(req.error);
  });
}
function _outboxTx(mode, fn) {
  return _openOutbox().then(db => new Promise((res, rej) => {
    const tx = db.transaction(_OUTBOX_STORE, mode);
    const out = fn(tx.objectStore(_OUTBOX_STORE));
    tx.oncomplete = () => res(out && out.result !== undefined ? out.result : out);
    tx.onerror = () => rej(tx.error);
  }));
}
const _outboxAdd    = item => _outboxTx('readwrite', s => s.add(item));
const _outboxAll    = ()   => _outboxTx('readonly',  s => s.getAll());
const _outboxDelete = id   => _outboxTx('readwrite', s => s.delete(id));

async function _updateOutboxBadge() {
  let n = 0;
  try { n = (await _outboxAll()).length; } catch (e) { return; }
  let el = document.getElementById('offline-badge');
  if (n <= 0) { if (el) el.style.display = 'none'; return; }
  if (!el) {
    el = document.createElement('div');
    el.id = 'offline-badge'; el.className = 'offline-badge';
    el.setAttribute('data-ev-click', 'flushOutbox()');
    el.title = 'Waiting to sync — tap to retry now';
    document.body.appendChild(el);
  }
  el.textContent = `⏳ ${n} waiting to sync`;
  el.style.display = 'block';
}

// Like fetch(), but a *write* that fails on the network is queued instead of
// lost, and reported back as {queued:true} so callers can message honestly.
async function syncableFetch(url, opts = {}) {
  try {
    return await fetch(url, opts);
  } catch (e) {
    const method = (opts.method || 'GET').toUpperCase();
    if (['POST', 'PUT', 'DELETE'].includes(method)) {
      try {
        await _outboxAdd({url, method, body: opts.body || null,
                          headers: {'Content-Type': 'application/json'}, ts: Date.now()});
        _updateOutboxBadge();
        return {ok: true, queued: true, status: 0, json: async () => ({success: true, queued: true})};
      } catch (_) { /* fall through to rethrow if we can't even queue */ }
    }
    throw e;
  }
}

let _flushing = false;
async function flushOutbox() {
  if (_flushing || (typeof navigator !== 'undefined' && navigator.onLine === false)) return 0;
  _flushing = true;
  let synced = 0;
  try {
    const items = await _outboxAll().catch(() => []);
    for (const it of items) {
      try {
        const r = await fetch(it.url, {method: it.method, headers: it.headers, body: it.body});
        if (r.ok) { await _outboxDelete(it.id); synced++; }
        else if (r.status >= 400 && r.status < 500) { await _outboxDelete(it.id); }  // a bad row won't fix itself — drop it
        else break;                                   // server hiccup — keep it for next time
      } catch (e) { break; }                           // still offline
    }
  } finally { _flushing = false; }
  _updateOutboxBadge();
  if (synced > 0) {
    showToast(tformat('✓ Synced %1 offline entries', synced), 'success');
    try { loadMedicines(); loadDashboard(); } catch (e) {}
  }
  return synced;
}

if (typeof window !== 'undefined' && window.addEventListener) {
  window.addEventListener('online', () => { try { flushOutbox(); } catch (e) {} });
}

async function markDoseTaken(medId, time, el) {
  const date = localToday();
  // Never claim a dose landed without checking. This is the core adherence
  // loop: if the write failed and we say "taken ✓", the user stops thinking
  // about it, the dose stays unlogged, and their family gets escalated to
  // about a dose they actually took. Offline, the write is queued (not
  // confirmed) — we say so, rather than lie or lose it.
  const r = await syncableFetch(`/api/medicines/${medId}/log`, {
    method:'POST', headers:{'Content-Type':'application/json'},
    body:JSON.stringify({ date, time, taken:true })
  }).then(r => r.json()).catch(() => null);
  if (!r?.success) {
    showToast("Couldn't log that dose — check your connection and try again", 'error');
    return;
  }
  if (r.queued) {
    // Optimistically show it as taken; skip the reloads (they'd fail offline).
    if (el) el.classList.add('taken');
    showToast("Saved offline — it'll sync when you're back online", 'success');
    return;
  }
  showToast('Dose marked as taken ✓', 'success');
  loadMedicines();
  loadDashboard();
}

// Skip a dose WITH a reason — an optional tap that turns a silent miss into a
// pattern you can see later. The reason set is closed (mirrors SKIP_REASONS
// server-side); "Just skip" logs the miss with no reason.
const SKIP_REASON_OPTS = [
  { id: 'forgot',      label: 'Forgot' },
  { id: 'away',        label: 'Was away' },
  { id: 'side_effect', label: 'Side effect' },
  { id: 'ran_out',     label: 'Ran out' },
  { id: 'felt_ok',     label: 'Felt fine' },
  { id: 'other',       label: 'Other' },
];

function skipDose(medId, time) {
  closeSkipPicker();
  const ov = document.createElement('div');
  ov.className = 'lang-picker-overlay';
  ov.id = 'skip-picker-overlay';
  ov.setAttribute('data-ev-click', 'skipPickerBackdrop(event)');
  ov.innerHTML = `<div class="lang-picker" role="menu" style="max-width:320px">
    <div class="lang-picker-head">${t('Why are you skipping this?')}</div>
    ${SKIP_REASON_OPTS.map(o => `<button class="lang-opt" role="menuitem" data-ev-click="confirmSkip('${medId}','${time}','${o.id}')">
        <span class="lang-opt-native" style="font-size:14px">${t(o.label)}</span></button>`).join('')}
    <button class="lang-opt" role="menuitem" data-ev-click="confirmSkip('${medId}','${time}','')">
      <span class="lang-opt-native" style="font-size:14px;color:var(--gray-500)">${t('Just skip')}</span></button>
  </div>`;
  document.body.appendChild(ov);
}
function skipPickerBackdrop(ev) { if (ev.target && ev.target.id === 'skip-picker-overlay') closeSkipPicker(); }
function closeSkipPicker() { const el = document.getElementById('skip-picker-overlay'); if (el) el.remove(); }

async function confirmSkip(medId, time, reason) {
  closeSkipPicker();
  const r = await fetch(`/api/medicines/${medId}/log`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ date: localToday(), time, taken: false, reason: reason || null })
  }).then(r => r.json()).catch(() => null);
  if (r?.success) { showToast(t('Dose skipped')); loadMedicines(); loadDashboard(); }
  else showToast(t('Could not update'), 'error');
}

// Summary of why doses get skipped — a pattern, not a scolding.
async function loadSkipReasons() {
  const el = document.getElementById('med-skip-section');
  if (!el) return;
  const d = await fetch('/api/medicines/skip-reasons?days=30').then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { el.innerHTML = ''; return; }
  const max = Math.max(...d.reasons.map(r => r.count), 1);
  const rows = d.reasons.map(r => `
    <div class="skip-row">
      <div class="skip-label">${t(r.label)}</div>
      <div class="skip-bar-wrap"><div class="skip-bar" style="width:${Math.round(r.count / max * 100)}%"></div></div>
      <div class="skip-count">${r.count}</div>
    </div>`).join('');
  el.innerHTML = `<div class="panel" style="padding:18px 20px">
      <div class="panel-header"><h2 class="panel-title">📝 ${t('Why doses get skipped')}</h2><span class="panel-badge">${t('last 30 days')}</span></div>
      ${rows}
    </div>`;
}

async function toggleMed(id) {
  await fetch(`/api/medicines/${id}/toggle`, { method:'POST' });
  loadMedicines();
}

// Mark a refill as ordered so it stops nudging until it arrives (restocking
// clears it). Server-side is the source of truth; we just reflect it.
async function orderRefill(id) {
  const r = await fetch(`/api/medicines/${id}/refill/ordered`, { method:'POST' })
    .then(r => r.json()).catch(() => null);
  if (r?.success) showToast('Refill marked as ordered 🚚', 'success');
  else showToast("Couldn't update the refill — try again", 'error');
  loadMedicines();
}

function fmtTime(iso) {
  try { return new Date(iso).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' }); }
  catch (e) { return ''; }
}

// Log a one-off, unscheduled ("as needed") dose taken right now.
async function takeNow(id, name) {
  const r = await fetch(`/api/medicines/${id}/take-now`, { method: 'POST', credentials: 'same-origin' })
    .then(r => r.json()).catch(() => null);
  if (r?.success) showToast(`${name || 'Dose'} logged ✓${r.time ? ' at ' + r.time : ''}`, 'success');
  else showToast("Couldn't log that dose — try again", 'error');
  loadMedicines();
  loadDashboard();
}

// ── Import from prescription ──────────────────────────────────────
// Reads a prescription and PROPOSES medicines; the user confirms every row
// before anything is saved (same safety stance as the lab-report parser).
let _rxMeds = [];

function openRxImport() {
  document.getElementById('rx-upload-step').style.display = '';
  const review = document.getElementById('rx-review-step');
  review.style.display = 'none'; review.innerHTML = '';
  document.getElementById('rx-status').innerHTML = '';
  const f = document.getElementById('rx-file'); if (f) f.value = '';
  document.getElementById('rx-import-overlay').style.display = 'flex';
}

async function submitRxFile(input) {
  const file = input.files && input.files[0];
  if (!file) return;
  const status = document.getElementById('rx-status');
  status.style.color = 'var(--gray-500)';
  status.textContent = '⏳ Reading your prescription…';
  const fd = new FormData(); fd.append('file', file);
  let d = {};
  try {
    d = await fetch('/api/medicines/parse-rx', { method: 'POST', credentials: 'same-origin', body: fd })
      .then(r => r.json());
  } catch (e) { d = { reason: 'Upload failed — check your connection.' }; }
  _rxMeds = d.medicines || [];
  if (!_rxMeds.length) {
    status.style.color = 'var(--gray-600)';
    status.innerHTML = escHtml(d.reason || "We couldn't find any medicines.") +
      `<div style="margin-top:12px"><button class="btn-outline" data-ev-click="closeModal('rx-import-overlay');openMedModal()">${t('Add manually instead')}</button></div>`;
    return;
  }
  status.textContent = '';
  renderRxReview();
}

function renderRxReview() {
  document.getElementById('rx-upload-step').style.display = 'none';
  const step = document.getElementById('rx-review-step');
  step.style.display = '';
  const FREQ = [['once_daily', 'Once daily'], ['twice_daily', 'Twice daily'],
                ['thrice_daily', 'Thrice daily'], ['weekly', 'Weekly']];
  step.innerHTML =
    `<div style="font-size:13px;color:var(--gray-600);margin-bottom:12px">
       Found ${_rxMeds.length}. Check each, fix anything, then add — nothing is saved until you tap Add.</div>` +
    _rxMeds.map((m, i) => `
      <div class="rx-row" data-i="${i}">
        <input class="form-input rx-name" value="${escHtml(m.name)}" placeholder="Medicine" aria-label="Medicine name">
        <input class="form-input rx-dose" value="${escHtml(m.dosage)}" placeholder="Dose" aria-label="Dose" style="max-width:76px">
        <select class="form-input rx-unit" aria-label="Unit" style="max-width:74px">
          ${['mg', 'mcg', 'g', 'ml', 'iu'].map(u => `<option ${u === m.unit ? 'selected' : ''}>${u}</option>`).join('')}
        </select>
        <select class="form-input rx-freq" aria-label="How often" style="max-width:128px">
          ${FREQ.map(([v, l]) => `<option value="${v}" ${v === m.frequency ? 'selected' : ''}>${l}</option>`).join('')}
        </select>
        <button class="btn-icon" title="Remove" data-ev-click="rxRemoveRow(${i})">✕</button>
      </div>`).join('') +
    `<div style="display:flex;gap:8px;margin-top:16px">
       <button class="btn-outline" data-ev-click="openRxImport()">${t('Start over')}</button>
       <button class="btn-primary" style="flex:1" data-ev-click="addRxMedicines()">${t('Add these medicines')}</button>
     </div>`;
}

function rxRemoveRow(i) {
  const row = document.querySelector(`#rx-review-step .rx-row[data-i="${i}"]`);
  if (row) row.remove();
}

function _defaultTimesFor(freq) {
  return ({ once_daily: ['09:00'], twice_daily: ['09:00', '21:00'],
            thrice_daily: ['08:00', '14:00', '20:00'], weekly: ['09:00'] })[freq] || ['09:00'];
}

async function addRxMedicines() {
  const meds = [...document.querySelectorAll('#rx-review-step .rx-row')].map(r => ({
    name: r.querySelector('.rx-name').value.trim(),
    dosage: r.querySelector('.rx-dose').value.trim(),
    unit: r.querySelector('.rx-unit').value,
    frequency: r.querySelector('.rx-freq').value,
  })).filter(m => m.name);
  if (!meds.length) { showToast('Nothing to add', 'error'); return; }
  let added = 0;
  for (const m of meds) {
    const r = await fetch('/api/medicines', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'same-origin',
      body: JSON.stringify({ name: m.name, dosage: m.dosage, unit: m.unit,
                             frequency: m.frequency, times: _defaultTimesFor(m.frequency) })
    }).then(r => r.json()).catch(() => null);
    if (r?.success) added++;
  }
  closeModal('rx-import-overlay');
  showToast(tformat('Added %1 medicine(s) 💊', added), 'success');
  loadMedicines();
  loadDashboard();
}

function deleteMed(id) {
  undoable('Removing medicine…', async () => {
    await fetch(`/api/medicines/${id}`, { method:'DELETE' });
    loadMedicines();
  });
}

function setupMedForm() {
  document.getElementById('med-form')?.addEventListener('submit', async e => {
    e.preventDefault();
    const form = e.target;
    const times = [...document.querySelectorAll('.time-input')].map(i => i.value).filter(Boolean);
    const body = {
      name: form.name.value,
      dosage: form.dosage.value,
      unit: form.unit.value,
      frequency: form.querySelector('input[name="frequency"]:checked')?.value || 'once_daily',
      times,
      timing: document.getElementById('med-timing')?.value || '',
      reminder_lead_min: parseInt(document.getElementById('med-lead')?.value) || 0,
      cost: document.getElementById('med-cost')?.value || '',
      notes: form.notes.value,
      purpose: form.purpose?.value || '',
      start_date: form.start_date.value,
      end_date: form.end_date.value,
      expiry_date: form.expiry_date?.value || '',
      schedule_days: _collectScheduleDays(),
      interval_days: _collectInterval(),
      icon: selectedIcon,
      color: selectedColor
    };
    const res = await fetch('/api/medicines', { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body) });
    const data = await res.json();
    if (data.success) {
      // Save pill count if entered
      const pillCount = parseInt(document.getElementById('med-pill-count')?.value);
      if (pillCount > 0) {
        await fetch(`/api/medicines/${data.medicine.id}/stock`, {
          method:'POST', headers:{'Content-Type':'application/json'},
          body: JSON.stringify({
            pill_count:  pillCount,
            pills_per_dose: parseInt(document.getElementById('med-pills-per-dose')?.value) || 1,
            refill_threshold: parseInt(document.getElementById('med-refill-threshold')?.value) || 7
          })
        });
      }
      showToast(`${body.name} added!`, 'success');
      form.reset(); setDates();
      resetTimeSlots();
      document.getElementById('med-pill-count').value = '';
      document.getElementById('med-pills-per-dose').value = '1';
      document.getElementById('med-refill-threshold').value = '7';
      document.getElementById('refill-fields').style.display = 'none';
      document.getElementById('refill-chevron').style.transform = 'rotate(-90deg)';
      closeModal('med-modal-overlay');
      loadMedicines();
    } else showToast('Failed to add medicine', 'error');
  });
}

function addTimeSlot() {
  const slots = document.getElementById('time-slots');
  const row = document.createElement('div');
  row.className = 'time-slot-row';
  row.innerHTML = `<input type="time" class="form-input time-input" value="12:00"><button type="button" class="btn-icon slot-remove" data-ev-click="removeTimeSlot(this)"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>`;
  slots.appendChild(row);
}

function removeTimeSlot(btn) {
  const slots = document.getElementById('time-slots');
  if (slots.children.length > 1) btn.closest('.time-slot-row').remove();
}

function resetTimeSlots() {
  const g = document.getElementById('med-times-group');   // un-hide after an as-needed add
  if (g) g.style.display = '';
  const dg = document.getElementById('med-repeat-group');   // un-hide + reset to "every day"
  if (dg) dg.style.display = '';
  try { _resetRepeat(); } catch (e) {}
  const slots = document.getElementById('time-slots');
  if (slots) slots.innerHTML = `<div class="time-slot-row"><input type="time" class="form-input time-input" value="08:00"><button type="button" class="btn-icon slot-remove" data-ev-click="removeTimeSlot(this)"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button></div>`;
}

function setupFreqPicker() {
  document.querySelectorAll('.freq-opt input').forEach(input => {
    input.addEventListener('change', () => {
      // As-needed meds have no schedule → hide the reminder times AND the
      // day-of-week picker (there's nothing to schedule).
      const timesGroup = document.getElementById('med-times-group');
      const repeatGroup = document.getElementById('med-repeat-group');
      if (input.value === 'as_needed') {
        if (timesGroup) timesGroup.style.display = 'none';
        if (repeatGroup) repeatGroup.style.display = 'none';
        return;
      }
      if (timesGroup) timesGroup.style.display = '';
      if (repeatGroup) repeatGroup.style.display = '';
      const counts = { once_daily:1, twice_daily:2, thrice_daily:3, weekly:1 };
      const count = counts[input.value] || 1;
      const slots = document.getElementById('time-slots');
      if (!slots) return;
      const defaultTimes = ['08:00','13:00','20:00'];
      while (slots.children.length < count) addTimeSlot();
      while (slots.children.length > count) slots.lastChild.remove();
      [...slots.querySelectorAll('.time-input')].forEach((inp, i) => { if (defaultTimes[i]) inp.value = defaultTimes[i]; });
    });
  });
}

function setupIconColorPicker() {
  document.querySelectorAll('.icon-opt').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.icon-opt').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      selectedIcon = btn.dataset.icon;
    });
  });
  document.querySelectorAll('.color-opt').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.color-opt').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      selectedColor = btn.dataset.color;
    });
  });
}

// ── Reminders / Notifications ──
function checkNotifPermission() {
  if (!('Notification' in window)) return;
  if (Notification.permission === 'default') {
    document.getElementById('notif-banner').style.display = 'flex';
  }
  notifPermission = Notification.permission;
}

function requestNotifPermission() {
  if (!('Notification' in window)) return;
  Notification.requestPermission().then(perm => {
    notifPermission = perm;
    document.getElementById('notif-banner').style.display = 'none';
    if (perm === 'granted') {
      showToast('Notifications enabled! 🔔', 'success');
      // Reminders come from the server (scheduler.py) so they arrive with the
      // tab closed and their action buttons actually work.
      setupPushSubscription();
    }
  });
}

// ── Fitness ──
function openActivityModal() {
  document.getElementById('activity-modal-overlay').style.display = 'flex';
  // Render fields for currently selected type (default: running)
  setTimeout(() => renderActivityFields(selectedActivityType || 'running'), 0);
}
function openConnectModal() { document.getElementById('connect-modal-overlay').style.display = 'flex'; }

async function loadFitness() {
  const today = localToday();
  const [stats, activities, consistency, foodDay, profile] = await Promise.all([
    fetch('/api/fitness/stats').then(r => r.json()).catch(() => ({})),
    fetch('/api/fitness/activities').then(r => r.json()).catch(() => []),
    fetch('/api/fitness/consistency').then(r => r.json()).catch(() => ({})),
    fetch(`/api/food/log/${today}`).then(r => r.json()).catch(() => null),
    fetch('/api/food/profile').then(r => r.json()).catch(() => null)
  ]);

  setText('fit-week-acts', stats.week?.activities || 0);
  setText('fit-week-min', stats.week?.duration || 0);
  setText('fit-week-cal', (stats.week?.calories || 0).toLocaleString());
  setText('fit-week-km', `${stats.week?.distance || 0} km`);
  // Show today's burned calories as a sub-label under the weekly total
  const todayCal = stats.today?.calories || 0;
  const todaySubEl = document.getElementById('fit-today-cal-sub');
  if (todaySubEl) todaySubEl.textContent = todayCal > 0 ? `${todayCal} today` : '';

  const sugEl = document.getElementById('fitness-suggestions');
  if (sugEl) renderSuggestions(sugEl, stats.suggestions || []);
  renderTypeChart(stats.type_breakdown || {});
  renderActivityFeed(activities);
  const ac = document.getElementById('activity-count');
  if (ac) ac.textContent = `${activities.length} total`;

  // Streak badge
  const streakBadge = document.getElementById('fitness-streak-badge');
  if (streakBadge) {
    const streak = consistency.current_streak || 0;
    if (streak > 0) { streakBadge.textContent = `🔥${streak}`; streakBadge.style.display = 'inline-block'; }
    else streakBadge.style.display = 'none';
  }

  // ── Calorie deficit banner ──
  // Use TODAY's burned calories only (not the whole week)
  const burnedCal    = stats.today?.calories || 0;
  const eatenCal     = foodDay?.summary?.totals?.calories || 0;
  // null, not 2000: calc_tdee can't compute a target without weight/height/
  // age/gender, and inventing one meant a brand-new user got a red "over
  // budget" bar for exceeding a number the app made up about them.
  const targetCal    = profile?.targets?.target_calories || null;

  const netEl    = document.getElementById('cdb-net');
  const netLbl   = document.getElementById('cdb-net-label');
  const progress = document.getElementById('cdb-progress');
  const banner   = document.getElementById('calorie-deficit-banner');

  setText('cdb-burned', burnedCal.toLocaleString() + ' kcal');
  setText('cdb-eaten',  Math.round(eatenCal) + ' kcal');

  if (!targetCal) {
    // Eaten and burned are true without a target. Net, target and the progress
    // bar are not — so say they're missing and point at how to get them.
    setText('cdb-target', 'Not set');
    setText('cdb-progress-pct', '—');
    if (netEl)  netEl.textContent = '—';
    if (netLbl) netLbl.textContent = 'Add your details for a target';
    if (progress) { progress.style.width = '0%'; progress.classList.remove('over'); }
    if (banner) banner.classList.remove('cdb-deficit','cdb-surplus','cdb-balanced');
  } else {
    // Net = TDEE target - (eaten - burned): how many kcal you still have left today
    // A positive number means you still have room; negative means surplus over goal
    const net = Math.round((targetCal + burnedCal) - eatenCal);
    const pct = Math.min(Math.round((eatenCal / (targetCal + burnedCal)) * 100), 150);
    setText('cdb-target', targetCal + ' kcal/day');
    setText('cdb-progress-pct', pct + '%');
    if (netEl)  netEl.textContent = Math.abs(net) + ' kcal';
    if (netLbl) netLbl.textContent = net > 100 ? '✅ Remaining' : net < -100 ? '⚠️ Over budget' : '⚖️ Balanced';
    if (progress) {
      progress.style.width = Math.min(pct, 100) + '%';
      progress.classList.toggle('over', pct > 105);
    }
    if (banner) {
      banner.classList.remove('cdb-deficit','cdb-surplus','cdb-balanced');
      banner.classList.add(net > 100 ? 'cdb-deficit' : net < -100 ? 'cdb-surplus' : 'cdb-balanced');
    }
  }

  // ── Nutrition strip ──
  renderFitnessNutritionStrip(foodDay, profile?.targets);

  // ── Personal Records ──
  loadFitnessPRs();

  // ── Body measurements + recomposition ──
  loadMeasurements();

  // ── Exercise heart-rate zones ──
  loadHrZones();
}

// Target HR training zones from age (Tanaka max-HR). Shows nothing but a gentle
// nudge when age is unknown.
const _HR_ZONE_COLOR = { warmup:'#3B82F6', fatburn:'#14B8A6', cardio:'#22C55E', anaerobic:'#F59E0B', peak:'#EF4444' };
async function loadHrZones() {
  const el = document.getElementById('hr-zones-section');
  if (!el) return;
  const d = await fetch('/api/health/hr-zones').then(r => r.json()).catch(() => null);
  if (!d) { el.innerHTML = ''; return; }
  if (!d.has_data) {
    el.innerHTML = `<div class="panel" style="padding:14px 18px;font-size:13px;color:var(--gray-500)">💓 ${tformat('Add %1 to see your training heart-rate zones', escHtml(t(d.reason || 'your age')))}</div>`;
    return;
  }
  const rows = d.zones.map(z => `
    <div class="hrz-row">
      <span class="hrz-dot" style="background:${_HR_ZONE_COLOR[z.key] || '#888'}"></span>
      <span class="hrz-name">${t(z.label)}</span>
      <span class="hrz-pct">${z.lo_pct}–${z.hi_pct}%</span>
      <span class="hrz-bpm"><b>${z.lo_bpm}–${z.hi_bpm}</b> bpm</span>
    </div>`).join('');
  el.innerHTML = `<div class="panel" style="padding:16px 18px">
      <div class="panel-header" style="padding:0 0 4px"><h2 class="panel-title">💓 ${t('Training heart-rate zones')}</h2>
        <span class="panel-badge">${tformat('max ~%1 bpm', d.max_hr)}</span></div>
      <div class="hrz-sub">${tformat('For age %1 · %2', d.age, escHtml(d.formula))}</div>
      ${rows}
    </div>`;
}

// Body-measurement trends (waist/hip/chest/arm/weight) + a recomposition read,
// with a compact inline logger. All the user's own numbers.
const _MEAS_INPUTS = [
  { id: 'meas-waist', field: 'waist_cm', label: 'Waist' },
  { id: 'meas-hip',   field: 'hip_cm',   label: 'Hip' },
  { id: 'meas-chest', field: 'chest_cm', label: 'Chest' },
  { id: 'meas-arm',   field: 'arm_cm',   label: 'Arm' },
];

async function loadMeasurements() {
  const el = document.getElementById('measurements-section');
  if (!el) return;
  const d = await fetch('/api/body-metrics/measurements?days=180').then(r => r.json()).catch(() => null);
  const form = `<div class="meas-form">
      ${_MEAS_INPUTS.map(m => `<div class="meas-field"><label>${t(m.label)}</label>
        <input type="number" id="${m.id}" step="0.1" min="0" placeholder="cm"></div>`).join('')}
      <button class="btn-primary btn-sm" data-ev-click="saveMeasurements()">${t('Log')}</button>
    </div>`;
  let body = '';
  if (d && d.has_data) {
    const recomp = d.recomp ? `<div class="meas-recomp">${d.recomp.kind === 'recomp'
        ? tformat('💪 Looks like recomposition — waist %1cm while weight held', d.recomp.waist_change)
        : tformat('📉 Fat loss — waist %1cm, weight %2kg', d.recomp.waist_change, d.recomp.weight_change)}</div>` : '';
    const rows = d.trends.map(tr => {
      const dir = tr.change < 0 ? '↓' : tr.change > 0 ? '↑' : '→';
      const col = tr.change < 0 ? '#22C55E' : tr.change > 0 ? '#F59E0B' : 'var(--gray-400)';
      return `<div class="meas-row">
        <span class="meas-label">${t(tr.label)}</span>
        <span class="meas-vals">${tr.first} → <b>${tr.latest}</b> ${tr.unit}</span>
        <span class="meas-change" style="color:${col}">${dir} ${Math.abs(tr.change)}${tr.unit}</span>
      </div>`;
    }).join('');
    body = `${recomp}<div class="meas-list">${rows}</div>`;
  } else {
    body = `<div style="font-size:12.5px;color:var(--gray-400);padding:4px 0">${t('Log measurements over time to see change and recomposition.')}</div>`;
  }
  el.innerHTML = `<div class="panel" style="padding:16px 18px">
      <div class="panel-header" style="padding:0 0 8px"><h2 class="panel-title">📏 ${t('Body measurements')}</h2><span class="panel-badge">${t('last 6 months')}</span></div>
      ${form}${body}
    </div>`;
}

async function saveMeasurements() {
  const payload = { date_key: localToday() };
  let any = false;
  for (const m of _MEAS_INPUTS) {
    const v = parseFloat(document.getElementById(m.id)?.value);
    if (v > 0) { payload[m.field] = v; any = true; }
  }
  if (!any) { showToast(t('Enter at least one measurement'), 'error'); return; }
  const r = await fetch('/api/body-metrics', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload)
  }).then(r => r.json()).catch(() => null);
  if (r?.success) {
    showToast(t('Measurements logged 📏'));
    _MEAS_INPUTS.forEach(m => { const el = document.getElementById(m.id); if (el) el.value = ''; });
    loadMeasurements();
  } else showToast(t('Could not save'), 'error');
}

function renderFitnessNutritionStrip(foodDay, targets) {
  if (!targets) return;
  // Same rule as the food page: without a real TDEE these "targets" are just
  // population averages presented as the user's own goals.
  const known = hasTargets(targets);
  const t    = foodDay?.summary?.totals || {};
  const defs = [
    { id:'cal',  val: Math.round(t.calories||0), target: targets.target_calories, unit:'kcal', label:'Calories', color:'#4F8D74' },
    { id:'prot', val: Math.round(t.protein||0),  target: targets.protein_g,       unit:'g',    label:'Protein',  color:'#5E8299' },
    { id:'carb', val: Math.round(t.carbs||0),    target: targets.carbs_g,         unit:'g',    label:'Carbs',    color:'#E0A34E' },
    { id:'fat',  val: Math.round(t.fat||0),      target: targets.fat_g,           unit:'g',    label:'Fat',      color:'#D07D4E' },
    { id:'fiber',val: Math.round(t.fiber||0),    target: targets.fiber_g,         unit:'g',    label:'Fiber',    color:'#5A9E70' },
  ];
  const R = 18, C = 2 * Math.PI * R; // circumference ~113

  defs.forEach(d => {
    const pct    = (known && d.target) ? Math.min(d.val / d.target, 1) : 0;
    const offset = C - pct * C;
    const ring   = document.getElementById(`fns-ring-${d.id}`);
    const valEl  = document.getElementById(`fns-${d.id}-val`);
    const subEl  = document.getElementById(`fns-${d.id}-sub`);
    if (ring)  ring.style.strokeDashoffset = offset.toFixed(1);
    if (valEl) valEl.textContent = d.id === 'cal' ? d.val : d.val + d.unit;
    // No denominator when we don't have one — an unfilled ring beats a ring
    // measured against an invented goal.
    if (subEl) subEl.textContent = (known && d.target)
      ? `/ ${d.target}${d.id !== 'cal' ? d.unit : ''}` : d.label;
  });

  // Nutrition suggestions in strip
  const sugEl = document.getElementById('fns-suggestions');
  if (sugEl) {
    const sugs = foodDay?.suggestions || [];
    if (sugs.length === 0) {
      sugEl.innerHTML = `<div style="color:var(--gray-400);font-size:12.5px">${t('Log food to see nutrition insights integrated with your workouts.')}</div>`;
    } else {
      sugEl.innerHTML = sugs.slice(0, 3).map(s => `
        <div class="fns-sug-row fns-sug-row--${s.type}">
          <span class="fns-sug-icon">${s.icon}</span>
          <span>${escHtml(s.text)}</span>
        </div>`).join('');
    }
  }
}

