async function loadSleepInsights() {
  const el = document.getElementById('sleep-insights-card');
  if (!el) return;
  const d = await fetch('/api/sleep/insights?days=14').then(r => r.json()).catch(() => null);
  if (!d) { el.style.display = 'none'; return; }
  el.style.display = 'block';

  // Target editor — always shown, so the user can set one and unlock debt math.
  const tgtVal = d.target_h != null ? d.target_h : '';
  const targetRow = `<div class="sleep-target-row">
    <label class="sleep-target-label">${t('Nightly goal')}</label>
    <input type="number" id="sleep-target-input" class="form-input" min="3" max="14" step="0.5"
           value="${tgtVal}" placeholder="8" style="width:80px">
    <span style="font-size:13px;color:var(--gray-500)">${t('hours')}</span>
    <button class="btn-outline btn-sm" data-ev-click="saveSleepTarget()">${t('Save')}</button>
  </div>`;

  let body;
  if (!d.has_data) {
    body = `<div style="color:var(--gray-400);font-size:13px;padding:8px 0">${t('Log a few nights to see your sleep debt and bedtime consistency.')}</div>`;
  } else {
    const tiles = [];
    // Sleep debt — only when a target exists.
    if (d.debt_h != null) {
      const col = d.debt_h > 0 ? '#EF4444' : '#22C55E';
      const sub = d.debt_h > 0
        ? tformat('%1 short of %2h over %3 night(s)', d.short_nights, d.target_h, d.nights)
        : t('No shortfall — nice');
      tiles.push(`<div class="sleep-ins-tile">
        <div class="sleep-ins-val" style="color:${col}">${d.debt_h > 0 ? '−' + d.debt_h + 'h' : '0h'}</div>
        <div class="sleep-ins-lbl">${t('Sleep debt')}</div>
        <div class="sleep-ins-sub">${escHtml(sub)}</div>
      </div>`);
    } else {
      tiles.push(`<div class="sleep-ins-tile">
        <div class="sleep-ins-val" style="color:var(--gray-300);font-size:20px">—</div>
        <div class="sleep-ins-lbl">${t('Sleep debt')}</div>
        <div class="sleep-ins-sub">${t('Set a nightly goal to track this')}</div>
      </div>`);
    }
    // Average duration.
    tiles.push(`<div class="sleep-ins-tile">
      <div class="sleep-ins-val">${d.avg_duration_h}h</div>
      <div class="sleep-ins-lbl">${t('Average night')}</div>
      <div class="sleep-ins-sub">${tformat('across %1 night(s)', d.nights)}</div>
    </div>`);
    // Bedtime consistency.
    if (d.consistency_min != null) {
      const steady = d.consistency_min <= 30 ? t('very steady') : d.consistency_min <= 60 ? t('fairly steady') : t('quite variable');
      tiles.push(`<div class="sleep-ins-tile">
        <div class="sleep-ins-val">±${d.consistency_min}m</div>
        <div class="sleep-ins-lbl">${t('Bedtime spread')}</div>
        <div class="sleep-ins-sub">${d.typical_bedtime ? tformat('usually ~%1 · %2', d.typical_bedtime, steady) : escHtml(steady)}</div>
      </div>`);
    } else {
      tiles.push(`<div class="sleep-ins-tile">
        <div class="sleep-ins-val" style="color:var(--gray-300);font-size:20px">—</div>
        <div class="sleep-ins-lbl">${t('Bedtime spread')}</div>
        <div class="sleep-ins-sub">${t('Needs 3+ nights with a bedtime')}</div>
      </div>`);
    }
    body = `<div class="sleep-ins-grid">${tiles.join('')}</div>`;
  }

  el.innerHTML = `<div class="panel-header" style="padding:0 0 6px"><h2 class="panel-title">😴 ${t('Sleep debt & rhythm')}</h2></div>
    ${body}${targetRow}`;
}

async function saveSleepTarget() {
  const raw = document.getElementById('sleep-target-input')?.value;
  const r = await fetch('/api/sleep/target', {
    method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({ hours: raw === '' ? null : parseFloat(raw) })
  }).then(r => r.json()).catch(() => null);
  if (r && r.success) {
    showToast(r.target_h ? t('Sleep goal saved 😴') : t('Sleep goal cleared'));
    loadSleepInsights();
  } else {
    showToast((r && r.error) || t('Could not save'), 'error');
  }
}

async function renderSleepFocal() {
  const el = document.getElementById('sleep-focal');
  if (!el) return;
  const logs = await fetch('/api/sleep?days=7', {cache: 'no-store'}).then(r => r.json()).catch(() => []);
  if (!Array.isArray(logs) || logs.length === 0) { el.style.display = 'none'; return; }
  el.style.display = 'flex';
  const sorted = [...logs].sort((a, b) => (b.date_key || '').localeCompare(a.date_key || ''));
  const last = sorted[0];
  // Average over the nights actually logged in the window — not the window
  // length. logs holds only real entries, so dividing by logs.length is right.
  const avg = logs.reduce((s, l) => s + (l.duration_h || 0), 0) / logs.length;
  const fmtDur = h => `${Math.floor(h)}h ${Math.round((h % 1) * 60)}m`;
  const qEmoji = { 1: '😩', 2: '😕', 3: '😐', 4: '😊', 5: '😴' }[last.quality] || '';
  // "last night" only when the newest log really is last night — otherwise it
  // claimed a days-old entry was last night's. Fall back to its date.
  const _y = new Date(Date.now() - 86400000).toLocaleDateString('en-CA');
  const lastLabel = (last.date_key === localToday() || last.date_key === _y)
    ? t('last night')
    : new Date(last.date_key + 'T12:00:00').toLocaleDateString('en-US', {month:'short', day:'numeric'});
  const byDate = {}; logs.forEach(l => { byDate[l.date_key] = l.duration_h; });
  const days = [];
  for (let i = 6; i >= 0; i--) {
    const d = new Date(); d.setDate(d.getDate() - i);
    const k = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    days.push({ h: byDate[k] || 0, lbl: ['S', 'M', 'T', 'W', 'T', 'F', 'S'][d.getDay()] });
  }
  const maxH = Math.max(9, ...days.map(d => d.h));
  const bars = days.map(d => `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:3px">
      <div style="width:100%;background:${d.h ? 'var(--teal-200)' : 'var(--gray-100)'};height:${Math.max(6, d.h / maxH * 44)}px;border-radius:3px 3px 0 0"></div>
      <span style="font-size:8px;color:var(--gray-400)">${d.lbl}</span></div>`).join('');
  el.innerHTML = `
    <div style="min-width:150px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:4px 8px">
      <div class="today-score-num" style="font-size:32px">${fmtDur(last.duration_h || 0)}</div>
      <div style="font-size:12.5px;color:var(--gray-500);margin-top:4px">${lastLabel} ${qEmoji}</div>
    </div>
    <div style="flex:1;display:flex;flex-direction:column;justify-content:center">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;padding:0 4px">
        <span style="font-size:12px;color:var(--gray-500)">${t('7-day average')}</span>
        <span style="font-size:16px;font-weight:700;color:var(--gray-800)">${fmtDur(avg)}</span>
      </div>
      <div style="display:flex;align-items:flex-end;gap:5px;height:52px;padding:0 4px">${bars}</div>
    </div>`;
}

// Re-render every sleep number from fresh data. Call this after any add or
// delete so the 7-day average, the 30-night stats and the dashboard strip all
// move together — the focal card used to be left stale because save/delete
// refreshed the trend and strip but not it.
function refreshSleep() {
  try { renderSleepFocal(); } catch (e) {}
  try { loadSleepTrend(); }  catch (e) {}
  try { loadWellnessStrip(); } catch (e) {}
}

// ── Duration-first sleep entry ─────────────────────────────────
// The state is a duration plus a wake-time anchor; bedtime is derived
// (wake − duration). The "Set exact times" row just exposes those two
// anchors as native time inputs, kept in sync both ways. Sleep tracking
// cares about how long and how well — so we lead with duration and let
// exact clock times be optional.
const _SLEEP_DUR_MIN = 180, _SLEEP_DUR_MAX = 720;   // 3h … 12h

const _fmtDurMin = m => { const h = Math.floor(m/60), mm = m%60; return h + 'h' + (mm ? ' ' + mm + 'm' : ''); };
const _minToHHMM = m => { m = ((m%1440)+1440)%1440; return String(Math.floor(m/60)).padStart(2,'0') + ':' + String(m%60).padStart(2,'0'); };
const _min12 = m => { m = ((m%1440)+1440)%1440; let h = Math.floor(m/60); const ap = h < 12 ? 'AM' : 'PM'; h = h%12 || 12; return h + ':' + String(m%60).padStart(2,'0') + ' ' + ap; };
const _clampDur = m => Math.max(_SLEEP_DUR_MIN, Math.min(_SLEEP_DUR_MAX, m));

async function initSleepEntry() {
  const usual = await usualSleep();
  window._sleepEntry = { durMin: usual.durMin, wakeMin: usual.wakeMin };
  window._sleepExactOpen = false;
  // Tap = 15 min; press-and-hold accelerates to 30-min jumps. Wired here (not
  // via the click-dispatcher) because that only handles click, and hold needs
  // pointer events. The buttons are freshly rendered each loadSleepView, so
  // these listeners don't accumulate.
  attachSleepHold(document.getElementById('sleep-dur-minus'), -1);
  attachSleepHold(document.getElementById('sleep-dur-plus'),  +1);
  sleepDurRender();
}

// Press-and-hold stepper. A quick tap steps once by 15 minutes; holding past a
// short threshold starts repeating in 30-minute chunks until release. Keyboard
// activation (Enter/Space fires click, not pointerdown) still gets one 15-min
// step, and we swallow the click that follows a pointer press so a mouse tap
// doesn't count twice.
function attachSleepHold(btn, dir) {
  if (!btn || btn._holdWired) return;
  btn._holdWired = true;
  let holdTimer = null, repeatTimer = null;
  const stop = () => { clearTimeout(holdTimer); clearInterval(repeatTimer); holdTimer = repeatTimer = null; };
  btn.addEventListener('pointerdown', e => {
    if (e.button != null && e.button !== 0) return;   // left button / touch only
    e.preventDefault();
    sleepDurStep(dir * 15);                            // immediate feedback
    holdTimer = setTimeout(() => {
      repeatTimer = setInterval(() => sleepDurStep(dir * 30), 150);
    }, 450);
  });
  ['pointerup', 'pointercancel', 'pointerleave'].forEach(ev => btn.addEventListener(ev, stop));
  // Keyboard activation (Enter/Space) fires a click with detail 0; a mouse or
  // touch click reports detail ≥ 1 and was already handled by pointerdown, so
  // we only act on the keyboard case — no flag to get stuck.
  btn.addEventListener('click', e => { if (e.detail === 0) sleepDurStep(dir * 15); });
}

// The user's usual duration + wake, learned from their own recent logs — the
// same "default to what you actually do" idea as food portions and water pours.
// A brand-new user falls back to 7h30m waking at 07:00.
async function usualSleep() {
  try {
    const logs = await fetch('/api/sleep?days=30', {cache:'no-store'}).then(r => r.json());
    if (Array.isArray(logs) && logs.length) {
      const durs = logs.map(l => Math.round((l.duration_h||0)*60)).filter(x => x > 0).sort((a,b)=>a-b);
      let durMin = durs.length ? durs[Math.floor(durs.length/2)] : 450;   // median
      durMin = _clampDur(Math.round(durMin/15)*15);
      const wakeCount = {};
      logs.forEach(l => {
        const t = (l.wake_time||'').slice(11,16); if (!/^\d\d:\d\d$/.test(t)) return;
        const [h,m] = t.split(':').map(Number); const wm = Math.round((h*60+m)/15)*15;
        wakeCount[wm] = (wakeCount[wm]||0) + 1;
      });
      let wakeMin = 420, best = 0;   // 07:00
      Object.entries(wakeCount).forEach(([wm,c]) => { if (c > best) { best = c; wakeMin = +wm; } });
      return { durMin, wakeMin };
    }
  } catch (e) {}
  return { durMin: 450, wakeMin: 420 };
}

function sleepDurStep(delta) {
  const s = window._sleepEntry; if (!s) return;
  s.durMin = _clampDur(s.durMin + delta);
  sleepDurRender();
}
function sleepDurDrag(val) {
  const s = window._sleepEntry; if (!s) return;
  s.durMin = _clampDur(parseInt(val) || 450);
  sleepDurRender();
}
function toggleSleepExact() {
  window._sleepExactOpen = !window._sleepExactOpen;
  const row = document.getElementById('sleep-exact-row');
  const btn = document.getElementById('sleep-exact-toggle');
  if (row) row.style.display = window._sleepExactOpen ? 'grid' : 'none';
  if (btn) btn.setAttribute('aria-expanded', window._sleepExactOpen ? 'true' : 'false');
  sleepDurRender();   // populate the inputs with the current implied times
}
// Editing an exact time drives the duration back the other way: change the wake
// anchor and the duration holds; type a bedtime and the duration recomputes.
function sleepExactChanged(which) {
  const s = window._sleepEntry; if (!s) return;
  const parse = id => { const v = document.getElementById(id)?.value || '';
    if (!/^\d\d:\d\d$/.test(v)) return null; const [h,m] = v.split(':').map(Number); return h*60 + m; };
  const wm = parse('sleep-wake-time'), bm = parse('sleep-bed-time');
  if (which === 'wake' && wm != null) {
    s.wakeMin = wm;                                   // duration unchanged
  } else if (which === 'bed' && bm != null) {
    const wake = wm != null ? wm : s.wakeMin;
    let d = ((wake - bm) % 1440 + 1440) % 1440;
    s.durMin = _clampDur(d === 0 ? _SLEEP_DUR_MAX : d);
    if (wm != null) s.wakeMin = wm;
  }
  sleepDurRender(true);   // true → don't overwrite the field being edited
}

function sleepDurRender(fromExact) {
  const s = window._sleepEntry; if (!s) return;
  const bedMin = ((s.wakeMin - s.durMin) % 1440 + 1440) % 1440;
  const h = Math.floor(s.durMin/60);

  const wrap    = document.getElementById('sleep-dur-wrap');
  const readout = document.getElementById('sleep-dur-readout');
  const cap     = document.getElementById('sleep-dur-caption');
  const range   = document.getElementById('sleep-dur-range');
  if (readout) readout.textContent = _fmtDurMin(s.durMin);
  if (wrap)    wrap.className = h >= 7 ? 'sleep-dur--good' : h >= 5 ? 'sleep-dur--ok' : 'sleep-dur--low';
  // Show the clock times this duration implies — keeps duration-first honest
  // about exactly what it will save.
  if (cap)     cap.textContent = `${_min12(bedMin)} → ${_min12(s.wakeMin)}`;
  if (range) {
    if (+range.value !== s.durMin) range.value = s.durMin;
    range.style.setProperty('--fill', (s.durMin - _SLEEP_DUR_MIN) / (_SLEEP_DUR_MAX - _SLEEP_DUR_MIN) * 100 + '%');
  }
  if (!fromExact) {
    const bedEl = document.getElementById('sleep-bed-time'), wakeEl = document.getElementById('sleep-wake-time');
    if (bedEl)  bedEl.value  = _minToHHMM(bedMin);
    if (wakeEl) wakeEl.value = _minToHHMM(s.wakeMin);
  }

  // Absolute datetimes for save — bedtime falls on the previous day whenever
  // the duration crosses midnight, which the old yesterday-string hack got
  // wrong for early/short entries. Anchor to this morning's wake and subtract.
  const now = new Date();
  const wakeDate = new Date(now.getFullYear(), now.getMonth(), now.getDate(), Math.floor(s.wakeMin/60), s.wakeMin%60);
  const bedDate  = new Date(wakeDate.getTime() - s.durMin*60000);
  const fmtDT = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}` +
                     `T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
  window._svBed  = fmtDT(bedDate);
  window._svWake = fmtDT(wakeDate);
}

function selectSleepQ(q, suffix) {
  const grid = document.getElementById('sleep-q-' + (suffix || ''));
  // The quality buttons carry class .sdial-q-btn — the old selector looked for
  // .sleep-q-btn and so never moved the highlight.
  if (grid) grid.querySelectorAll('.sdial-q-btn').forEach(b => {
    b.classList.toggle('active', parseInt(b.dataset.q) === q);
  });
  if (suffix === 'sv') window._svQuality = q;
  else window._sleepQ = q;
}

async function saveSleepLogFromView() {
  // Full local datetimes computed by sleepDurRender (bed may be the prior day).
  const bed = window._svBed, wake = window._svWake;
  if (!bed || !wake) { showToast('Set how long you slept', 'error'); return; }

  const r = await fetch('/api/sleep', {
    method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({
      bedtime:   bed,
      wake_time: wake,
      // The night is keyed to the morning you woke, so re-logging the same
      // night replaces it regardless of whether bedtime was before midnight.
      date_key:  wake.slice(0, 10),
      quality:   window._svQuality || 4,
      notes:     document.getElementById('sleep-notes-sv')?.value || '',
    })
  }).then(r => r.json()).catch(() => null);

  if (r?.success) {
    showToast('Sleep logged ✓', 'success');
    refreshSleep();   // focal 7-day average included — not just the trend/strip
  } else {
    showToast(r?.error || 'Failed to save', 'error');
  }
}

// ════════════════════════════════════════════════════════════
// BODY & VITALS VIEW — standalone page
// ════════════════════════════════════════════════════════════
// ── Health goals ─────────────────────────────────────────────────────────────
// Outcome goals with a finish line (target + direction + optional deadline).
// Progress is derived from the user's own logged values — honest "log X to see
// progress" when there's no reading yet.
let _goalMetrics = [];
let _goalShowDone = false;

const GOAL_DIR = { below:'Get below', above:'Get above', reach:'Reach' };

async function loadGoals() {
  const el = document.getElementById('goals-view-content');
  if (!el) return;
  const d = await fetch('/api/goals' + (_goalShowDone ? '?all=1' : ''), {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {goals:[],metrics:[]}).catch(() => ({goals:[],metrics:[]}));
  _goalMetrics = d.metrics || [];
  el.innerHTML = renderGoals(d.goals || []);
}

function onGoalMetricPick() {
  // Default the direction to the metric's natural one; unit hint on the target.
  const sel = document.getElementById('goal-metric');
  const m = _goalMetrics.find(x => x.key === sel?.value);
  const dir = document.getElementById('goal-dir');
  if (m && dir) dir.value = m.dir;
  const unit = document.getElementById('goal-unit');
  if (unit) unit.textContent = m ? m.unit : '';
}

function renderGoals(goals) {
  const mOpts = _goalMetrics.map(m => `<option value="${m.key}">${t(m.name)}</option>`).join('');
  const dOpts = Object.entries(GOAL_DIR).map(([k, v]) => `<option value="${k}">${t(v)}</option>`).join('');
  const today = localToday();
  const form = `
    <div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Set a goal')}</h2>
      <div class="goal-form">
        <select id="goal-metric" class="form-input" data-ev-change="onGoalMetricPick()" style="max-width:170px">${mOpts}</select>
        <select id="goal-dir" class="form-input" style="max-width:130px">${dOpts}</select>
        <input type="number" step="any" id="goal-target" class="form-input" placeholder="${t('Target')}" style="max-width:110px">
        <span id="goal-unit" class="goal-unit"></span>
        <input type="date" id="goal-deadline" class="form-input" min="${today}" title="${t('Deadline (optional)')}" style="max-width:160px">
        <button class="btn-primary" data-ev-click="addGoal()">${t('Add')}</button>
      </div>
    </div>`;

  const toggle = `<div style="text-align:right;margin-bottom:10px">
      <button class="btn-outline" style="font-size:12px" data-ev-click="toggleGoalDone()">${_goalShowDone ? t('Hide finished') : t('Show finished')}</button></div>`;

  if (!goals.length) {
    return form + `<div class="panel" style="padding:28px;text-align:center">
        <div style="font-size:30px;margin-bottom:8px">🎯</div>
        <div style="font-size:14px;font-weight:600;margin-bottom:4px">${t('No goals yet')}</div>
        <div style="font-size:13px;color:var(--gray-400)">${t('Set a target above — like HbA1c below 6.5, or 8,000 steps a day.')}</div>
      </div>`;
  }

  const cards = goals.map(g => {
    const done = g.status !== 'active';
    const pct = g.progress != null ? Math.round(g.progress * 100) : null;
    const dirWord = t(GOAL_DIR[g.direction] || 'Reach').toLowerCase();
    const title = g.title || `${t(g.metric_name)} · ${dirWord} ${g.target_value}${g.unit ? ' ' + g.unit : ''}`;
    const bar = pct != null
      ? `<div class="goal-bar"><div class="goal-fill${g.auto_achieved ? ' goal-fill--done' : ''}" style="width:${pct}%"></div></div>
         <div class="goal-progress-label">${g.current != null ? `${t('now')} ${g.current}${g.unit ? ' ' + g.unit : ''}` : ''} · ${pct}%${g.auto_achieved ? ' · ' + t('🎉 reached!') : ''}</div>`
      : `<div class="goal-nodata">${tformat('Log a %1 reading to see progress.', t(g.metric_name).toLowerCase())}</div>`;
    let deadline = '';
    if (g.days_left != null) {
      deadline = g.days_left < 0 ? `<span class="goal-overdue">${tformat('%1 days overdue', -g.days_left)}</span>`
               : `<span class="goal-deadline">${tformat('%1 days left', g.days_left)}</span>`;
    }
    return `<div class="panel goal-card${done ? ' goal-card--done' : ''}" style="padding:16px 18px;margin-bottom:12px">
        <div class="goal-head">
          <div style="flex:1"><div class="goal-title">${escHtml(title)}</div>
            <div class="goal-meta">${t('target')} ${g.target_value}${g.unit ? ' ' + g.unit : ''}${deadline ? ' · ' + deadline : ''}</div></div>
          ${done ? `<span class="goal-badge">${g.status === 'achieved' ? t('done') : t('archived')}</span>` :
            (g.auto_achieved ? `<button class="btn-outline" style="font-size:11px" data-ev-click="markGoal('${g.id}','achieved')">${t('Mark done')}</button>` : '')}
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteGoal('${g.id}')" style="color:var(--gray-300)">✕</button>
        </div>
        ${bar}
      </div>`;
  }).join('');

  return form + toggle + cards;
}

function toggleGoalDone() { _goalShowDone = !_goalShowDone; loadGoals(); }

async function addGoal() {
  const metric = document.getElementById('goal-metric')?.value;
  const target_value = document.getElementById('goal-target')?.value;
  const direction = document.getElementById('goal-dir')?.value;
  const deadline = document.getElementById('goal-deadline')?.value || null;
  if (target_value === '' || target_value == null) { showToast('Enter a target', 'error'); return; }
  const r = await fetch('/api/goals', {
    method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
    body: JSON.stringify({metric, target_value, direction, deadline}),
  }).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(t('Goal set 🎯')); loadGoals(); }
  else showToast((r && r.error) || 'Could not save', 'error');
}

async function markGoal(id, status) {
  await fetch('/api/goals/' + id, {method:'PATCH', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify({status})}).catch(() => {});
  if (status === 'achieved') { try { celebrate && celebrate(); } catch (e) {} }
  loadGoals();
}

async function deleteGoal(id) {
  await fetch('/api/goals/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadGoals();
}

// ── Fasting tracker ──────────────────────────────────────────────────────────
// A neutral eating-window log: start a fast, watch the clock, end it when you
// eat. The live timer ticks from the recorded start; nothing is invented.
// Deliberately un-gamified — no streaks, plus a soft support note.
let _fastTimer = null;
let _activeFast = null;

function _fastFmt(h) {
  if (h == null) return '—';
  const total = Math.max(0, Math.round(h * 60));
  const hh = Math.floor(total / 60), mm = total % 60;
  return hh + 'h ' + String(mm).padStart(2, '0') + 'm';
}

async function loadFasting() {
  if (_fastTimer) { clearInterval(_fastTimer); _fastTimer = null; }
  const el = document.getElementById('fasting-view-content');
  if (!el) return;
  const d = await fetch('/api/fasting', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : null).catch(() => null);
  if (!d) { el.innerHTML = `<div class="panel" style="padding:20px">${t('Could not load')}</div>`; return; }
  _activeFast = d.active ? {start_at: d.active.start_at, target: d.active.target_hours} : null;
  el.innerHTML = renderFasting(d);
  if (_activeFast) {
    _tickFast();
    _fastTimer = setInterval(_tickFast, 1000 * 30);   // 30s is plenty for h:m
  }
}

function _tickFast() {
  if (!_activeFast) return;
  const box = document.getElementById('fast-elapsed');
  if (!box) { if (_fastTimer) { clearInterval(_fastTimer); _fastTimer = null; } return; }
  const elapsed = (Date.now() - Date.parse(_activeFast.start_at)) / 3600000;
  const target = _activeFast.target || 0;
  box.textContent = _fastFmt(elapsed);
  const rem = document.getElementById('fast-remaining');
  const fill = document.getElementById('fast-fill');
  if (target > 0) {
    const reached = elapsed >= target;
    if (rem) rem.textContent = reached ? t('🎉 Target reached — end whenever you like')
                                       : tformat('%1 to go', _fastFmt(target - elapsed));
    if (fill) {
      fill.style.width = Math.max(0, Math.min(elapsed / target, 1)) * 100 + '%';
      fill.classList.toggle('goal-fill--done', reached);
    }
  }
}

function renderFasting(d) {
  let top;
  if (d.active) {
    const started = new Date(Date.parse(d.active.start_at));
    const startLbl = started.toLocaleString([], {weekday:'short', hour:'2-digit', minute:'2-digit'});
    // Compute the first paint from the SAME client clock _tickFast uses, so the
    // display doesn't jump on the first tick if the server's local time differs.
    const target = d.active.target_hours || 0;
    const elapsed0 = (Date.now() - Date.parse(d.active.start_at)) / 3600000;
    const reached0 = target > 0 && elapsed0 >= target;
    const pct0 = target > 0 ? Math.max(0, Math.min(elapsed0 / target, 1)) : 0;
    top = `<div class="panel fast-live" style="padding:26px 22px;text-align:center;margin-bottom:16px">
        <div class="fast-target-lbl">${tformat('%1 h fast', d.active.target_hours)}</div>
        <div id="fast-elapsed" class="fast-clock">${_fastFmt(elapsed0)}</div>
        <div id="fast-remaining" class="fast-remaining">${
          reached0 ? t('🎉 Target reached — end whenever you like')
          : tformat('%1 to go', _fastFmt(Math.max(0, target - elapsed0)))}</div>
        <div class="goal-bar" style="max-width:320px;margin:14px auto 4px">
          <div id="fast-fill" class="goal-fill${reached0 ? ' goal-fill--done' : ''}"
               style="width:${Math.round(pct0 * 100)}%"></div></div>
        <div class="fast-started">${tformat('Started %1', startLbl)}</div>
        <button class="btn-primary" style="margin-top:16px" data-ev-click="endFast()">${t('End fast')}</button>
      </div>`;
  } else {
    const presets = (d.presets || []).map(p =>
      `<button class="fast-preset" data-ev-click="startFast(${p.hours})">
         <div class="fast-preset-lbl">${p.label}</div>
         <div class="fast-preset-h">${tformat('%1 h', p.hours)}</div></button>`).join('');
    top = `<div class="panel" style="padding:22px;margin-bottom:16px">
        <h2 class="panel-title" style="margin-bottom:14px">${t('Start a fast')}</h2>
        <div class="fast-presets">${presets}</div>
        <div class="fast-custom">
          <input type="number" id="fast-custom-h" class="form-input" min="1" max="48" step="1"
                 placeholder="${t('Custom hours')}" style="max-width:140px">
          <button class="btn-outline" data-ev-click="startFast()">${t('Start')}</button>
        </div>
      </div>`;
  }

  const s = d.stats || {};
  const stats = s.completed ? `<div class="fast-stats">
      <div class="fast-stat"><div class="fast-stat-n">${s.completed}</div><div class="fast-stat-l">${t('fasts logged')}</div></div>
      <div class="fast-stat"><div class="fast-stat-n">${s.avg_hours != null ? s.avg_hours + 'h' : '—'}</div><div class="fast-stat-l">${t('average')}</div></div>
      <div class="fast-stat"><div class="fast-stat-n">${s.longest_hours != null ? s.longest_hours + 'h' : '—'}</div><div class="fast-stat-l">${t('longest')}</div></div>
    </div>` : '';

  let history = '';
  if ((d.history || []).length) {
    const rows = d.history.map(h => {
      const dt = new Date(Date.parse(h.start_at));
      const day = dt.toLocaleDateString([], {month:'short', day:'numeric'});
      const hit = h.reached_target ? '<span class="fast-hit">✓</span>' : '';
      return `<div class="fast-hist-row">
          <div class="fast-hist-day">${day}</div>
          <div class="fast-hist-dur">${_fastFmt(h.duration_hours)} ${hit}</div>
          <div class="fast-hist-target">${tformat('target %1 h', h.target_hours)}</div>
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteFast('${h.id}')" style="color:var(--gray-300)">✕</button>
        </div>`;
    }).join('');
    history = `<div class="panel" style="padding:16px 20px"><h2 class="panel-title" style="margin-bottom:8px">${t('History')}</h2>${rows}</div>`;
  }

  const note = `<p class="fast-note">${t('This is a simple log, not medical advice. If food or fasting feels hard to control, talking to a doctor or counsellor can help.')}</p>`;
  return top + stats + history + note;
}

async function startFast(hours) {
  let target = hours;
  if (target == null) {
    const v = document.getElementById('fast-custom-h')?.value;
    target = v ? Number(v) : null;
    if (!target || target <= 0) { showToast(t('Enter hours'), 'error'); return; }
  }
  const r = await fetch('/api/fasting/start', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify({target_hours: target})})
    .then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(t('Fast started ⏱️')); loadFasting(); }
  else showToast((r && r.error) || t('Could not start'), 'error');
}

async function endFast() {
  const r = await fetch('/api/fasting/end', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify({})}).then(x => x.json()).catch(() => null);
  if (r && r.success) {
    if (r.fast && r.fast.reached_target) { try { celebrate && celebrate(); } catch (e) {} }
    showToast(t('Fast ended'));
    loadFasting();
  } else showToast((r && r.error) || t('Could not end'), 'error');
}

async function deleteFast(id) {
  await fetch('/api/fasting/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadFasting();
}

// ── Health ID card ───────────────────────────────────────────────────────────
// A wallet-style card to show at a hospital/pharmacy. Composes the profile,
// the emergency card, and the user's ACTUAL active medicines (read live from
// the tracker, so it never drifts). Printable; contacts are tap-to-call.
async function loadHealthId() {
  const el = document.getElementById('health-id-content');
  if (!el) return;
  const d = await fetch('/api/health-id', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : null).catch(() => null);
  if (!d) { el.innerHTML = `<div class="panel" style="padding:20px">${t('Could not load')}</div>`; return; }
  el.innerHTML = renderHealthId(d);
  loadHealthIdQr();
}

// Scannable emergency QR on the ID card — a self-contained SVG from the server
// (segno). Renders only when there's info to encode and the library is present.
async function loadHealthIdQr() {
  const slot = document.getElementById('hid-qr');
  if (!slot) return;
  const d = await fetch('/api/health-id/qr').then(r => r.json()).catch(() => null);
  if (!d || !d.available || !d.svg) { slot.innerHTML = ''; return; }
  // The SVG is generated by our own backend (segno) — safe to inline.
  slot.innerHTML = `<div class="hid-qr-img">${d.svg}</div>
    <div class="hid-qr-cap">${t('Scan for emergency info')}</div>`;
}

function _hidRow(label, value, cls) {
  if (!value) return '';
  return `<div class="hid-row"><div class="hid-label">${t(label)}</div>
    <div class="hid-value ${cls || ''}">${escHtml(value)}</div></div>`;
}

// Allergies on the ID card: prefer the structured list (with severity), fall
// back to the legacy free-text box.
function _hidAllergyRow(d) {
  const list = d.allergy_list || [];
  if (list.length) {
    const items = list.map(a => {
      const sev = a.severity === 'severe' ? ` <b>(${t('severe')})</b>` : '';
      return `<div>${escHtml(a.allergen)}${sev}${a.reaction ? ` — ${escHtml(a.reaction)}` : ''}</div>`;
    }).join('');
    return `<div class="hid-row"><div class="hid-label">${t('Allergies')}</div>
      <div class="hid-value hid-alert">${items}</div></div>`;
  }
  return _hidRow('Allergies', d.allergies, 'hid-alert');
}

function renderHealthId(d) {
  const id = d.identity || {};
  const sub = [];
  if (id.age != null) sub.push(tformat('%1 yrs', id.age));
  // escHtml: gender is free-text the user controls and could contain markup;
  // t() is a passthrough that doesn't escape, so escape before it hits innerHTML.
  if (id.gender) sub.push(escHtml(t(id.gender)));
  if (id.blood_type || d.blood_type) { /* shown as its own row */ }
  const bio = [];
  if (id.height_cm) bio.push(id.height_cm + ' cm');
  if (id.weight_kg) bio.push(id.weight_kg + ' kg');

  // Active meds — the live list. Fall back to the emergency free-text if the
  // tracker is empty (honest: it's what they typed, labelled as such).
  let medsHtml = '';
  if ((d.active_medicines || []).length) {
    medsHtml = d.active_medicines.map(m =>
      `<li>${escHtml(m.name)}${m.dose ? ' · ' + escHtml(m.dose) : ''}</li>`).join('');
    medsHtml = `<ul class="hid-meds">${medsHtml}</ul>`;
  } else if (d.notes_medications) {
    medsHtml = `<div class="hid-value">${escHtml(d.notes_medications)}</div>`;
  }
  const medsBlock = medsHtml
    ? `<div class="hid-row"><div class="hid-label">${t('Current medicines')}</div>${medsHtml}</div>` : '';

  const contacts = (d.contacts || []).map(c => {
    const tel = (c.phone || '').replace(/[^\d+]/g, '');
    const num = c.phone ? `<a href="tel:${tel}" class="hid-tel">${escHtml(c.phone)}</a>` : '';
    return `<div class="hid-contact"><span>${escHtml(c.name || t('Contact'))}</span>${num}</div>`;
  }).join('');
  const contactsBlock = contacts
    ? `<div class="hid-row hid-emergency"><div class="hid-label">${t('In an emergency, call')}</div>
        <div class="hid-contacts">${contacts}</div></div>` : '';

  const ins = d.insurance || {};
  const insVal = [ins.provider, ins.number].filter(Boolean).join(' · ');

  // M1 — advance-care wishes, shown verbatim (the user's own words), only when set.
  const ac = d.advance_care || {};
  const acBlock = [
    ac.organ_donor ? _hidRow('Organ donor', ac.organ_donor) : '',
    ac.directive_wishes ? _hidRow('Medical wishes', ac.directive_wishes) : '',
    ac.directive_location ? _hidRow('Directives kept', ac.directive_location) : '',
  ].join('');

  const anyData = id.name || d.blood_type || d.allergies || (d.allergy_list || []).length ||
    d.conditions || (d.active_medicines || []).length || contacts || insVal ||
    ac.organ_donor || ac.directive_wishes || ac.directive_location;

  const card = `
    <div id="health-id-card" class="hid-card">
      <div class="hid-brand">🌱 Arogo · ${t('Health ID')}</div>
      <div class="hid-name">${escHtml(id.name || t('Add your name in Settings'))}</div>
      ${(sub.length || bio.length) ? `<div class="hid-sub">${[...sub, ...bio].join(' · ')}</div>` : ''}
      <div class="hid-body">
        ${_hidRow('Blood type', d.blood_type, 'hid-blood')}
        ${_hidAllergyRow(d)}
        ${_hidRow('Conditions', d.conditions)}
        ${medsBlock}
        ${contactsBlock}
        ${_hidRow('Insurance', insVal)}
        ${acBlock}
      </div>
      <div id="hid-qr" class="hid-qr"></div>
      <div class="hid-foot">${t('Generated by Arogo from your own records. Not a substitute for official ID.')}</div>
    </div>`;

  const actions = `<div class="hid-actions">
      <button class="btn-primary" data-ev-click="printHealthId()">🖨️ ${t('Print / Save PDF')}</button>
      <button class="btn-outline" data-ev-click="switchView('reports');setTimeout(()=>switchMedTab&&switchMedTab('emergency'),60)">${t('Edit details')}</button>
    </div>`;

  const empty = anyData ? '' :
    `<p class="hid-empty-note">${t('Fill in your blood type, allergies and an emergency contact under Edit details to make this card useful.')}</p>`;

  return card + actions + empty;
}

function printHealthId() {
  document.body.classList.add('printing-health-id');
  const clear = () => { document.body.classList.remove('printing-health-id'); window.removeEventListener('afterprint', clear); };
  window.addEventListener('afterprint', clear);
  try { window.print(); } catch (e) { clear(); }
  // Safari/some browsers don't fire afterprint reliably — clear on a fallback timer.
  setTimeout(clear, 1500);
}

// ── Shared care plan ─────────────────────────────────────────────────────────
// The agreements between a person, their caregiver and their doctor: what to do,
// who owns it, when to review. Shared through the same acting-as model, so a
// caregiver managing a member sees and edits that member's plan. All items are
// human-authored — the app never writes medical advice of its own.
const CARE_CAT = {
  medication:  {icon:'💊', label:'Medication'},
  lifestyle:   {icon:'🏃', label:'Lifestyle'},
  monitoring:  {icon:'📈', label:'Monitoring'},
  appointment: {icon:'📅', label:'Appointments'},
  other:       {icon:'📋', label:'Other'},
};
const CARE_OWNER = {me:'Me', caregiver:'Caregiver', doctor:'Doctor'};

async function loadCarePlan() {
  const el = document.getElementById('care-plan-content');
  if (!el) return;
  const d = await fetch('/api/care-plan', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : null).catch(() => null);
  if (!d) { el.innerHTML = `<div class="panel" style="padding:20px">${t('Could not load')}</div>`; return; }
  el.innerHTML = renderCarePlan(d);
}

function renderCarePlan(d) {
  const catOpts = (d.categories || []).map(c =>
    `<option value="${c}">${CARE_CAT[c] ? CARE_CAT[c].icon + ' ' + t(CARE_CAT[c].label) : c}</option>`).join('');
  const ownerOpts = (d.owners || []).map(o =>
    `<option value="${o}">${t(CARE_OWNER[o] || o)}</option>`).join('');

  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Add to the plan')}</h2>
      <div class="cp-form">
        <input type="text" id="cp-title" class="form-input" placeholder="${t('What to do (e.g. Walk 30 min after dinner)')}" style="flex:2;min-width:200px">
        <select id="cp-category" class="form-input" style="max-width:160px">${catOpts}</select>
        <select id="cp-owner" class="form-input" style="max-width:130px" title="${t('Who is responsible')}">${ownerOpts}</select>
        <input type="date" id="cp-review" class="form-input" title="${t('Review date (optional)')}" style="max-width:150px">
        <button class="btn-primary" data-ev-click="addCareItem()">${t('Add')}</button>
      </div>
    </div>`;

  const s = d.summary || {};
  const summary = s.total ? `<div class="cp-summary">${
      tformat('%1 active · %2 done', s.active, s.done)}</div>` : '';

  if (!(d.items || []).length) {
    return form + `<div class="panel" style="padding:28px;text-align:center">
        <div style="font-size:30px;margin-bottom:8px">📋</div>
        <div style="font-size:14px;font-weight:600;margin-bottom:4px">${t('No plan yet')}</div>
        <div style="font-size:13px;color:var(--gray-400)">${t('Add what you and your care team have agreed on — medicines, lifestyle changes, things to monitor, appointments.')}</div>
      </div>`;
  }

  // Group by category, active before done (list already sorts done last).
  const byCat = {};
  d.items.forEach(i => { (byCat[i.category] = byCat[i.category] || []).push(i); });
  const groups = Object.keys(CARE_CAT).filter(c => byCat[c]).map(c => {
    const meta = CARE_CAT[c];
    const rows = byCat[c].map(i => {
      const done = i.status === 'done';
      const ownerChip = `<span class="cp-owner cp-owner--${i.owner}">${t(CARE_OWNER[i.owner] || i.owner)}</span>`;
      const review = i.review_date ? `<span class="cp-review">${tformat('review %1', i.review_date)}</span>` : '';
      return `<div class="cp-item${done ? ' cp-item--done' : ''}">
          <button class="cp-check${done ? ' cp-check--done' : ''}" title="${done ? t('Mark active') : t('Mark done')}"
                  data-ev-click="toggleCareItem('${i.id}','${done ? 'active' : 'done'}')">${done ? '✓' : ''}</button>
          <div class="cp-main">
            <div class="cp-item-title">${escHtml(i.title)}</div>
            ${i.detail ? `<div class="cp-item-detail">${escHtml(i.detail)}</div>` : ''}
            <div class="cp-item-meta">${ownerChip}${review}</div>
          </div>
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteCareItem('${i.id}')" style="color:var(--gray-300)">✕</button>
        </div>`;
    }).join('');
    return `<div class="panel cp-group" style="padding:14px 18px;margin-bottom:12px">
        <div class="cp-group-head">${meta.icon} ${t(meta.label)}</div>${rows}</div>`;
  }).join('');

  return form + summary + groups;
}

async function addCareItem() {
  const title = document.getElementById('cp-title')?.value?.trim();
  if (!title) { showToast(t('Enter what to do'), 'error'); return; }
  const body = {
    title,
    category: document.getElementById('cp-category')?.value || 'other',
    owner: document.getElementById('cp-owner')?.value || 'me',
    review_date: document.getElementById('cp-review')?.value || null,
  };
  const r = await fetch('/api/care-plan', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(t('Added to plan')); loadCarePlan(); }
  else showToast((r && r.error) || t('Could not save'), 'error');
}

async function toggleCareItem(id, status) {
  await fetch('/api/care-plan/' + id, {method:'PATCH', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify({status})}).catch(() => {});
  loadCarePlan();
}

async function deleteCareItem(id) {
  await fetch('/api/care-plan/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadCarePlan();
}

// ── My care team (provider directory) ────────────────────────────────────────
// The user's own doctors and clinics: name, specialty, phone (tap-to-call),
// clinic, address, notes. Plain contact records they type themselves.
let _editingProvider = null;

async function loadCareTeam() {
  const el = document.getElementById('care-team-content');
  if (!el) return;
  const d = await fetch('/api/providers', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {providers:[]}).catch(() => ({providers:[]}));
  el.innerHTML = renderCareTeam(d.providers || []);
}

function renderCareTeam(providers) {
  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px" id="ct-form-title">${t('Add a provider')}</h2>
      <div class="ct-form">
        <input type="text" id="ct-name" class="form-input" placeholder="${t('Name (e.g. Dr Meera Nair)')}" style="flex:2;min-width:180px">
        <input type="text" id="ct-specialty" class="form-input" placeholder="${t('Specialty')}" style="max-width:150px">
        <input type="tel" id="ct-phone" class="form-input" placeholder="${t('Phone')}" style="max-width:150px">
        <input type="text" id="ct-clinic" class="form-input" placeholder="${t('Clinic / hospital')}" style="flex:1;min-width:150px">
        <input type="text" id="ct-address" class="form-input" placeholder="${t('Address (optional)')}" style="flex:2;min-width:180px">
        <button class="btn-primary" data-ev-click="saveProvider()" id="ct-save-btn">${t('Add')}</button>
        <button class="btn-outline" data-ev-click="cancelProviderEdit()" id="ct-cancel-btn" style="display:none">${t('Cancel')}</button>
      </div>
    </div>`;

  if (!providers.length) {
    return form + `<div class="panel" style="padding:28px;text-align:center">
        <div style="font-size:30px;margin-bottom:8px">🩺</div>
        <div style="font-size:14px;font-weight:600;margin-bottom:4px">${t('No providers yet')}</div>
        <div style="font-size:13px;color:var(--gray-400)">${t('Add your GP, specialists and clinics so their numbers are one tap away.')}</div>
      </div>`;
  }

  const cards = providers.map(p => {
    const tel = (p.phone || '').replace(/[^\d+]/g, '');
    const call = p.phone ? `<a href="tel:${tel}" class="ct-call" title="${t('Call')}">📞 ${escHtml(p.phone)}</a>` : '';
    const loc = [p.clinic, p.address].filter(Boolean).map(escHtml).join(' · ');
    return `<div class="panel ct-card" style="padding:15px 18px;margin-bottom:12px">
        <div class="ct-card-head">
          <div class="ct-avatar">🩺</div>
          <div style="flex:1;min-width:0">
            <div class="ct-name">${escHtml(p.name)}</div>
            ${p.specialty ? `<div class="ct-specialty">${escHtml(p.specialty)}</div>` : ''}
          </div>
          <button class="btn-icon" title="${t('Edit')}" data-ev-click="startProviderEdit('${p.id}')">✎</button>
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteProvider('${p.id}')" style="color:var(--gray-300)">✕</button>
        </div>
        <div class="ct-card-body">
          ${call}
          ${loc ? `<div class="ct-loc">📍 ${loc}</div>` : ''}
          ${p.notes ? `<div class="ct-notes">${escHtml(p.notes)}</div>` : ''}
        </div>
      </div>`;
  }).join('');
  return form + cards;
}

function _providerForm() {
  return {
    name: document.getElementById('ct-name')?.value?.trim(),
    specialty: document.getElementById('ct-specialty')?.value || '',
    phone: document.getElementById('ct-phone')?.value || '',
    clinic: document.getElementById('ct-clinic')?.value || '',
    address: document.getElementById('ct-address')?.value || '',
  };
}

async function saveProvider() {
  const body = _providerForm();
  if (!body.name) { showToast(t('Enter a name'), 'error'); return; }
  const url = _editingProvider ? '/api/providers/' + _editingProvider : '/api/providers';
  const method = _editingProvider ? 'PATCH' : 'POST';
  const r = await fetch(url, {method, headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(_editingProvider ? t('Provider updated') : t('Provider added')); _editingProvider = null; loadCareTeam(); }
  else showToast((r && r.error) || t('Could not save'), 'error');
}

async function startProviderEdit(id) {
  const d = await fetch('/api/providers', {credentials:'same-origin'}).then(r => r.json()).catch(() => null);
  const p = d && d.providers.find(x => x.id === id);
  if (!p) return;
  _editingProvider = id;
  const set = (i, v) => { const el = document.getElementById(i); if (el) el.value = v || ''; };
  set('ct-name', p.name); set('ct-specialty', p.specialty); set('ct-phone', p.phone);
  set('ct-clinic', p.clinic); set('ct-address', p.address);
  const title = document.getElementById('ct-form-title'); if (title) title.textContent = t('Edit provider');
  const save = document.getElementById('ct-save-btn'); if (save) save.textContent = t('Save');
  const cancel = document.getElementById('ct-cancel-btn'); if (cancel) cancel.style.display = '';
  document.getElementById('ct-name')?.scrollIntoView({block:'center'});
}

function cancelProviderEdit() { _editingProvider = null; loadCareTeam(); }

async function deleteProvider(id) {
  await fetch('/api/providers/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  if (_editingProvider === id) _editingProvider = null;
  loadCareTeam();
}

// ── Prescription library ─────────────────────────────────────────────────────
// The paperwork behind the medicines: prescriber, date, validity, refills left,
// and which medicines each Rx covers. A renewal nudge is derived from the expiry
// date — a reminder to renew, never a clinical instruction.
let _editingRx = null;
let _rxLibMeds = [];

async function loadPrescriptions() {
  const el = document.getElementById('prescriptions-content');
  if (!el) return;
  const [d, meds] = await Promise.all([
    fetch('/api/prescriptions', {credentials:'same-origin'}).then(r => r.ok ? r.json() : {prescriptions:[]}).catch(() => ({prescriptions:[]})),
    fetch('/api/medicines', {credentials:'same-origin'}).then(r => r.ok ? r.json() : []).catch(() => []),
  ]);
  _rxLibMeds = (meds || []).filter(m => m.active);
  el.innerHTML = renderPrescriptions(d.prescriptions || []);
}

const RX_STATUS = {
  expired:  {cls:'rx-expired',  label:'Expired'},
  expiring: {cls:'rx-expiring', label:'Renew soon'},
  valid:    {cls:'rx-valid',    label:'Valid'},
};

function renderPrescriptions(list) {
  const today = localToday();
  const medChecks = _rxLibMeds.length
    ? `<div class="rx-med-picker">${_rxLibMeds.map(m => `<label class="rx-med-chk">
         <input type="checkbox" value="${m.id}" class="rx-med-cb"> ${escHtml(m.icon || '💊')} ${escHtml(m.name)}</label>`).join('')}</div>`
    : `<div class="rx-note">${t('Add medicines first to link them to a prescription.')}</div>`;

  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px" id="rx-form-title">${t('Add a prescription')}</h2>
      <div class="rx-form">
        <input type="text" id="rx-prescriber" class="form-input" placeholder="${t('Prescriber (e.g. Dr Nair)')}" style="flex:2;min-width:170px">
        <label class="rx-field"><span>${t('Issued')}</span><input type="date" id="rx-issued" class="form-input" value="${today}" max="${today}"></label>
        <label class="rx-field"><span>${t('Valid until')}</span><input type="date" id="rx-valid" class="form-input"></label>
        <label class="rx-field"><span>${t('Refills left')}</span><input type="number" id="rx-refills" class="form-input" min="0" max="99" style="max-width:80px"></label>
      </div>
      <div class="rx-med-label">${t('Covers')}</div>
      ${medChecks}
      <div style="margin-top:12px">
        <button class="btn-primary" data-ev-click="saveRx()" id="rx-save-btn">${t('Add')}</button>
        <button class="btn-outline" data-ev-click="cancelRxEdit()" id="rx-cancel-btn" style="display:none">${t('Cancel')}</button>
      </div>
    </div>`;

  if (!list.length) {
    return form + `<div class="panel" style="padding:28px;text-align:center">
        <div style="font-size:30px;margin-bottom:8px">📄</div>
        <div style="font-size:14px;font-weight:600;margin-bottom:4px">${t('No prescriptions yet')}</div>
        <div style="font-size:13px;color:var(--gray-400)">${t('Log a prescription to track its refills and renewal date.')}</div>
      </div>`;
  }

  const cards = list.map(p => {
    const badge = p.status ? `<span class="rx-badge ${RX_STATUS[p.status].cls}">${t(RX_STATUS[p.status].label)}</span>` : '';
    let expiry = '';
    if (p.valid_until) {
      const d = p.days_until_expiry;
      expiry = p.status === 'expired' ? `<span class="rx-expiry-txt rx-expired">${tformat('expired %1 days ago', -d)}</span>`
             : p.status === 'expiring' ? `<span class="rx-expiry-txt rx-expiring">${tformat('expires in %1 days', d)}</span>`
             : `<span class="rx-expiry-txt">${tformat('valid to %1', _fmtShortDate(p.valid_until))}</span>`;
    }
    const refill = p.refills_left != null
      ? `<span class="rx-refill${p.refills_left === 0 ? ' rx-refill-0' : ''}">${tformat('%1 refills left', p.refills_left)}</span>` : '';
    const meds = (p.medicines || []).map(m => `<span class="rx-med-chip">${escHtml(m.icon || '💊')} ${escHtml(m.name)}</span>`).join('');
    return `<div class="panel rx-card" style="padding:15px 18px;margin-bottom:12px">
        <div class="rx-card-head">
          <div style="flex:1;min-width:0">
            <div class="rx-prescriber">${escHtml(p.prescriber || t('Prescription'))} ${badge}</div>
            <div class="rx-meta">${tformat('issued %1', _fmtShortDate(p.date_issued))}${expiry ? ' · ' : ''}${expiry}${refill ? ' · ' + refill : ''}</div>
          </div>
          <button class="btn-icon" title="${t('Edit')}" data-ev-click="startRxEdit('${p.id}')">✎</button>
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteRx('${p.id}')" style="color:var(--gray-300)">✕</button>
        </div>
        ${meds ? `<div class="rx-meds">${meds}</div>` : ''}
        ${p.notes ? `<div class="rx-notes">${escHtml(p.notes)}</div>` : ''}
      </div>`;
  }).join('');
  return form + cards;
}

function _rxFormBody() {
  const checked = [...document.querySelectorAll('.rx-med-cb:checked')].map(c => c.value);
  return {
    prescriber: document.getElementById('rx-prescriber')?.value?.trim() || '',
    date_issued: document.getElementById('rx-issued')?.value || '',
    valid_until: document.getElementById('rx-valid')?.value || null,
    refills_left: document.getElementById('rx-refills')?.value || null,
    medicine_ids: checked,
  };
}

async function saveRx() {
  const body = _rxFormBody();
  if (!body.prescriber && !body.medicine_ids.length) { showToast(t('Add a prescriber or a medicine'), 'error'); return; }
  const url = _editingRx ? '/api/prescriptions/' + _editingRx : '/api/prescriptions';
  const r = await fetch(url, {method: _editingRx ? 'PATCH' : 'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(_editingRx ? t('Prescription updated') : t('Prescription added')); _editingRx = null; loadPrescriptions(); }
  else showToast((r && r.error) || t('Could not save'), 'error');
}

async function startRxEdit(id) {
  const d = await fetch('/api/prescriptions', {credentials:'same-origin'}).then(r => r.json()).catch(() => null);
  const p = d && d.prescriptions.find(x => x.id === id);
  if (!p) return;
  _editingRx = id;
  // v ?? '' (not || '') so a real 0 (e.g. "0 refills left") survives editing.
  const set = (i, v) => { const el = document.getElementById(i); if (el) el.value = v ?? ''; };
  set('rx-prescriber', p.prescriber); set('rx-issued', p.date_issued);
  set('rx-valid', p.valid_until); set('rx-refills', p.refills_left);
  const ids = new Set(p.medicine_ids || []);
  document.querySelectorAll('.rx-med-cb').forEach(cb => { cb.checked = ids.has(cb.value); });
  const title = document.getElementById('rx-form-title'); if (title) title.textContent = t('Edit prescription');
  const save = document.getElementById('rx-save-btn'); if (save) save.textContent = t('Save');
  const cancel = document.getElementById('rx-cancel-btn'); if (cancel) cancel.style.display = '';
  document.getElementById('rx-prescriber')?.scrollIntoView({block:'center'});
}

function cancelRxEdit() { _editingRx = null; loadPrescriptions(); }

async function deleteRx(id) {
  await fetch('/api/prescriptions/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  if (_editingRx === id) _editingRx = null;
  loadPrescriptions();
}

// ── Insurance claims ─────────────────────────────────────────────────────────
// Track a claim through its real lifecycle. The reimbursed figure is what has
// ACTUALLY been paid, kept separate from the amount claimed — a submitted claim
// is not money in hand, and "awaiting" only counts still-open claims.
let _editingClaim = null;

const CLAIM_STATUS = {
  submitted:      {label:'Submitted',      cls:'clm-pending'},
  under_review:   {label:'Under review',   cls:'clm-pending'},
  approved:       {label:'Approved',       cls:'clm-pending'},
  partially_paid: {label:'Partially paid', cls:'clm-partial'},
  paid:           {label:'Paid',           cls:'clm-paid'},
  rejected:       {label:'Rejected',       cls:'clm-rejected'},
};

async function loadClaims() {
  const el = document.getElementById('claims-content');
  if (!el) return;
  const d = await fetch('/api/claims', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {claims:[],summary:{},statuses:[]}).catch(() => ({claims:[],summary:{},statuses:[]}));
  el.innerHTML = renderClaims(d);
}

function renderClaims(d) {
  const today = localToday();
  const statuses = d.statuses || Object.keys(CLAIM_STATUS);
  const statusOpts = statuses.map(s => `<option value="${s}">${t(CLAIM_STATUS[s]?.label || s)}</option>`).join('');

  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px" id="clm-form-title">${t('Add a claim')}</h2>
      <div class="clm-form">
        <input type="text" id="clm-insurer" class="form-input" placeholder="${t('Insurer (e.g. Star Health)')}" style="flex:2;min-width:170px">
        <input type="number" step="any" min="0" id="clm-amount" class="form-input" placeholder="₹ ${t('claimed')}" style="max-width:120px">
        <input type="number" step="any" min="0" id="clm-reimbursed" class="form-input" placeholder="₹ ${t('reimbursed')}" style="max-width:130px">
        <select id="clm-status" class="form-input" style="max-width:150px">${statusOpts}</select>
        <input type="date" id="clm-date" class="form-input" value="${today}" max="${today}" style="max-width:160px">
        <button class="btn-primary" data-ev-click="saveClaim()" id="clm-save-btn">${t('Add')}</button>
        <button class="btn-outline" data-ev-click="cancelClaimEdit()" id="clm-cancel-btn" style="display:none">${t('Cancel')}</button>
      </div>
    </div>`;

  const s = d.summary || {};
  const hero = (d.claims || []).length ? `<div class="panel clm-hero" style="padding:18px 20px;margin-bottom:16px">
      <div class="clm-hero-grid">
        <div><div class="clm-hero-n">${_rupee(s.total_claimed)}</div><div class="clm-hero-l">${t('claimed')}</div></div>
        <div><div class="clm-hero-n clm-hero-paid">${_rupee(s.total_reimbursed)}</div><div class="clm-hero-l">${t('reimbursed')}</div></div>
        <div><div class="clm-hero-n clm-hero-await">${_rupee(s.awaiting)}</div><div class="clm-hero-l">${tformat('awaiting (%1 open)', s.pending_count || 0)}</div></div>
      </div>
      <div class="clm-note">${t('“Awaiting” counts only still-open claims — a rejected claim isn’t money that’s coming.')}</div>
    </div>` : '';

  if (!(d.claims || []).length) {
    return form + `<div class="panel" style="padding:28px;text-align:center">
        <div style="font-size:30px;margin-bottom:8px">🧾</div>
        <div style="font-size:14px;font-weight:600;margin-bottom:4px">${t('No claims yet')}</div>
        <div style="font-size:13px;color:var(--gray-400)">${t('Log an insurance claim to track its status and what gets reimbursed.')}</div>
      </div>`;
  }

  const cards = d.claims.map(c => {
    const st = CLAIM_STATUS[c.status] || {label:c.status, cls:''};
    const badge = `<span class="clm-badge ${st.cls}">${t(st.label)}</span>`;
    const paid = c.reimbursed > 0 ? tformat('%1 reimbursed', _rupee(c.reimbursed)) : t('nothing reimbursed yet');
    const outstanding = (c.outstanding > 0 && c.pending) ? ` · ${tformat('%1 outstanding', _rupee(c.outstanding))}` : '';
    return `<div class="panel clm-card" style="padding:15px 18px;margin-bottom:12px">
        <div class="clm-card-head">
          <div style="flex:1;min-width:0">
            <div class="clm-insurer">${escHtml(c.insurer)} ${badge}</div>
            <div class="clm-meta">${_rupee(c.amount)} ${t('claimed')} · ${tformat('submitted %1', _fmtShortDate(c.date_submitted))}</div>
            <div class="clm-paid">${paid}${outstanding}</div>
          </div>
          <button class="btn-icon" title="${t('Edit')}" data-ev-click="startClaimEdit('${c.id}')">✎</button>
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteClaim('${c.id}')" style="color:var(--gray-300)">✕</button>
        </div>
        ${c.notes ? `<div class="clm-notes">${escHtml(c.notes)}</div>` : ''}
      </div>`;
  }).join('');
  return form + hero + cards;
}

function _claimFormBody() {
  return {
    insurer: document.getElementById('clm-insurer')?.value?.trim() || '',
    amount: document.getElementById('clm-amount')?.value || '',
    reimbursed: document.getElementById('clm-reimbursed')?.value || 0,
    status: document.getElementById('clm-status')?.value || 'submitted',
    date_submitted: document.getElementById('clm-date')?.value || '',
  };
}

async function saveClaim() {
  const body = _claimFormBody();
  if (!body.insurer) { showToast(t('Enter an insurer'), 'error'); return; }
  if (!body.amount || Number(body.amount) <= 0) { showToast(t('Enter the amount claimed'), 'error'); return; }
  const url = _editingClaim ? '/api/claims/' + _editingClaim : '/api/claims';
  const r = await fetch(url, {method: _editingClaim ? 'PATCH' : 'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(_editingClaim ? t('Claim updated') : t('Claim added')); _editingClaim = null; loadClaims(); }
  else showToast((r && r.error) || t('Could not save'), 'error');
}

async function startClaimEdit(id) {
  const d = await fetch('/api/claims', {credentials:'same-origin'}).then(r => r.json()).catch(() => null);
  const c = d && d.claims.find(x => x.id === id);
  if (!c) return;
  _editingClaim = id;
  const set = (i, v) => { const el = document.getElementById(i); if (el) el.value = v ?? ''; };
  set('clm-insurer', c.insurer); set('clm-amount', c.amount); set('clm-reimbursed', c.reimbursed);
  set('clm-status', c.status); set('clm-date', c.date_submitted);
  const title = document.getElementById('clm-form-title'); if (title) title.textContent = t('Edit claim');
  const save = document.getElementById('clm-save-btn'); if (save) save.textContent = t('Save');
  const cancel = document.getElementById('clm-cancel-btn'); if (cancel) cancel.style.display = '';
  document.getElementById('clm-insurer')?.scrollIntoView({block:'center'});
}

function cancelClaimEdit() { _editingClaim = null; loadClaims(); }

async function deleteClaim(id) {
  await fetch('/api/claims/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  if (_editingClaim === id) _editingClaim = null;
  loadClaims();
}

// ── Allergy & reactions log ──────────────────────────────────────────────────
// One structured row per allergen — what it is, the reaction, severity, when
// noticed. Severe entries are red-flagged and feed the Health ID card.
let _editingAllergy = null;

const ALLERGY_SEV = {
  severe:   {label:'Severe',   cls:'alg-severe'},
  moderate: {label:'Moderate', cls:'alg-moderate'},
  mild:     {label:'Mild',     cls:'alg-mild'},
};

async function loadAllergies() {
  const el = document.getElementById('allergies-content');
  if (!el) return;
  const d = await fetch('/api/allergies', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {allergies:[]}).catch(() => ({allergies:[]}));
  el.innerHTML = renderAllergies(d.allergies || [], d.severities || ['mild','moderate','severe']);
}

function renderAllergies(list, severities) {
  const today = localToday();
  const sevOpts = severities.map(s => `<option value="${s}">${t(ALLERGY_SEV[s]?.label || s)}</option>`).join('');
  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px" id="alg-form-title">${t('Add an allergy')}</h2>
      <div class="alg-form">
        <input type="text" id="alg-allergen" class="form-input" placeholder="${t('Allergen (e.g. Penicillin, Peanuts)')}" style="flex:2;min-width:180px">
        <input type="text" id="alg-reaction" class="form-input" placeholder="${t('Reaction (e.g. rash, swelling)')}" style="flex:2;min-width:180px">
        <select id="alg-severity" class="form-input" style="max-width:140px">${sevOpts}</select>
        <input type="date" id="alg-date" class="form-input" max="${today}" title="${t('Date noticed (optional)')}" style="max-width:160px">
        <button class="btn-primary" data-ev-click="saveAllergy()" id="alg-save-btn">${t('Add')}</button>
        <button class="btn-outline" data-ev-click="cancelAllergyEdit()" id="alg-cancel-btn" style="display:none">${t('Cancel')}</button>
      </div>
    </div>`;

  if (!list.length) {
    return form + `<div class="panel" style="padding:28px;text-align:center">
        <div style="font-size:30px;margin-bottom:8px">⚠️</div>
        <div style="font-size:14px;font-weight:600;margin-bottom:4px">${t('No allergies logged')}</div>
        <div style="font-size:13px;color:var(--gray-400)">${t('Add any drug, food or other allergies so they show on your Health ID card.')}</div>
      </div>`;
  }

  const cards = list.map(a => {
    const sev = ALLERGY_SEV[a.severity] || {label:a.severity, cls:''};
    const badge = `<span class="alg-badge ${sev.cls}">${t(sev.label)}</span>`;
    const meta = [a.reaction && `${t('Reaction')}: ${escHtml(a.reaction)}`,
                  a.date_noted && tformat('noted %1', _fmtShortDate(a.date_noted))].filter(Boolean).join(' · ');
    return `<div class="panel alg-card ${a.severity === 'severe' ? 'alg-card--severe' : ''}" style="padding:14px 18px;margin-bottom:10px">
        <div class="alg-head">
          <div style="flex:1;min-width:0">
            <div class="alg-allergen">${escHtml(a.allergen)} ${badge}</div>
            ${meta ? `<div class="alg-meta">${meta}</div>` : ''}
            ${a.notes ? `<div class="alg-notes">${escHtml(a.notes)}</div>` : ''}
          </div>
          <button class="btn-icon" title="${t('Edit')}" data-ev-click="startAllergyEdit('${a.id}')">✎</button>
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteAllergy('${a.id}')" style="color:var(--gray-300)">✕</button>
        </div>
      </div>`;
  }).join('');
  return form + cards;
}

function _allergyFormBody() {
  return {
    allergen: document.getElementById('alg-allergen')?.value?.trim() || '',
    reaction: document.getElementById('alg-reaction')?.value || '',
    severity: document.getElementById('alg-severity')?.value || 'moderate',
    date_noted: document.getElementById('alg-date')?.value || null,
  };
}

async function saveAllergy() {
  const body = _allergyFormBody();
  if (!body.allergen) { showToast(t('Enter an allergen'), 'error'); return; }
  const url = _editingAllergy ? '/api/allergies/' + _editingAllergy : '/api/allergies';
  const r = await fetch(url, {method: _editingAllergy ? 'PATCH' : 'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(_editingAllergy ? t('Allergy updated') : t('Allergy added')); _editingAllergy = null; loadAllergies(); }
  else showToast((r && r.error) || t('Could not save'), 'error');
}

async function startAllergyEdit(id) {
  const d = await fetch('/api/allergies', {credentials:'same-origin'}).then(r => r.json()).catch(() => null);
  const a = d && d.allergies.find(x => x.id === id);
  if (!a) return;
  _editingAllergy = id;
  const set = (i, v) => { const el = document.getElementById(i); if (el) el.value = v ?? ''; };
  set('alg-allergen', a.allergen); set('alg-reaction', a.reaction);
  set('alg-severity', a.severity); set('alg-date', a.date_noted);
  const title = document.getElementById('alg-form-title'); if (title) title.textContent = t('Edit allergy');
  const save = document.getElementById('alg-save-btn'); if (save) save.textContent = t('Save');
  const cancel = document.getElementById('alg-cancel-btn'); if (cancel) cancel.style.display = '';
  document.getElementById('alg-allergen')?.scrollIntoView({block:'center'});
}

function cancelAllergyEdit() { _editingAllergy = null; loadAllergies(); }

async function deleteAllergy(id) {
  await fetch('/api/allergies/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  if (_editingAllergy === id) _editingAllergy = null;
  loadAllergies();
}

// ── Dental & vision care ─────────────────────────────────────────────────────
// Two easy-to-forget checkups plus the user's own glasses/contacts prescription.
// Everything shown is a factual record the user entered — dates are echoed with
// a countdown, never scheduled; Rx values are kept verbatim, never interpreted.
async function loadDentalVision() {
  const el = document.getElementById('dentalvision-content');
  if (!el) return;
  el.innerHTML = `<div style="padding:24px;text-align:center;color:var(--gray-400)">${t('Loading…')}</div>`;
  const [visitsD, rxD, dueD] = await Promise.all([
    fetch('/api/dental-vision/visits', {credentials:'same-origin'}).then(r => r.ok ? r.json() : {visits:[]}).catch(() => ({visits:[]})),
    fetch('/api/dental-vision/rx', {credentials:'same-origin'}).then(r => r.ok ? r.json() : {prescriptions:[]}).catch(() => ({prescriptions:[]})),
    fetch('/api/dental-vision/due', {credentials:'same-origin'}).then(r => r.ok ? r.json() : {due:[]}).catch(() => ({due:[]})),
  ]);
  el.innerHTML = renderDentalVision(visitsD.visits || [], rxD.prescriptions || [], dueD.due || []);
}

function _dvKindLabel(k) {
  return k === 'dental' ? '🦷 ' + t('Dental') : '👁️ ' + t('Eye exam');
}

function renderDentalVision(visits, prescriptions, due) {
  const today = localToday();

  // Due countdown — only echoes a next-due date the user recorded.
  const dueRows = (due || []).filter(d => d.overdue || d.due_soon).map(d => {
    const when = d.overdue ? tformat('overdue by %1 days', Math.abs(d.days_until))
                           : (d.days_until === 0 ? t('due today') : tformat('in %1 days', d.days_until));
    return `<div class="dv-due-row ${d.overdue ? 'overdue' : ''}">
        <span>${_dvKindLabel(d.kind)}</span>
        <span class="dv-due-when">${escHtml(_fmtShortDate(d.next_due))} · ${when}</span></div>`;
  }).join('');
  const dueBanner = dueRows ? `<div class="panel dv-due-panel">
      <div class="dv-due-title">${t('Next checkups you noted')}</div>${dueRows}</div>` : '';

  // Checkup form + list.
  const visitForm = `<div class="panel" style="padding:18px 20px;margin-bottom:14px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Add a checkup')}</h2>
      <div class="dv-form">
        <select id="dv-kind" class="form-input" style="max-width:150px">
          <option value="dental">${t('Dental')}</option>
          <option value="eye">${t('Eye exam')}</option>
        </select>
        <input type="date" id="dv-date" class="form-input" max="${today}" title="${t('Visit date')}" style="max-width:160px">
        <input type="text" id="dv-provider" class="form-input" placeholder="${t('Clinic / doctor (optional)')}" style="flex:2;min-width:160px">
        <input type="date" id="dv-next" class="form-input" title="${t('Next due (optional)')}" style="max-width:160px">
      </div>
      <div class="dv-form" style="margin-top:8px">
        <input type="text" id="dv-summary" class="form-input" placeholder="${t('What was done (optional)')}" style="flex:3;min-width:200px">
        <button class="btn-primary" data-ev-click="saveDVVisit()">${t('Add')}</button>
      </div>
    </div>`;

  const visitCards = (visits || []).length ? visits.map(v => {
    const meta = [v.provider && escHtml(v.provider),
                  v.next_due && tformat('next due %1', _fmtShortDate(v.next_due))].filter(Boolean).join(' · ');
    return `<div class="panel dv-card">
        <div class="dv-card-head">
          <div style="flex:1;min-width:0">
            <div class="dv-card-title">${_dvKindLabel(v.kind)} <span class="dv-card-date">${escHtml(_fmtShortDate(v.visit_date))}</span></div>
            ${meta ? `<div class="dv-card-meta">${meta}</div>` : ''}
            ${v.summary ? `<div class="dv-card-summary">${escHtml(v.summary)}</div>` : ''}
          </div>
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteDVVisit('${v.id}')" style="color:var(--gray-300)">✕</button>
        </div>
      </div>`;
  }).join('') : `<div class="dv-empty">${t('No checkups logged yet.')}</div>`;

  // Vision prescription form + list.
  const cell = (id, ph) => `<input type="text" id="${id}" class="form-input dv-rx-cell" placeholder="${ph}">`;
  const rxForm = `<div class="panel" style="padding:18px 20px;margin:18px 0 14px">
      <h2 class="panel-title" style="margin-bottom:6px">${t('Add a vision prescription')}</h2>
      <p class="dv-fineprint">${t('Copied exactly from your prescription — Arogo stores it, it never reads your vision from these numbers.')}</p>
      <div class="dv-form" style="margin:10px 0">
        <select id="dv-rx-kind" class="form-input" style="max-width:150px">
          <option value="glasses">${t('Glasses')}</option>
          <option value="contacts">${t('Contacts')}</option>
        </select>
        <input type="date" id="dv-rx-date" class="form-input" max="${today}" title="${t('Prescription date')}" style="max-width:160px">
      </div>
      <table class="dv-rx-table"><thead><tr>
        <th></th><th>${t('SPH')}</th><th>${t('CYL')}</th><th>${t('Axis')}</th><th>${t('ADD')}</th></tr></thead>
        <tbody>
          <tr><th>${t('Right (OD)')}</th><td>${cell('dv-r-sph','')}</td><td>${cell('dv-r-cyl','')}</td><td>${cell('dv-r-axis','')}</td><td>${cell('dv-r-add','')}</td></tr>
          <tr><th>${t('Left (OS)')}</th><td>${cell('dv-l-sph','')}</td><td>${cell('dv-l-cyl','')}</td><td>${cell('dv-l-axis','')}</td><td>${cell('dv-l-add','')}</td></tr>
        </tbody></table>
      <div class="dv-form" style="margin-top:10px">
        <input type="text" id="dv-rx-pd" class="form-input" placeholder="${t('PD (optional)')}" style="max-width:130px">
        <input type="text" id="dv-rx-notes" class="form-input" placeholder="${t('Notes (optional)')}" style="flex:2;min-width:160px">
        <button class="btn-primary" data-ev-click="saveVisionRx()">${t('Add')}</button>
      </div>
    </div>`;

  const rxCards = (prescriptions || []).length ? prescriptions.map(p => {
    const row = (lbl, sph, cyl, axis, add) => `<tr><th>${lbl}</th>
        <td>${escHtml(sph || '—')}</td><td>${escHtml(cyl || '—')}</td>
        <td>${escHtml(axis || '—')}</td><td>${escHtml(add || '—')}</td></tr>`;
    return `<div class="panel dv-card">
        <div class="dv-card-head">
          <div style="flex:1;min-width:0">
            <div class="dv-card-title">${p.kind === 'contacts' ? '👁️ ' + t('Contacts') : '👓 ' + t('Glasses')}
              <span class="dv-card-date">${escHtml(_fmtShortDate(p.rx_date))}</span></div>
            <table class="dv-rx-table dv-rx-view"><thead><tr><th></th><th>${t('SPH')}</th><th>${t('CYL')}</th><th>${t('Axis')}</th><th>${t('ADD')}</th></tr></thead>
              <tbody>${row(t('Right (OD)'), p.right_sph, p.right_cyl, p.right_axis, p.right_add)}
              ${row(t('Left (OS)'), p.left_sph, p.left_cyl, p.left_axis, p.left_add)}</tbody></table>
            ${(p.pd || p.notes) ? `<div class="dv-card-meta">${[p.pd && tformat('PD %1', escHtml(p.pd)), p.notes && escHtml(p.notes)].filter(Boolean).join(' · ')}</div>` : ''}
          </div>
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteVisionRx('${p.id}')" style="color:var(--gray-300)">✕</button>
        </div>
      </div>`;
  }).join('') : `<div class="dv-empty">${t('No vision prescription saved yet.')}</div>`;

  return dueBanner
    + `<div class="section-header"><h2 class="section-title">${t('Checkups')}</h2></div>`
    + visitForm + visitCards
    + `<div class="section-header"><h2 class="section-title">${t('Vision prescription')}</h2></div>`
    + rxForm + rxCards;
}

async function saveDVVisit() {
  const val = id => (document.getElementById(id) || {}).value || '';
  const body = { kind: val('dv-kind'), visit_date: val('dv-date'),
                 provider: val('dv-provider'), summary: val('dv-summary'),
                 next_due: val('dv-next') || null };
  if (!body.visit_date) { showToast('Pick a visit date', 'error'); return; }
  const r = await fetch('/api/dental-vision/visits', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast('Checkup added'); loadDentalVision(); }
  else showToast((r && r.error) || 'Could not save', 'error');
}

async function deleteDVVisit(id) {
  await fetch('/api/dental-vision/visits/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadDentalVision();
}

async function saveVisionRx() {
  const val = id => (document.getElementById(id) || {}).value || '';
  const body = { rx_date: val('dv-rx-date'), kind: val('dv-rx-kind'),
                 right_sph: val('dv-r-sph'), right_cyl: val('dv-r-cyl'), right_axis: val('dv-r-axis'), right_add: val('dv-r-add'),
                 left_sph: val('dv-l-sph'), left_cyl: val('dv-l-cyl'), left_axis: val('dv-l-axis'), left_add: val('dv-l-add'),
                 pd: val('dv-rx-pd'), notes: val('dv-rx-notes') };
  if (!body.rx_date) { showToast('Pick a prescription date', 'error'); return; }
  const r = await fetch('/api/dental-vision/rx', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast('Prescription saved'); loadDentalVision(); }
  else showToast((r && r.error) || 'Could not save', 'error');
}

async function deleteVisionRx(id) {
  await fetch('/api/dental-vision/rx/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadDentalVision();
}

// ── Home medical supplies (M2) ───────────────────────────────────────────────
// First-aid kit + OTC basics with quantity, optional expiry, and an optional
// restock threshold. Factual inventory only — an OTC item here is a thing on a
// shelf, never a treatment recommendation.
const _SUP_CAT = { first_aid: 'First aid', otc: 'OTC medicine', device: 'Device', other: 'Other' };

async function loadSupplies() {
  const el = document.getElementById('supplies-content');
  if (!el) return;
  el.innerHTML = `<div style="padding:24px;text-align:center;color:var(--gray-400)">${t('Loading…')}</div>`;
  const [listD, alertD] = await Promise.all([
    fetch('/api/supplies', {credentials:'same-origin'}).then(r => r.ok ? r.json() : {supplies:[]}).catch(() => ({supplies:[]})),
    fetch('/api/supplies/alerts', {credentials:'same-origin'}).then(r => r.ok ? r.json() : {}).catch(() => ({})),
  ]);
  el.innerHTML = renderSupplies(listD.supplies || [], alertD || {});
}

function _supExpiryTag(item) {
  if (!item.expiry_date) return '';
  const d = escHtml(_fmtShortDate(item.expiry_date));
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const exp = new Date(item.expiry_date + 'T00:00:00');
  const days = Math.round((exp - today) / 864e5);
  let cls = '';
  if (days < 0) cls = 'expired';
  else if (days <= 60) cls = 'soon';
  const label = days < 0 ? tformat('expired %1', d) : tformat('expires %1', d);
  return `<span class="sup-exp ${cls}">${label}</span>`;
}

function renderSupplies(list, alerts) {
  const alertLine = [];
  if ((alerts.expired || []).length) alertLine.push(`<span class="sup-al expired">${tformat('%1 expired', alerts.expired.length)}</span>`);
  if ((alerts.expiring || []).length) alertLine.push(`<span class="sup-al soon">${tformat('%1 expiring soon', alerts.expiring.length)}</span>`);
  if ((alerts.low || []).length) alertLine.push(`<span class="sup-al low">${tformat('%1 running low', alerts.low.length)}</span>`);
  const alertBanner = alertLine.length
    ? `<div class="panel sup-alert-panel"><div class="sup-alert-title">${t('Needs attention')}</div><div class="sup-al-row">${alertLine.join('')}</div></div>` : '';

  const catOpts = Object.keys(_SUP_CAT).map(k => `<option value="${k}">${t(_SUP_CAT[k])}</option>`).join('');
  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:14px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Add an item')}</h2>
      <div class="dv-form">
        <input type="text" id="sup-name" class="form-input" placeholder="${t('Item (e.g. Paracetamol, Bandages)')}" style="flex:2;min-width:180px">
        <select id="sup-cat" class="form-input" style="max-width:160px">${catOpts}</select>
        <input type="number" id="sup-qty" class="form-input" placeholder="${t('Qty')}" min="0" style="max-width:90px">
        <input type="text" id="sup-unit" class="form-input" placeholder="${t('Unit')}" style="max-width:120px">
      </div>
      <div class="dv-form" style="margin-top:8px">
        <input type="date" id="sup-expiry" class="form-input" title="${t('Expiry (optional)')}" style="max-width:160px">
        <input type="number" id="sup-lowat" class="form-input" placeholder="${t('Nudge at (optional)')}" min="0" title="${t('Nudge me when the quantity drops to this')}" style="max-width:150px">
        <button class="btn-primary" data-ev-click="saveSupply()">${t('Add')}</button>
      </div>
    </div>`;

  if (!list.length) {
    return alertBanner + form + `<div class="dv-empty">${t('Nothing in your kit yet. Add your first-aid supplies and OTC basics above.')}</div>`;
  }

  // Group by category, in the fixed order.
  let body = '';
  Object.keys(_SUP_CAT).forEach(cat => {
    const items = list.filter(s => (s.category || 'other') === cat);
    if (!items.length) return;
    body += `<div class="section-header"><h2 class="section-title">${t(_SUP_CAT[cat])}</h2></div>`;
    body += items.map(s => {
      const qty = s.quantity || 0;
      const low = (s.low_at || 0) > 0 && qty <= s.low_at;
      const qtyText = qty + (s.unit ? ' ' + escHtml(s.unit) : '');
      return `<div class="panel sup-card">
          <div class="sup-head">
            <div style="flex:1;min-width:0">
              <div class="sup-name">${escHtml(s.name)}</div>
              <div class="sup-meta">
                <span class="sup-qty ${low ? 'low' : ''}">${qtyText}${low ? ' · ' + t('low') : ''}</span>
                ${s.expiry_date ? _supExpiryTag(s) : ''}
              </div>
              ${s.notes ? `<div class="sup-notes">${escHtml(s.notes)}</div>` : ''}
            </div>
            <div class="sup-actions">
              <button class="btn-icon" title="${t('Use one')}" data-ev-click="restockSupply('${s.id}', ${qty}, -1)">−</button>
              <button class="btn-icon" title="${t('Add one')}" data-ev-click="restockSupply('${s.id}', ${qty}, 1)">＋</button>
              <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteSupply('${s.id}')" style="color:var(--gray-300)">✕</button>
            </div>
          </div>
        </div>`;
    }).join('');
  });

  return alertBanner + form + body;
}

async function saveSupply() {
  const val = id => (document.getElementById(id) || {}).value || '';
  const body = { name: val('sup-name'), category: val('sup-cat'),
                 quantity: val('sup-qty') || 0, unit: val('sup-unit'),
                 expiry_date: val('sup-expiry') || null, low_at: val('sup-lowat') || 0 };
  if (!body.name.trim()) { showToast('Enter an item name', 'error'); return; }
  const r = await fetch('/api/supplies', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast('Item added'); loadSupplies(); }
  else showToast((r && r.error) || 'Could not save', 'error');
}

async function restockSupply(id, currentQty, delta) {
  const next = Math.max(0, (Number(currentQty) || 0) + delta);
  const r = await fetch('/api/supplies/' + id, {method:'PATCH', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify({quantity: next})}).then(x => x.json()).catch(() => null);
  if (r && r.success) loadSupplies();
  else showToast('Could not update', 'error');
}

async function deleteSupply(id) {
  await fetch('/api/supplies/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadSupplies();
}

// ── Symptom photo journal (M3) ───────────────────────────────────────────────
// Photograph a rash / wound / swelling and follow how it looks over time.
// Grouped by a free-text label into per-subject timelines. Own images only,
// shown by date — Arogo never analyses or diagnoses from a photo.
async function loadSymptomPhotos() {
  const el = document.getElementById('symptomphotos-content');
  if (!el) return;
  el.innerHTML = `<div style="padding:24px;text-align:center;color:var(--gray-400)">${t('Loading…')}</div>`;
  const d = await fetch('/api/symptom-photos', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {photos:[]}).catch(() => ({photos:[]}));
  el.innerHTML = renderSymptomPhotos(d.photos || []);
}

function renderSymptomPhotos(photos) {
  const today = localToday();
  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Add a photo')}</h2>
      <div class="dv-form">
        <input type="text" id="sp-label" class="form-input" placeholder="${t('What is it? (e.g. Left forearm rash)')}" style="flex:2;min-width:200px">
        <input type="date" id="sp-date" class="form-input" max="${today}" value="${today}" style="max-width:160px">
      </div>
      <div class="dv-form" style="margin-top:8px">
        <input type="text" id="sp-notes" class="form-input" placeholder="${t('Notes (optional)')}" style="flex:2;min-width:180px">
        <input type="file" id="sp-file" accept="image/*" class="form-input" style="max-width:230px">
        <button class="btn-primary" data-ev-click="uploadSymptomPhoto()">${t('Add')}</button>
      </div>
    </div>`;

  if (!photos.length) {
    return form + `<div class="dv-empty">${t('No photos yet. Add one above, using the same label each time to build a timeline.')}</div>`;
  }

  // Group by label; within a group show oldest → newest so change reads left to right.
  const groups = {};
  photos.forEach(p => { (groups[p.label] = groups[p.label] || []).push(p); });
  let body = '';
  Object.keys(groups).forEach(label => {
    const items = groups[label].slice().sort((a, b) =>
      (a.taken_date || '').localeCompare(b.taken_date || ''));
    const thumbs = items.map(p => {
      const enc = encodeURIComponent(p.filename);
      return `<figure class="sp-thumb">
          <img src="/uploads/${enc}" alt="${escHtml(label)}" loading="lazy"
               data-ev-click="viewMedPhoto('${enc}','${escHtml(label)}')">
          <figcaption>${escHtml(_fmtShortDate(p.taken_date))}</figcaption>
          <button class="sp-del" title="${t('Delete')}" data-ev-click="deleteSymptomPhoto('${p.id}')">✕</button>
          ${p.notes ? `<div class="sp-note">${escHtml(p.notes)}</div>` : ''}
        </figure>`;
    }).join('');
    body += `<div class="panel sp-group">
        <div class="sp-group-head">${escHtml(label)} <span class="sp-count">${tformat('%1 photos', items.length)}</span></div>
        <div class="sp-strip">${thumbs}</div>
      </div>`;
  });

  return form + body;
}

async function uploadSymptomPhoto() {
  const label = (document.getElementById('sp-label') || {}).value || '';
  const date = (document.getElementById('sp-date') || {}).value || '';
  const notes = (document.getElementById('sp-notes') || {}).value || '';
  const fileEl = document.getElementById('sp-file');
  const file = fileEl && fileEl.files && fileEl.files[0];
  if (!file) { showToast('Choose a photo first', 'error'); return; }
  if (!label.trim()) { showToast('Add a label so photos group together', 'error'); return; }
  const fd = new FormData();
  fd.append('file', file);
  fd.append('label', label);
  fd.append('taken_date', date);
  fd.append('notes', notes);
  showToast('Uploading…');
  const r = await fetch('/api/symptom-photos', {method:'POST', credentials:'same-origin', body: fd})
    .then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast('Photo added'); loadSymptomPhotos(); }
  else showToast((r && r.error) || 'Could not upload', 'error');
}

async function deleteSymptomPhoto(id) {
  await fetch('/api/symptom-photos/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadSymptomPhotos();
}

// ── Health binder (N2) ───────────────────────────────────────────────────────
// One always-current, printable summary composed from the user's own records.
// Read-only; empty sections simply don't render. Nothing is scored or invented.
async function loadHealthBinder() {
  const el = document.getElementById('binder-content');
  if (!el) return;
  el.innerHTML = `<div style="padding:24px;text-align:center;color:var(--gray-400)">${t('Loading…')}</div>`;
  const d = await fetch('/api/health-binder', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : null).catch(() => null);
  if (!d) { el.innerHTML = `<div class="dv-empty">${t('Could not load')}</div>`; return; }
  el.innerHTML = renderHealthBinder(d);
}

function _bindSection(title, inner) {
  return inner ? `<section class="bnd-sec"><h2 class="bnd-sec-title">${title}</h2>${inner}</section>` : '';
}

function renderHealthBinder(d) {
  const id = d.identity || {};
  const sub = [];
  if (id.age != null) sub.push(tformat('%1 yrs', id.age));
  if (id.gender) sub.push(escHtml(t(id.gender)));
  if (id.height_cm) sub.push(escHtml(id.height_cm) + ' cm');
  if (id.weight_kg) sub.push(escHtml(id.weight_kg) + ' kg');

  // Critical: blood type, allergies, conditions.
  const critRows = [];
  if (d.blood_type) critRows.push(`<div class="bnd-row"><span class="bnd-k">${t('Blood type')}</span><span class="bnd-v">${escHtml(d.blood_type)}</span></div>`);
  const allergies = (d.allergy_list || []).length
    ? d.allergy_list.map(a => escHtml(a.allergen) + (a.severity ? ` (${escHtml(a.severity)})` : '')).join(', ')
    : escHtml(d.allergies_text || '');
  if (allergies) critRows.push(`<div class="bnd-row"><span class="bnd-k">${t('Allergies')}</span><span class="bnd-v">${allergies}</span></div>`);
  if (d.conditions) critRows.push(`<div class="bnd-row"><span class="bnd-k">${t('Conditions')}</span><span class="bnd-v">${escHtml(d.conditions)}</span></div>`);

  // Advance care.
  const ac = d.advance_care || {};
  const acRows = [];
  if (ac.organ_donor) acRows.push(`<div class="bnd-row"><span class="bnd-k">${t('Organ donor')}</span><span class="bnd-v">${escHtml(ac.organ_donor)}</span></div>`);
  if (ac.directive_wishes) acRows.push(`<div class="bnd-row"><span class="bnd-k">${t('Medical wishes')}</span><span class="bnd-v">${escHtml(ac.directive_wishes)}</span></div>`);
  if (ac.directive_location) acRows.push(`<div class="bnd-row"><span class="bnd-k">${t('Directives kept')}</span><span class="bnd-v">${escHtml(ac.directive_location)}</span></div>`);

  // Medicines (live).
  let medsInner = '';
  if ((d.active_medicines || []).length) {
    medsInner = `<ul class="bnd-list">${d.active_medicines.map(m =>
      `<li>${escHtml(m.name)}${m.dose ? ' · ' + escHtml(m.dose) : ''}${m.frequency ? ' · ' + escHtml((m.frequency || '').replace(/_/g, ' ')) : ''}</li>`).join('')}</ul>`;
  } else if (d.notes_medications) {
    medsInner = `<div class="bnd-v">${escHtml(d.notes_medications)}</div>`;
  }

  // Recent labs.
  let labsInner = '';
  if ((d.labs || []).length) {
    // Coerce value to a string BEFORE escHtml — escHtml does String(x||''),
    // which would silently blank a genuine numeric reading of 0.
    labsInner = `<table class="bnd-table"><tbody>${d.labs.map(l => {
      const val = (l.value === null || l.value === undefined) ? '' : String(l.value);
      return `<tr><td>${escHtml(l.name)}</td><td>${escHtml(val)}${l.unit ? ' ' + escHtml(l.unit) : ''}</td>
        <td class="bnd-dim">${escHtml(_fmtShortDate(l.date))}</td></tr>`;
    }).join('')}</tbody></table>`;
  }

  // Vaccines.
  let vaxInner = '';
  if ((d.vaccines || []).length) {
    vaxInner = `<ul class="bnd-list">${d.vaccines.map(v =>
      `<li>${escHtml(v.name)}${v.last_date ? ' · ' + escHtml(_fmtShortDate(v.last_date)) : ''}${v.dose_count > 1 ? ` · ${tformat('%1 doses', v.dose_count)}` : ''}</li>`).join('')}</ul>`;
  }

  // Dental & vision.
  const dv = d.dental_vision || {};
  const dvBits = [];
  (dv.due || []).forEach(x => dvBits.push(`${x.kind === 'dental' ? t('Dental') : t('Eye exam')}: ${escHtml(_fmtShortDate(x.next_due))}`));
  if (dv.rx) {
    const r = dv.rx;
    dvBits.push(`${t('Glasses')} — ${t('Right (OD)')} ${escHtml(r.right_sph || '—')}/${escHtml(r.right_cyl || '—')}, ${t('Left (OS)')} ${escHtml(r.left_sph || '—')}/${escHtml(r.left_cyl || '—')}`);
  }
  const dvInner = dvBits.length ? `<div class="bnd-v">${dvBits.join('<br>')}</div>` : '';

  // Contacts.
  let contactsInner = '';
  if ((d.contacts || []).length) {
    contactsInner = d.contacts.map(c =>
      `<div class="bnd-row"><span class="bnd-k">${escHtml(c.name || t('Contact'))}</span><span class="bnd-v">${escHtml(c.phone || '')}</span></div>`).join('');
  }

  const ins = d.insurance || {};
  const insVal = [ins.provider, ins.number].filter(Boolean).map(escHtml).join(' · ');

  const actions = `<div class="hid-actions bnd-actions">
      <button class="btn-primary" data-ev-click="printHealthBinder()">🖨️ ${t('Print / Save PDF')}</button>
    </div>`;

  const doc = `<div id="health-binder-doc" class="bnd-doc">
      <div class="bnd-head">
        <div class="bnd-brand">🌱 Arogo · ${t('Health binder')}</div>
        <div class="bnd-name">${escHtml(id.name || t('Add your name in Settings'))}</div>
        ${sub.length ? `<div class="bnd-sub">${sub.join(' · ')}</div>` : ''}
        <div class="bnd-gen">${tformat('As of %1', escHtml(_fmtShortDate(d.generated)))}</div>
      </div>
      ${_bindSection(t('Critical'), critRows.join(''))}
      ${_bindSection(t('Advance care & wishes'), acRows.join(''))}
      ${_bindSection(t('Current medicines'), medsInner)}
      ${_bindSection(t('Recent labs'), labsInner)}
      ${_bindSection(t('Vaccines'), vaxInner)}
      ${_bindSection(t('Dental & vision'), dvInner)}
      ${_bindSection(t('In an emergency, call'), contactsInner)}
      ${_bindSection(t('Insurance'), insVal ? `<div class="bnd-v">${insVal}</div>` : '')}
      <div class="bnd-foot">${t('Generated by Arogo from your own records. Not a substitute for official medical records.')}</div>
    </div>`;

  return actions + doc;
}

function printHealthBinder() {
  document.body.classList.add('printing-binder');
  const clear = () => { document.body.classList.remove('printing-binder'); window.removeEventListener('afterprint', clear); };
  window.addEventListener('afterprint', clear);
  try { window.print(); } catch (e) { clear(); }
  setTimeout(clear, 1500);
}

// ── Family medical history (N3) ──────────────────────────────────────────────
// Plain, user-stated facts about relatives' conditions — the question every new
// doctor asks. Never turned into a risk score or a prediction.
const _FAM_RELATIONS = ['mother','father','sister','brother','daughter','son',
                        'grandmother','grandfather','aunt','uncle','other'];
const _FAM_LABEL = {mother:'Mother',father:'Father',sister:'Sister',brother:'Brother',
  daughter:'Daughter',son:'Son',grandmother:'Grandmother',grandfather:'Grandfather',
  aunt:'Aunt',uncle:'Uncle',other:'Other relative'};

async function loadFamilyHistory() {
  const el = document.getElementById('familyhistory-content');
  if (!el) return;
  el.innerHTML = `<div style="padding:24px;text-align:center;color:var(--gray-400)">${t('Loading…')}</div>`;
  const d = await fetch('/api/family-history', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {entries:[]}).catch(() => ({entries:[]}));
  el.innerHTML = renderFamilyHistory(d.entries || []);
}

function renderFamilyHistory(entries) {
  const relOpts = _FAM_RELATIONS.map(r => `<option value="${r}">${t(_FAM_LABEL[r])}</option>`).join('');
  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Add a family condition')}</h2>
      <div class="dv-form">
        <select id="fh-relation" class="form-input" style="max-width:170px">${relOpts}</select>
        <input type="text" id="fh-condition" class="form-input" placeholder="${t('Condition (e.g. Diabetes, Heart disease)')}" style="flex:2;min-width:200px">
        <input type="number" id="fh-age" class="form-input" placeholder="${t('Age it began (optional)')}" min="0" max="120" style="max-width:170px">
      </div>
      <div class="dv-form" style="margin-top:8px">
        <input type="text" id="fh-notes" class="form-input" placeholder="${t('Notes (optional)')}" style="flex:2;min-width:180px">
        <button class="btn-primary" data-ev-click="saveFamilyEntry()">${t('Add')}</button>
      </div>
    </div>`;

  if (!entries.length) {
    return form + `<div class="dv-empty">${t('Nothing recorded yet. Add conditions that run in your family so they’re ready at your next appointment.')}</div>`;
  }

  // Group by relation, in the fixed order.
  const byRel = {};
  entries.forEach(e => { (byRel[e.relation] = byRel[e.relation] || []).push(e); });
  let body = '';
  _FAM_RELATIONS.forEach(rel => {
    const items = byRel[rel];
    if (!items || !items.length) return;
    body += `<div class="section-header"><h2 class="section-title">${t(_FAM_LABEL[rel] || rel)}</h2></div>`;
    body += items.map(e => {
      const meta = [e.age_at_onset != null ? tformat('began at %1', e.age_at_onset) : '',
                    e.notes ? escHtml(e.notes) : ''].filter(Boolean).join(' · ');
      return `<div class="panel fh-card">
          <div class="fh-head">
            <div style="flex:1;min-width:0">
              <div class="fh-cond">${escHtml(e.condition)}</div>
              ${meta ? `<div class="fh-meta">${meta}</div>` : ''}
            </div>
            <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteFamilyEntry('${e.id}')" style="color:var(--gray-300)">✕</button>
          </div>
        </div>`;
    }).join('');
  });

  return form + body;
}

async function saveFamilyEntry() {
  const val = id => (document.getElementById(id) || {}).value || '';
  const body = { relation: val('fh-relation'), condition: val('fh-condition'),
                 age_at_onset: val('fh-age') || null, notes: val('fh-notes') };
  if (!body.condition.trim()) { showToast('Enter a condition', 'error'); return; }
  const r = await fetch('/api/family-history', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast('Added to family history'); loadFamilyHistory(); }
  else showToast((r && r.error) || 'Could not save', 'error');
}

async function deleteFamilyEntry(id) {
  await fetch('/api/family-history/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadFamilyHistory();
}

// ── Data check (data-trust: freshness + confidence) ──────────────────────────
// Honest, descriptive-only: how current each part of the record is, and where a
// summary rests on thin data. No cadence expectations, no verdicts, no advice.
const _DT_LABELS = {
  doses: 'Medication doses', vitals: 'Vitals', weight: 'Body measurements',
  labs: 'Lab results', symptoms: 'Symptoms', sleep: 'Sleep', food: 'Food',
  water: 'Water', activity: 'Activity',
};
const _DT_ICON = {
  doses: '💊', vitals: '❤️', weight: '⚖️', labs: '🧪', symptoms: '🤒',
  sleep: '😴', food: '🍽️', water: '💧', activity: '🏃',
};

function _dtAgo(days) {
  if (days == null) return '';
  if (days <= 0) return t('today');
  if (days === 1) return t('yesterday');
  return tformat('%1 days ago', days);
}

async function loadDataTrust() {
  const el = document.getElementById('datatrust-content');
  if (!el) return;
  el.innerHTML = `<div style="padding:24px;text-align:center;color:var(--gray-400)">${t('Loading…')}</div>`;
  const d = await fetch('/api/data-trust', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : null).catch(() => null);
  if (!d) { el.innerHTML = `<div class="dv-empty">${t('Could not load your data check.')}</div>`; return; }
  el.innerHTML = renderDataTrust(d);
}

function renderDataTrust(d) {
  const fresh = d.freshness || [];
  if (!fresh.length) {
    return `<div class="dv-empty">${t('Nothing tracked yet. As you log medicines, vitals and more, this page shows how current each part of your record is.')}</div>`;
  }

  const s = d.summary || {};
  const bits = [tformat('You use %1 tracker(s).', s.tracked || 0)];
  if (s.stale) bits.push(tformat('%1 not updated in over a month.', s.stale));
  if (s.thin)  bits.push(tformat('%1 with too little data to show a trend.', s.thin));
  const summary = `<div class="panel dt-summary">${escHtml(bits.join(' '))}</div>`;

  // Honest caveats on headline numbers (thin sample).
  let notes = '';
  (d.notes || []).forEach(n => {
    if (n.kind === 'thin_adherence') {
      notes += `<div class="dt-note">⚠️ ${escHtml(tformat('Your adherence % is based on only %1 scheduled dose(s) so far — read it as a rough early signal, not a settled number.', n.count))}</div>`;
    }
  });

  const tiles = fresh.map(r => {
    const label = t(_DT_LABELS[r.key] || r.label || r.key);
    const ago = _dtAgo(r.days_since);
    const when = r.last_date ? `${escHtml(r.last_date)}${ago ? ' · ' + escHtml(ago) : ''}` : t('never');
    const countLine = tformat('%1 in the last 30 days', r.count_30d || 0);
    const thin = r.thin ? `<div class="dt-thin">${escHtml(tformat('Only %1 entry(ies) — no trend yet', r.total))}</div>` : '';
    return `<div class="panel dt-tile dt-${escHtml(r.status)}">
        <div class="dt-icon">${_DT_ICON[r.key] || '•'}</div>
        <div class="dt-body">
          <div class="dt-label">${escHtml(label)}</div>
          <div class="dt-when">${when}</div>
          <div class="dt-count">${escHtml(countLine)}</div>
          ${thin}
        </div>
        <div class="dt-dot" title="${escHtml(t(r.status === 'recent' ? 'Up to date' : r.status === 'week' ? 'A little old' : 'Out of date'))}"></div>
      </div>`;
  }).join('');

  return summary + notes + `<div class="dt-grid">${tiles}</div>`;
}

// ── Procedures & hospitalizations (O1) ───────────────────────────────────────
const _PROC_KIND = { surgery: 'Surgery', hospitalization: 'Hospital stay', procedure: 'Procedure' };

async function loadProcedures() {
  const el = document.getElementById('procedures-content');
  if (!el) return;
  el.innerHTML = `<div style="padding:24px;text-align:center;color:var(--gray-400)">${t('Loading…')}</div>`;
  const d = await fetch('/api/procedures', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {procedures:[]}).catch(() => ({procedures:[]}));
  el.innerHTML = renderProcedures(d.procedures || []);
}

function renderProcedures(list) {
  const today = localToday();
  const kinds = Object.keys(_PROC_KIND).map(k => `<option value="${k}">${t(_PROC_KIND[k])}</option>`).join('');
  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Add a procedure')}</h2>
      <div class="dv-form">
        <select id="proc-kind" class="form-input" style="max-width:160px">${kinds}</select>
        <input type="text" id="proc-name" class="form-input" placeholder="${t('What was it? (e.g. Appendectomy)')}" style="flex:2;min-width:190px">
        <input type="date" id="proc-date" class="form-input" max="${today}" title="${t('Date')}" style="max-width:160px">
        <input type="date" id="proc-end" class="form-input" max="${today}" title="${t('End date (optional)')}" style="max-width:160px">
      </div>
      <div class="dv-form" style="margin-top:8px">
        <input type="text" id="proc-provider" class="form-input" placeholder="${t('Doctor / hospital (optional)')}" style="flex:1;min-width:160px">
        <input type="text" id="proc-notes" class="form-input" placeholder="${t('Notes (optional)')}" style="flex:2;min-width:160px">
        <button class="btn-primary" data-ev-click="saveProcedure()">${t('Add')}</button>
      </div>
    </div>`;
  if (!list.length) return form + `<div class="dv-empty">${t('No procedures logged yet.')}</div>`;
  const cards = list.map(p => {
    const when = p.end_date && p.end_date !== p.date_key
      ? `${escHtml(_fmtShortDate(p.date_key))} – ${escHtml(_fmtShortDate(p.end_date))}`
      : escHtml(_fmtShortDate(p.date_key));
    const meta = [p.provider && escHtml(p.provider), p.location && escHtml(p.location)].filter(Boolean).join(' · ');
    return `<div class="panel fh-card"><div class="fh-head"><div style="flex:1;min-width:0">
        <div class="fh-cond">${escHtml(p.name)} <span class="dv-card-date">${escHtml(t(_PROC_KIND[p.kind] || p.kind))} · ${when}</span></div>
        ${meta ? `<div class="fh-meta">${meta}</div>` : ''}
        ${p.notes ? `<div class="sup-notes">${escHtml(p.notes)}</div>` : ''}
      </div><button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteProcedure('${p.id}')" style="color:var(--gray-300)">✕</button></div></div>`;
  }).join('');
  return form + cards;
}

async function saveProcedure() {
  const v = id => (document.getElementById(id) || {}).value || '';
  const body = { kind: v('proc-kind'), name: v('proc-name'), date_key: v('proc-date'),
                 end_date: v('proc-end') || null, provider: v('proc-provider'), notes: v('proc-notes') };
  if (!body.name.trim()) { showToast('Enter what it was', 'error'); return; }
  if (!body.date_key) { showToast('Pick a date', 'error'); return; }
  const r = await fetch('/api/procedures', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast('Procedure added'); loadProcedures(); }
  else showToast((r && r.error) || 'Could not save', 'error');
}

async function deleteProcedure(id) {
  await fetch('/api/procedures/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadProcedures();
}

// ── Quit tracker (O2) ────────────────────────────────────────────────────────
const _QUIT_KIND = { smoking: 'Smoking', alcohol: 'Alcohol', other: 'Other' };
const _QUIT_UNIT = { smoking: 'cigarettes', alcohol: 'drinks', other: 'units' };

async function loadQuit() {
  const el = document.getElementById('quit-content');
  if (!el) return;
  el.innerHTML = `<div style="padding:24px;text-align:center;color:var(--gray-400)">${t('Loading…')}</div>`;
  const d = await fetch('/api/quit', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {plans:[]}).catch(() => ({plans:[]}));
  el.innerHTML = renderQuit(d.plans || []);
}

function renderQuit(plans) {
  const today = localToday();
  const kinds = Object.keys(_QUIT_KIND).map(k => `<option value="${k}">${t(_QUIT_KIND[k])}</option>`).join('');
  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Start a quit')}</h2>
      <div class="dv-form">
        <select id="quit-kind" class="form-input" style="max-width:150px">${kinds}</select>
        <input type="date" id="quit-date" class="form-input" max="${today}" value="${today}" title="${t('Quit date')}" style="max-width:160px">
      </div>
      <div class="dv-form" style="margin-top:8px">
        <input type="number" id="quit-baseline" class="form-input" placeholder="${t('Per day before (optional)')}" min="0" step="any" style="max-width:180px">
        <input type="number" id="quit-cost" class="form-input" placeholder="${t('Cost each ₹ (optional)')}" min="0" step="any" style="max-width:170px">
        <button class="btn-primary" data-ev-click="saveQuit()">${t('Start')}</button>
      </div>
    </div>`;
  if (!plans.length) return form + `<div class="dv-empty">${t('No quit started yet. Set a date above and watch the days add up.')}</div>`;
  const cards = plans.map(p => {
    const unit = t(_QUIT_UNIT[p.kind] || 'units');
    const stats = [];
    if (p.units_avoided != null) stats.push(`<div class="quit-stat"><div class="quit-stat-n">${trimG(p.units_avoided)}</div><div class="quit-stat-l">${tformat('%1 avoided', unit)}</div></div>`);
    if (p.money_saved != null) stats.push(`<div class="quit-stat"><div class="quit-stat-n">₹${escHtml(String(p.money_saved))}</div><div class="quit-stat-l">${t('saved')}</div></div>`);
    return `<div class="panel quit-card">
        <div class="quit-head">
          <div><div class="quit-kind">${t(_QUIT_KIND[p.kind] || p.kind)}${p.label ? ' · ' + escHtml(p.label) : ''}</div>
            <div class="quit-since">${tformat('since %1', escHtml(_fmtShortDate(p.quit_date)))}</div></div>
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteQuit('${p.id}')" style="color:var(--gray-300)">✕</button>
        </div>
        <div class="quit-days"><span class="quit-days-n">${p.days_free}</span> ${t('days free')}</div>
        ${stats.length ? `<div class="quit-stats">${stats.join('')}</div>` : ''}
        <button class="btn-outline btn-sm" data-ev-click="resetQuit('${p.id}')" style="margin-top:10px">${t('Reset to today (relapse)')}</button>
      </div>`;
  }).join('');
  return form + cards;
}

async function saveQuit() {
  const v = id => (document.getElementById(id) || {}).value || '';
  const body = { kind: v('quit-kind'), quit_date: v('quit-date'),
                 baseline_per_day: v('quit-baseline') || null, unit_cost: v('quit-cost') || null };
  if (!body.quit_date) { showToast('Pick a quit date', 'error'); return; }
  const r = await fetch('/api/quit', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast('Quit started — you got this'); loadQuit(); }
  else showToast((r && r.error) || 'Could not save', 'error');
}

async function resetQuit(id) {
  const r = await fetch('/api/quit/' + id, {method:'PATCH', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify({quit_date: localToday()})}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast('Fresh start from today'); loadQuit(); }
  else showToast('Could not update', 'error');
}

async function deleteQuit(id) {
  await fetch('/api/quit/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadQuit();
}

// ── Menopause companion (O3) ─────────────────────────────────────────────────
const _MENO_SYM = { hot_flashes: 'Hot flashes', night_sweats: 'Night sweats', sleep: 'Sleep disruption', mood: 'Mood' };
const _MENO_SEV = ['—', 'Mild', 'Moderate', 'Severe'];

async function loadMenopause() {
  const el = document.getElementById('menopause-content');
  if (!el) return;
  el.innerHTML = `<div style="padding:24px;text-align:center;color:var(--gray-400)">${t('Loading…')}</div>`;
  const d = await fetch('/api/menopause', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {logs:[],summary:{}}).catch(() => ({logs:[],summary:{}}));
  el.innerHTML = renderMenopause(d.logs || [], d.summary || {});
}

function _sevSelect(id) {
  const opts = _MENO_SEV.map((lbl, i) => `<option value="${i}">${i === 0 ? t('None') : t(lbl)}</option>`).join('');
  return `<select id="${id}" class="form-input mp-sev">${opts}</select>`;
}

function renderMenopause(logs, summary) {
  const today = localToday();
  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:10px">${t('Log today')}</h2>
      <input type="date" id="mp-date" class="form-input" max="${today}" value="${today}" style="max-width:170px;margin-bottom:10px">
      <div class="mp-grid">
        ${Object.keys(_MENO_SYM).map(s => `<label class="mp-row"><span>${t(_MENO_SYM[s])}</span>${_sevSelect('mp-' + s)}</label>`).join('')}
      </div>
      <div class="dv-form" style="margin-top:10px">
        <input type="text" id="mp-notes" class="form-input" placeholder="${t('Notes (optional)')}" style="flex:2;min-width:180px">
        <button class="btn-primary" data-ev-click="saveMenopause()">${t('Add')}</button>
      </div>
    </div>`;

  let summaryHtml = '';
  if (summary.has_data) {
    const rows = Object.keys(_MENO_SYM).map(s => {
      const d = (summary.symptoms || {})[s] || {};
      const avg = d.avg_when_present != null ? tformat('avg %1', d.avg_when_present) : t('none logged');
      return `<div class="bnd-row"><span class="bnd-k">${t(_MENO_SYM[s])}</span><span class="bnd-v">${tformat('%1 tougher days', d.flare_days || 0)} · ${avg}</span></div>`;
    }).join('');
    summaryHtml = `<div class="panel" style="padding:16px 20px;margin-bottom:14px">
        <div class="sup-alert-title">${tformat('Last %1 days', summary.days)}</div>${rows}</div>`;
  }

  const list = logs.length ? logs.slice(0, 30).map(l => {
    const bits = Object.keys(_MENO_SYM).filter(s => (l[s] || 0) >= 1)
      .map(s => `${t(_MENO_SYM[s])} ${t(_MENO_SEV[l[s]])}`).join(' · ');
    return `<div class="panel fh-card"><div class="fh-head"><div style="flex:1;min-width:0">
        <div class="fh-cond" style="font-size:13.5px">${escHtml(_fmtShortDate(l.date_key))}</div>
        <div class="fh-meta">${bits || t('No symptoms logged')}${l.notes ? ' · ' + escHtml(l.notes) : ''}</div>
      </div><button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteMenopause('${l.id}')" style="color:var(--gray-300)">✕</button></div></div>`;
  }).join('') : `<div class="dv-empty">${t('No entries yet.')}</div>`;

  return form + summaryHtml + list;
}

async function saveMenopause() {
  const v = id => (document.getElementById(id) || {}).value || '';
  const body = { date_key: v('mp-date'), notes: v('mp-notes') };
  Object.keys(_MENO_SYM).forEach(s => { body[s] = v('mp-' + s) || 0; });
  const r = await fetch('/api/menopause', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast('Logged'); loadMenopause(); }
  else showToast('Could not save', 'error');
}

async function deleteMenopause(id) {
  await fetch('/api/menopause/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadMenopause();
}

// ── Pregnancy tracker (O4) ───────────────────────────────────────────────────
async function loadPregnancy() {
  const el = document.getElementById('pregnancy-content');
  if (!el) return;
  el.innerHTML = `<div style="padding:24px;text-align:center;color:var(--gray-400)">${t('Loading…')}</div>`;
  const d = await fetch('/api/pregnancy', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {pregnancy:{active:false},logs:[]}).catch(() => ({pregnancy:{active:false},logs:[]}));
  el.innerHTML = renderPregnancy(d.pregnancy || {active:false}, d.logs || []);
}

function renderPregnancy(preg, logs) {
  const today = localToday();
  if (!preg.active) {
    return `<div class="panel" style="padding:20px 22px;max-width:520px">
        <h2 class="panel-title" style="margin-bottom:6px">${t('Start tracking')}</h2>
        <p class="dv-fineprint" style="margin-bottom:12px">${t('Enter your last period date (or a due date) — Arogo works out the week. It offers no medical guidance.')}</p>
        <div class="dv-form">
          <input type="date" id="preg-lmp" class="form-input" max="${today}" title="${t('Last period (LMP)')}" style="max-width:190px">
          <input type="date" id="preg-due" class="form-input" title="${t('Due date (optional)')}" style="max-width:190px">
          <button class="btn-primary" data-ev-click="savePregnancy()">${t('Start')}</button>
        </div>
      </div>`;
  }
  const weekStr = preg.week != null
    ? `<span class="preg-week-n">${preg.week}</span><span class="preg-week-u">${tformat('weeks %1 days', preg.day_in_week || 0)}</span>`
    : `<span class="preg-week-u">${t('week not available')}</span>`;
  const due = [];
  if (preg.due_date) due.push(tformat('due %1', escHtml(_fmtShortDate(preg.due_date))));
  if (preg.days_to_due != null) due.push(preg.days_to_due >= 0 ? tformat('%1 days to go', preg.days_to_due) : tformat('%1 days over', Math.abs(preg.days_to_due)));

  const hero = `<div class="panel preg-hero">
      <div class="preg-week">${weekStr}</div>
      ${due.length ? `<div class="preg-due">${due.join(' · ')}</div>` : ''}
      <button class="btn-outline btn-sm" data-ev-click="endPregnancy()" style="margin-top:12px">${t('End tracking')}</button>
    </div>`;

  const logForm = `<div class="panel" style="padding:16px 20px;margin:14px 0">
      <h2 class="panel-title" style="margin-bottom:10px">${t('Add a log')}</h2>
      <div class="dv-form">
        <input type="date" id="preg-log-date" class="form-input" max="${today}" value="${today}" style="max-width:160px">
        <input type="number" id="preg-weight" class="form-input" placeholder="${t('Weight kg (optional)')}" min="20" max="250" step="any" style="max-width:170px">
        <input type="number" id="preg-kicks" class="form-input" placeholder="${t('Kicks (optional)')}" min="0" style="max-width:150px">
        <button class="btn-primary" data-ev-click="savePregnancyLog()">${t('Add')}</button>
      </div>
    </div>`;

  const list = logs.length ? logs.map(l => {
    const bits = [l.weight_kg != null ? trimG(l.weight_kg) + ' kg' : '', l.kicks != null ? tformat('%1 kicks', l.kicks) : '', l.notes ? escHtml(l.notes) : ''].filter(Boolean).join(' · ');
    return `<div class="panel fh-card"><div class="fh-head"><div style="flex:1;min-width:0">
        <div class="fh-cond" style="font-size:13.5px">${escHtml(_fmtShortDate(l.date_key))}</div>
        <div class="fh-meta">${bits || '—'}</div>
      </div><button class="btn-icon" title="${t('Delete')}" data-ev-click="deletePregnancyLog('${l.id}')" style="color:var(--gray-300)">✕</button></div></div>`;
  }).join('') : `<div class="dv-empty">${t('No logs yet.')}</div>`;

  return hero + logForm + list;
}

async function savePregnancy() {
  const v = id => (document.getElementById(id) || {}).value || '';
  const body = { lmp_date: v('preg-lmp') || null, due_date: v('preg-due') || null };
  if (!body.lmp_date && !body.due_date) { showToast('Enter a last-period or due date', 'error'); return; }
  const r = await fetch('/api/pregnancy', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast('Tracking started'); loadPregnancy(); }
  else showToast((r && r.error) || 'Could not save', 'error');
}

async function savePregnancyLog() {
  const v = id => (document.getElementById(id) || {}).value || '';
  const body = { date_key: v('preg-log-date'), weight_kg: v('preg-weight') || null, kicks: v('preg-kicks') || null };
  const r = await fetch('/api/pregnancy/log', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast('Logged'); loadPregnancy(); }
  else showToast((r && r.error) || 'Could not save', 'error');
}

async function endPregnancy() {
  await fetch('/api/pregnancy/end', {method:'POST', credentials:'same-origin'}).catch(() => {});
  loadPregnancy();
}

async function deletePregnancyLog(id) {
  await fetch('/api/pregnancy/log/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadPregnancy();
}

// ── Custom health reminders (D) ──────────────────────────────────────────────
// The user's own health to-dos with a due date and optional repeat. User-defined
// only — Arogo recommends no screening schedule; it just tracks what's due.
async function loadHealthReminders() {
  const el = document.getElementById('reminders-content');
  if (!el) return;
  el.innerHTML = `<div style="padding:24px;text-align:center;color:var(--gray-400)">${t('Loading…')}</div>`;
  const d = await fetch('/api/health-reminders', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {reminders:[]}).catch(() => ({reminders:[]}));
  el.innerHTML = renderHealthReminders(d.reminders || []);
}

function renderHealthReminders(list) {
  const today = localToday();
  const repeatOpts = [['', t('One-off')], ['30', t('Monthly')], ['90', t('Every 3 months')],
                      ['180', t('Every 6 months')], ['365', t('Yearly')], ['730', t('Every 2 years')]]
    .map(([v, l]) => `<option value="${v}">${l}</option>`).join('');
  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Add a reminder')}</h2>
      <div class="dv-form">
        <input type="text" id="rem-title" class="form-input" placeholder="${t('What? (e.g. Annual check-up, Eye test)')}" style="flex:2;min-width:200px">
        <input type="date" id="rem-date" class="form-input" title="${t('Due date')}" style="max-width:160px">
        <select id="rem-repeat" class="form-input" style="max-width:160px" title="${t('Repeat')}">${repeatOpts}</select>
        <button class="btn-primary" data-ev-click="saveHealthReminder()">${t('Add')}</button>
      </div>
    </div>`;

  if (!list.length) {
    return form + `<div class="dv-empty">${t('Nothing to remember yet. Add the health tasks you want nudged — you decide what and when.')}</div>`;
  }
  const cards = list.map(r => {
    const when = r.days_until == null ? '' :
      (r.overdue ? tformat('overdue by %1 days', Math.abs(r.days_until))
       : r.days_until === 0 ? t('due today') : tformat('in %1 days', r.days_until));
    return `<div class="panel rem-card ${r.overdue ? 'overdue' : ''}">
        <div class="rem-head">
          <div style="flex:1;min-width:0">
            <div class="rem-title">${escHtml(r.title)}</div>
            <div class="rem-meta"><span class="${r.overdue ? 'rem-over' : ''}">${escHtml(_fmtShortDate(r.due_date))} · ${when}</span>${r.recurring ? ' · ↻ ' + t('repeats') : ''}${r.notes ? ' · ' + escHtml(r.notes) : ''}</div>
          </div>
          <button class="btn-icon" title="${t('Mark done')}" data-ev-click="completeHealthReminder('${r.id}')">✓</button>
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteHealthReminder('${r.id}')" style="color:var(--gray-300)">✕</button>
        </div>
      </div>`;
  }).join('');
  return form + cards;
}

async function saveHealthReminder() {
  const v = id => (document.getElementById(id) || {}).value || '';
  const body = { title: v('rem-title'), due_date: v('rem-date'), repeat_days: v('rem-repeat') || null };
  if (!body.title.trim()) { showToast('Enter what to remember', 'error'); return; }
  if (!body.due_date) { showToast('Pick a due date', 'error'); return; }
  const r = await fetch('/api/health-reminders', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast('Reminder added'); loadHealthReminders(); }
  else showToast((r && r.error) || 'Could not save', 'error');
}

async function completeHealthReminder(id) {
  const r = await fetch('/api/health-reminders/' + id + '/done', {method:'POST', credentials:'same-origin'})
    .then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(r.reminder && r.reminder.recurring ? t('Done — rolled to next time') : t('Done ✓')); loadHealthReminders(); }
  else showToast('Could not update', 'error');
}

async function deleteHealthReminder(id) {
  await fetch('/api/health-reminders/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadHealthReminders();
}

// ── Device CSV import (Category 1) ───────────────────────────────────────────
// Paste or upload a CSV from a home BP monitor / glucometer / oximeter and
// review the parsed readings before anything is saved. The server re-validates
// every committed row (ranges enforced), so a junk reading is skipped, not saved.
let _vitalsImportPreview = null;

function openVitalsImport() {
  const el = document.getElementById('vitals-import-box');
  if (!el) return;
  if (el.innerHTML.trim()) { el.innerHTML = ''; _vitalsImportPreview = null; return; }   // toggle off
  el.innerHTML = `<div class="panel" style="padding:16px 18px;margin-bottom:14px">
      <h3 class="panel-title" style="margin-bottom:6px">${t('Import readings from a device')}</h3>
      <p class="dv-fineprint">${t('Export a CSV from your BP monitor, glucometer, oximeter or thermometer, then paste it or choose the file. Nothing is saved until you review and confirm.')}</p>
      <input type="file" id="vimp-file" accept=".csv,text/csv,text/plain" class="form-input" style="margin:10px 0;max-width:280px">
      <textarea id="vimp-text" class="form-input" rows="4" placeholder="${t('…or paste CSV here (e.g. Date,Systolic,Diastolic,Glucose)')}"></textarea>
      <div style="margin-top:10px"><button class="btn-primary btn-sm" data-ev-click="previewVitalsImport()">${t('Preview')}</button>
        <button class="btn-outline btn-sm" data-ev-click="openVitalsImport()" style="margin-left:6px">${t('Cancel')}</button></div>
      <div id="vimp-result" style="margin-top:12px"></div>
    </div>`;
}

async function previewVitalsImport() {
  let csv = (document.getElementById('vimp-text') || {}).value || '';
  const f = (document.getElementById('vimp-file') || {}).files && document.getElementById('vimp-file').files[0];
  if (f && !csv.trim()) { try { csv = await f.text(); } catch (e) {} }
  if (!csv.trim()) { showToast('Paste or choose a CSV first', 'error'); return; }
  const d = await fetch('/api/import/vitals/preview', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify({csv})}).then(r => r.json()).catch(() => null);
  const res = document.getElementById('vimp-result');
  if (!res) return;
  if (!d || !(d.candidates || []).length) {
    _vitalsImportPreview = null;
    res.innerHTML = `<div class="dv-empty">${t('No readings recognised in that file.')}</div>`;
    return;
  }
  _vitalsImportPreview = d.candidates;
  const rows = d.candidates.map((c, i) => `<label class="vimp-row">
      <input type="checkbox" class="vimp-ck" data-i="${i}" checked>
      <span>${escHtml(_fmtShortDate(c.date_key))} · ${escHtml(t(c.label))} · ${escHtml(String(c.value1))}${c.value2 != null ? '/' + escHtml(String(c.value2)) : ''} ${escHtml(c.unit || '')}</span>
    </label>`).join('');
  res.innerHTML = `<div class="vimp-preview">${rows}</div>
    <div style="font-size:12px;color:var(--gray-400);margin:8px 0">${tformat('%1 recognised · %2 rows skipped', d.candidates.length, d.skipped || 0)}</div>
    <button class="btn-primary btn-sm" data-ev-click="commitVitalsImport()">${t('Import selected')}</button>`;
}

async function commitVitalsImport() {
  if (!_vitalsImportPreview) return;
  const checked = [...document.querySelectorAll('#vitals-import-box .vimp-ck:checked')]
    .map(ck => _vitalsImportPreview[+ck.dataset.i]).filter(Boolean);
  if (!checked.length) { showToast('Select at least one reading', 'error'); return; }
  const r = await fetch('/api/import/vitals/commit', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify({rows: checked})}).then(x => x.json()).catch(() => null);
  if (r && r.success) {
    showToast(tformat('%1 imported%2', r.saved, r.failed ? ', ' + tformat('%1 skipped', r.failed) : ''));
    const box = document.getElementById('vitals-import-box'); if (box) box.innerHTML = '';
    _vitalsImportPreview = null;
    try { loadVitals(); } catch (e) {}
    try { loadVitalSparks(); } catch (e) {}
  } else showToast('Could not import', 'error');
}

// ── Family health calendar (upcoming) ────────────────────────────────────────
// A forward-looking merge of everything coming up — appointments, lab rechecks,
// prescription renewals, vaccines due, and future-dated dependent records — for
// the user and their family. All derived; nothing invented.
const UPC_TYPE = {
  appointment: {icon:'🗓️', label:'Appointment'},
  lab_recheck: {icon:'🧪', label:'Lab recheck'},
  rx_renewal:  {icon:'📄', label:'Prescription renewal'},
  vaccine:     {icon:'💉', label:'Vaccine due'},
  dependent:   {icon:'👤', label:'Family'},
};

async function loadUpcoming() {
  const el = document.getElementById('upcoming-content');
  if (!el) return;
  const d = await fetch('/api/upcoming?days=90', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {events:[]}).catch(() => ({events:[]}));
  el.innerHTML = renderUpcoming(d);
}

function _upcTitle(e) {
  const name = escHtml(e.name || '');
  switch (e.type) {
    case 'appointment': return name || t('Appointment');
    case 'lab_recheck': return tformat('%1 recheck', name);
    case 'rx_renewal':  return name ? tformat('Renew prescription · %1', name) : t('Renew a prescription');
    case 'vaccine':     return tformat('%1 due', name);
    case 'dependent':   return name;
    default:            return name;
  }
}

function _upcWhen(du) {
  if (du < 0)  return {txt: tformat('%1 days overdue', -du), cls: 'upc-overdue'};
  if (du === 0) return {txt: t('today'), cls: 'upc-today'};
  if (du === 1) return {txt: t('tomorrow'), cls: 'upc-soon'};
  if (du <= 7)  return {txt: tformat('in %1 days', du), cls: 'upc-soon'};
  return {txt: tformat('in %1 days', du), cls: ''};
}

function renderUpcoming(d) {
  const events = d.events || [];
  if (!events.length) {
    return `<div class="panel" style="padding:32px;text-align:center">
        <div style="font-size:30px;margin-bottom:8px">📆</div>
        <div style="font-size:14px;font-weight:600;margin-bottom:4px">${t('Nothing coming up')}</div>
        <div style="font-size:13px;color:var(--gray-400)">${t('Appointments, lab rechecks, renewals and vaccines due will appear here as you add them.')}</div>
      </div>`;
  }

  // Group into relative buckets.
  const buckets = [
    {key: 'overdue', label: t('Overdue'), test: e => e.days_until < 0, items: []},
    {key: 'week',    label: t('This week'), test: e => e.days_until >= 0 && e.days_until <= 7, items: []},
    {key: 'month',   label: t('Next 30 days'), test: e => e.days_until > 7 && e.days_until <= 30, items: []},
    {key: 'later',   label: t('Later'), test: e => e.days_until > 30, items: []},
  ];
  for (const e of events) (buckets.find(b => b.test(e)) || buckets[3]).items.push(e);

  const summary = (d.overdue_count || d.this_week)
    ? `<div class="upc-summary">${[
        d.overdue_count ? `<span class="upc-summary-overdue">${tformat('%1 overdue', d.overdue_count)}</span>` : '',
        d.this_week ? tformat('%1 this week', d.this_week) : '',
      ].filter(Boolean).join(' · ')}</div>` : '';

  const sections = buckets.filter(b => b.items.length).map(b => {
    const rows = b.items.map(e => {
      const ty = UPC_TYPE[e.type] || {icon:'•', label:e.type};
      const when = _upcWhen(e.days_until);
      const dt = new Date(e.date + 'T12:00:00');
      const dayLbl = dt.toLocaleDateString([], {weekday:'short', month:'short', day:'numeric'});
      const who = e.who ? `<span class="upc-who">${escHtml(e.who)}</span>` : '';
      const detail = e.detail && e.type !== 'dependent' ? ` · ${escHtml(e.detail)}` : '';
      return `<div class="upc-item">
          <div class="upc-icon">${ty.icon}</div>
          <div class="upc-main">
            <div class="upc-title">${_upcTitle(e)} ${who}</div>
            <div class="upc-sub">${t(ty.label)}${detail} · ${dayLbl}</div>
          </div>
          <div class="upc-when ${when.cls}">${when.txt}</div>
        </div>`;
    }).join('');
    return `<div class="panel" style="padding:14px 18px;margin-bottom:12px">
        <div class="upc-bucket-head">${b.label}</div>${rows}</div>`;
  }).join('');

  return summary + sections;
}

// ── Meal planner + grocery list ──────────────────────────────────────────────
// Plan items to a day + meal for the week ahead, then roll the plan up into a
// grocery list that sums the same item across days. Free-text items; quantities
// optional. Distinct from the food LOG (what was eaten).
const MEAL_SLOTS = {
  breakfast: {icon:'🌅', label:'Breakfast'},
  lunch:     {icon:'🍛', label:'Lunch'},
  dinner:    {icon:'🌙', label:'Dinner'},
  snack:     {icon:'🍎', label:'Snack'},
};
let _showGrocery = false;

async function loadMealPlan() {
  const el = document.getElementById('meal-plan-content');
  if (!el) return;
  const d = await fetch('/api/meal-plan?days=7', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {days:[]}).catch(() => ({days:[]}));
  el.innerHTML = renderMealPlan(d);
  if (_showGrocery) loadGrocery();
}

function renderMealPlan(d) {
  const today = localToday();
  const mealOpts = Object.entries(MEAL_SLOTS).map(([k, v]) => `<option value="${k}">${v.icon} ${t(v.label)}</option>`).join('');
  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Add to the plan')}</h2>
      <div class="mp-form">
        <input type="text" id="mp-item" class="form-input" placeholder="${t('Food (e.g. Toor dal, Roti)')}" style="flex:2;min-width:170px">
        <input type="number" step="any" min="0" id="mp-qty" class="form-input" placeholder="${t('Qty')}" style="max-width:80px">
        <input type="text" id="mp-unit" class="form-input" placeholder="${t('unit')}" style="max-width:80px" value="g">
        <input type="date" id="mp-date" class="form-input" value="${today}" style="max-width:150px">
        <select id="mp-meal" class="form-input" style="max-width:150px">${mealOpts}</select>
        <button class="btn-primary" data-ev-click="addMealItem()">${t('Add')}</button>
      </div>
      <div style="margin-top:10px">
        <button class="btn-outline" data-ev-click="toggleGrocery()">🛒 ${_showGrocery ? t('Hide grocery list') : t('Grocery list')}</button>
      </div>
    </div>`;

  const grocery = _showGrocery ? `<div id="mp-grocery" class="panel" style="padding:16px 20px;margin-bottom:16px">
      <div style="font-size:13px;color:var(--gray-400)">${t('Loading…')}</div></div>` : '';

  const anyPlanned = (d.days || []).some(day => Object.values(day.meals).some(arr => arr.length));
  const daysHtml = (d.days || []).map(day => {
    const dt = new Date(day.date + 'T12:00:00');
    const isToday = day.date === today;
    const dayLbl = dt.toLocaleDateString([], {weekday:'long', month:'short', day:'numeric'});
    const slots = Object.entries(MEAL_SLOTS).map(([k, v]) => {
      const items = day.meals[k] || [];
      if (!items.length) return '';
      const rows = items.map(i => {
        const qty = i.quantity != null ? ` · ${i.quantity}${escHtml(String(i.unit || ''))}` : '';
        return `<div class="mp-item"><span>${escHtml(i.item)}${qty}</span>
          <button class="btn-icon" title="${t('Remove')}" data-ev-click="deleteMealItem('${i.id}')" style="color:var(--gray-300);font-size:12px">✕</button></div>`;
      }).join('');
      return `<div class="mp-slot"><div class="mp-slot-head">${v.icon} ${t(v.label)}</div>${rows}</div>`;
    }).join('');
    const empty = slots ? '' : `<div class="mp-day-empty">${t('Nothing planned')}</div>`;
    return `<div class="panel mp-day${isToday ? ' mp-day--today' : ''}" style="padding:14px 18px;margin-bottom:12px">
        <div class="mp-day-head">${dayLbl}${isToday ? ` · <span class="mp-today-tag">${t('today')}</span>` : ''}</div>
        ${slots}${empty}
      </div>`;
  }).join('');

  return form + grocery + daysHtml;
}

async function addMealItem() {
  const item = document.getElementById('mp-item')?.value?.trim();
  if (!item) { showToast(t('Enter a food'), 'error'); return; }
  const body = {
    item,
    quantity: document.getElementById('mp-qty')?.value || null,
    unit: document.getElementById('mp-unit')?.value || '',
    date: document.getElementById('mp-date')?.value || localToday(),
    meal_type: document.getElementById('mp-meal')?.value || 'lunch',
  };
  const r = await fetch('/api/meal-plan', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify(body)}).then(x => x.json()).catch(() => null);
  if (r && r.success) {
    showToast(t('Added to plan'));
    const it = document.getElementById('mp-item'); if (it) it.value = '';
    loadMealPlan();
  } else showToast((r && r.error) || t('Could not save'), 'error');
}

async function deleteMealItem(id) {
  await fetch('/api/meal-plan/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadMealPlan();
}

function toggleGrocery() { _showGrocery = !_showGrocery; loadMealPlan(); }

async function loadGrocery() {
  const box = document.getElementById('mp-grocery');
  if (!box) return;
  const d = await fetch('/api/meal-plan/grocery?days=7', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {items:[]}).catch(() => ({items:[]}));
  if (!(d.items || []).length) {
    box.innerHTML = `<div class="mp-grocery-head">🛒 ${t('Grocery list')}</div>
      <div style="font-size:13px;color:var(--gray-400)">${t('Plan some meals and your grocery list builds itself.')}</div>`;
    return;
  }
  const rows = d.items.map(i => {
    const unit = escHtml(String(i.unit || ''));
    let qty = i.quantity != null ? `${i.quantity}${unit}` : (i.count > 1 ? `×${i.count}` : '');
    if (i.extra > 0) qty += ` ${tformat('+%1 more', i.extra)}`;    // unquantified extras
    return `<div class="mp-grocery-row"><span>${escHtml(i.item)}</span><span class="mp-grocery-qty">${qty}</span></div>`;
  }).join('');
  box.innerHTML = `<div class="mp-grocery-head">🛒 ${tformat('Grocery list · %1 items', d.total)}</div>${rows}`;
}

// ── Med budget & run-out forecast ────────────────────────────────────────────
// Run-out DATE per tracked medicine + monthly/yearly cost projection. All from
// the user's own pill counts and per-med costs.
// I2: Travel supply planner — pills to pack + refill-before-you-go list.
async function planTravelSupply() {
  const start = document.getElementById('trip-start')?.value;
  const end   = document.getElementById('trip-end')?.value;
  const out   = document.getElementById('trip-plan-result');
  if (!out) return;
  if (!start || !end) { out.innerHTML = `<div class="hint-inline">${t('Pick both dates.')}</div>`; return; }
  out.innerHTML = `<div class="hint-inline">${t('Working it out…')}</div>`;
  const d = await fetch(`/api/medicines/travel-supply?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`,
    {credentials:'same-origin'}).then(r => r.json()).catch(() => null);
  if (!d || !d.ok) {
    const msg = d && d.reason === 'end_before_start' ? t('Return date is before you leave.')
              : d && d.reason === 'trip_too_long'    ? t('That trip is over a year — pick a shorter range.')
              : t('Please check the dates.');
    out.innerHTML = `<div class="hint-inline">${msg}</div>`; return;
  }
  if (!d.items.length) {
    out.innerHTML = `<div class="hint-inline">${t('No scheduled medicines to pack. (As-needed medicines aren’t counted.)')}</div>`;
    return;
  }
  const rows = d.items.map(it => {
    const packBadge = `<b>${it.needed}</b> ${t('to pack')}`;
    let status;
    if (it.available === null) status = `<span style="color:var(--gray-400)">${t('stock not tracked')}</span>`;
    else if (it.covered)       status = `<span style="color:var(--teal-600)">✓ ${t('you have enough')}</span>`;
    else                       status = `<span style="color:#B45309;font-weight:600">${tformat('refill %1 more', it.shortfall)}</span>`;
    return `<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;
                 padding:10px 0;border-top:1px solid var(--gray-100);font-size:14px">
              <span style="font-weight:600;color:var(--gray-800)">${escapeHtml(it.name)}</span>
              <span style="text-align:right">${packBadge} · ${status}</span>
            </div>`;
  }).join('');
  const banner = d.refill_needed.length
    ? `<div style="background:#FEF3C7;border:1px solid #FDE68A;border-radius:10px;padding:12px 14px;
           font-size:13.5px;color:#92400E;margin-bottom:12px">
         ⚠️ ${tformat('%1 medicine(s) need a refill before you leave.', d.refill_needed.length)}</div>`
    : `<div style="background:var(--teal-50);border:1px solid var(--teal-200);border-radius:10px;padding:12px 14px;
           font-size:13.5px;color:var(--teal-700);margin-bottom:12px">
         ✓ ${t('You’re covered for the whole trip.')}</div>`;
  out.innerHTML = banner +
    `<div style="font-size:12px;color:var(--gray-400);margin-bottom:2px">
       ${tformat('%1 days · %2 pills total', d.trip_days, d.total_pills)}</div>` +
    rows;
}

async function loadMedBudget() {
  const el = document.getElementById('med-budget-content');
  if (!el) return;
  const d = await fetch('/api/medicines/forecast', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : null).catch(() => null);
  if (!d) { el.innerHTML = `<div class="panel" style="padding:20px">${t('Could not load')}</div>`; return; }
  el.innerHTML = renderMedBudget(d) + '<div id="cost-per-day-section"></div><div id="med-spend-timeline"></div>';
  loadCostPerDay();
  loadMedSpendTimeline();
}

// I9: each medicine's monthly cost broken down to a per-day figure, ranked.
// Only medicines the user priced; unpriced ones are counted, never assumed ₹0.
async function loadCostPerDay() {
  const el = document.getElementById('cost-per-day-section');
  if (!el) return;
  const d = await fetch('/api/medicines/cost-per-day', {credentials:'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { el.innerHTML = ''; return; }
  const inr = n => '₹' + (Math.round(n * 100) / 100).toLocaleString('en-IN', {minimumFractionDigits: 2, maximumFractionDigits: 2});
  const maxDay = Math.max(...d.items.map(i => i.per_day), 0.01);
  const rows = d.items.map(i => `
    <div class="cpd-row">
      <div class="cpd-name">${escapeHtml(i.name)}</div>
      <div class="cpd-bar-wrap"><div class="cpd-bar" style="width:${(i.per_day / maxDay * 100).toFixed(1)}%"></div></div>
      <div class="cpd-day">${inr(i.per_day)}<span class="cpd-mo">${tformat('%1/mo', inr(i.monthly))}</span></div>
    </div>`).join('');
  const unpriced = d.unpriced
    ? `<div class="cpd-note">${tformat('%1 medicine(s) have no price set — not counted.', d.unpriced)}</div>` : '';
  el.innerHTML = `<div class="panel" style="padding:18px 20px;margin-top:20px">
      <div class="panel-header"><h2 class="panel-title">🪙 ${t('Cost per day')}</h2>
        <span class="panel-badge">${tformat('%1/day total', inr(d.total_per_day))}</span></div>
      ${rows}
      ${unpriced}
    </div>`;
}

// Estimated medicine spend per month + YTD + projected annual.
async function loadMedSpendTimeline() {
  const el = document.getElementById('med-spend-timeline');
  if (!el) return;
  const d = await fetch('/api/medicines/spend-timeline?months=12').then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { el.innerHTML = ''; return; }
  const max = Math.max(...d.timeline.map(t => t.spend), 1);
  const bars = d.timeline.map(t => {
    const h = Math.round(t.spend / max * 70);
    const mlabel = new Date(t.month + '-01T12:00:00').toLocaleDateString([], { month: 'short' });
    return `<div class="mst-col" title="${t.month}: ${_rupee(t.spend)}">
      <div class="mst-bar" style="height:${h}px"></div><div class="mst-x">${mlabel}</div></div>`;
  }).join('');
  el.innerHTML = `<div class="panel" style="padding:16px 18px;margin-top:16px">
      <div class="panel-header" style="padding:0 0 8px"><h2 class="panel-title">📈 ${t('Spend over time')}</h2><span class="panel-badge">${t('last 12 months')}</span></div>
      <div class="mst-stats">
        <div><div class="mst-n">${_rupee(d.current_monthly)}</div><div class="mst-l">${t('this month')}</div></div>
        <div><div class="mst-n">${_rupee(d.ytd)}</div><div class="mst-l">${t('this year')}</div></div>
        <div><div class="mst-n">${_rupee(d.projected_annual)}</div><div class="mst-l">${t('projected/yr')}</div></div>
      </div>
      <div class="mst-chart">${bars}</div>
      <div class="mst-disc">${t('An estimate: costs are taken at their current value; deleted medicines are not counted.')}</div>
    </div>`;
}

function renderMedBudget(d) {
  const cost = d.priced_count ? `<div class="panel mb-hero" style="padding:18px 20px;margin-bottom:16px">
      <div class="mb-hero-grid">
        <div><div class="mb-hero-n">${_rupee(d.monthly_cost)}</div><div class="mb-hero-l">${t('per month')}</div></div>
        <div><div class="mb-hero-n">${_rupee(d.yearly_cost)}</div><div class="mb-hero-l">${t('per year')}</div></div>
        <div><div class="mb-hero-n">${d.priced_count}</div><div class="mb-hero-l">${t('priced meds')}</div></div>
      </div>
      ${(d.cost_items || []).length ? `<div class="mb-cost-list">${d.cost_items.map(i =>
        `<div class="mb-cost-row"><span>${escHtml(i.icon || '💊')} ${escHtml(i.name)}</span><span>${_rupee(i.cost)}/mo</span></div>`).join('')}</div>` : ''}
    </div>` : `<div class="panel" style="padding:16px 20px;margin-bottom:16px;font-size:13px;color:var(--gray-400)">${t('Add a monthly cost to your medicines to see the budget here.')}</div>`;

  let runouts;
  if (!(d.run_outs || []).length) {
    runouts = `<div class="panel" style="padding:22px;text-align:center;color:var(--gray-400);font-size:13px">${t('Track pill counts on your medicines to forecast run-out dates.')}</div>`;
  } else {
    const rows = d.run_outs.map(r => {
      const dt = new Date(r.run_out + 'T12:00:00').toLocaleDateString([], {weekday:'short', month:'short', day:'numeric'});
      return `<div class="mb-run-row${r.low ? ' mb-run-low' : ''}">
          <span class="mb-run-name">${escHtml(r.icon || '💊')} ${escHtml(r.name)}</span>
          <span class="mb-run-days">${tformat('%1 days left', Math.round(r.days_left))}</span>
          <span class="mb-run-date">${tformat('runs out %1', dt)}</span>
        </div>`;
    }).join('');
    runouts = `<div class="panel" style="padding:16px 20px"><h2 class="panel-title" style="margin-bottom:10px">${t('Runs out')}</h2>${rows}</div>`;
  }
  return cost + runouts;
}

// ── Strength training log ────────────────────────────────────────────────────
// One row per set. Sessions group same-day sets of the same lift. Estimated 1RM
// (Epley) is always labelled "est." — it's a model, not a number you lifted.
let _strengthUnit = 'kg';

async function loadStrength() {
  const el = document.getElementById('strength-content');
  if (!el) return;
  el.innerHTML = `
    <div style="display:grid;grid-template-columns:340px 1fr;gap:18px;align-items:start" class="strength-grid">
      <div class="panel" style="padding:16px 18px 18px">
        <div class="panel-header" style="padding:0 0 8px"><h2 class="panel-title">${t('Log a set')}</h2></div>
        <div class="form-group" style="margin-bottom:8px">
          <label class="form-label">${t('Exercise')}</label>
          <input type="text" class="form-input" id="wk-exercise" list="wk-exercise-list" placeholder="${t('e.g. Bench Press')}" autocomplete="off">
          <datalist id="wk-exercise-list"></datalist>
        </div>
        <div class="form-row" style="display:grid;grid-template-columns:1fr 1fr auto;gap:8px;margin-bottom:10px">
          <div class="form-group"><label class="form-label">${t('Reps')}</label>
            <input type="number" class="form-input" id="wk-reps" min="1" max="1000" placeholder="8"></div>
          <div class="form-group"><label class="form-label">${t('Weight')}</label>
            <input type="number" class="form-input" id="wk-weight" min="0" step="0.5" placeholder="60"></div>
          <div class="form-group"><label class="form-label">&nbsp;</label>
            <div class="wk-unit-toggle" id="wk-unit-toggle">
              <button type="button" class="wk-unit selected" data-unit="kg" data-ev-click="setStrengthUnit('kg')">kg</button>
              <button type="button" class="wk-unit" data-unit="lb" data-ev-click="setStrengthUnit('lb')">lb</button>
            </div>
          </div>
        </div>
        <button class="btn-primary" style="width:100%" data-ev-click="addWorkoutSet()">${t('Add set')}</button>
        <div id="wk-progression" style="margin-top:16px"></div>
      </div>
      <div>
        <div id="wk-sessions"></div>
      </div>
    </div>`;
  loadWorkoutExercises();
  loadWorkoutSessions();
}

function setStrengthUnit(u) {
  _strengthUnit = (u === 'lb') ? 'lb' : 'kg';
  document.querySelectorAll('#wk-unit-toggle .wk-unit').forEach(b => b.classList.toggle('selected', b.dataset.unit === _strengthUnit));
}

async function loadWorkoutExercises() {
  const d = await fetch('/api/workouts/exercises').then(r => r.json()).catch(() => null);
  const dl = document.getElementById('wk-exercise-list');
  if (dl && d && d.exercises) dl.innerHTML = d.exercises.map(e => `<option value="${escHtml(e)}">`).join('');
}

async function addWorkoutSet() {
  const exercise = (document.getElementById('wk-exercise')?.value || '').trim();
  const reps = parseInt(document.getElementById('wk-reps')?.value, 10);
  const weight = parseFloat(document.getElementById('wk-weight')?.value) || 0;
  if (!exercise) { showToast(t('Enter an exercise'), 'error'); return; }
  if (!reps || reps < 1) { showToast(t('Enter reps'), 'error'); return; }
  const r = await fetch('/api/workouts', {
    method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({ exercise, reps, weight, unit:_strengthUnit, date_key: localToday() })
  }).then(r => r.json()).catch(() => null);
  if (r && r.success) {
    showToast(t('Set logged 💪'));
    document.getElementById('wk-reps').value = '';
    document.getElementById('wk-weight').value = '';
    loadWorkoutSessions();
    loadWorkoutExercises();
    loadWorkoutProgression(exercise);
  } else {
    showToast((r && r.error) || t('Could not save'), 'error');
  }
}

async function loadWorkoutSessions() {
  const el = document.getElementById('wk-sessions');
  if (!el) return;
  const d = await fetch('/api/workouts?days=90').then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) {
    el.innerHTML = `<div class="panel" style="padding:28px;text-align:center;color:var(--gray-400);font-size:13px">${t('No sets logged yet. Log your first set to start tracking progress.')}</div>`;
    return;
  }
  el.innerHTML = d.sessions.map(s => {
    const setStr = s.sets.map(st => `${st.reps}×${st.weight || t('BW')}`).join(' · ');
    const dateStr = new Date(s.date_key + 'T12:00:00').toLocaleDateString([], {weekday:'short', month:'short', day:'numeric'});
    const oneRm = s.best_1rm > 0 ? `<span class="wk-1rm">${t('est. 1RM')} ${s.best_1rm}${s.unit}</span>` : '';
    return `<div class="panel wk-session" style="padding:14px 18px;margin-bottom:10px">
      <div class="wk-session-head">
        <button class="wk-name-link" data-exercise="${escHtml(s.exercise)}" data-ev-click="progFromEl()">${escHtml(s.exercise)}</button>
        <span class="wk-session-date">${dateStr}</span>
      </div>
      <div class="wk-session-sets">${escHtml(setStr)}</div>
      <div class="wk-session-meta">${tformat('volume %1%2', Math.round(s.volume), s.unit)} · ${tformat('top %1%2', s.top_weight, s.unit)} ${oneRm}</div>
    </div>`;
  }).join('');
}

// Called via data-ev-click with `this` bound to the clicked element; reads the
// exercise from a data attribute so a name with quotes can't break out of the
// handler string (delegation parses args, but the data-attr path never eval's).
function progFromEl() { loadWorkoutProgression(this.dataset.exercise); }

async function loadWorkoutProgression(exercise) {
  const el = document.getElementById('wk-progression');
  if (!el || !exercise) return;
  const d = await fetch('/api/workouts/progression?exercise=' + encodeURIComponent(exercise))
    .then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { el.innerHTML = ''; return; }
  // Simple inline sparkline of best est-1RM per session.
  const pts = d.points.map(p => p.best_1rm);
  const max = Math.max(...pts, 1), min = Math.min(...pts);
  const bars = d.points.slice(-12).map(p => {
    const h = max === min ? 60 : Math.round(((p.best_1rm - min) / (max - min)) * 46 + 14);
    return `<div class="wk-spark-bar" style="height:${h}px" title="${p.date_key}: ${p.best_1rm}${d.unit}"></div>`;
  }).join('');
  const first = pts[0], last = pts[pts.length - 1];
  const delta = last - first;
  const deltaStr = pts.length > 1
    ? (delta > 0 ? `<span style="color:#22C55E">▲ +${Math.round(delta * 10) / 10}${d.unit}</span>`
       : delta < 0 ? `<span style="color:#EF4444">▼ ${Math.round(delta * 10) / 10}${d.unit}</span>`
       : `<span style="color:var(--gray-400)">${t('no change')}</span>`)
    : '';
  el.innerHTML = `<div class="wk-prog-card">
    <div class="wk-prog-head">${escHtml(d.display_name)}</div>
    <div class="wk-prog-pb">${t('Best')}: ${d.best_weight}${d.unit} · ${t('est. 1RM')} ${d.best_1rm}${d.unit}</div>
    <div class="wk-spark">${bars}</div>
    <div class="wk-prog-delta">${tformat('over %1 session(s)', d.points.length)} ${deltaStr}</div>
  </div>`;
}

// ── Medication dose taper ────────────────────────────────────────────────────
// A schedule of dated dose steps for one medicine. The step active today is
// highlighted; the current dose is derived, never guessed.
let _taperMed = null;

async function loadTaper() {
  const el = document.getElementById('taper-content');
  if (!el) return;
  const [meds, overview] = await Promise.all([
    fetch('/api/medicines', {credentials:'same-origin'}).then(r => r.ok ? r.json() : []).catch(() => []),
    fetch('/api/tapers', {credentials:'same-origin'}).then(r => r.ok ? r.json() : {tapers:[]}).catch(() => ({tapers:[]})),
  ]);
  const active = (meds || []).filter(m => m.active);
  if (!_taperMed && active.length) _taperMed = active[0].id;
  el.innerHTML = renderTaperShell(active, overview.tapers || []);
  if (_taperMed) loadTaperSteps();
}

function renderTaperShell(meds, overview) {
  if (!meds.length) {
    return `<div class="panel" style="padding:28px;text-align:center">
        <div style="font-size:30px;margin-bottom:8px">💊</div>
        <div style="font-size:14px;font-weight:600;margin-bottom:4px">${t('No medicines yet')}</div>
        <div style="font-size:13px;color:var(--gray-400)">${t('Add a medicine first, then build its taper here.')}</div>
      </div>`;
  }
  const opts = meds.map(m => `<option value="${m.id}"${m.id === _taperMed ? ' selected' : ''}>${escHtml(m.icon || '💊')} ${escHtml(m.name)}</option>`).join('');
  const form = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <div class="tp-pick">
        <label class="rs-label">${t('Medicine')}</label>
        <select id="tp-med" class="form-input" data-ev-change="onTaperMedPick()" style="max-width:220px">${opts}</select>
      </div>
      <h2 class="panel-title" style="margin:14px 0 10px">${t('Add a dose step')}</h2>
      <div class="tp-form">
        <input type="text" id="tp-dose" class="form-input" placeholder="${t('Dose (e.g. 20mg)')}" style="max-width:130px">
        <input type="date" id="tp-date" class="form-input" style="max-width:160px">
        <input type="text" id="tp-note" class="form-input" placeholder="${t('Note (optional)')}" style="flex:1;min-width:140px">
        <button class="btn-primary" data-ev-click="addTaperStep()">${t('Add step')}</button>
      </div>
      <div class="rs-hint" style="margin-top:8px">${t('The step with the most recent start date on or before today is your current dose.')}</div>
    </div>
    <div id="tp-steps"></div>`;

  const others = overview.filter(o => o.medicine_id !== _taperMed);
  const ov = others.length ? `<div class="panel" style="padding:14px 18px;margin-top:16px">
      <div class="tp-ov-head">${t('Other tapers')}</div>
      ${others.map(o => `<div class="tp-ov-row" data-ev-click="pickTaper('${o.medicine_id}')">
        <span>${escHtml(o.icon || '💊')} ${escHtml(o.name)}</span>
        <span class="tp-ov-dose">${o.current ? escHtml(o.current.dosage) : t('not started')}</span></div>`).join('')}
    </div>` : '';
  return form + ov;
}

function onTaperMedPick() { _taperMed = document.getElementById('tp-med')?.value || null; loadTaperSteps(); }
function pickTaper(mid) { _taperMed = mid; loadTaper(); }

async function loadTaperSteps() {
  const box = document.getElementById('tp-steps');
  if (!box || !_taperMed) return;
  const d = await fetch('/api/tapers/' + _taperMed, {credentials:'same-origin'}).then(r => r.json()).catch(() => ({steps:[]}));
  if (!(d.steps || []).length) {
    box.innerHTML = `<div class="panel" style="padding:22px;text-align:center;color:var(--gray-400);font-size:13px">${t('No steps yet — add the first dose above.')}</div>`;
    return;
  }
  const rows = d.steps.map(s => {
    const dt = new Date(s.start_date + 'T12:00:00').toLocaleDateString([], {month:'short', day:'numeric', year:'numeric'});
    const when = s.status === 'upcoming' && s.days_until != null ? ` · ${tformat('in %1 days', s.days_until)}` : '';
    return `<div class="tp-step tp-step--${s.status}">
        <div class="tp-step-dot"></div>
        <div class="tp-step-main">
          <div class="tp-step-dose">${escHtml(s.dosage)}${s.status === 'current' ? ` <span class="tp-now">${t('now')}</span>` : ''}</div>
          <div class="tp-step-meta">${t('from')} ${dt}${when}${s.note ? ' · ' + escHtml(s.note) : ''}</div>
        </div>
        <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteTaperStep('${s.id}')" style="color:var(--gray-300)">✕</button>
      </div>`;
  }).join('');
  box.innerHTML = `<div class="panel" style="padding:16px 20px"><div class="tp-timeline">${rows}</div></div>`;
}

async function addTaperStep() {
  const dosage = document.getElementById('tp-dose')?.value?.trim();
  const date = document.getElementById('tp-date')?.value;
  if (!dosage) { showToast(t('Enter a dose'), 'error'); return; }
  if (!date) { showToast(t('Pick a start date'), 'error'); return; }
  const r = await fetch('/api/tapers', {method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
    body: JSON.stringify({medicine_id: _taperMed, dosage, start_date: date, note: document.getElementById('tp-note')?.value || ''})})
    .then(x => x.json()).catch(() => null);
  if (r && r.success) {
    showToast(t('Step added'));
    ['tp-dose','tp-note'].forEach(i => { const el = document.getElementById(i); if (el) el.value = ''; });
    loadTaperSteps();
  } else showToast((r && r.error) || t('Could not save'), 'error');
}

async function deleteTaperStep(id) {
  await fetch('/api/tapers/step/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadTaperSteps();
}

// ── Dependents / family profiles ─────────────────────────────────────────────
// Track health for someone who doesn't use the app themselves (a child's
// vaccines, a parent's meds) from the caregiver's own account. All owned and
// scoped to the caregiver; ownership re-checked server-side on every record op.
let _activeDependent = null;

const DEP_REL = { child:'🧒 Child', parent:'👵 Parent', spouse:'💑 Spouse',
  sibling:'👫 Sibling', grandparent:'👴 Grandparent', other:'👤 Other' };
const DEP_KIND = { medicine:'💊 Medicines', vaccine:'💉 Vaccines',
  note:'📝 Notes', measurement:'📏 Measurements' };

function _relLabel(k) { const m = DEP_REL[k] || '👤 Other'; const [e, ...r] = m.split(' '); return e + ' ' + t(r.join(' ')); }

async function loadDependents() {
  const el = document.getElementById('dependents-view-content');
  if (!el) return;
  if (_activeDependent) return renderDependentDetail(_activeDependent);
  const d = await fetch('/api/dependents', {credentials:'same-origin'}).then(r => r.ok ? r.json() : {dependents:[]}).catch(() => ({dependents:[]}));
  el.innerHTML = renderDependentsList(d.dependents || []);
}

function renderDependentsList(deps) {
  const form = `
    <div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Add someone')}</h2>
      <div class="dep-form">
        <input type="text" id="dep-name" class="form-input" placeholder="${t('Name')}" style="max-width:180px">
        <select id="dep-rel" class="form-input" style="max-width:150px">
          ${Object.keys(DEP_REL).map(k => `<option value="${k}">${_relLabel(k)}</option>`).join('')}
        </select>
        <input type="date" id="dep-birthdate" class="form-input" title="${t('Birthdate (optional)')}" max="${localToday()}" style="max-width:160px">
        <button class="btn-primary" data-ev-click="addDependent()">${t('Add')}</button>
      </div>
    </div>`;

  if (!deps.length) {
    return form + `<div class="panel" style="padding:28px;text-align:center">
        <div style="font-size:30px;margin-bottom:8px">👪</div>
        <div style="font-size:14px;font-weight:600;margin-bottom:4px">${t('No one added yet')}</div>
        <div style="font-size:13px;color:var(--gray-400)">${t('Add a child or parent above to keep their vaccines, medicines and notes.')}</div>
      </div>`;
  }

  const cards = deps.map(d => {
    const chips = Object.entries(d.counts || {}).map(([k, n]) =>
      `<span class="dep-count">${(DEP_KIND[k] || k).split(' ')[0]} ${n}</span>`).join('');
    return `<button class="dep-card" data-ev-click="openDependent('${d.id}')">
        <div class="dep-avatar">${(DEP_REL[d.relationship] || '👤').split(' ')[0]}</div>
        <div class="dep-card-body">
          <div class="dep-card-name">${escHtml(d.name)}${d.age != null ? ` <span class="dep-age">${tformat('%1 yr', d.age)}</span>` : ''}</div>
          <div class="dep-card-rel">${_relLabel(d.relationship)}</div>
          ${chips ? `<div class="dep-counts">${chips}</div>` : ''}
        </div>
        <span class="dep-chevron">›</span>
      </button>`;
  }).join('');
  return form + `<div class="dep-grid">${cards}</div>`;
}

function openDependent(id) { _activeDependent = id; renderDependentDetail(id); }
function closeDependent() { _activeDependent = null; loadDependents(); }

async function renderDependentDetail(id) {
  const el = document.getElementById('dependents-view-content');
  if (!el) return;
  const d = await fetch(`/api/dependents/${id}/records`, {credentials:'same-origin'}).then(r => r.ok ? r.json() : null).catch(() => null);
  if (!d || !d.dependent || !d.dependent.id) { closeDependent(); return; }
  const dep = d.dependent;

  const addForm = `
    <div class="panel" style="padding:16px 18px;margin-bottom:16px">
      <div class="dep-rec-form">
        <select id="dep-rec-kind" class="form-input" style="max-width:150px">
          ${Object.keys(DEP_KIND).map(k => { const [e, ...r] = DEP_KIND[k].split(' '); return `<option value="${k}">${e} ${t(r.join(' '))}</option>`; }).join('')}
        </select>
        <input type="text" id="dep-rec-label" class="form-input" placeholder="${t('What? (e.g. MR vaccine, Amlodipine)')}" style="max-width:200px">
        <input type="text" id="dep-rec-detail" class="form-input" placeholder="${t('Detail (optional)')}" style="max-width:160px">
        <input type="date" id="dep-rec-date" class="form-input" max="${localToday()}" style="max-width:150px">
        <button class="btn-primary" data-ev-click="addDependentRecord('${id}')">${t('Add')}</button>
      </div>
    </div>`;

  const sections = Object.keys(DEP_KIND).map(kind => {
    const items = d.records[kind] || [];
    if (!items.length) return '';
    const [emoji, ...rest] = DEP_KIND[kind].split(' ');
    return `<div class="panel" style="padding:16px 18px;margin-bottom:14px">
        <h2 class="panel-title" style="margin-bottom:10px">${emoji} ${t(rest.join(' '))}</h2>
        ${items.map(r => `<div class="dep-rec-row">
          <div class="dep-rec-main"><div class="dep-rec-label">${escHtml(r.label)}</div>
            ${r.detail ? `<span class="dep-rec-detail">${escHtml(r.detail)}</span>` : ''}</div>
          ${r.date_key ? `<span class="dep-rec-date">${_fmtShortDate(r.date_key)}</span>` : ''}
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteDependentRecord('${r.id}', '${id}')" style="color:var(--gray-300)">✕</button>
        </div>`).join('')}
      </div>`;
  }).join('');

  el.innerHTML = `
    <button class="btn-outline" style="font-size:12px;margin-bottom:14px" data-ev-click="closeDependent()">‹ ${t('Everyone')}</button>
    <div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <div class="dep-head">
        <div class="dep-avatar dep-avatar--lg">${(DEP_REL[dep.relationship] || '👤').split(' ')[0]}</div>
        <div style="flex:1">
          <div class="dep-detail-name">${escHtml(dep.name)}</div>
          <div class="dep-detail-rel">${_relLabel(dep.relationship)}${dep.age != null ? ' · ' + tformat('%1 yr', dep.age) : ''}</div>
          ${dep.notes ? `<div class="dep-detail-notes">${escHtml(dep.notes)}</div>` : ''}
        </div>
        <button class="btn-icon" title="${t('Remove')}" data-ev-click="deleteDependent('${id}')" style="color:#DC2626">🗑</button>
      </div>
    </div>
    ${addForm}
    ${sections || `<div class="panel" style="padding:24px;text-align:center;color:var(--gray-400);font-size:13px">${t('No records yet — add a vaccine, medicine or note above.')}</div>`}`;
}

async function addDependent() {
  const name = document.getElementById('dep-name')?.value.trim();
  if (!name) { showToast('Enter a name', 'error'); return; }
  const r = await fetch('/api/dependents', {
    method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
    body: JSON.stringify({name, relationship: document.getElementById('dep-rel')?.value || 'other',
                          birthdate: document.getElementById('dep-birthdate')?.value || null}),
  }).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(t('Added')); loadDependents(); }
  else showToast((r && r.error) || 'Could not add', 'error');
}

async function deleteDependent(id) {
  await fetch('/api/dependents/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  _activeDependent = null; loadDependents();
}

async function addDependentRecord(id) {
  const kind = document.getElementById('dep-rec-kind')?.value;
  const label = document.getElementById('dep-rec-label')?.value.trim();
  if (!label) { showToast('What is it?', 'error'); return; }
  const r = await fetch(`/api/dependents/${id}/records`, {
    method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
    body: JSON.stringify({kind, label, detail: document.getElementById('dep-rec-detail')?.value || '',
                          date_key: document.getElementById('dep-rec-date')?.value || ''}),
  }).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(t('Added')); renderDependentDetail(id); }
  else showToast((r && r.error) || 'Could not add', 'error');
}

async function deleteDependentRecord(rid, depId) {
  await fetch('/api/dependents/records/' + rid, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  renderDependentDetail(depId);
}

// ── Health timeline ──────────────────────────────────────────────────────────
// One chronological "health story" merging meds/symptoms/vitals/labs/
// appointments/vaccines. Private diary categories (journal/mood/cycle) are
// excluded server-side. Filterable by type; grouped by month.
let _timelineTypes = new Set();     // empty = all
let _timelineMeta = null;

const TL_COLOR = {
  medicine:'#3E7862', symptom:'#D97706', vital:'#DC2626',
  lab:'#2563EB', appointment:'#7C3AED', vaccine:'#0E9F8B',
};

async function loadTimeline() {
  const el = document.getElementById('timeline-view-content');
  if (!el) return;
  const q = _timelineTypes.size ? ('?types=' + [..._timelineTypes].join(',')) : '';
  const d = await fetch('/api/timeline' + q, {credentials:'same-origin'}).then(r => r.ok ? r.json() : null).catch(() => null);
  if (!d) { el.innerHTML = ''; return; }
  _timelineMeta = d.types;
  el.innerHTML = renderTimeline(d);
}

function toggleTimelineType(key) {
  if (_timelineTypes.has(key)) _timelineTypes.delete(key);
  else _timelineTypes.add(key);
  loadTimeline();
}

function _monthKey(iso) { return (iso || '').slice(0, 7); }
function _monthTitle(ym) {
  const [y, m] = ym.split('-').map(Number);
  return new Date(y, m - 1, 1).toLocaleDateString('en-US', {month: 'long', year: 'numeric'});
}

function renderTimeline(d) {
  const chips = (d.types || []).map(tp => {
    const on = _timelineTypes.has(tp.key);
    return `<button class="tl-chip${on ? ' active' : ''}" data-ev-click="toggleTimelineType('${tp.key}')">${tp.icon} ${t(tp.label)}</button>`;
  }).join('');
  const filterBar = `<div class="tl-filter">${chips}${_timelineTypes.size
    ? `<button class="tl-chip tl-clear" data-ev-click="clearTimelineFilter()">${t('Clear')}</button>` : ''}</div>`;

  if (!d.events.length) {
    return filterBar + `<div class="panel" style="padding:28px;text-align:center">
        <div style="font-size:30px;margin-bottom:8px">🧬</div>
        <div style="font-size:14px;font-weight:600;margin-bottom:4px">${t('Nothing here yet')}</div>
        <div style="font-size:13px;color:var(--gray-400)">${t('As you log medicines, vitals, labs, visits and vaccines, they appear here in order.')}</div>
      </div>`;
  }

  // Group by month.
  let html = '', curMonth = null;
  for (const e of d.events) {
    const ym = _monthKey(e.date);
    if (ym !== curMonth) {
      if (curMonth !== null) html += `</div>`;
      html += `<div class="tl-month-label">${_monthTitle(ym)}</div><div class="tl-month">`;
      curMonth = ym;
    }
    const c = TL_COLOR[e.type] || 'var(--gray-400)';
    const icon = (_timelineMeta.find(x => x.key === e.type) || {}).icon || '•';
    html += `<div class="tl-event">
      <div class="tl-dot" style="background:${c}"><span>${icon}</span></div>
      <div class="tl-body">
        <div class="tl-title">${escHtml(e.title)}</div>
        ${e.detail ? `<div class="tl-detail">${escHtml(e.detail)}</div>` : ''}
      </div>
      <div class="tl-date">${_fmtShortDate(e.date)}</div>
    </div>`;
  }
  html += `</div>`;
  const more = d.total > d.events.length
    ? `<div class="tl-more">${tformat('Showing the most recent %1 of %2 events.', d.events.length, d.total)}</div>` : '';
  return filterBar + `<div class="panel" style="padding:8px 18px 18px">${html}${more}</div>`;
}

function clearTimelineFilter() { _timelineTypes.clear(); loadTimeline(); }

// ── Immunizations ────────────────────────────────────────────────────────────
// Vaccine dose records + an honest "next due" estimate for the few recurring
// vaccines (tetanus/flu/typhoid). Catalog is India-weighted (UIP/IAP). Timing
// text is guidance, never a personal schedule.
let _vaxCatalog = null;

async function loadImmunizations() {
  const el = document.getElementById('immunizations-view-content');
  if (!el) return;
  const [rec, cat] = await Promise.all([
    fetch('/api/immunizations', {credentials:'same-origin'}).then(r => r.ok ? r.json() : {vaccines:[],due:[],total_doses:0}).catch(() => ({vaccines:[],due:[],total_doses:0})),
    fetch('/api/immunizations/catalog', {credentials:'same-origin'}).then(r => r.ok ? r.json() : null).catch(() => null),
  ]);
  _vaxCatalog = cat;
  el.innerHTML = renderImmunizations(rec, cat);
}

function _dueLabel(d) {
  if (d.overdue) return t('overdue');
  if (d.days_until <= 0) return t('due now');
  return tformat('due in %1 days', d.days_until);
}

function renderImmunizations(rec, cat) {
  const today = localToday();
  let opts = `<option value="">${t('Choose a vaccine…')}</option>`;
  if (cat && cat.vaccines) {
    for (const c of cat.categories) {
      opts += `<optgroup label="${escHtml(c)}">`;
      for (const v of (cat.vaccines[c] || [])) {
        opts += `<option value="${v.key}">${escHtml(v.name)}${v.when ? ' — ' + escHtml(v.when) : ''}</option>`;
      }
      opts += `</optgroup>`;
    }
  }

  const dueBanner = (rec.due && rec.due.length) ? `
    <div class="vax-due-banner">
      <div class="vax-due-title">💉 ${t('Due soon')}</div>
      ${rec.due.map(d => `<div class="vax-due-row"><span>${escHtml(t2vaxname(d.name))}</span>
        <span class="vax-due-when ${d.overdue ? 'vax-overdue' : ''}">${_dueLabel(d)} · ${_fmtShortDate(d.date)}</span></div>`).join('')}
      <div class="vax-due-note">${t('An estimate from your last dose — your doctor\'s advice always wins.')}</div>
    </div>` : '';

  const form = `
    <div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Add a dose')}</h2>
      <div class="vax-form">
        <select id="vax-key" class="form-input" style="max-width:280px">${opts}</select>
        <input type="text" id="vax-dose" class="form-input" placeholder="${t('Dose (e.g. Dose 1, Booster)')}" style="max-width:180px">
        <input type="date" id="vax-date" class="form-input" value="${today}" max="${today}" style="max-width:160px">
        <button class="btn-primary" data-ev-click="logVaccine()">${t('Save')}</button>
      </div>
    </div>`;

  if (!rec.vaccines.length) {
    return dueBanner + form + `<div class="panel" style="padding:28px;text-align:center">
        <div style="font-size:30px;margin-bottom:8px">💉</div>
        <div style="font-size:14px;font-weight:600;margin-bottom:4px">${t('No vaccines recorded yet')}</div>
        <div style="font-size:13px;color:var(--gray-400)">${t('Add a dose from your vaccination card above.')}</div>
      </div>`;
  }

  const byCat = {};
  for (const v of rec.vaccines) (byCat[v.category] = byCat[v.category] || []).push(v);
  const cards = Object.entries(byCat).map(([c, items]) => `
    <div class="panel" style="padding:16px 18px;margin-bottom:14px">
      <h2 class="panel-title" style="margin-bottom:10px">${escHtml(c)}</h2>
      ${items.map(v => `
        <div class="vax-row">
          <div class="vax-row-main">
            <div class="vax-name">${escHtml(v.name)}${v.dose_count > 1 ? ` <span class="vax-count">×${v.dose_count}</span>` : ''}</div>
            <div class="vax-meta">${t('last')}: ${_fmtShortDate(v.last_date)}${v.next_due ? ` · ${t('next')} ~${_fmtShortDate(v.next_due.date)}${v.next_due.overdue ? ' ⚠️' : ''}` : ''}</div>
          </div>
          <div class="vax-doses">${v.doses.map(dz => `
            <span class="vax-dose-chip" title="${escHtml(dz.notes||'')}">${dz.dose_label ? escHtml(dz.dose_label) + ' · ' : ''}${_fmtShortDate(dz.date_given)}
              <button class="vax-dose-x" data-ev-click="deleteVaccine('${dz.id}')" title="${t('Delete')}">✕</button></span>`).join('')}</div>
        </div>`).join('')}
    </div>`).join('');

  return dueBanner + form + cards;
}

// Vaccine names come from the catalog already; helper kept for clarity/i18n hook.
function t2vaxname(n) { return n; }

async function logVaccine() {
  const vaccine_key = document.getElementById('vax-key')?.value;
  const date_given = document.getElementById('vax-date')?.value || localToday();
  const dose_label = document.getElementById('vax-dose')?.value || '';
  if (!vaccine_key) { showToast('Pick a vaccine', 'error'); return; }
  const r = await fetch('/api/immunizations', {
    method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
    body: JSON.stringify({vaccine_key, date_given, dose_label}),
  }).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(t('Dose recorded')); loadImmunizations(); }
  else showToast((r && r.error) || 'Could not save', 'error');
}

async function deleteVaccine(id) {
  await fetch('/api/immunizations/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadImmunizations();
}

// ── Condition dashboards ─────────────────────────────────────────────────────
// One focused view per chronic condition, pulling its labs + vitals + medicines
// (+ cycle for PCOS) together. Pure read over existing data — no diagnosis, no
// targets of our own; lab status still comes from the typical-range catalog.
let _activeCondition = null;

async function loadConditionsView() {
  const el = document.getElementById('conditions-view-content');
  if (!el) return;
  if (_activeCondition) return renderConditionDashboard(_activeCondition);
  const d = await fetch('/api/conditions', {credentials:'same-origin'}).then(r => r.ok ? r.json() : {conditions:[]}).catch(() => ({conditions:[]}));
  el.innerHTML = `
    <div class="cond-grid">
      ${(d.conditions || []).map(c => `
        <button class="cond-card" data-ev-click="openCondition('${c.key}')">
          <span class="cond-emoji">${c.emoji}</span>
          <span class="cond-name">${t(c.name)}</span>
          <span class="cond-blurb">${t(c.blurb)}</span>
        </button>`).join('')}
    </div>`;
}

function openCondition(key) { _activeCondition = key; renderConditionDashboard(key); }
function closeCondition() { _activeCondition = null; loadConditionsView(); }

const _LAB_ST = {low:{c:'lab-low',l:'Low'}, high:{c:'lab-high',l:'High'}, in_range:{c:'lab-ok',l:'OK'}};

async function renderConditionDashboard(key) {
  const el = document.getElementById('conditions-view-content');
  if (!el) return;
  const d = await fetch('/api/conditions/' + key, {credentials:'same-origin'}).then(r => r.ok ? r.json() : null).catch(() => null);
  if (!d) { el.innerHTML = ''; return; }

  const labs = d.labs.map(l => {
    if (!l.have) return `<div class="cond-metric cond-missing">
        <div class="cond-metric-name">${escHtml(l.name)}</div>
        <div class="cond-metric-empty">${t('not logged yet')}</div></div>`;
    const st = _LAB_ST[l.status];
    return `<div class="cond-metric">
        <div class="cond-metric-name">${escHtml(l.name)} ${st ? `<span class="lab-badge ${st.c}">${t(st.l)}</span>` : ''}</div>
        <div class="cond-metric-val ${st ? st.c : ''}">${l.value}<span class="cond-metric-unit">${escHtml(l.unit||'')}</span></div>
        <div class="cond-metric-meta">${_fmtShortDate(l.date)}${l.ref_low != null ? ` · ${t('typical')} ${l.ref_low}–${l.ref_high}` : ''}</div>
      </div>`;
  }).join('');

  const vitals = d.vitals.map(v => {
    if (!v.have) return '';
    const val = v.value2 != null ? `${v.value1}/${v.value2}` : v.value1;
    const nm = ({blood_sugar:'Blood sugar', blood_pressure:'Blood pressure', heart_rate:'Heart rate'})[v.type] || v.type;
    return `<div class="cond-metric">
        <div class="cond-metric-name">${t(nm)}</div>
        <div class="cond-metric-val">${val}<span class="cond-metric-unit">${escHtml(v.unit||'')}</span></div>
        <div class="cond-metric-meta">${_fmtShortDate(v.date)}</div>
      </div>`;
  }).join('');

  const meds = d.medicines.length
    ? `<div class="cond-meds">${d.medicines.map(m => `<span class="cond-med">💊 ${escHtml(m.name)}${m.dosage ? ' · ' + escHtml(m.dosage) : ''}</span>`).join('')}</div>`
    : `<div class="cond-empty-line">${t('No matching medicine found. Add one in Medicines and set its purpose to link it here.')}</div>`;

  let cycleBlock = '';
  if (d.cycle) {
    const reg = d.cycle.regularity;
    const regLine = reg
      ? (reg.irregular
          ? `⚠️ ${tformat('Recent cycles ranged %1–%2 days — worth mentioning to a doctor', reg.min, reg.max)}`
          : `✓ ${tformat('Recent cycles look regular (~%1 days)', d.cycle.cycle_length || reg.min)}`)
      : t('Log a couple of cycles to see regularity.');
    const syms = (d.cycle.symptoms || []).map(s => `${(CYCLE_SYMPTOMS[s.key]||s.key)} ×${s.count}`).join(' · ');
    cycleBlock = `
      <div class="cond-section">
        <div class="cond-section-title">${t('Cycle')}</div>
        <div class="cond-cycle-reg">${regLine}</div>
        ${syms ? `<div class="cond-empty-line" style="margin-top:6px">${t('Most logged')}: ${syms}</div>` : ''}
      </div>`;
  }

  el.innerHTML = `
    <button class="btn-outline" style="font-size:12px;margin-bottom:14px" data-ev-click="closeCondition()">‹ ${t('All conditions')}</button>
    <div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <div class="cond-head"><span class="cond-emoji-lg">${d.emoji}</span>
        <div><div class="cond-title">${t(d.name)}</div><div class="cond-sub">${t(d.blurb)}</div></div></div>
    </div>
    ${(labs || vitals) ? `<div class="panel" style="padding:16px 18px;margin-bottom:16px">
      <div class="cond-section-title">${t('Latest numbers')}</div>
      <div class="cond-metrics">${vitals}${labs}</div>
      <div class="lab-note" style="margin-top:12px">🩺 ${t('Typical ranges are for orientation only — discuss anything out of range with your doctor.')}</div>
    </div>` : ''}
    <div class="panel" style="padding:16px 18px${d.cycle ? ';margin-bottom:16px' : ''}">
      <div class="cond-section-title">${t('Medicines')}</div>${meds}
    </div>
    ${d.cycle ? `<div class="panel" style="padding:16px 18px">${cycleBlock}</div>` : ''}
    ${d.cycle_private ? `<div class="panel" style="padding:16px 18px"><div class="cond-empty-line">🔒 ${t('Cycle details are private to this member and aren\'t shown while managing their account.')}</div></div>` : ''}`;
}

// ── Health spending ──────────────────────────────────────────────────────────
// Out-of-pocket health costs by month, net of any scheme/insurance cover. India
// is largely pay-as-you-go, so the number that matters is what you actually paid.
let _spendMonth = null;   // 'YYYY-MM'; null → current month

const SPEND_CATS = {
  medicines:    '💊 Medicines',
  consultation: '🩺 Consultation',
  lab:          '🧪 Lab tests',
  hospital:     '🏥 Hospital',
  insurance:    '🛡️ Insurance premium',
  other:        '📌 Other',
};

function _rupee(n) { return '₹' + Math.round(n || 0).toLocaleString('en-IN'); }
function _spendCatLabel(k) {
  const meta = SPEND_CATS[k] || ('📌 ' + k);
  const [emoji, ...rest] = meta.split(' ');
  return emoji + ' ' + t(rest.join(' '));
}

function _thisMonthKey() {
  // Uses the app's local-today helper so it matches server month bounds.
  return localToday().slice(0, 7);
}

async function loadSpendingView() {
  const el = document.getElementById('spending-view-content');
  if (!el) return;
  const month = _spendMonth || _thisMonthKey();
  const [data, trend] = await Promise.all([
    fetch('/api/expenses?month=' + month, {credentials:'same-origin'}).then(r => r.ok ? r.json() : null).catch(() => null),
    fetch('/api/expenses/trend', {credentials:'same-origin'}).then(r => r.ok ? r.json() : {months:[]}).catch(() => ({months:[]})),
  ]);
  if (!data) { el.innerHTML = ''; return; }
  el.innerHTML = renderSpendingView(data, trend.months || []);
}

function _shiftMonth(month, delta) {
  let [y, m] = month.split('-').map(Number);
  m += delta;
  while (m < 1) { m += 12; y--; }
  while (m > 12) { m -= 12; y++; }
  return `${y}-${String(m).padStart(2,'0')}`;
}

function spendPrevMonth() { _spendMonth = _shiftMonth(_spendMonth || _thisMonthKey(), -1); loadSpendingView(); }
function spendNextMonth() {
  const cur = _spendMonth || _thisMonthKey();
  if (cur >= _thisMonthKey()) return;       // don't go into the future
  _spendMonth = _shiftMonth(cur, 1); loadSpendingView();
}

function _monthLabel(m) {
  const [y, mo] = m.split('-').map(Number);
  return new Date(y, mo - 1, 1).toLocaleDateString('en-US', {month:'long', year:'numeric'});
}

function renderSpendingView(d, trendMonths) {
  const today = localToday();
  const catOptions = Object.keys(SPEND_CATS).map(k =>
    `<option value="${k}">${_spendCatLabel(k)}</option>`).join('');

  const form = `
    <div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:12px">${t('Add an expense')}</h2>
      <div class="spend-form">
        <select id="spend-cat" class="form-input" style="max-width:190px">${catOptions}</select>
        <input type="text" id="spend-desc" class="form-input" placeholder="${t('What for? (optional)')}" style="max-width:200px">
        <input type="number" step="any" min="0" id="spend-amount" class="form-input" placeholder="₹ ${t('amount')}" style="max-width:120px">
        <input type="number" step="any" min="0" id="spend-covered" class="form-input" placeholder="${t('covered ₹0')}" title="${t('Reimbursed by insurance or a scheme')}" style="max-width:130px">
        <input type="date" id="spend-date" class="form-input" value="${today}" max="${today}" style="max-width:160px">
        <button class="btn-primary" data-ev-click="logExpense()">${t('Add')}</button>
      </div>
    </div>`;

  // Month header + out-of-pocket hero
  const canNext = (d.month < _thisMonthKey());
  const hero = `
    <div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <div class="spend-monthnav">
        <button class="btn-icon" data-ev-click="spendPrevMonth()" title="${t('Previous month')}">‹</button>
        <span class="spend-month">${_monthLabel(d.month)}</span>
        <button class="btn-icon" data-ev-click="spendNextMonth()" title="${t('Next month')}" ${canNext ? '' : 'disabled style="opacity:.3"'}>›</button>
      </div>
      <div class="spend-hero">
        <div class="spend-hero-main">
          <div class="spend-oop">${_rupee(d.out_of_pocket)}</div>
          <div class="spend-oop-label">${t('out of pocket this month')}</div>
        </div>
        ${d.covered > 0 ? `<div class="spend-covered">${tformat('%1 covered by insurance/scheme', _rupee(d.covered))}</div>` : ''}
      </div>
      ${(trendMonths.length >= 2) ? _spendTrendBars(trendMonths) : ''}
    </div>`;

  // Category breakdown
  const breakdown = d.breakdown.length ? `
    <div class="panel" style="padding:16px 18px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:10px">${t('Where it went')}</h2>
      ${(() => {
        const max = Math.max(...d.breakdown.map(b => b.net), 1);
        return d.breakdown.map(b => `
          <div class="spend-cat-row">
            <span class="spend-cat-name">${_spendCatLabel(b.category)}</span>
            <div class="spend-cat-bar"><div class="spend-cat-fill" style="width:${(b.net/max*100).toFixed(0)}%"></div></div>
            <span class="spend-cat-amt">${_rupee(b.net)}</span>
          </div>`).join('');
      })()}
    </div>` : '';

  // Itemised list
  const items = d.items.length ? `
    <div class="panel" style="padding:16px 18px">
      <h2 class="panel-title" style="margin-bottom:10px">${t('Expenses')}</h2>
      ${d.items.map(i => `
        <div class="spend-row">
          <div class="spend-row-main">
            <div class="spend-row-title">${_spendCatLabel(i.category)}${i.description ? ' · ' + escHtml(i.description) : ''}</div>
            <div class="spend-row-meta">${_fmtShortDate(i.date_key)}${i.covered > 0 ? ' · ' + tformat('%1 covered', _rupee(i.covered)) : ''}</div>
          </div>
          <div class="spend-row-amt">${_rupee(i.net)}</div>
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteExpense('${i.id}')" style="color:var(--gray-300)">✕</button>
        </div>`).join('')}
    </div>` : `<div class="panel" style="padding:24px;text-align:center;color:var(--gray-400);font-size:13px">${t('No expenses logged this month.')}</div>`;

  return form + hero + breakdown + items;
}

function _spendTrendBars(months) {
  const max = Math.max(...months.map(m => m.out_of_pocket), 1);
  return `<div class="spend-trend">${months.map(m => `
    <div class="spend-trend-col" title="${_monthLabel(m.month)}: ${_rupee(m.out_of_pocket)}">
      <div class="spend-trend-bar" style="height:${Math.max(m.out_of_pocket/max*46, 2).toFixed(0)}px"></div>
      <div class="spend-trend-lbl">${m.month.slice(5)}</div>
    </div>`).join('')}</div>`;
}

async function logExpense() {
  const category = document.getElementById('spend-cat')?.value || 'other';
  const amount = document.getElementById('spend-amount')?.value;
  const covered = document.getElementById('spend-covered')?.value || 0;
  const description = document.getElementById('spend-desc')?.value || '';
  const date_key = document.getElementById('spend-date')?.value || localToday();
  if (!amount || Number(amount) <= 0) { showToast('Enter an amount', 'error'); return; }
  const r = await fetch('/api/expenses', {
    method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
    body: JSON.stringify({category, amount, covered, description, date_key}),
  }).then(x => x.json()).catch(() => null);
  if (r && r.success) {
    _spendMonth = date_key.slice(0, 7);      // jump to the month we just logged into
    showToast(t('Expense added')); loadSpendingView();
  } else showToast((r && r.error) || 'Could not save', 'error');
}

async function deleteExpense(id) {
  await fetch('/api/expenses/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadSpendingView();
}

// ── Lab results ──────────────────────────────────────────────────────────────
// Blood-panel values (HbA1c, lipids, thyroid, vitamins…) kept over time with
// trend charts. Reference ranges + status come from the server (lab_catalog) and
// are ALWAYS framed as "worth discussing with a doctor," never a diagnosis.
let _labCatalog = null;

async function loadLabsView() {
  const el = document.getElementById('labs-view-content');
  if (!el) return;
  const [results, catalog, rechecks] = await Promise.all([
    fetch('/api/labs', {credentials:'same-origin'}).then(r => r.ok ? r.json() : {results:[]}).catch(() => ({results:[]})),
    fetch('/api/labs/catalog', {credentials:'same-origin'}).then(r => r.ok ? r.json() : null).catch(() => null),
    fetch('/api/labs/rechecks', {credentials:'same-origin'}).then(r => r.ok ? r.json() : {rechecks:[]}).catch(() => ({rechecks:[]})),
  ]);
  _labCatalog = catalog;
  el.innerHTML = renderLabsView(results.results || [], catalog, rechecks.rechecks || []);
}

async function setLabRecheck(key) {
  const r = await fetch('/api/labs/rechecks', {method:'POST', headers:{'Content-Type':'application/json'},
    credentials:'same-origin', body: JSON.stringify({lab_key: key})}).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(t('Recheck reminder on')); loadLabsView(); }
  else showToast((r && r.error) || t('Could not save'), 'error');
}

async function clearLabRecheck(key) {
  await fetch('/api/labs/rechecks/' + encodeURIComponent(key), {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadLabsView();
}

const LAB_STATUS = {
  low:      {cls:'lab-low',  label:'Below range'},
  high:     {cls:'lab-high', label:'Above range'},
  in_range: {cls:'lab-ok',   label:'In range'},
};

function _labStatusBadge(status) {
  const s = LAB_STATUS[status];
  return s ? `<span class="lab-badge ${s.cls}">${t(s.label)}</span>` : '';
}

function renderRecheckBanner(rechecks) {
  const flagged = (rechecks || []).filter(r => r.status === 'due' || r.status === 'soon');
  if (!flagged.length) return '';
  const rows = flagged.map(r => {
    const cls = r.status === 'due' ? 'lrc-due' : 'lrc-soon';
    const when = r.status === 'due'
      ? (r.days_until === 0 ? t('due now') : tformat('%1 days overdue', -r.days_until))
      : tformat('due in %1 days', r.days_until);
    const iv = r.interval_days < 30
      ? tformat('typically every %1 days', r.interval_days)
      : tformat('typically every %1 months', Math.max(1, Math.round(r.interval_days / 30)));
    return `<div class="lrc-item ${cls}">
        <span class="lrc-name">🧪 ${escHtml(r.name)}</span>
        <span class="lrc-when">${when}</span>
        <span class="lrc-typical">${iv}</span>
      </div>`;
  }).join('');
  return `<div class="panel lrc-panel" style="padding:14px 18px;margin-bottom:16px">
      <div class="lrc-head">🔔 ${t('Due for a recheck')}</div>
      ${rows}
      <div class="lrc-note">${t('Suggested intervals are typical guidance, not a doctor’s order.')}</div>
    </div>`;
}

function renderLabsView(results, catalog, rechecks) {
  const recheckKeys = new Set((rechecks || []).map(r => r.lab_key));
  // Add-a-lab picker — optgroups by category, each option carries unit + range.
  let options = `<option value="">${t('Choose a test…')}</option>`;
  if (catalog && catalog.tests) {
    for (const cat of catalog.categories) {
      options += `<optgroup label="${escHtml(cat)}">`;
      for (const tst of (catalog.tests[cat] || [])) {
        const rng = (tst.ref_low != null) ? ` (${tst.ref_low}–${tst.ref_high} ${tst.unit})` : '';
        options += `<option value="${tst.key}" data-unit="${escHtml(tst.unit)}">${escHtml(tst.name)}${rng}</option>`;
      }
      options += `</optgroup>`;
    }
  }
  const today = localToday();

  const form = `
    <div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:6px">${t('Add a result')}</h2>
      <div class="lab-note">🩺 ${t('Reference ranges are typical adult values for orientation only — labs and your doctor\'s targets vary. An out-of-range number is worth discussing with your doctor, never a diagnosis.')}</div>
      <div class="lab-form">
        <select id="lab-test" class="form-input" data-ev-change="onLabTestPick()">${options}</select>
        <input type="number" step="any" id="lab-value" class="form-input" placeholder="${t('Value')}" style="max-width:120px">
        <span id="lab-unit" class="lab-unit"></span>
        <input type="date" id="lab-date" class="form-input" value="${today}" max="${today}" style="max-width:160px">
        <button class="btn-primary" data-ev-click="logLab()">${t('Save')}</button>
      </div>
    </div>`;

  if (!results.length) {
    return form + `<div class="panel" style="padding:28px;text-align:center">
        <div style="font-size:30px;margin-bottom:8px">🧪</div>
        <div style="font-size:14px;font-weight:600;margin-bottom:4px">${t('No lab results yet')}</div>
        <div style="font-size:13px;color:var(--gray-400)">${t('Add a value from your latest blood test above to start tracking it.')}</div>
      </div>`;
  }

  // Group latest-per-test by category.
  const byCat = {};
  for (const r of results) (byCat[r.category] = byCat[r.category] || []).push(r);
  const cards = Object.entries(byCat).map(([cat, items]) => `
    <div class="panel" style="padding:16px 18px;margin-bottom:14px">
      <h2 class="panel-title" style="margin-bottom:10px">${escHtml(cat)}</h2>
      ${items.map(r => {
        const rng = (r.ref_low != null) ? `${r.ref_low}–${r.ref_high} ${escHtml(r.unit||'')}` : t('no set range');
        return `<div class="lab-row">
          <div class="lab-row-main">
            <div class="lab-name">${escHtml(r.name)} ${_labStatusBadge(r.status)}</div>
            <div class="lab-meta">${t('typical')}: ${rng} · ${_fmtShortDate(r.date_key)}</div>
            ${_labBandBar(r)}
          </div>
          <div class="lab-value ${LAB_STATUS[r.status]?.cls || ''}">${r.value}<span class="lab-value-unit">${escHtml(r.unit||'')}</span></div>
          <button class="btn-outline" style="font-size:12px" data-ev-click="toggleLabTrend('${r.lab_key}')">${t('Trend')}</button>
          ${recheckKeys.has(r.lab_key)
            ? `<button class="btn-icon lab-bell-on" title="${t('Recheck reminder on — tap to turn off')}" data-ev-click="clearLabRecheck('${r.lab_key}')">🔔</button>`
            : `<button class="btn-icon" title="${t('Remind me to recheck this')}" data-ev-click="setLabRecheck('${r.lab_key}')" style="opacity:.5">🔕</button>`}
          <button class="btn-icon" title="${t('Delete')}" data-ev-click="deleteLab('${r.id}')" style="color:var(--gray-300)">✕</button>
        </div>
        <div id="lab-trend-${r.lab_key}" class="lab-trend" style="display:none"></div>`;
      }).join('')}
    </div>`).join('');

  return form + renderRecheckBanner(rechecks) + cards;
}

// I6: a reference-band gauge — shows where the latest value sits within the
// typical range. Framing only, never a diagnosis. Renders nothing when the test
// has no set range or a degenerate one.
function _labBandBar(r) {
  const lo = r.ref_low, hi = r.ref_high, v = Number(r.value);
  if (lo == null || hi == null || !(hi > lo) || !Number.isFinite(v)) return '';
  const span = hi - lo;
  const dispLo = lo - span * 0.6, dispHi = hi + span * 0.6;   // pad so out-of-range values stay visible
  const width = dispHi - dispLo;
  const pos = x => Math.max(0, Math.min(100, ((x - dispLo) / width) * 100));
  const zoneL = pos(lo), zoneR = pos(hi);
  const markPct = pos(v);
  const beyond = v < dispLo ? 'left' : v > dispHi ? 'right' : '';
  const cls = LAB_STATUS[r.status]?.cls || 'lab-ok';
  return `<div class="lab-band" role="img" aria-label="${escHtml(r.name)} ${v} — ${t(LAB_STATUS[r.status]?.label || 'In range')}">
      <div class="lab-band-track">
        <div class="lab-band-zone" style="left:${zoneL.toFixed(1)}%;width:${(zoneR - zoneL).toFixed(1)}%"></div>
        <div class="lab-band-mark ${cls}${beyond ? ' lab-band-mark--edge' : ''}" style="left:${markPct.toFixed(1)}%"></div>
      </div>
    </div>`;
}

function onLabTestPick() {
  const sel = document.getElementById('lab-test');
  const opt = sel?.selectedOptions?.[0];
  const unitEl = document.getElementById('lab-unit');
  if (unitEl) unitEl.textContent = opt ? (opt.dataset.unit || '') : '';
}

async function logLab() {
  const key = document.getElementById('lab-test')?.value;
  const value = document.getElementById('lab-value')?.value;
  const date_key = document.getElementById('lab-date')?.value || localToday();
  if (!key) { showToast('Pick a test', 'error'); return; }
  if (value === '' || value == null) { showToast('Enter a value', 'error'); return; }
  const r = await fetch('/api/labs', {
    method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
    body: JSON.stringify({lab_key:key, value, date_key}),
  }).then(x => x.json()).catch(() => null);
  if (r && r.success) { showToast(t('Result saved')); loadLabsView(); }
  else showToast((r && r.error) || 'Could not save', 'error');
}

async function deleteLab(id) {
  await fetch('/api/labs/' + id, {method:'DELETE', credentials:'same-origin'}).catch(() => {});
  loadLabsView();
}

async function toggleLabTrend(key) {
  const box = document.getElementById('lab-trend-' + key);
  if (!box) return;
  if (box.style.display !== 'none') { box.style.display = 'none'; return; }
  box.style.display = 'block';
  box.innerHTML = `<div style="font-size:12px;color:var(--gray-400);padding:8px">${t('Loading…')}</div>`;
  const d = await fetch('/api/labs/trend/' + key, {credentials:'same-origin'}).then(r => r.json()).catch(() => null);
  if (!d || !d.points || !d.points.length) { box.innerHTML = ''; return; }
  box.innerHTML = renderLabTrend(d);
}

// Compact SVG trend: reference band shaded, points colored by status, connected.
function renderLabTrend(d) {
  const pts = d.points;
  if (pts.length < 2) {
    const p = pts[0];
    return `<div class="lab-trend-single">${t('Only one reading so far')} — ${p.value} ${escHtml(d.unit||'')} · ${_fmtShortDate(p.date)}. ${t('Add another to see a trend.')}</div>`;
  }
  const W = 320, H = 90, pad = 6;
  const vals = pts.map(p => p.value);
  let lo = Math.min(...vals), hi = Math.max(...vals);
  if (d.ref_low != null) { lo = Math.min(lo, d.ref_low); hi = Math.max(hi, d.ref_high); }
  const span = (hi - lo) || 1;
  const x = i => pad + (i / (pts.length - 1)) * (W - 2*pad);
  const y = v => (H - pad) - ((v - lo) / span) * (H - 2*pad);
  const line = pts.map((p, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(p.value).toFixed(1)}`).join(' ');
  const band = (d.ref_low != null)
    ? `<rect x="0" y="${y(d.ref_high).toFixed(1)}" width="${W}" height="${(y(d.ref_low)-y(d.ref_high)).toFixed(1)}" fill="var(--teal-50)" opacity="0.7"/>` : '';
  const dots = pts.map((p, i) => {
    const c = p.status === 'high' ? '#D97706' : p.status === 'low' ? '#3B82F6' : '#3E7862';
    return `<circle cx="${x(i).toFixed(1)}" cy="${y(p.value).toFixed(1)}" r="3.5" fill="${c}"/>`;
  }).join('');
  const latest = pts[pts.length - 1];
  return `
    <div class="lab-trend-wrap">
      <svg viewBox="0 0 ${W} ${H}" class="lab-trend-svg" preserveAspectRatio="none">
        ${band}
        <path d="${line}" fill="none" stroke="var(--gray-300)" stroke-width="1.5"/>
        ${dots}
      </svg>
      <div class="lab-trend-legend">${tformat('%1 readings · latest %2 %3', pts.length, latest.value, d.unit||'')}
        ${d.ref_low != null ? `· ${t('shaded = typical range')}` : ''}</div>
    </div>`;
}

